/*
 * Start every close departure/crossing throat from a known safe setting.
 * These are startup defaults only: after initialization SW1/SW2/SW3/SW4/
 * SW12 are ordinary logical motors protected by their compound next or
 * nextnext resource set.  Treating the defaults as permanent constraints
 * rejects otherwise valid routes and defeats the all-member group arbiter.
 */
static const int tc2_startup_turnout_switches[] = {1, 2, 3, 4, 12};
static const char tc2_startup_turnout_directions[] = {
        'S', 'S', 'C', 'S', 'C'
};

static char startup_turnout_direction(int switch_number) {
        for (unsigned int index = 0;
             index < sizeof(tc2_startup_turnout_switches) /
                     sizeof(tc2_startup_turnout_switches[0]);
             ++index) {
                if (tc2_startup_turnout_switches[index] ==
                    switch_number) {
                        return tc2_startup_turnout_directions[index];
                }
        }
        return 0;
}

