int Tc2DispatchGetSnapshot(int tid, tc2_dispatch_snapshot *snapshot) {
        tc2_dispatch_request request;
        if (!snapshot) return -1;
        clear_request(&request, TC2_DISPATCH_MSG_SNAPSHOT);
        int ret = Send(tid, (const char *)&request, sizeof(request),
                       (char *)snapshot, sizeof(*snapshot));
        return ret == (int)sizeof(*snapshot) ? 0 : -1;
}

int Tc2DispatchGetBlockedSnapshot(
        int tid, tc2_dispatch_blocked_snapshot *snapshot) {
        tc2_dispatch_request request;
        if (!snapshot) return -1;
        clear_request(&request, TC2_DISPATCH_MSG_BLOCKED_SNAPSHOT);
        int ret = Send(tid, (const char *)&request, sizeof(request),
                       (char *)snapshot, sizeof(*snapshot));
        return ret == (int)sizeof(*snapshot) ? 0 : -1;
}

int Tc2DispatchGetProjectionHeader(
        int tid, int train,
        tc2_dispatch_projection_header *header) {
        tc2_dispatch_request request;
        if (!header) return TC2_DISPATCH_PROJECTION_INVALID_ARGUMENT;
        util_zero_bytes(
                (volatile unsigned char *)header,
                (unsigned int)sizeof(*header));
        header->status = TC2_DISPATCH_PROJECTION_INTERNAL;
        clear_request(
                &request,
                TC2_DISPATCH_MSG_PROJECTION_HEADER);
        request.train = train;
        int ret = Send(
                tid, (const char *)&request, sizeof(request),
                (char *)header, sizeof(*header));
        if (ret != (int)sizeof(*header)) {
                util_zero_bytes(
                        (volatile unsigned char *)header,
                        (unsigned int)sizeof(*header));
                header->status =
                        TC2_DISPATCH_PROJECTION_INTERNAL;
                return TC2_DISPATCH_PROJECTION_INTERNAL;
        }
        return header->status;
}

int Tc2DispatchGetProjectionPage(
        int tid, int train, uint64_t publication_serial,
        uint32_t plan_generation, uint32_t launch_epoch,
        int first_waypoint,
        tc2_dispatch_projection_page *page) {
        tc2_dispatch_request request;
        if (!page) return TC2_DISPATCH_PROJECTION_INVALID_ARGUMENT;
        util_zero_bytes(
                (volatile unsigned char *)page,
                (unsigned int)sizeof(*page));
        page->status = TC2_DISPATCH_PROJECTION_INTERNAL;
        clear_request(
                &request,
                TC2_DISPATCH_MSG_PROJECTION_PAGE);
        request.train = train;
        request.projection_serial = publication_serial;
        request.projection_generation = plan_generation;
        request.projection_launch_epoch = launch_epoch;
        request.projection_first_waypoint = first_waypoint;
        int ret = Send(
                tid, (const char *)&request, sizeof(request),
                (char *)page, sizeof(*page));
        if (ret != (int)sizeof(*page)) {
                util_zero_bytes(
                        (volatile unsigned char *)page,
                        (unsigned int)sizeof(*page));
                page->status =
                        TC2_DISPATCH_PROJECTION_INTERNAL;
                return TC2_DISPATCH_PROJECTION_INTERNAL;
        }
        return page->status;
}

int Tc2DispatchDemoSwitchBatch(
        int tid, const int *switches, const char *directions, int count) {
        tc2_dispatch_request request;
        if (!switches || !directions || count < 1 || count > 4) {
                return -1;
        }
        clear_request(&request, TC2_DISPATCH_MSG_DEMO_TURNOUT_BATCH);
        request.train = count;
        request.start_index = switches[0];
        request.speed = count > 1 ? switches[1] : 0;
        request.destination_index = count > 2 ? switches[2] : 0;
        request.node_index = count > 3 ? switches[3] : 0;
        request.reserved =
                (uint32_t)(unsigned char)directions[0] |
                ((uint32_t)(count > 1 ?
                        (unsigned char)directions[1] : 0) << 8) |
                ((uint32_t)(count > 2 ?
                        (unsigned char)directions[2] : 0) << 16) |
                ((uint32_t)(count > 3 ?
                        (unsigned char)directions[3] : 0) << 24);
        return send_request(tid, &request);
}

static void copy_can_health(tc2_dispatch_job_snapshot *job,
                            const can_health_t *health) {
        job->can_tx_completed = health->tx_completed;
        job->can_tx_failed = health->tx_failed;
        job->can_tx_timeout = health->tx_timeout;
        job->can_rx_dropped = health->rx_dropped;
        job->can_rx_overflow = health->rx_overflow;
        job->can_turnout_changes = health->turnout_changes;
}

static int can_health_is_safe(
        int slot, int establish_baseline, int now) {
        can_health_t health;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        (void)establish_baseline;
        if (now < 0 ||
            CanGetHealth(dispatch_can_tid, &health) < 0) {
                return TC2_CAN_HEALTH_HARD_FAIL;
        }
        copy_can_health(job, &health);
        if (!health.hw_ready) {
                return TC2_CAN_HEALTH_HARD_FAIL;
        }
        /*
         * Confirmed dispatcher commands are consumed as matching responses
         * and do not increment this counter.  A change here is therefore an
         * out-of-band physical turnout mutation whose identity is unknown;
         * the global S/C table can no longer authorize motion.
         */
        if (health.turnout_changes !=
            dispatch_unexpected_turnout_changes) {
                return TC2_CAN_HEALTH_HARD_FAIL;
        }
        if (health.tx_notifier_heartbeat == 0 ||
            health.rx_notifier_heartbeat == 0) {
                return TC2_CAN_HEALTH_RETRY;
        }
        if (!dispatch_can_heartbeat_valid) {
                dispatch_can_heartbeat_valid = 1;
                dispatch_can_tx_heartbeat =
                        health.tx_notifier_heartbeat;
                dispatch_can_rx_heartbeat =
                        health.rx_notifier_heartbeat;
                dispatch_can_tx_heartbeat_tick = now;
                dispatch_can_rx_heartbeat_tick = now;
                return TC2_CAN_HEALTH_OK;
        }
        /*
         * CAN health counters are controller-wide lifetime totals.  They are
         * useful diagnostics, but a normal turnout change by another train
         * (or one old recovered error) is not a fault in this job.  Per-job
         * command safety is decided by the exact Can* return/batch status;
         * service liveness remains guarded by the two heartbeat deadlines.
         */
        if (health.tx_notifier_heartbeat !=
            dispatch_can_tx_heartbeat) {
                dispatch_can_tx_heartbeat =
                        health.tx_notifier_heartbeat;
                dispatch_can_tx_heartbeat_tick = now;
        }
        if (health.rx_notifier_heartbeat !=
            dispatch_can_rx_heartbeat) {
                dispatch_can_rx_heartbeat =
                        health.rx_notifier_heartbeat;
                dispatch_can_rx_heartbeat_tick = now;
        }
        if (dispatch_can_tx_heartbeat_tick < 0 ||
            dispatch_can_rx_heartbeat_tick < 0 ||
            tick_age(now, dispatch_can_tx_heartbeat_tick) >
                    TC2_SERVICE_HEARTBEAT_MAX_AGE ||
            tick_age(now, dispatch_can_rx_heartbeat_tick) >
                    TC2_SERVICE_HEARTBEAT_MAX_AGE) {
                return TC2_CAN_HEALTH_RETRY;
        }
        return TC2_CAN_HEALTH_OK;
}

static int sensor_health_is_safe(
        int slot, const train_sensor_snapshot_t *sensor,
        int establish_baseline, int now) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!sensor || now < 0 ||
            !sensor->sensor_server_registered ||
            !sensor->courier_created || !sensor->courier_ready) {
                dispatch_jobs[slot].sensor_health_fault =
                        TC2_SENSOR_HEALTH_SERVICE_UNAVAILABLE;
                return -1;
        }
        if (!service_heartbeat_is_fresh(
                    now, sensor->courier_last_heartbeat_tick)) {
                dispatch_jobs[slot].sensor_health_fault =
                        TC2_SENSOR_HEALTH_HEARTBEAT_STALE;
                return -1;
        }
        if (establish_baseline ||
            !runtime->sensor_health_baseline_valid) {
                runtime->sensor_receive_failure_baseline =
                        sensor->courier_receive_failure_count;
                runtime->sensor_time_failure_baseline =
                        sensor->time_failure_count;
                runtime->sensor_health_baseline_valid = 1;
                dispatch_jobs[slot].sensor_health_fault =
                        TC2_SENSOR_HEALTH_OK;
                return 0;
        }
        if (sensor->courier_receive_failure_count !=
                    runtime->sensor_receive_failure_baseline) {
                dispatch_jobs[slot].sensor_health_fault =
                        TC2_SENSOR_HEALTH_RECEIVE_FAILURE;
                return -1;
        }
        if (sensor->time_failure_count !=
                    runtime->sensor_time_failure_baseline) {
                dispatch_jobs[slot].sensor_health_fault =
                        TC2_SENSOR_HEALTH_TIME_FAILURE;
                return -1;
        }
        dispatch_jobs[slot].sensor_health_fault =
                TC2_SENSOR_HEALTH_OK;
        return 0;
}

static void fail_job(int slot, int reason) {
        /*
         * A failed control epoch must disappear from every UI reader before
         * any further state is exposed.  The physical reservation is
         * deliberately retained below until the normal cancel/remove
         * recovery completes.
         */
        invalidate_projection(slot);
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        /*
         * CURRENT replacement validation is transactional until the
         * reservation generation changes.  Its temporary job carries the
         * live hold's CAN tokens and conflict-zone ownership metadata;
         * canceling either here would be an external side effect that no
         * byte-for-byte rollback can undo.  Record only the candidate result.
         * process_pending_retargets() restores the authoritative live hold.
         */
        if (dispatch_retarget_candidate_pre_cas) {
                job->state = TC2_JOB_FAILED;
                job->stop_trigger = TC2_STOP_TRIGGER_FAILSAFE;
                job->failure_reason = reason;
                job->ready_at_tick = -1;
                job->braking_at_tick = -1;
                return;
        }
        int conflict_cleanup_status =
                discard_future_conflict_zone_work(slot);
        if (conflict_cleanup_status < 0) {
                dispatch_scheduler_healthy = 0;
        }
        if (job->state == TC2_JOB_LAUNCHING &&
            runtime->launch_batch_token != 0) {
                (void)CanCancelBatch(
                        dispatch_can_tid,
                        runtime->launch_batch_token);
        }
        if (runtime->turnout_batch_token != 0) {
                (void)CanCancelBatch(
                        dispatch_can_tid,
                        runtime->turnout_batch_token);
        }
        job->state = TC2_JOB_FAILED;
        job->stop_trigger = TC2_STOP_TRIGGER_FAILSAFE;
        job->failure_reason = reason;
        job->ready_at_tick = -1;
        job->braking_at_tick = -1;
        runtime->launch_batch_token = 0;
        runtime->turnout_batch_token = 0;
        runtime->turnout_queue_pending = 0;
        runtime->movement_plan_active = 0;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_FAILSAFE;
        if (conflict_cleanup_status == 0) {
                runtime->conflict_zone_batch_token = 0;
                runtime->conflict_zone_soft_batch_token = 0;
                runtime->conflict_zone_soft_batch_step = -1;
                runtime->conflict_zone_soft_action_index = 0;
                runtime->conflict_zone_soft_settle_at_tick = -1;
                runtime->conflict_zone_soft_prefetched_step = -1;
                runtime->conflict_zone_soft_confirmed_step = -1;
                runtime->conflict_zone_queue_pending = 0;
                runtime->conflict_zone_settle_at_tick = -1;
        }
        int train = job->train;
        int token = CanTrainEmergencyStopBatch(
                dispatch_can_tid, &train, 1);
        runtime->emergency_stop_token =
                token > 0 ? (unsigned int)token : 0;
        /*
         * Keep the retry flag raised until the CAN server reports that the
         * stop itself was acknowledged. Queue admission is not motion proof.
         */
        job->needs_stop_retry = 1;
}

static int build_route_slice(const track_route *source, int first, int last,
                             track_route *slice) {
        if (!source || !slice || first < 0 || last < first ||
            last >= source->node_count) {
                return -1;
        }
        slice->node_count = 0;
        slice->distance_mm = 0;
        slice->optimization_cost_mm = 0;
        slice->reversal_count = 0;
        for (int offset = first; offset <= last; ++offset) {
                if (slice->node_count >= TRACK_MAX) return -1;
                slice->nodes[slice->node_count++] = source->nodes[offset];
                if (offset < last &&
                    dispatch_track[source->nodes[offset]].reverse ==
                            &dispatch_track[source->nodes[offset + 1]]) {
                        ++slice->reversal_count;
                }
        }
        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, source, first, last,
                    &slice->distance_mm) < 0) {
                return -1;
        }
        slice->optimization_cost_mm = slice->distance_mm;
        return 0;
}

static int append_unique_node(track_route *route, int node) {
        if (!route || node < 0 || node >= TRACK_MAX) return -1;
        if (route_contains_node(route, node)) return 0;
        if (route->node_count >= TRACK_MAX) return -1;
        route->nodes[route->node_count++] = node;
        return 0;
}

static int append_route_nodes(track_route *destination,
                              const track_route *source) {
        if (!destination || !source ||
            source->node_count < 0 ||
            source->node_count > TRACK_MAX) {
                return -1;
        }
        for (int offset = 0; offset < source->node_count; ++offset) {
                if (append_unique_node(
                            destination,
                            source->nodes[offset]) < 0) {
                        return -1;
                }
        }
        return 0;
}

static int paired_turnout_mate(int switch_number) {
        switch (switch_number) {
        case 153: return 154;
        case 154: return 153;
        case 155: return 156;
        case 156: return 155;
        default: return 0;
        }
}

/*
 * The central crossing contains two distinct physical resources.  A train
 * body in SW153/SW154 protects that pair; a train body in SW155/SW156 protects
 * the other pair.  The actuators and their S/C settings remain independent.
 */
static int append_paired_turnout_resources(track_route *footprint) {
        unsigned char protect_153_154 = 0;
        unsigned char protect_155_156 = 0;
        if (!footprint) return -1;

        for (int offset = 0; offset < footprint->node_count; ++offset) {
                int node = footprint->nodes[offset];
                int number = dispatch_track[node].num;
                if (number == 153 || number == 154) protect_153_154 = 1;
                if (number == 155 || number == 156) protect_155_156 = 1;
        }
        if (!protect_153_154 && !protect_155_156) return 0;
        for (int node = 0; node < TRACK_MAX; ++node) {
                int number = dispatch_track[node].num;
                if ((protect_153_154 &&
                     (number == 153 || number == 154)) ||
                    (protect_155_156 &&
                     (number == 155 || number == 156))) {
                        if (append_unique_node(footprint, node) < 0) {
                                return -1;
                        }
                }
        }
        return 0;
}

static int append_forward_guard_reachable(track_route *footprint,
                                          int start_node,
                                          int guard_distance_mm) {
        int distance[TRACK_MAX];
        unsigned char visited[TRACK_MAX];
        for (int node = 0; node < TRACK_MAX; ++node) {
                distance[node] = 0x3fffffff;
                visited[node] = 0;
        }
        if (start_node < 0 || start_node >= TRACK_MAX ||
            guard_distance_mm < 0) {
                return -1;
        }
        distance[start_node] = 0;
        for (int step = 0; step < TRACK_MAX; ++step) {
                int current = -1;
                for (int node = 0; node < TRACK_MAX; ++node) {
                        if (!visited[node] &&
                            distance[node] != 0x3fffffff &&
                            (current < 0 ||
                             distance[node] < distance[current])) {
                                current = node;
                        }
                }
                if (current < 0) break;
                visited[current] = 1;
                if (append_unique_node(footprint, current) < 0) return -1;
                if (distance[current] >= guard_distance_mm) continue;
                int edge_count =
                        dispatch_track[current].type == NODE_BRANCH ? 2 :
                        (dispatch_track[current].type == NODE_EXIT ||
                         dispatch_track[current].type == NODE_NONE ? 0 : 1);
                for (int direction = 0;
                     direction < edge_count; ++direction) {
                        track_edge *edge =
                                &dispatch_track[current].edge[direction];
                        if (!edge->dest || edge->dist < 0) continue;
                        int next = (int)(edge->dest - dispatch_track);
                        if (next < 0 || next >= TRACK_MAX) return -1;
                        int candidate =
                                distance[current] + edge->dist;
                        if (candidate < distance[next]) {
                                distance[next] = candidate;
                        }
                }
        }
        return 0;
}

static int build_safety_footprint_for_route(
        const track_route *motion_route, int first_motion_offset,
        int anchor_offset, int destination_route_offset,
        int destination_offset_mm_value, int speed,
        track_route *footprint) {
        if (!motion_route || !footprint ||
            first_motion_offset < 0 ||
            destination_route_offset < first_motion_offset ||
            destination_route_offset >= motion_route->node_count ||
            anchor_offset < 0 ||
            anchor_offset > destination_route_offset ||
            destination_offset_mm_value < 0 ||
            Tc2MotionBrakingDistanceMm(speed) < 0) {
                return -1;
        }
        /*
         * A complete trip owns only the driven prefix through the endpoint
         * ceiling.  The route suffix after d1-d8 is monitor topology, not
         * movement authority and not a reservation guard.  Reserving that
         * suffix made B->d3 wait forever on an A->d5 train sitting at E5
         * (data 90/92).  Turnout correctness is enforced by next/nextnext
         * zone permission before entry; wrong branches must not be reserved
         * as a substitute for that verification.
         */
        if (build_route_slice(
                    motion_route, first_motion_offset,
                    destination_route_offset, footprint) < 0) {
                return -1;
        }
        if (append_paired_turnout_resources(footprint) < 0) {
                return -1;
        }
        footprint->distance_mm = motion_route->distance_mm;
        footprint->optimization_cost_mm =
                motion_route->optimization_cost_mm;
        return 0;
}

/*
 * A rolling authority is deliberately node-granular.  It owns one contiguous
 * route slice, both physical directions of those nodes (in the reservation
 * server), and paired 153-156 interlock resources.  Wrong branches are not
 * part of movement authority: including both branches turns one local
 * turnout into a distant route-wide lock and prevents another train from
 * safely approaching its own 20 mm gate.  The conflict-zone arbiter owns and
 * settles the selected physical turnout before this exact route slice can be
 * promoted.
 */
static int build_rolling_authority_footprint(
        const track_route *motion_route,
        int first_motion_offset, int last_motion_offset,
        int speed, track_route *footprint) {
        if (!motion_route || !footprint ||
            first_motion_offset < 0 ||
            last_motion_offset < first_motion_offset ||
            last_motion_offset >= motion_route->node_count ||
            build_route_slice(
                    motion_route, first_motion_offset,
                    last_motion_offset, footprint) < 0) {
                return -1;
        }
        if (Tc2MotionBrakingDistanceMm(speed) < 0) return -1;
        if (append_paired_turnout_resources(footprint) < 0) {
                return -1;
        }
        footprint->distance_mm = motion_route->distance_mm;
        footprint->optimization_cost_mm =
                motion_route->optimization_cost_mm;
        return 0;
}

/*
 * Rebuild one local rolling-authority window exactly as it was selected.
 * A window ending at an in-route reversal sensor needs a larger forward
 * overrun guard: the train must stop, keep its complete body plus the delayed
 * 200 mm release margin clear, and only then perform the stopped handoff.
 * This helper is used both at selection and after every sensor/tail rebase so
 * that a footprint can never silently shrink at a reversal boundary.
 */
static int build_local_authority_footprint(
        const track_route *motion_route,
        int first_motion_offset, int last_motion_offset,
        int motion_leg_start_offset,
        int destination_route_offset, int speed,
        track_route *footprint) {
        if (!motion_route || !footprint ||
            motion_leg_start_offset < 0 ||
            motion_leg_start_offset >= motion_route->node_count ||
            destination_route_offset < motion_leg_start_offset ||
            destination_route_offset >= motion_route->node_count ||
            build_rolling_authority_footprint(
                    motion_route, first_motion_offset,
                    last_motion_offset, speed,
                    footprint) < 0) {
                return -1;
        }
        int motion_leg_end =
                TrackRouteMotionLegEnd(
                        dispatch_track, motion_route,
                        motion_leg_start_offset);
        if (motion_leg_end < motion_leg_start_offset ||
            motion_leg_end >= motion_route->node_count) {
                return -1;
        }
        if (last_motion_offset == motion_leg_end &&
            motion_leg_end < destination_route_offset) {
                int guard =
                        Tc2MotionBrakingDistanceMm(speed);
                if (guard < 0 ||
                    guard > 0x7fffffff -
                                    TC2_TRAIN_HALF_LENGTH_MM ||
                    guard + TC2_TRAIN_HALF_LENGTH_MM >
                                    0x7fffffff -
                                    TC2_INTERSECTION_RELEASE_MARGIN_MM) {
                        return -1;
                }
                guard +=
                        TC2_TRAIN_HALF_LENGTH_MM +
                        TC2_INTERSECTION_RELEASE_MARGIN_MM;
                if (append_forward_guard_reachable(
                            footprint,
                            motion_route->nodes[motion_leg_end],
                            guard) < 0 ||
                    append_paired_turnout_resources(
                            footprint) < 0) {
                        return -1;
                }
        }
        footprint->distance_mm =
                motion_route->distance_mm;
        footprint->optimization_cost_mm =
                motion_route->optimization_cost_mm;
        return 0;
}

static int authority_footprint_available(
        const track_route *footprint, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_reservation_conflict *conflict) {
        if (!footprint || !reservation || !sensors ||
            train < 1 || train > 255) {
                return -1;
        }
        if (conflict) {
                conflict->node_index = -1;
                conflict->owner_train = 0;
        }
        for (int offset = 0;
             offset < footprint->node_count; ++offset) {
                int node = footprint->nodes[offset];
                int physical[2] = {
                        node, physical_reverse_index(node)
                };
                for (int side = 0; side < 2; ++side) {
                        int candidate = physical[side];
                        if (candidate < 0 ||
                            candidate >= TRACK_MAX) {
                                continue;
                        }
                        int owner =
                                reservation
                                        ->owner_by_node[candidate];
                        if (owner != 0 && owner != train) {
                                if (conflict) {
                                        conflict->node_index =
                                                candidate;
                                        conflict->owner_train =
                                                owner;
                                }
                                return 1;
                        }
                        if (candidate <
                                    TRAIN_SENSOR_COUNT &&
                            sensors->sensor_state[candidate] &&
                            owner != train) {
                                if (conflict) {
                                        conflict->node_index =
                                                candidate;
                                        conflict->owner_train =
                                                owner;
                                }
                                return 1;
                        }
                }
        }
        return 0;
}

static int route_distance_to_offset(
        const track_route *route, int offset,
        int *distance_mm) {
        if (!route || !distance_mm || offset < 0 ||
            offset >= route->node_count) {
                return -1;
        }
        if (offset == 0) {
                *distance_mm = 0;
                return 0;
        }
        return TrackRouteDistanceBetweenOffsets(
                dispatch_track, route, 0, offset,
                distance_mm);
}

static int footprint_tail_offset_for_anchor(
        const track_route *route, int current,
        int speed) {
        if (!route || route->node_count < 1 ||
            speed < 1 || speed > 120) {
                return -1;
        }
        if (current < 0) current = 0;
        if (current >= route->node_count) return -1;
        /*
         * A detector localizes the pickup at the end of its incoming edge.
         * Even when that edge is longer than the numeric release margin, the
         * train body can still straddle it at the instant of the report.
         * Retain the immediately preceding route node unconditionally, then
         * extend farther back by the body-plus-delay distance.
         */
        int tail = current > 0 ? current - 1 : current;
        int release_margin =
                Tc2MotionUncertaintyMm(speed);
        if (release_margin < 0) return -1;
        if (release_margin <
            TC2_INTERSECTION_RELEASE_MARGIN_MM) {
                release_margin =
                        TC2_INTERSECTION_RELEASE_MARGIN_MM;
        }
        int protected_behind =
                TC2_TRAIN_HALF_LENGTH_MM +
                release_margin;
        while (tail > 0) {
                int distance;
                if (TrackRouteDistanceBetweenOffsets(
                            dispatch_track, route,
                            tail - 1, current, &distance) < 0 ||
                    distance > protected_behind) {
                        break;
                }
                --tail;
        }
        return tail;
}

/*
 * A HEAD_ON CURRENT replacement cannot release its inherited corridor from a
 * continuously predicted position.  update_remaining_footprint() releases it
 * only after an ordered sensor observation advances reservation_anchor_offset
 * far enough that footprint_tail_offset() places the complete train plus the
 * delayed 200 mm margin beyond the new route origin.
 *
 * During inherited CURRENT/reversal ambiguity,
 * reservation_anchor_offset deliberately trails ordered detector evidence by
 * one observation.  Ordinary trips use their latest exact ordered detector.
 * The first recovery event therefore still retains the old origin.  When the
 * immediately following event arrives, the first downstream sensor becomes
 * the corroborated reservation anchor.  That anchor must put the computed
 * tail past the origin, while the train's physical position at the second
 * event must still leave a complete conservative stop inside the same active
 * authority ceiling.
 */
static int head_on_recovery_window_has_release_witness(
        const track_route *route, int origin_offset,
        int authority_end_offset,
        int authority_center_ceiling_mm, int speed) {
        if (!route || origin_offset < 0 ||
            origin_offset >= route->node_count ||
            authority_end_offset <= origin_offset ||
            authority_end_offset >= route->node_count ||
            authority_center_ceiling_mm < 0 ||
            speed < 1 || speed > 120) {
                return 0;
        }
        int braking = Tc2MotionBrakingDistanceMm(speed);
        if (braking < 0) return 0;

        int first_sensor = -1;
        for (int anchor = origin_offset + 1;
             anchor <= authority_end_offset; ++anchor) {
                int anchor_node = route->nodes[anchor];
                if (dispatch_track[anchor_node].type !=
                            NODE_SENSOR) {
                        continue;
                }
                int tail =
                        footprint_tail_offset_for_anchor(
                                route, anchor, speed);
                if (tail < 0) return 0;
                if (first_sensor < 0) {
                        /*
                         * This anchor is applied only when the next ordered
                         * sensor event corroborates it.  It must then prove
                         * that the complete delayed-release footprint is
                         * beyond the inherited CURRENT origin.
                         */
                        if (tail <= origin_offset) return 0;
                        first_sensor = anchor;
                        continue;
                }
                int second_event_distance;
                if (route_distance_to_offset(
                            route, anchor,
                            &second_event_distance) < 0) {
                        return 0;
                }
                if (second_event_distance <=
                            authority_center_ceiling_mm &&
                    authority_center_ceiling_mm -
                                    second_event_distance >=
                                    braking) {
                        return 1;
                }
                return 0;
        }
        return 0;
}

static int authority_prefetch_lead_mm(int speed) {
        int fast_tenths =
                Tc2MotionFastVelocityTenthsMmPerTick(
                        speed);
        int latency_ticks =
                TC2_TURNOUT_SETTLE_TICKS +
                TC2_AUTHORITY_CAN_BUDGET_TICKS;
        if (fast_tenths < 0 ||
            fast_tenths >
                    (0x7fffffff - 9) /
                            latency_ticks) {
                return -1;
        }
        /*
         * The authority ceiling already stays one half train plus 200 mm
         * behind the last owned node.  Add only the distance travelled while
         * CAN confirmation and mechanical turnout settling are pending; adding
         * another 200 mm here would count the following clearance twice.
         */
        return (fast_tenths * latency_ticks + 9) / 10;
}

/*
 * Select the shortest currently conflict-free movement-authority window that
 * can contain one complete conservative stop.  Reserving the longest prefix
 * (or the complete remaining route) makes a distant merge exclusive long
 * before the train can reach it and prevents a safe same-direction follower
 * from using its own later physical next-authority window.
 *
 * A partial window leaves its center-line ceiling one train half-length plus
 * 200 mm before the last owned route node.  Only when the physical destination
 * itself is the first reachable safe boundary do we install the complete
 * endpoint/braking guard.
 */
static int select_rolling_authority_window_for_leg(
        const track_route *route, int first_motion_offset,
        int motion_leg_start_offset,
        int minimum_end_offset, int target_offset,
        int destination_route_offset,
        int destination_offset_mm_value,
        int destination_distance_mm, int speed,
        int current_progress_mm, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_route *selected, int *selected_end_offset,
        int *selected_center_ceiling_mm,
        track_reservation_conflict *conflict) {
        if (!route || !selected || !selected_end_offset ||
            !selected_center_ceiling_mm || !reservation ||
            !sensors || route->node_count < 2 ||
            first_motion_offset < 0 ||
            motion_leg_start_offset < 0 ||
            motion_leg_start_offset >= route->node_count ||
            minimum_end_offset < first_motion_offset ||
            target_offset < 0 ||
            destination_route_offset < target_offset ||
            destination_route_offset >= route->node_count ||
            destination_distance_mm < 0 ||
            current_progress_mm < 0) {
                return -1;
        }
        int braking_envelope =
                Tc2MotionBrakingDistanceMm(speed);
        int measured_stop =
                Tc2MotionStopDistanceMm(speed);
        if (braking_envelope < 0 || measured_stop < 0) {
                return -1;
        }
        /*
         * A granted window only has to contain one complete conservative stop.
         * CAN/turnout latency controls how early the running prefetch starts;
         * charging that distance again here can reject an otherwise safe local
         * prefix and unnecessarily leave the train at its origin.
         */
        int partial_headroom = braking_envelope;
        track_reservation_conflict first_conflict;
        first_conflict.node_index = -1;
        first_conflict.owner_train = 0;

        int motion_leg_end =
                TrackRouteMotionLegEnd(
                        dispatch_track, route,
                        motion_leg_start_offset);
        if (motion_leg_end < motion_leg_start_offset ||
            motion_leg_end >= route->node_count) {
                return -1;
        }
        int final_motion_leg =
                motion_leg_end >= destination_route_offset;
        int full_end = final_motion_leg ?
                destination_route_offset : motion_leg_end;
        /*
         * Every newly granted window, including the initial fixed departure,
         * must let the train reach one real detector before the conservative
         * braking trigger is reached.  Merely owning that detector node is not
         * enough: the runtime stops when progress + braking_envelope reaches
         * the centre-line ceiling.  A ceiling at the detector therefore stops
         * one whole braking envelope too early and leaves the route cursor
         * permanently without a new observation (data 888/8882).
         */
        int first_new_sensor_offset = -1;
        int first_new_sensor_distance = -1;
        int sensor_search_offset = first_motion_offset;
        int confirmed_sensor = -1;
        if (train >= 0 &&
            train < (int)(sizeof(sensors->position_by_train) /
                          sizeof(sensors->position_by_train[0]))) {
                confirmed_sensor = sensors->position_by_train[train];
        }
        int require_sensor_center_reach = 1;
        if (confirmed_sensor >= 0 && confirmed_sensor < TRACK_MAX) {
                int confirmed_route_offset = -1;
                int confirmed_route_distance = -1;
                /*
                 * A route may revisit the same detector.  Select the latest
                 * occurrence which the monotonic motion model has not yet
                 * ruled out; the sensor observation, rather than a projected
                 * prefetch origin, remains the localization authority.
                 */
                for (int offset = first_motion_offset;
                     offset <= full_end; ++offset) {
                        if (route->nodes[offset] != confirmed_sensor) {
                                continue;
                        }
                        int distance = -1;
                        if (route_distance_to_offset(
                                    route, offset, &distance) < 0) {
                                return -1;
                        }
                        if (distance <= current_progress_mm &&
                            distance >= confirmed_route_distance) {
                                confirmed_route_offset = offset;
                                confirmed_route_distance = distance;
                        }
                }
                if (confirmed_route_offset < 0) {
                        for (int offset = first_motion_offset;
                             offset <= full_end; ++offset) {
                                if (route->nodes[offset] ==
                                            confirmed_sensor) {
                                        confirmed_route_offset = offset;
                                        break;
                                }
                        }
                }
                if (confirmed_route_offset >= 0) {
                        sensor_search_offset =
                                confirmed_route_offset + 1;
                }
        } else if (first_motion_offset != motion_leg_start_offset) {
                /*
                 * A moving extension should normally have a persisted real
                 * detector.  If it does not, do not let a tail node behind
                 * the model cursor satisfy the witness requirement.
                 */
                for (int offset = first_motion_offset;
                     offset <= full_end; ++offset) {
                        int distance = -1;
                        if (dispatch_track[route->nodes[offset]].type !=
                                    NODE_SENSOR) {
                                continue;
                        }
                        if (route_distance_to_offset(
                                    route, offset, &distance) < 0) {
                                return -1;
                        }
                        if (distance > current_progress_mm) {
                                sensor_search_offset = offset;
                                break;
                        }
                }
        }
        for (int offset = sensor_search_offset;
             offset <= full_end; ++offset) {
                if (dispatch_track[route->nodes[offset]].type ==
                            NODE_SENSOR) {
                        first_new_sensor_offset = offset;
                        if (route_distance_to_offset(
                                    route, offset,
                                    &first_new_sensor_distance) < 0) {
                                return -1;
                        }
                        break;
                }
        }
        track_route candidate;
        int boundary_margin =
                (TC2_TRAIN_BODY_MM + 1) / 2 +
                TC2_INTERSECTION_RELEASE_MARGIN_MM;
        for (int end = minimum_end_offset;
             end <= full_end; ++end) {
                if (require_sensor_center_reach &&
                    first_new_sensor_offset >= 0 &&
                    end < first_new_sensor_offset) {
                        continue;
                }
                /*
                 * Nodes after the physical destination are braking/wrong-turn
                 * guards, not another movement block.  Once a window reaches
                 * the endpoint, select the complete destination footprint and
                 * its exact center stop; never authorize the train center to a
                 * synthetic ceiling beyond d1-d8.
                 */
                if (end >= destination_route_offset &&
                    end != full_end) {
                        continue;
                }
                int complete =
                        final_motion_leg &&
                        end == full_end;
                int reversal_terminal =
                        !final_motion_leg &&
                        end == full_end;
                int ceiling;
                int footprint_end = end;
                if (complete) {
                        ceiling = destination_distance_mm;
                        int zero_motion =
                                ceiling == current_progress_mm;
                        if (ceiling < current_progress_mm ||
                            (!zero_motion &&
                             ceiling - current_progress_mm <
                                     measured_stop) ||
                            build_safety_footprint_for_route(
                                    route, first_motion_offset,
                                    target_offset,
                                    destination_route_offset,
                                    destination_offset_mm_value,
                                    speed, &candidate) < 0) {
                                continue;
                        }
                } else if (reversal_terminal) {
                        int end_distance;
                        if (route_distance_to_offset(
                                    route, end,
                                    &end_distance) < 0) {
                                return -1;
                        }
                        ceiling = end_distance;
                        if (ceiling < current_progress_mm ||
                            ceiling - current_progress_mm <
                                    measured_stop ||
                            build_local_authority_footprint(
                                    route,
                                    first_motion_offset,
                                    end,
                                    motion_leg_start_offset,
                                    destination_route_offset,
                                    speed, &candidate) < 0) {
                                continue;
                        }
                } else {
                        int end_distance;
                        if (route_distance_to_offset(
                                    route, end,
                                    &end_distance) < 0 ||
                            end_distance < boundary_margin) {
                                continue;
                        }
                        ceiling =
                                end_distance - boundary_margin;
                        if (ceiling < current_progress_mm ||
                            ceiling - current_progress_mm <
                                    partial_headroom) {
                                continue;
                        }
                        /*
                         * Leave a complete braking envelope after the next
                         * detector.  The runtime braking predicate subtracts
                         * this same envelope from the ceiling, so this is the
                         * minimum window which can actually produce that
                         * detector observation before speed zero is issued.
                         * The footprint still owns the full body/release
                         * margin beyond the selected boundary.
                         */
                        if (require_sensor_center_reach &&
                            first_new_sensor_offset >= 0 &&
                            first_new_sensor_distance >= 0 &&
                            (ceiling < first_new_sensor_distance ||
                             ceiling - first_new_sensor_distance <
                                     braking_envelope)) {
                                continue;
                        }
                        /*
                         * Keep one real detector beyond the selected center
                         * ceiling as an attribution-only braking witness.
                         * The center ceiling remains derived from `end`, so
                         * this does not authorize the train to roll another
                         * section or cross a later turnout.  It only prevents
                         * the physical coast after a zero issued at E10 from
                         * making E13 ownerless (data 98).
                         *
                         * Do not turn the destination itself into a guard:
                         * reaching destination authority changes the stop
                         * controller and must be selected by the complete
                         * branch above with its exact endpoint ceiling.
                         */
                        for (int guard = end + 1;
                             guard < destination_route_offset &&
                             guard <= full_end;
                             ++guard) {
                                int guard_type = dispatch_track[
                                            route->nodes[guard]].type;
                                if (guard_type == NODE_SENSOR) {
                                        int guard_distance = -1;
                                        if (route_distance_to_offset(
                                                    route, guard,
                                                    &guard_distance) < 0) {
                                                return -1;
                                        }
                                        /*
                                         * Guard only a detector which the
                                         * already-commanded train could
                                         * physically coast into after zero.
                                         * A remote detector must belong to a
                                         * later authority window; extending
                                         * through intervening conflicts just
                                         * for attribution would turn a safe
                                         * local prefix into a route-wide lock.
                                         */
                                        if (guard_distance <= ceiling +
                                                            measured_stop) {
                                                footprint_end = guard;
                                        }
                                        break;
                                }
                        }
                        if (build_local_authority_footprint(
                                    route, first_motion_offset,
                                    footprint_end,
                                    motion_leg_start_offset,
                                    destination_route_offset,
                                    speed,
                                    &candidate) < 0) {
                                return -1;
                        }
                }
                track_reservation_conflict candidate_conflict;
                int available =
                        authority_footprint_available(
                                &candidate, train,
                                reservation, sensors,
                                &candidate_conflict);
                if (available < 0) return -1;
                if (available != 0) {
                        if (first_conflict.node_index < 0) {
                                first_conflict =
                                        candidate_conflict;
                                /*
                                 * Publish the exact blocked local request for
                                 * resource-scoped FIFO.  The caller must not
                                 * treat it as granted, but an older waiter can
                                 * now arbitrate this block without consulting
                                 * either train's distant destination route.
                                 */
                                *selected = candidate;
                                *selected_end_offset = footprint_end;
                                *selected_center_ceiling_mm =
                                        ceiling;
                        }
                        /*
                         * Every farther window contains this same route
                         * prefix.  Continuing could only grow the monopoly;
                         * wait for the conflicting owner to release it.
                         */
                        break;
                }
                *selected = candidate;
                *selected_end_offset = footprint_end;
                *selected_center_ceiling_mm = ceiling;
                if (conflict) {
                        conflict->node_index = -1;
                        conflict->owner_train = 0;
                }
                return 0;
        }
        if (conflict) *conflict = first_conflict;
        return 1;
}

/*
 * Prefer one bounded local authority at the highest usable speed.
 *
 * A complete destination footprint is local only when the physical
 * destination is already inside the next requested block.  Otherwise a full
 * result would reserve every remaining intersection merely because the
 * requested stopping envelope does not fit an earlier boundary.  Retry at
 * lower speeds first.  Never synthesize a speed below the smallest physical
 * command which this layout can actually move: data303 showed that a speed-2
 * authority window advances only the software model while the locomotive
 * remains in the hardware deadzone.  If no physically usable bounded prefix
 * exists, a conflict-free complete remainder is the only movement window from
 * which the train can still stop safely.  Keep that requested-speed candidate
 * as the final fallback instead of leaving a single survivor permanently
 * stopped at its old ceiling.
 *
 * A blocked bounded candidate is retained for resource-scoped FIFO.  A blocked
 * remote complete candidate is deliberately discarded because it is not a
 * local resource request.  A free complete candidate at the immutable
 * requested speed is retained only as the last resort, after every bounded
 * local/lower-speed candidate has been tried.  Initial departure admission is
 * still governed separately by the first hard `next` physical zone; this
 * fallback only prevents a later rolling hold from waiting forever when no
 * intermediate safe stopping boundary exists.
 */
static int select_bounded_rolling_authority_window_for_leg(
        const track_route *route, int first_motion_offset,
        int motion_leg_start_offset, int minimum_end_offset,
        int target_offset, int destination_route_offset,
        int destination_offset_mm_value,
        int destination_distance_mm, int requested_speed,
        int allow_partial_speed_fallback,
        int current_progress_mm, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_route *selected, int *selected_end_offset,
        int *selected_center_ceiling_mm, int *selected_speed,
        track_reservation_conflict *conflict) {
        if (!route || !selected || !selected_end_offset ||
            !selected_center_ceiling_mm || !selected_speed ||
            !reservation || !sensors ||
            (allow_partial_speed_fallback != 0 &&
             allow_partial_speed_fallback != 1) ||
            requested_speed < 1 || requested_speed > 120) {
                return -1;
        }

        selected->node_count = 0;
        selected->distance_mm = 0;
        selected->optimization_cost_mm = 0;
        selected->reversal_count = 0;
        *selected_end_offset = -1;
        *selected_center_ceiling_mm = -1;
        *selected_speed = -1;
        if (conflict) {
                conflict->node_index = -1;
                conflict->owner_train = 0;
        }

        track_route blocked;
        blocked.node_count = 0;
        blocked.distance_mm = 0;
        blocked.optimization_cost_mm = 0;
        blocked.reversal_count = 0;
        int blocked_end = -1;
        int blocked_ceiling = -1;
        int blocked_speed = -1;
        track_reservation_conflict blocked_conflict;
        blocked_conflict.node_index = -1;
        blocked_conflict.owner_train = 0;

        track_route requested_complete;
        requested_complete.node_count = 0;
        requested_complete.distance_mm = 0;
        requested_complete.optimization_cost_mm = 0;
        requested_complete.reversal_count = 0;
        int requested_complete_end = -1;
        int requested_complete_ceiling = -1;

        int minimum_end_distance = -1;
        int local_destination_limit = -1;
        int boundary_margin =
                (TC2_TRAIN_BODY_MM + 1) / 2 +
                TC2_INTERSECTION_RELEASE_MARGIN_MM;
        if (route_distance_to_offset(
                    route, minimum_end_offset,
                    &minimum_end_distance) < 0 ||
            minimum_end_distance >
                    0x7fffffff - boundary_margin) {
                return -1;
        }
        local_destination_limit =
                minimum_end_distance + boundary_margin;
        int destination_is_local =
                destination_distance_mm <=
                        local_destination_limit;

        int minimum_usable_speed =
                requested_speed < TC2_ROLLING_AUTHORITY_MIN_SPEED ?
                requested_speed : TC2_ROLLING_AUTHORITY_MIN_SPEED;
        for (int speed = requested_speed;
             speed >= minimum_usable_speed; --speed) {
                track_route candidate;
                candidate.node_count = 0;
                candidate.distance_mm = 0;
                candidate.optimization_cost_mm = 0;
                candidate.reversal_count = 0;
                int candidate_end = -1;
                int candidate_ceiling = -1;
                track_reservation_conflict candidate_conflict;
                candidate_conflict.node_index = -1;
                candidate_conflict.owner_train = 0;
                int status =
                        select_rolling_authority_window_for_leg(
                                route, first_motion_offset,
                                motion_leg_start_offset,
                                minimum_end_offset, target_offset,
                                destination_route_offset,
                                destination_offset_mm_value,
                                destination_distance_mm, speed,
                                current_progress_mm, train,
                                reservation, sensors, &candidate,
                                &candidate_end, &candidate_ceiling,
                                &candidate_conflict);
                if (status < 0) return -1;

                int remote_complete =
                        candidate.node_count > 0 &&
                        candidate_end == destination_route_offset &&
                        !destination_is_local;
                int terminal_precision_partial =
                        candidate_end >= target_offset;
                int forbidden_lower_speed_partial =
                        !allow_partial_speed_fallback &&
                        speed < requested_speed &&
                        candidate_end < destination_route_offset &&
                        !terminal_precision_partial;
                if (speed == requested_speed &&
                    status == 0 && remote_complete) {
                        requested_complete = candidate;
                        requested_complete_end = candidate_end;
                        requested_complete_ceiling =
                                candidate_ceiling;
                }
                if (status == 0 && !remote_complete &&
                    !forbidden_lower_speed_partial) {
                        *selected = candidate;
                        *selected_end_offset = candidate_end;
                        *selected_center_ceiling_mm =
                                candidate_ceiling;
                        *selected_speed = speed;
                        if (conflict) *conflict = candidate_conflict;
                        return 0;
                }
                if (status > 0 && candidate.node_count > 0 &&
                    !remote_complete &&
                    !forbidden_lower_speed_partial) {
                        /*
                         * Lower speeds can expose a shorter free prefix, so
                         * retain this exact local conflict but keep searching.
                         * The last retained request is the shortest one.
                         */
                        blocked = candidate;
                        blocked_end = candidate_end;
                        blocked_ceiling = candidate_ceiling;
                        blocked_speed = speed;
                        blocked_conflict = candidate_conflict;
                }
        }

        if (requested_complete.node_count > 0) {
                *selected = requested_complete;
                *selected_end_offset = requested_complete_end;
                *selected_center_ceiling_mm =
                        requested_complete_ceiling;
                *selected_speed = requested_speed;
                if (conflict) {
                        conflict->node_index = -1;
                        conflict->owner_train = 0;
                }
                return 0;
        }

        if (blocked.node_count > 0) {
                *selected = blocked;
                *selected_end_offset = blocked_end;
                *selected_center_ceiling_mm = blocked_ceiling;
                *selected_speed = blocked_speed;
                if (conflict) *conflict = blocked_conflict;
        }
        return 1;
}

/*
 * Admit one fixed-start train under exactly its first hard physical zone.
 *
 * The conflict-zone ticket, not a route-wide braking footprint, is the
 * movement permission for this first `next` traversal.  In particular, a
 * later train approaching SW4 must not reserve (or be downshifted merely to
 * avoid reserving) SW12 while SW12 is still only its `nextnext` preparation
 * step.  Once the train clears this step, the ordinary running prefetch makes
 * the following step hard and either extends the node reservation or stops at
 * that new gate.
 */
static int select_initial_next_zone_window(
        const track_route *route,
        const tc2_conflict_zone_route_plan *zone_plan,
        int first_motion_offset, int motion_leg_start_offset,
        int minimum_end_offset, int destination_route_offset,
        int speed, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_route *selected, int *selected_end_offset,
        int *selected_center_ceiling_mm,
        track_reservation_conflict *conflict) {
        if (!route || !zone_plan || !reservation || !sensors ||
            !selected || !selected_end_offset ||
            !selected_center_ceiling_mm ||
            zone_plan->step_count < 1 ||
            first_motion_offset < 0 ||
            motion_leg_start_offset < 0 ||
            minimum_end_offset < first_motion_offset ||
            destination_route_offset < minimum_end_offset ||
            destination_route_offset >= route->node_count ||
            speed < 1 || speed > 120) {
                return -1;
        }

        const tc2_conflict_zone_route_step *next =
                &zone_plan->steps[0];
        int end = next->last_route_offset;
        if (next->first_route_offset < first_motion_offset ||
            end < minimum_end_offset ||
            end > destination_route_offset ||
            end >= route->node_count) {
                return 2;
        }

        if (build_local_authority_footprint(
                    route, first_motion_offset, end,
                    motion_leg_start_offset,
                    destination_route_offset, speed,
                    selected) < 0) {
                return -1;
        }
        int available = authority_footprint_available(
                selected, train, reservation, sensors, conflict);
        if (available != 0) return available < 0 ? -1 : 1;

        int end_distance = -1;
        int boundary_margin =
                (TC2_TRAIN_BODY_MM + 1) / 2 +
                TC2_INTERSECTION_RELEASE_MARGIN_MM;
        if (route_distance_to_offset(route, end, &end_distance) < 0 ||
            end_distance < 0) {
                return -1;
        }
        *selected_end_offset = end;
        *selected_center_ceiling_mm =
                end_distance > boundary_margin ?
                end_distance - boundary_margin : 0;
        if (conflict) {
                conflict->node_index = -1;
                conflict->owner_train = 0;
        }
        return 0;
}

/*
 * Select the first HEAD_ON CURRENT recovery window.
 *
 * The ordinary bounded selector deliberately returns the shortest stoppable
 * prefix.  That is insufficient for a recovery if the prefix ends before
 * ordered detector evidence can retire the inherited CURRENT footprint.  Keep
 * extending the local candidate at a given speed until it contains the
 * two-sensor release witness described above; if necessary retry at a lower
 * speed.  A remote complete candidate remains forbidden exactly as in the
 * ordinary bounded selector.
 */
static int select_head_on_recovery_initial_authority(
        const track_route *route, int first_motion_offset,
        int minimum_end_offset, int target_offset,
        int destination_route_offset,
        int destination_offset_mm_value,
        int destination_distance_mm, int requested_speed,
        int allow_partial_speed_fallback,
        int current_progress_mm, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_route *selected, int *selected_end_offset,
        int *selected_center_ceiling_mm, int *selected_speed,
        track_reservation_conflict *conflict) {
        if (!route || !selected || !selected_end_offset ||
            !selected_center_ceiling_mm || !selected_speed ||
            !reservation || !sensors ||
            first_motion_offset < 0 ||
            minimum_end_offset < first_motion_offset ||
            minimum_end_offset >= route->node_count ||
            (allow_partial_speed_fallback != 0 &&
             allow_partial_speed_fallback != 1) ||
            requested_speed < 1 || requested_speed > 120) {
                return -1;
        }
        selected->node_count = 0;
        selected->distance_mm = 0;
        selected->optimization_cost_mm = 0;
        selected->reversal_count = 0;
        *selected_end_offset = -1;
        *selected_center_ceiling_mm = -1;
        *selected_speed = -1;
        if (conflict) {
                conflict->node_index = -1;
                conflict->owner_train = 0;
        }

        int minimum_end_distance;
        int boundary_margin =
                (TC2_TRAIN_BODY_MM + 1) / 2 +
                TC2_INTERSECTION_RELEASE_MARGIN_MM;
        if (route_distance_to_offset(
                    route, minimum_end_offset,
                    &minimum_end_distance) < 0 ||
            minimum_end_distance >
                    0x7fffffff - boundary_margin) {
                return -1;
        }
        int destination_is_local =
                destination_distance_mm <=
                        minimum_end_distance +
                                boundary_margin;

        track_route blocked = {0};
        int blocked_end = -1;
        int blocked_ceiling = -1;
        int blocked_speed = -1;
        track_reservation_conflict blocked_conflict;
        blocked_conflict.node_index = -1;
        blocked_conflict.owner_train = 0;

        track_route requested_complete = {0};
        int requested_complete_end = -1;
        int requested_complete_ceiling = -1;

        for (int speed = requested_speed; speed >= 1; --speed) {
                int candidate_minimum_end =
                        minimum_end_offset;
                while (candidate_minimum_end <
                       route->node_count) {
                        track_route candidate = {0};
                        int candidate_end = -1;
                        int candidate_ceiling = -1;
                        track_reservation_conflict
                                candidate_conflict;
                        candidate_conflict.node_index = -1;
                        candidate_conflict.owner_train = 0;
                        int status =
                                select_rolling_authority_window_for_leg(
                                        route,
                                        first_motion_offset,
                                        first_motion_offset,
                                        candidate_minimum_end,
                                        target_offset,
                                        destination_route_offset,
                                        destination_offset_mm_value,
                                        destination_distance_mm,
                                        speed,
                                        current_progress_mm,
                                        train, reservation, sensors,
                                        &candidate,
                                        &candidate_end,
                                        &candidate_ceiling,
                                        &candidate_conflict);
                        if (status < 0) return -1;
                        if (candidate.node_count < 1 ||
                            candidate_end <
                                    candidate_minimum_end) {
                                break;
                        }

                        int remote_complete =
                                candidate_end ==
                                        destination_route_offset &&
                                !destination_is_local;
                        int terminal_precision_partial =
                                candidate_end >= target_offset;
                        int forbidden_lower_speed_partial =
                                !allow_partial_speed_fallback &&
                                speed < requested_speed &&
                                candidate_end <
                                        destination_route_offset &&
                                !terminal_precision_partial;
                        int has_release_witness =
                                head_on_recovery_window_has_release_witness(
                                        route,
                                        first_motion_offset,
                                        candidate_end,
                                        candidate_ceiling,
                                        speed);
                        if (!allow_partial_speed_fallback &&
                            speed == requested_speed &&
                            status == 0 && remote_complete &&
                            has_release_witness) {
                                requested_complete = candidate;
                                requested_complete_end =
                                        candidate_end;
                                requested_complete_ceiling =
                                        candidate_ceiling;
                        }
                        if (has_release_witness &&
                            !remote_complete) {
                                if (status == 0 &&
                                    !forbidden_lower_speed_partial) {
                                        *selected = candidate;
                                        *selected_end_offset =
                                                candidate_end;
                                        *selected_center_ceiling_mm =
                                                candidate_ceiling;
                                        *selected_speed = speed;
                                        if (conflict) {
                                                *conflict =
                                                        candidate_conflict;
                                        }
                                        return 0;
                                }
                                if (status > 0 &&
                                    !forbidden_lower_speed_partial) {
                                        blocked = candidate;
                                        blocked_end = candidate_end;
                                        blocked_ceiling =
                                                candidate_ceiling;
                                        blocked_speed = speed;
                                        blocked_conflict =
                                                candidate_conflict;
                                }
                                /*
                                 * Every farther candidate contains this same
                                 * blocked prefix.  Wait on this exact local
                                 * resource instead of growing the request.
                                 */
                                if (status > 0) break;
                        }
                        if (status > 0 ||
                            candidate_end >=
                                    destination_route_offset) {
                                break;
                        }
                        candidate_minimum_end =
                                candidate_end + 1;
                }
        }

        if (requested_complete.node_count > 0) {
                *selected = requested_complete;
                *selected_end_offset = requested_complete_end;
                *selected_center_ceiling_mm =
                        requested_complete_ceiling;
                *selected_speed = requested_speed;
                if (conflict) {
                        conflict->node_index = -1;
                        conflict->owner_train = 0;
                }
                return 0;
        }

        if (blocked.node_count > 0) {
                *selected = blocked;
                *selected_end_offset = blocked_end;
                *selected_center_ceiling_mm =
                        blocked_ceiling;
                *selected_speed = blocked_speed;
                if (conflict) *conflict = blocked_conflict;
        }
        return 1;
}

static int select_bounded_rolling_authority_window(
        const track_route *route, int first_motion_offset,
        int minimum_end_offset, int target_offset,
        int destination_route_offset,
        int destination_offset_mm_value,
        int destination_distance_mm, int requested_speed,
        int allow_partial_speed_fallback,
        int current_progress_mm, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        track_route *selected, int *selected_end_offset,
        int *selected_center_ceiling_mm, int *selected_speed,
        track_reservation_conflict *conflict) {
        return select_bounded_rolling_authority_window_for_leg(
                route, first_motion_offset, first_motion_offset,
                minimum_end_offset, target_offset,
                destination_route_offset,
                destination_offset_mm_value,
                destination_distance_mm, requested_speed,
                allow_partial_speed_fallback,
                current_progress_mm, train, reservation, sensors,
                selected, selected_end_offset,
                selected_center_ceiling_mm, selected_speed,
                conflict);
}

static int turnout_plan_is_consistent(
        const track_turnout_plan *plan) {
        if (!plan || plan->action_count < 0 ||
            plan->action_count > TRACK_MAX) {
                return 0;
        }
        for (int left = 0; left < plan->action_count; ++left) {
                for (int right = left + 1;
                     right < plan->action_count; ++right) {
                        if (plan->actions[left].switch_number ==
                                    plan->actions[right].switch_number &&
                            plan->actions[left].direction !=
                                    plan->actions[right].direction) {
                                return 0;
                        }
                        if (paired_turnout_mate(
                                    plan->actions[left].switch_number) ==
                                    plan->actions[right].switch_number &&
                            plan->actions[left].direction == DIR_CURVED &&
                            plan->actions[right].direction == DIR_CURVED) {
                                return 0;
                        }
                }
        }
        return 1;
}

static int build_turnout_plan_range_checked(
        const track_route *route, int first, int last,
        track_turnout_plan *plan) {
        track_route leg;
        if (build_route_slice(route, first, last, &leg) < 0 ||
            TrackBuildTurnoutPlan(dispatch_track, &leg, plan) < 0) {
                return -1;
        }
        return turnout_plan_is_consistent(plan) ? 0 : -1;
}

static int footprint_tail_offset(const tc2_dispatch_runtime *runtime,
                                 const tc2_dispatch_job_snapshot *job) {
        if (!runtime || !job) return -1;
        return footprint_tail_offset_for_anchor(
                &runtime->route,
                runtime->reservation_anchor_offset,
                job->speed);
}

static int update_remaining_footprint(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        track_route footprint;
        track_reservation_conflict conflict;
        unsigned int generation;
        int footprint_speed =
                runtime->command_speed > 0 ?
                        runtime->command_speed :
                runtime->traffic_resume_speed > 0 ?
                        runtime->traffic_resume_speed :
                        job->speed;
        int tail = footprint_tail_offset(runtime, job);
        /*
         * A CURRENT replacement carries the old collision/arrival footprint.
         * Do not drop it after merely one downstream anchor advance.  The same
         * delayed-release calculation used for intersections must put the
         * train tail plus 200 mm beyond the new route origin first.
         */
        int retain_carry =
                runtime->carry_ambiguity_active &&
                tail <= runtime->leg_start_offset;
        int retain_reversal_carry =
                runtime->reversal_carry_active &&
                tail <=
                        runtime
                                ->reversal_carry_origin_offset;
        int reserved_authority_end =
                runtime->authority_prefetch_active ?
                runtime->authority_prefetch_end_offset :
                runtime->authority_end_offset;
        int full_authority =
                !runtime->rolling_authority_active ||
                reserved_authority_end >=
                        job->destination_route_offset;
        int footprint_status =
                full_authority ?
                build_safety_footprint_for_route(
                        &runtime->route, tail,
                        job->target_route_offset,
                        job->destination_route_offset,
                        job->destination_offset_mm,
                        footprint_speed,
                        &footprint) :
                build_local_authority_footprint(
                        &runtime->route, tail,
                        reserved_authority_end,
                        runtime->leg_start_offset,
                        job->destination_route_offset,
                        footprint_speed, &footprint);
        if (footprint_status < 0 ||
            (retain_carry &&
             append_route_nodes(
                     &footprint,
                     &runtime->carry_ambiguity_footprint) < 0) ||
            (retain_reversal_carry &&
             append_route_nodes(
                     &footprint,
                     &runtime
                              ->reversal_carry_footprint) < 0) ||
            (full_authority &&
             !route_contains_node(
                     &footprint, job->target_node))) {
                return -1;
        }
        int status = runtime->rolling_authority_active ?
                TrackReservationServerUpdateWindow(
                        dispatch_reservation_tid,
                        &footprint, job->train,
                        job->target_node,
                        job->plan_generation, &conflict,
                        &generation) :
                TrackReservationServerUpdateFootprint(
                        dispatch_reservation_tid,
                        &footprint, job->train,
                        job->target_node,
                        job->plan_generation, &conflict,
                        &generation);
        if (status != 0 || generation != job->plan_generation) {
                job->conflict_train = conflict.owner_train;
                job->conflict_node = conflict.node_index;
                return -1;
        }
        runtime->safety_footprint = footprint;
        if (runtime->carry_ambiguity_active && !retain_carry) {
                runtime->carry_ambiguity_active = 0;
                runtime->carry_ambiguity_footprint.node_count = 0;
                /*
                 * This bit is a release witness for the train left behind
                 * by a HEAD_ON recovery.  It is set only after the
                 * generation-checked reservation update above has removed
                 * the old corridor and footprint_tail_offset() has proved
                 * that the complete train plus the delayed-release margin
                 * is beyond the CURRENT origin.  A mere cancel/STOPPED
                 * transition can therefore never wake the opposing train.
                 */
                if (runtime->head_on_recovery_active) {
                        runtime->head_on_recovery_cleared = 1;
                }
                if (runtime->carry_position_estimated) {
                        job->position_estimated = 0;
                }
                runtime->carry_position_estimated = 0;
        }
        if (runtime->reversal_carry_active &&
            !retain_reversal_carry) {
                runtime->reversal_carry_active = 0;
                runtime->reversal_carry_footprint.node_count = 0;
                runtime->reversal_carry_origin_offset = -1;
        }
        return 0;
}

static int stationary_window_contains_physical_node(
        const track_route *window, int node) {
        if (!window || node < 0 || node >= TRACK_MAX) return 0;
        if (route_contains_node(window, node)) return 1;
        int reverse = physical_reverse_index(node);
        return reverse >= 0 && route_contains_node(window, reverse);
}

/*
 * Preserve only turnout resources physically covered by the stopped train.
 * The previous and next turnouts describe how another route can approach the
 * body, but the stationary train does not own either actuator merely because
 * it lies between them.  Exact route-node reservation against the retained
 * body/anchor is what prevents a peer from selecting a branch into the train.
 * Only nodes already owned before the stop may be retained, so stopping can
 * never steal a peer's reservation.
 */
static int append_stationary_zone_block(
        int slot, int64_t stationary_distance_um,
        const track_route *owned_before_stop,
        track_route *hold) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            stationary_distance_um < 0 || !owned_before_stop || !hold) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_plan_valid ||
            runtime->conflict_zone_plan.step_count < 1) {
                return 0;
        }
        int center_mm = (int)((stationary_distance_um + 500) / 1000);
        int body_first = center_mm - TC2_TRAIN_HALF_LENGTH_MM;
        int body_last = center_mm + TC2_TRAIN_HALF_LENGTH_MM;
        if (body_first < 0) body_first = 0;

        for (int index = 0;
             index < runtime->conflict_zone_plan.step_count; ++index) {
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[index];
                if (step->entry_distance_mm > body_last ||
                    step->exit_distance_mm < body_first) {
                        continue;
                }
                if (step->first_route_offset < 0 ||
                    step->last_route_offset < step->first_route_offset ||
                    step->last_route_offset >= runtime->route.node_count) {
                        return -1;
                }
                for (int offset = step->first_route_offset;
                     offset <= step->last_route_offset; ++offset) {
                        int node = runtime->route.nodes[offset];
                        if (stationary_window_contains_physical_node(
                                    owned_before_stop, node) &&
                            append_unique_node(hold, node) < 0) {
                                return -1;
                        }
                }
        }
        return 0;
}

/*
 * A stationary train keeps its latest real anchor plus any turnout physically
 * under its body.  It owns no adjacent turnout merely because that turnout is
 * one possible entrance to the stopped track. Waiting peers retain their
 * complete plans but cannot acquire a rolling window whose actual route nodes
 * overlap this body footprint until remove or CURRENT moves the block.
 */
static int update_stationary_hold(
        int slot, int64_t stationary_distance_um) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        track_route hold;
        track_reservation_conflict conflict;
        unsigned int generation;
        int anchor_offset = job->current_route_offset;
        if (!runtime->route_valid || job->plan_generation == 0 ||
            stationary_distance_um < 0 || anchor_offset < 0 ||
            anchor_offset >= runtime->route.node_count) {
                return -1;
        }
        hold.node_count = 0;
        hold.distance_mm = 0;
        hold.optimization_cost_mm = 0;
        hold.reversal_count = 0;
        if (append_unique_node(
                    &hold,
                    runtime->route.nodes[anchor_offset]) < 0) return -1;
        track_route owned_before_stop = runtime->safety_footprint;
        if (append_stationary_zone_block(
                    slot, stationary_distance_um,
                    &owned_before_stop, &hold) < 0) {
                return -1;
        }
        if ((runtime->carry_ambiguity_active &&
             append_route_nodes(
                     &hold,
                     &runtime
                              ->carry_ambiguity_footprint) < 0) ||
            (runtime->reversal_carry_active &&
             append_route_nodes(
                     &hold,
                     &runtime
                              ->reversal_carry_footprint) < 0)) {
                return -1;
        }
        if (append_paired_turnout_resources(&hold) < 0) {
                return -1;
        }
        int status = TrackReservationServerUpdateWindow(
                dispatch_reservation_tid, &hold, job->train,
                job->target_node, job->plan_generation, &conflict,
                &generation);
        if (status != 0 || generation != job->plan_generation) {
                job->conflict_train = conflict.owner_train;
                job->conflict_node = conflict.node_index;
                return -1;
        }
        runtime->safety_footprint = hold;
        runtime->traffic_hold_distance_um = stationary_distance_um;
        runtime->static_center_lower_um = stationary_distance_um;
        runtime->static_center_upper_um = stationary_distance_um;
        runtime->static_center_bounds_valid = 1;
        job->traffic_hold_distance_um = stationary_distance_um;
        job->hold_active = 1;
        return 0;
}

/*
 * A real detector is the normal cancel anchor.  Before the first detector of
 * an initial A-F trip, however, the fixed physical departure ENTER is the
 * only localization fact the dispatcher can possibly have.  Accept that one
 * origin only while the immutable route still begins there and no real
 * detector has been observed.  CURRENT and every estimated/rebased ENTER are
 * deliberately excluded.
 */
static int cancel_anchor_is_trusted(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int confirmed_offset = runtime->monitor.confirmed_offset;
        if (!runtime->route_valid || confirmed_offset < 0 ||
            confirmed_offset >= runtime->route.node_count) {
                return 0;
        }
        int confirmed_node = runtime->route.nodes[confirmed_offset];
        if (confirmed_node < 0 || confirmed_node >= TRACK_MAX) return 0;
        if (dispatch_track[confirmed_node].type == NODE_SENSOR) return 1;

        return job->start_index >= 0 &&
               job->start_index < TC2_DISPATCH_START_COUNT &&
               runtime->leg_start_offset == 0 &&
               runtime->monitor.origin_offset == 0 &&
               confirmed_offset == runtime->leg_start_offset &&
               runtime->monitor.last_observed_node < 0 &&
               runtime->start_node == confirmed_node &&
               runtime->route.nodes[0] == runtime->start_node &&
               dispatch_track[confirmed_node].type == NODE_ENTER;
}

/*
 * Cancel has no destination sensor at which to localize the final centre.
 * Build its static block from the last ordered real sensor (or the strictly
 * validated fixed departure origin above) through the conservative
 * zero-speed upper bound.  Only nodes already owned by this train and
 * physically lying inside that possible body interval survive; the estimated
 * current node, adjacent turnouts, and old future route do not.
 */
static int update_cancel_stationary_hold(
        int slot, int64_t lower_center_um,
        int64_t upper_center_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            lower_center_um < 0 || upper_center_um < lower_center_um) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        int confirmed_offset = runtime->monitor.confirmed_offset;
        if (!runtime->route_valid || job->plan_generation == 0 ||
            !cancel_anchor_is_trusted(slot)) {
                return -1;
        }

        int64_t body_first_um = lower_center_um -
                (int64_t)(TC2_TRAIN_HALF_LENGTH_MM + 20) * 1000;
        int64_t body_last_um = upper_center_um +
                (int64_t)(TC2_TRAIN_HALF_LENGTH_MM + 20) * 1000;
        if (body_first_um < 0) body_first_um = 0;

        track_route hold;
        hold.node_count = 0;
        hold.distance_mm = 0;
        hold.optimization_cost_mm = 0;
        hold.reversal_count = 0;
        track_route owned_before_stop = runtime->safety_footprint;

        int confirmed_node = runtime->route.nodes[confirmed_offset];
        if (!stationary_window_contains_physical_node(
                    &owned_before_stop, confirmed_node) ||
            append_unique_node(&hold, confirmed_node) < 0) {
                return -1;
        }
        for (int offset = 0;
             offset < runtime->route.node_count; ++offset) {
                int distance_mm = -1;
                int node = runtime->route.nodes[offset];
                if (Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            offset, &distance_mm) < 0) {
                        return -1;
                }
                int64_t distance_um = (int64_t)distance_mm * 1000;
                if (distance_um < body_first_um ||
                    distance_um > body_last_um ||
                    !stationary_window_contains_physical_node(
                            &owned_before_stop, node)) {
                        continue;
                }
                if (append_unique_node(&hold, node) < 0) return -1;
        }
        /* Only expand a central paired resource when the body covers it. */
        if (append_paired_turnout_resources(&hold) < 0) return -1;

        track_reservation_conflict conflict;
        unsigned int generation = 0;
        int status = TrackReservationServerUpdateWindow(
                dispatch_reservation_tid, &hold, job->train,
                job->target_node, job->plan_generation,
                &conflict, &generation);
        if (status != 0 || generation != job->plan_generation) {
                job->conflict_train = conflict.owner_train;
                job->conflict_node = conflict.node_index;
                return -1;
        }
        runtime->safety_footprint = hold;
        runtime->traffic_hold_distance_um = upper_center_um;
        runtime->static_center_lower_um = lower_center_um;
        runtime->static_center_upper_um = upper_center_um;
        runtime->static_center_bounds_valid = 1;
        job->traffic_hold_distance_um = upper_center_um;
        job->hold_active = 1;
        /*
         * A canceled body may lie anywhere in the bounded interval above,
         * but the last real detector is the only directed localization
         * proof from which a later CURRENT route may be rebuilt.  Never let
         * the pre-cancel model cursor become that new route's origin.
         */
        job->current_route_offset = confirmed_offset;
        job->current_node = confirmed_node;
        job->position_estimated = 1;
        return 0;
}

/*
 * A cancel stop has no destination detector.  The last accepted detector (or
 * the strictly validated fixed departure origin before the first detector)
 * is the only lower position proof; the train may have travelled after that
 * fact and may still coast after the zero-speed command.  Bound that travel
 * with the fastest calibrated velocity, full stop distance, and model
 * uncertainty.  This range is used only to protect the possible body, never
 * to advance the route cursor or claim a turnout motor.
 */
static int cancel_stationary_center_bounds(
        int slot, int stop_speed, int zero_confirmed_tick,
        int64_t *lower_center_um,
        int64_t *upper_center_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            stop_speed <= 0 || zero_confirmed_tick < 0 ||
            !lower_center_um || !upper_center_um) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            runtime->monitor.confirmed_distance_mm < 0 ||
            !cancel_anchor_is_trusted(slot)) {
                return -1;
        }

        int state = dispatch_jobs[slot].state;
        /*
         * These states are physically stationary by definition.  In
         * particular, READY may cache the requested speed before any
         * positive-speed CAN frame has been committed, so command_speed is
         * not evidence that the train has moved.  Requiring it to be zero
         * made cancel fail at a validated fixed departure and left the old
         * next/nextnext plan published indefinitely.
         */
        int already_stationary =
                state == TC2_JOB_TRAFFIC_HOLD ||
                state == TC2_JOB_PREPARING ||
                state == TC2_JOB_READY ||
                state == TC2_JOB_WAITING ||
                state == TC2_JOB_STAGED ||
                state == TC2_JOB_STOP_UNCONFIRMED ||
                state == TC2_JOB_ARRIVED ||
                state == TC2_JOB_STOPPED;
        if (already_stationary) {
                int64_t lower_um =
                        (int64_t)runtime->monitor
                                .confirmed_distance_mm * 1000;
                int64_t upper_um =
                        runtime->traffic_hold_distance_um >= lower_um ?
                        runtime->traffic_hold_distance_um : lower_um;
                *lower_center_um = lower_um;
                *upper_center_um = upper_um;
                return 0;
        }

        /*
         * A stationary fixed-origin job can be canceled before its first
         * positive command and therefore before any detector timestamp
         * exists.  The validated ENTER origin above is already an exact
         * stationary bound; detector age is needed only for a train which
         * may actually have moved after its last observation.
         */
        if (runtime->last_confirmed_tick < 0) return -1;

        int age = motion_tick_age(
                zero_confirmed_tick, runtime->last_confirmed_tick);
        int fast_velocity_tenths =
                Tc2MotionFastVelocityTenthsMmPerTick(stop_speed);
        int stop_distance_mm = Tc2MotionStopDistanceMm(stop_speed);
        int uncertainty_mm = Tc2MotionUncertaintyMm(stop_speed);
        if (age < 0 || fast_velocity_tenths <= 0 ||
            stop_distance_mm < 0 || uncertainty_mm < 0) {
                return -1;
        }

        int64_t detector_travel_mm =
                ((int64_t)age * fast_velocity_tenths + 9) / 10;
        int64_t lower_mm = runtime->monitor.confirmed_distance_mm;
        int64_t upper_mm = lower_mm + detector_travel_mm;
        if (upper_mm < lower_mm ||
            upper_mm > INT64_MAX - stop_distance_mm ||
            upper_mm + stop_distance_mm >
                    INT64_MAX - uncertainty_mm) {
                return -1;
        }
        upper_mm += stop_distance_mm + uncertainty_mm;
        if (lower_mm > INT64_MAX / 1000 ||
            upper_mm > INT64_MAX / 1000) {
                return -1;
        }
        *lower_center_um = lower_mm * 1000;
        *upper_center_um = upper_mm * 1000;
        return 0;
}

static int update_arrival_hold(int slot) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (job->destination_distance_mm < 0) {
                return -1;
        }
        return update_stationary_hold(
                slot,
                (int64_t)job->destination_distance_mm * 1000);
}

/*
 * Before an ARRIVED train is rerouted, discard every old-route guard which is
 * not part of the train's bounded stationary body.  The directed route and
 * last real sensor remain localization history, but neither an old next nor a
 * destination carry corridor may survive as turnout authority.  STOPPED
 * cancel bodies are already built by update_cancel_stationary_hold().
 */
static int normalize_operator_reroute_static_hold(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state != TC2_JOB_ARRIVED) return 0;
        if (!runtime->route_valid || job->plan_generation == 0 ||
            !runtime->static_center_bounds_valid ||
            runtime->static_center_lower_um < 0 ||
            runtime->static_center_upper_um <
                    runtime->static_center_lower_um ||
            job->current_node < 0 || job->current_node >= TRACK_MAX) {
                return -1;
        }

        int64_t body_first_um = runtime->static_center_lower_um -
                (int64_t)(TC2_TRAIN_HALF_LENGTH_MM + 20) * 1000;
        int64_t body_last_um = runtime->static_center_upper_um +
                (int64_t)(TC2_TRAIN_HALF_LENGTH_MM + 20) * 1000;
        if (body_first_um < 0) body_first_um = 0;

        track_route hold;
        hold.node_count = 0;
        hold.distance_mm = 0;
        hold.optimization_cost_mm = 0;
        hold.reversal_count = 0;
        track_route owned_before = runtime->safety_footprint;
        if (!stationary_window_contains_physical_node(
                    &owned_before, job->current_node) ||
            append_unique_node(&hold, job->current_node) < 0) {
                return -1;
        }
        for (int offset = 0; offset < runtime->route.node_count; ++offset) {
                int distance_mm = -1;
                int node = runtime->route.nodes[offset];
                if (Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            offset, &distance_mm) < 0) {
                        return -1;
                }
                int64_t distance_um = (int64_t)distance_mm * 1000;
                if (distance_um < body_first_um ||
                    distance_um > body_last_um ||
                    !stationary_window_contains_physical_node(
                            &owned_before, node)) {
                        continue;
                }
                if (append_unique_node(&hold, node) < 0) return -1;
        }
        if (append_paired_turnout_resources(&hold) < 0) return -1;

        track_reservation_conflict conflict;
        unsigned int generation = 0;
        int status = TrackReservationServerUpdateWindow(
                dispatch_reservation_tid, &hold, job->train,
                job->target_node, job->plan_generation,
                &conflict, &generation);
        if (status != 0 || generation != job->plan_generation) {
                job->conflict_train = conflict.owner_train;
                job->conflict_node = conflict.node_index;
                return -1;
        }
        runtime->safety_footprint = hold;
        runtime->carry_ambiguity_active = 0;
        runtime->reversal_carry_active = 0;
        return 0;
}

static void build_unavailable(
        int slot, const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        unsigned char unavailable[TRACK_MAX],
        int ignore_managed_traffic) {
        int train = dispatch_jobs[slot].train;
        for (int node = 0; node < TRACK_MAX; ++node) {
                unavailable[node] = dispatch_blocked_by_node[node];
                if (!ignore_managed_traffic &&
                    reservation->owner_by_node[node] != 0 &&
                    reservation->owner_by_node[node] != train) {
                        unavailable[node] = 1;
                }
                if (node < TRAIN_SENSOR_COUNT &&
                    sensors->sensor_state[node] &&
                    reservation->owner_by_node[node] != train &&
                    (!ignore_managed_traffic ||
                     reservation->owner_by_node[node] == 0)) {
                        mark_physical(unavailable, node);
                }
        }
        if (ignore_managed_traffic) return;
        for (int other = 0; other < TC2_DISPATCH_MAX_JOBS; ++other) {
                if (other == slot ||
                    dispatch_jobs[other].state == TC2_JOB_EMPTY) {
                        continue;
                }
                int occupied = dispatch_jobs[other].current_node;
                if (occupied < 0 &&
                    dispatch_jobs[other].start_index >= 0) {
                        occupied = TrackFindNodeByName(
                                dispatch_track,
                                Tc2DispatchStartNodeName(
                                        dispatch_jobs[other].start_index));
                }
                mark_physical(unavailable, occupied);
        }
}

static int reversal_turnout_clearance_is_safe(
        const track_route *route, int target_offset, int speed) {
        int uncertainty = Tc2MotionUncertaintyMm(speed);
        if (!route || target_offset < 0 ||
            target_offset >= route->node_count ||
            uncertainty < 0) {
                return 0;
        }
        int required_clearance =
                TC2_TRAIN_HALF_LENGTH_MM +
                uncertainty;
        for (int offset = 0;
             offset < target_offset; ++offset) {
                int node = route->nodes[offset];
                int next = route->nodes[offset + 1];
                if (dispatch_track[node].reverse !=
                    &dispatch_track[next]) {
                        continue;
                }
                for (int candidate = offset + 1;
                     candidate <= target_offset; ++candidate) {
                        int candidate_node =
                                route->nodes[candidate];
                        if (dispatch_track[candidate_node].type !=
                            NODE_BRANCH) {
                                continue;
                        }
                        int distance;
                        if (TrackRouteDistanceBetweenOffsets(
                                    dispatch_track, route,
                                    offset + 1, candidate,
                                    &distance) < 0 ||
                            distance < required_clearance) {
                                return 0;
                        }
                        break;
                }
        }
        return 1;
}

static int turnout_action_overlaps_footprint(
        const track_turnout_action *action,
        const track_route *footprint) {
        if (!action || !footprint) return 0;
        int controlled = action->switch_number;
        int controlled_mate =
                paired_turnout_mate(controlled);
        for (int offset = 0;
             offset < footprint->node_count; ++offset) {
                int node = footprint->nodes[offset];
                int number = dispatch_track[node].num;
                if ((dispatch_track[node].type == NODE_BRANCH ||
                     dispatch_track[node].type == NODE_MERGE) &&
                    (number == controlled ||
                     number == controlled_mate ||
                     paired_turnout_mate(number) ==
                             controlled)) {
                        return 1;
                }
        }
        return 0;
}

static int turnout_plan_direction_for_switch(
        const track_turnout_plan *plan, int switch_number,
        int *direction) {
        int found = 0;
        int selected = DIR_STRAIGHT;
        if (!turnout_plan_is_consistent(plan) ||
            switch_number < 1 || !direction) {
                return -1;
        }
        for (int action = 0;
             action < plan->action_count; ++action) {
                const track_turnout_action *candidate =
                        &plan->actions[action];
                int candidate_direction;
                if (candidate->switch_number ==
                    switch_number) {
                        candidate_direction =
                                candidate->direction;
                } else if (candidate->direction ==
                                   DIR_CURVED &&
                           paired_turnout_mate(
                                   candidate
                                           ->switch_number) ==
                                   switch_number) {
                        candidate_direction = DIR_STRAIGHT;
                } else {
                        continue;
                }
                if (found &&
                    candidate_direction != selected) {
                        return -1;
                }
                selected = candidate_direction;
                found = 1;
        }
        if (!found) return 1;
        *direction = selected;
        return 0;
}

static int turnout_action_matches_confirmed_plan(
        const track_turnout_action *action,
        const track_turnout_plan *confirmed) {
        int direction;
        if (!action || !confirmed ||
            turnout_plan_direction_for_switch(
                    confirmed, action->switch_number,
                    &direction) != 0 ||
            direction != action->direction) {
                return 0;
        }
        int mate = paired_turnout_mate(
                action->switch_number);
        if (action->direction == DIR_CURVED &&
            mate != 0 &&
            (turnout_plan_direction_for_switch(
                     confirmed, mate, &direction) != 0 ||
             direction != DIR_STRAIGHT)) {
                return 0;
        }
        return 1;
}

static int turnout_plan_safe_for_carried_footprint(
        const track_turnout_plan *plan,
        const track_route *footprint,
        const track_turnout_plan *confirmed) {
        if (!turnout_plan_is_consistent(plan) || !footprint ||
            footprint->node_count < 0 ||
            footprint->node_count > TRACK_MAX) {
                return 0;
        }
        for (int action = 0; action < plan->action_count; ++action) {
                if (turnout_action_overlaps_footprint(
                            &plan->actions[action],
                            footprint) &&
                    !turnout_action_matches_confirmed_plan(
                            &plan->actions[action],
                            confirmed)) {
                        return 0;
                }
        }
        return 1;
}

static int initial_turnouts_clear_of_carried_ambiguity(
        const track_route *route, int target_offset,
        const track_route *ambiguity,
        const track_turnout_plan *confirmed) {
        track_turnout_plan plan;
        int leg_start = 0;
        int leg_end;
        if (!route || !ambiguity || route->node_count < 1 ||
            target_offset < 0 ||
            target_offset >= route->node_count) {
                return 0;
        }
        /*
         * A stopped CURRENT route may deliberately begin with a sensor
         * reversal.  That transition has no turnout action, so validate the
         * first physical-motion leg that will actually be queued after the
         * confirmed direction change.  Otherwise an empty offset-zero plan
         * could hide a conflicting turnout immediately beyond the reverse.
         */
        if (target_offset > 0 &&
            dispatch_track[route->nodes[0]].reverse ==
                    &dispatch_track[route->nodes[1]]) {
                leg_start = 1;
        }
        leg_end = TrackRouteMotionLegEnd(
                dispatch_track, route, leg_start);
        if (leg_end >= target_offset) {
                leg_end = route->node_count - 1;
        }
        if (leg_end < leg_start ||
            build_turnout_plan_range_checked(
                    route, leg_start, leg_end, &plan) < 0) {
                return 0;
        }
        return turnout_plan_safe_for_carried_footprint(
                &plan, ambiguity, confirmed);
}

static int route_has_consecutive_reversals(
        const track_route *route, int target_offset) {
        int previous_was_reversal = 0;
        if (!route || route->node_count < 1 ||
            route->node_count > TRACK_MAX ||
            target_offset < 0 ||
            target_offset >= route->node_count) {
                return 1;
        }
        for (int offset = 0;
             offset < target_offset; ++offset) {
                int node = route->nodes[offset];
                int next = route->nodes[offset + 1];
                if (node < 0 || node >= TRACK_MAX ||
                    next < 0 || next >= TRACK_MAX) {
                        return 1;
                }
                int is_reversal =
                        dispatch_track[node].reverse ==
                        &dispatch_track[next];
                if (is_reversal && previous_was_reversal) {
                        /*
                         * Two zero-distance reversals return to the original
                         * orientation, add no reachability, and can otherwise
                         * make preparation launch into another immediate
                         * reversal. Reject the non-canonical route.
                         */
                        return 1;
                }
                previous_was_reversal = is_reversal;
        }
        return 0;
}

static int route_does_not_reenter_before_localization(
        const track_route *route,
        const track_route *ambiguity) {
        int left_ambiguity = 0;
        if (!route || !ambiguity || route->node_count < 1 ||
            route->node_count > TRACK_MAX) {
                return 0;
        }
        for (int offset = 0; offset < route->node_count; ++offset) {
                int in_ambiguity =
                        route_contains_node(
                                ambiguity,
                                route->nodes[offset]);
                if (!in_ambiguity) {
                        left_ambiguity = 1;
                } else if (left_ambiguity) {
                        /*
                         * The first expected report can be the one false
                         * pulse and the next report can legitimately skip
                         * one missing sensor.  Therefore no static count of
                         * intervening sensors proves that the train left the
                         * carried footprint.  A route may not leave and then
                         * re-enter it while the CURRENT origin is estimated.
                         */
                        return 0;
                }
        }
        return 1;
}

static int route_has_named_node_after(
        const track_route *route, int after_offset,
        const char *name, int through_offset) {
        if (!name) return 1;
        int node = TrackFindNodeByName(dispatch_track, name);
        if (!route || node < 0 || after_offset < -1 ||
            through_offset >= route->node_count) {
                return 0;
        }
        for (int offset = after_offset + 1;
             offset <= through_offset; ++offset) {
                if (route->nodes[offset] == node) return 1;
        }
        return 0;
}

/*
 * A virtual destination can lie inside an edge. Return the first route-node
 * offset at or beyond that exact scalar point; callers use the scalar
 * distance for cost/timing and the ceiling only for graph traversal,
 * turnout planning, and conservative reservation.
 */
static int route_ceiling_after_offset(
        const track_route *route, int anchor_offset,
        int additional_mm, int *ceiling_offset) {
        if (!route || !ceiling_offset || additional_mm < 0 ||
            anchor_offset < 0 ||
            anchor_offset >= route->node_count) {
                return -1;
        }
        if (additional_mm == 0) {
                *ceiling_offset = anchor_offset;
                return 0;
        }
        for (int offset = anchor_offset + 1;
             offset < route->node_count; ++offset) {
                int distance;
                if (TrackRouteDistanceBetweenOffsets(
                            dispatch_track, route,
                            anchor_offset, offset,
                            &distance) < 0) {
                        return -1;
                }
                if (distance >= additional_mm) {
                        *ceiling_offset = offset;
                        return 0;
                }
        }
        return -1;
}

static int validate_and_guard_candidate(
        const unsigned char unavailable[TRACK_MAX], int speed,
        int destination_offset_mm_value,
        const char *straight_guide,
        track_route *route, int *target_offset,
        int *destination_route_offset, int *path_distance,
        int *path_cost) {
        if (!route || route->node_count < 1 ||
            destination_offset_mm_value < 0 ||
            route->distance_mm >
                    0x7fffffff - destination_offset_mm_value ||
            route->optimization_cost_mm >
                    0x7fffffff - destination_offset_mm_value) {
                return -1;
        }
        *target_offset = route->node_count - 1;
        *path_distance =
                route->distance_mm + destination_offset_mm_value;
        *path_cost =
                route->optimization_cost_mm +
                destination_offset_mm_value;
        if (route_has_consecutive_reversals(
                    route, *target_offset)) {
                return -1;
        }
        int braking = Tc2MotionBrakingDistanceMm(speed);
        if (braking < 0 ||
            destination_offset_mm_value >
                    0x7fffffff - braking) {
                return -1;
        }
        int represented = TrackExtendRouteAhead(
                dispatch_track, route,
                destination_offset_mm_value + braking);
        if (represented >=
                    destination_offset_mm_value + braking &&
            route->node_count < TRACK_MAX &&
            dispatch_track[
                    route->nodes[
                            route->node_count - 1]].type ==
                    NODE_BRANCH) {
                /*
                 * Do not leave a braking extension ending on an
                 * unconfigured branch. Add its selected outgoing edge so
                 * the prelaunch turnout batch establishes the direction a
                 * possible overrun (and later relocalization) will follow.
                 */
                int before = route->node_count;
                int extra = TrackExtendRouteAhead(
                        dispatch_track, route, 1);
                if (extra <= 0 ||
                    route->node_count <= before) {
                        return -1;
                }
        }
        if (represented <
                    destination_offset_mm_value + braking ||
            route_ceiling_after_offset(
                    route, *target_offset,
                    destination_offset_mm_value,
                    destination_route_offset) < 0 ||
            !route_has_named_node_after(
                    route, *target_offset, straight_guide,
                    *destination_route_offset) ||
            !reversal_turnout_clearance_is_safe(
                    route, *destination_route_offset, speed)) {
                return -1;
        }
        int leg_start = 0;
        while (leg_start <= *destination_route_offset) {
                track_turnout_plan plan;
                int leg_end = TrackRouteMotionLegEnd(
                        dispatch_track, route, leg_start);
                if (leg_end >= *destination_route_offset) {
                        leg_end = route->node_count - 1;
                }
                if (leg_end < leg_start ||
                    build_turnout_plan_range_checked(
                            route, leg_start, leg_end,
                            &plan) < 0) {
                        return -1;
                }
                if (leg_end >= *destination_route_offset) break;
                leg_start = leg_end + 1;
        }
        track_route safety;
        if (build_safety_footprint_for_route(
                    route, 0, *target_offset,
                    *destination_route_offset,
                    destination_offset_mm_value,
                    speed, &safety) < 0) {
                return -1;
        }
        for (int offset = 0; offset < safety.node_count; ++offset) {
                int node = safety.nodes[offset];
                if (unavailable[node]) return -1;
                int reverse = physical_reverse_index(node);
                if (reverse >= 0 && unavailable[reverse]) return -1;
        }
        return 0;
}

static int candidate_route(int start, int target,
                           const unsigned char unavailable[TRACK_MAX],
                           int speed, int allow_reversals,
                           int prefer_forward,
                           int destination_offset_mm_value,
                           const char *straight_guide,
                           track_route *route,
                           int *target_offset,
                           int *destination_route_offset,
                           int *path_distance,
                           int *path_cost) {
        track_route forward;
        track_route reversal;
        int forward_target = -1;
        int forward_destination = -1;
        int forward_distance = 0;
        int forward_cost = 0;
        int reversal_target = -1;
        int reversal_destination = -1;
        int reversal_distance = 0;
        int reversal_cost = 0;
        int have_forward =
                TrackFindShortestRouteWithUnavailable(
                        dispatch_track, start, target,
                        unavailable, &forward) == 0 &&
                validate_and_guard_candidate(
                        unavailable, speed,
                        destination_offset_mm_value,
                        straight_guide, &forward,
                        &forward_target, &forward_destination,
                        &forward_distance,
                        &forward_cost) == 0;
        int have_reversal =
                allow_reversals &&
                TrackFindShortestRouteWithSensorReversalsAndUnavailable(
                        dispatch_track, start, target,
                        TC2_REVERSAL_PENALTY_MM, unavailable,
                        &reversal) == 0 &&
                validate_and_guard_candidate(
                        unavailable, speed,
                        destination_offset_mm_value,
                        straight_guide, &reversal,
                        &reversal_target, &reversal_destination,
                        &reversal_distance,
                        &reversal_cost) == 0;
        if (!have_forward && !have_reversal) return -1;
        /*
         * A catalogued A-F dispatch owns a known departure direction.
         * Preserve that direction whenever a safe forward route exists;
         * changing direction is a fallback for a topology/blocking case,
         * not a distance shortcut.  This keeps live control identical to
         * the offline 48-route oracle and prevents an unexpected reversal
         * from replacing the operator's shortest forward turnout plan.
         */
        if (have_forward &&
            (prefer_forward ||
             !have_reversal ||
             forward_cost <= reversal_cost)) {
                *route = forward;
                *target_offset = forward_target;
                *destination_route_offset =
                        forward_destination;
                *path_distance = forward_distance;
                *path_cost = forward_cost;
        } else {
                *route = reversal;
                *target_offset = reversal_target;
                *destination_route_offset =
                        reversal_destination;
                *path_distance = reversal_distance;
                *path_cost = reversal_cost;
        }
        return 0;
}

static int head_on_recovery_candidate_has_initial_authority(
        const track_route *route, int target_offset,
        int destination_route_offset,
        int destination_offset_mm_value,
        int destination_distance_mm, int speed, int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors) {
        if (!route || !reservation || !sensors ||
            route->node_count < 2) {
                return 0;
        }
        int first_motion_offset = 0;
        int minimum_end_offset = 1;
        int initial_leg_end =
                TrackRouteMotionLegEnd(
                        dispatch_track, route, 0);
        if (initial_leg_end < 0 ||
            initial_leg_end >= route->node_count) {
                return 0;
        }
        if (initial_leg_end == 0 &&
            destination_route_offset > 0) {
                if (route->node_count < 3 ||
                    dispatch_track[route->nodes[0]].reverse !=
                            &dispatch_track[
                                    route->nodes[1]]) {
                        return 0;
                }
                first_motion_offset = 1;
                minimum_end_offset = 2;
        }

        track_route authority;
        int authority_end = -1;
        int authority_ceiling = -1;
        int authority_speed = -1;
        track_reservation_conflict conflict;
        int status =
                select_head_on_recovery_initial_authority(
                        route, first_motion_offset,
                        minimum_end_offset, target_offset,
                        destination_route_offset,
                        destination_offset_mm_value,
                        destination_distance_mm, speed,
                        first_motion_offset == 1 ? 1 : 0,
                        0, train, reservation, sensors,
                        &authority, &authority_end,
                        &authority_ceiling, &authority_speed,
                        &conflict);
        /*
         * A free local window is immediately usable.  A blocked local window is
         * still a valid route candidate and must be retained for FIFO; an empty
         * WAIT means no bounded sensor-witness authority exists on this route.
         */
        return status == 0 ||
                (status > 0 &&
                 authority.node_count > 0);
}

static int candidate_route_for_current_hold(
        int start, int target,
        const unsigned char unavailable[TRACK_MAX],
        int speed, int destination_offset_mm_value,
        const char *straight_guide,
        int force_reverse_first,
        int select_lowest_cost_direction,
        int forbid_leading_reverse,
        const track_route *carried,
        const track_turnout_plan *confirmed,
        int train,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors,
        int require_head_on_release_witness,
        track_route *route,
        int *target_offset, int *destination_route_offset,
        int *path_distance,
        int *path_cost, int *hold_blocked) {
        track_route forward;
        track_route reversal;
        int forward_target = -1;
        int forward_destination = -1;
        int forward_distance = 0;
        int forward_cost = 0;
        int reversal_target = -1;
        int reversal_destination = -1;
        int reversal_distance = 0;
        int reversal_cost = 0;
        track_route leading;
        int leading_target = -1;
        int leading_destination = -1;
        int leading_distance = 0;
        int leading_cost = 0;
        if (!hold_blocked) return -1;
        *hold_blocked = 0;
        int forward_graph =
                TrackFindShortestRouteWithUnavailable(
                        dispatch_track, start, target,
                        unavailable, &forward) == 0 &&
                validate_and_guard_candidate(
                        unavailable, speed,
                        destination_offset_mm_value,
                        straight_guide, &forward,
                        &forward_target, &forward_destination,
                        &forward_distance,
                        &forward_cost) == 0;
        int have_forward =
                forward_graph &&
                initial_turnouts_clear_of_carried_ambiguity(
                        &forward, forward_destination, carried,
                        confirmed);
        if (forward_graph && !have_forward) {
                *hold_blocked = 1;
        }
        if (have_forward &&
            require_head_on_release_witness &&
            !head_on_recovery_candidate_has_initial_authority(
                    &forward, forward_target,
                    forward_destination,
                    destination_offset_mm_value,
                    forward_distance, speed, train,
                    reservation, sensors)) {
                have_forward = 0;
        }
        int reversal_graph =
                TrackFindShortestRouteWithSensorReversalsAndUnavailable(
                        dispatch_track, start, target,
                        TC2_REVERSAL_PENALTY_MM, unavailable,
                        &reversal) == 0 &&
                validate_and_guard_candidate(
                        unavailable, speed,
                        destination_offset_mm_value,
                        straight_guide, &reversal,
                        &reversal_target, &reversal_destination,
                        &reversal_distance,
                        &reversal_cost) == 0;
        int have_reversal =
                reversal_graph &&
                initial_turnouts_clear_of_carried_ambiguity(
                        &reversal, reversal_destination, carried,
                        confirmed);
        if (reversal_graph && !have_reversal) {
                *hold_blocked = 1;
        }
        if (have_reversal &&
            require_head_on_release_witness &&
            !head_on_recovery_candidate_has_initial_authority(
                    &reversal, reversal_target,
                    reversal_destination,
                    destination_offset_mm_value,
                    reversal_distance, speed, train,
                    reservation, sensors)) {
                have_reversal = 0;
        }
        /*
         * Public reroute chooses its physical direction before this route is
         * allowed to own any future resource.  Once that reverse has settled,
         * a generalized route may still contain a later, ordinary reversal,
         * but it must not begin by reversing straight back into the discarded
         * direction.  TrackRouteMotionLegEnd()==0 is the canonical immediate
         * sensor-reversal prefix used by the normal reversal state machine.
         */
        if (have_reversal && forbid_leading_reverse &&
            TrackRouteMotionLegEnd(
                    dispatch_track, &reversal, 0) == 0) {
                have_reversal = 0;
        }
        int have_leading = 0;
        int reverse_start = physical_reverse_index(start);
        if (!forbid_leading_reverse && reverse_start >= 0 &&
            dispatch_track[start].type == NODE_SENSOR &&
            dispatch_track[reverse_start].type == NODE_SENSOR &&
            /*
             * This is the explicit "reverse first" alternative.  Search
             * forward-only after that one intentional reversal; allowing a
             * second generalized reversal here can produce the useless
             * start -> reverse(start) -> start prefix and hide the actual
             * opposite-direction route.
             */
            TrackFindShortestRouteWithUnavailable(
                    dispatch_track, reverse_start, target,
                    unavailable,
                    &leading) == 0 &&
            leading.node_count < TRACK_MAX &&
            leading.optimization_cost_mm <=
                    0x7fffffff -
                            TC2_REVERSAL_PENALTY_MM) {
                for (int offset = leading.node_count;
                     offset > 0; --offset) {
                        leading.nodes[offset] =
                                leading.nodes[offset - 1];
                }
                leading.nodes[0] = start;
                ++leading.node_count;
                ++leading.reversal_count;
                leading.optimization_cost_mm +=
                        TC2_REVERSAL_PENALTY_MM;
                int leading_graph =
                        validate_and_guard_candidate(
                                unavailable, speed,
                                destination_offset_mm_value,
                                straight_guide, &leading,
                                &leading_target,
                                &leading_destination,
                                &leading_distance,
                                &leading_cost) == 0;
                have_leading =
                        leading_graph &&
                        initial_turnouts_clear_of_carried_ambiguity(
                                &leading, leading_destination,
                                carried, confirmed);
                if (leading_graph && !have_leading) {
                        *hold_blocked = 1;
                }
                if (have_leading &&
                    require_head_on_release_witness &&
                    !head_on_recovery_candidate_has_initial_authority(
                            &leading, leading_target,
                            leading_destination,
                            destination_offset_mm_value,
                            leading_distance, speed, train,
                            reservation, sensors)) {
                        have_leading = 0;
                }
        }
        if ((force_reverse_first && !have_leading) ||
            (!force_reverse_first &&
             !have_forward && !have_reversal &&
             !have_leading)) {
                return -1;
        }
        if (force_reverse_first) {
                *route = leading;
                *target_offset = leading_target;
                *destination_route_offset =
                        leading_destination;
                *path_distance = leading_distance;
                *path_cost = leading_cost;
        } else if (select_lowest_cost_direction) {
                /*
                 * Reroute has no implicit direction command.  Compare every
                 * independently validated CURRENT alternative by physical
                 * travel first, using optimization cost only as the tie
                 * breaker.  A reversal penalty is useful when two routes
                 * cover the same distance, but it must not send a train all
                 * the way around the layout past the nearby destination-side
                 * detector merely to avoid one safe reverse.
                 */
                int selected_cost = 0;
                int selected_distance = 0;
                int selected = 0;
                if (have_forward) {
                        *route = forward;
                        *target_offset = forward_target;
                        *destination_route_offset =
                                forward_destination;
                        selected_distance = forward_distance;
                        selected_cost = forward_cost;
                        selected = 1;
                }
                if (have_reversal &&
                    (!selected ||
                     reversal_distance < selected_distance ||
                     (reversal_distance == selected_distance &&
                      reversal_cost < selected_cost))) {
                        *route = reversal;
                        *target_offset = reversal_target;
                        *destination_route_offset =
                                reversal_destination;
                        selected_distance = reversal_distance;
                        selected_cost = reversal_cost;
                        selected = 1;
                }
                if (have_leading &&
                    (!selected ||
                     leading_distance < selected_distance ||
                     (leading_distance == selected_distance &&
                      leading_cost < selected_cost))) {
                        *route = leading;
                        *target_offset = leading_target;
                        *destination_route_offset =
                                leading_destination;
                        selected_distance = leading_distance;
                        selected_cost = leading_cost;
                        selected = 1;
                }
                if (!selected) return -1;
                *path_distance = selected_distance;
                *path_cost = selected_cost;
        } else if (have_forward) {
                *route = forward;
                *target_offset = forward_target;
                *destination_route_offset =
                        forward_destination;
                *path_distance = forward_distance;
                *path_cost = forward_cost;
        } else if (have_reversal) {
                *route = reversal;
                *target_offset = reversal_target;
                *destination_route_offset =
                        reversal_destination;
                *path_distance = reversal_distance;
                *path_cost = reversal_cost;
        } else {
                *route = leading;
                *target_offset = leading_target;
                *destination_route_offset =
                        leading_destination;
                *path_distance = leading_distance;
                *path_cost = leading_cost;
        }
        return 0;
}

static int routes_have_identical_nodes(
        const track_route *left,
        const track_route *right) {
        if (!left || !right ||
            left->node_count != right->node_count) {
                return 0;
        }
        for (int offset = 0;
             offset < left->node_count; ++offset) {
                if (left->nodes[offset] !=
                    right->nodes[offset]) {
                        return 0;
                }
        }
        return 1;
}

/*
 * Build prediction metadata only for ordinary, catalogued A-F dispatches.
 * CURRENT continuations depend on a live localization anchor, while the
 * supervised calibration command has its own deliberately provisional
 * execution path. Neither may inherit fixed-start transfer evidence.
 *
 * The route passed to the predictor ends at the geometry anchor. The
 * dispatch candidate itself remains extended through the physical endpoint,
 * conservative braking distance, train body, uncertainty, and turnout
 * branches by the existing authoritative safety-footprint logic.
 */
static int build_candidate_prediction_plan(
        const tc2_dispatch_job_snapshot *job,
        const track_route *candidate,
        int geometry_anchor_offset,
        int destination_side,
        tc2_prediction_plan *plan) {
        if (!job || !candidate || !plan ||
            job->provisional_prediction ||
            job->start_index < 0 ||
            job->start_index >= TC2_TRACK_START_COUNT ||
            destination_side < 0 ||
            destination_side >=
                    TC2_TRACK_DESTINATION_SIDE_COUNT) {
                return -1;
        }

        track_route geometry_route;
        if (build_route_slice(
                    candidate, 0, geometry_anchor_offset,
                    &geometry_route) < 0) {
                return -1;
        }
        tc2_prediction_request request;
        request.train = job->train;
        request.start_index = job->start_index;
        request.destination_index =
                job->destination_index;
        request.destination_side = destination_side;
        request.speed = job->speed;
        request.reversal_count =
                geometry_route.reversal_count;
        if (Tc2PredictionBuildPlan(
                    dispatch_track, &geometry_route,
                    &request, plan) != TC2_PREDICTION_OK) {
                return -1;
        }

        /*
         * The only exact motion profile is the measured canonical
         * T14/A/D7/no-reversal path. If a live block makes the dispatcher
         * choose another node sequence, retain the plan as transferred
         * inference rather than mislabelling it exact.
         */
        if (plan->exact_profile) {
                track_route canonical;
                int canonical_ok =
                        TrackFindShortestRoute(
                                dispatch_track,
                                geometry_route.nodes[0],
                                geometry_route.nodes[
                                        geometry_route.node_count - 1],
                                &canonical) == 0 &&
                        routes_have_identical_nodes(
                                &canonical,
                                &geometry_route);
                if (!canonical_ok) {
                        plan->exact_profile = 0;
                        plan->profile_evidence =
                                TC2_PREDICTION_PROFILE_TRANSFERRED_T14_A_D7;
                }
        }

        /*
         * This is only a consistency assertion. It can reject incomplete
         * graph coverage, but it can never reduce the physical reservation
         * that validate_and_guard_candidate already required.
         */
        if ((int64_t)candidate->distance_mm * 1000 <
            plan->minimum_reservation_ceiling_distance_um) {
                return -1;
        }
        return 0;
}

static int choose_shortest_available_route(
        int slot, const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors, track_route *selected,
        int *target_node, int *target_offset,
        int *destination_route_offset,
        int *destination_offset_value,
        int *destination_confirmed,
        int *path_distance,
        int *selected_side, int *estimated_ambiguity_blocked,
        int ignore_managed_traffic) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        util_zero_bytes(
                (volatile unsigned char *)
                        &runtime->prediction_plan,
                (unsigned int)sizeof(
                        runtime->prediction_plan));
        runtime->prediction_plan_valid = 0;
        clear_prediction_snapshot(job);
        unsigned char unavailable[TRACK_MAX];
        build_unavailable(
                slot, reservation, sensors, unavailable,
                ignore_managed_traffic);
        if (runtime->start_node < 0 || runtime->start_node >= TRACK_MAX ||
            unavailable[runtime->start_node] ||
            !estimated_ambiguity_blocked) {
                return -1;
        }
        *estimated_ambiguity_blocked = 0;

        int found = 0;
        int selected_cost = 0;
        for (int side = 0; side < 2; ++side) {
                const tc2_track_destination_side *side_definition =
                        Tc2TrackDestinationSide(
                                job->destination_index, side);
                if (!side_definition) continue;
                const char *name =
                        side_definition->anchor_sensor;
                int target = TrackFindNodeByName(dispatch_track, name);
                track_route candidate;
                int candidate_target_offset;
                int candidate_destination_offset;
                int candidate_distance;
                int candidate_cost;
                int candidate_hold_blocked = 0;
                tc2_prediction_plan candidate_prediction;
                int candidate_prediction_valid = 0;
                int virtual_offset =
                        side_definition->base_offset_mm;
                if (job->provisional_prediction &&
                    job->destination_index == 6 && side == 0) {
                        int correction =
                                Tc2MotionD7EndpointCorrectionMm(
                                        job->speed);
                        if (correction > 0 &&
                            virtual_offset >
                                    0x7fffffff - correction) {
                                continue;
                        }
                        virtual_offset += correction;
                        if (virtual_offset < 0) {
                                if (!side_definition
                                             ->previous_anchor_sensor ||
                                    side_definition
                                             ->previous_anchor_distance_mm <=
                                             0 ||
                                    virtual_offset <
                                    -side_definition
                                             ->previous_anchor_distance_mm) {
                                        continue;
                                }
                                name =
                                        side_definition
                                                ->previous_anchor_sensor;
                                target = TrackFindNodeByName(
                                        dispatch_track, name);
                                virtual_offset +=
                                        side_definition
                                                ->previous_anchor_distance_mm;
                        }
                }
                const char *straight_guide =
                        side_definition->straight_guide;
                int candidate_status =
                        job->start_index ==
                                        TC2_DISPATCH_START_CURRENT ?
                        candidate_route_for_current_hold(
                                runtime->start_node, target,
                                unavailable, job->speed,
                                virtual_offset,
                                straight_guide,
                                runtime->force_reverse_first,
                                runtime->reroute_select_direction,
                                runtime->retarget_direction_locked,
                                &runtime
                                         ->carry_ambiguity_footprint,
                                runtime
                                        ->carry_confirmed_turnouts_valid ?
                                &runtime
                                         ->carry_confirmed_turnouts :
                                0,
                                job->train,
                                reservation, sensors,
                                runtime
                                        ->head_on_recovery_active &&
                                runtime
                                        ->carry_ambiguity_active,
                                &candidate,
                                &candidate_target_offset,
                                &candidate_destination_offset,
                                &candidate_distance,
                                &candidate_cost,
                                &candidate_hold_blocked) :
                        candidate_route(
                                runtime->start_node, target,
                                unavailable, job->speed,
                                !runtime
                                         ->carry_position_estimated,
                                !job->provisional_prediction,
                                virtual_offset,
                                straight_guide,
                                &candidate,
                                &candidate_target_offset,
                                &candidate_destination_offset,
                                &candidate_distance,
                                &candidate_cost);
                if (target < 0 || unavailable[target] ||
                    candidate_status < 0) {
                        if (candidate_hold_blocked) {
                                *estimated_ambiguity_blocked = 1;
                        } else if (
                                target >= 0 &&
                                !unavailable[target] &&
                                runtime
                                        ->carry_position_estimated) {
                                /*
                                 * Distinguish a direction/topology limit
                                 * from a temporary foreign reservation or
                                 * operator block.  Only the former may start
                                 * another confirmed-direction localization
                                 * phase; if the forward candidate exists on
                                 * an otherwise clear graph, the live
                                 * unavailability is the reason and the train
                                 * must remain stopped in WAIT_ROUTE.
                                 */
                                unsigned char clear[TRACK_MAX];
                                for (int node = 0;
                                     node < TRACK_MAX; ++node) {
                                        clear[node] = 0;
                                }
                                track_route clear_candidate;
                                int clear_target_offset;
                                int clear_destination_offset;
                                int clear_distance;
                                int clear_cost;
                                if (candidate_route(
                                            runtime->start_node,
                                            target, clear,
                                            job->speed, 0, 1,
                                            virtual_offset,
                                            straight_guide,
                                            &clear_candidate,
                                            &clear_target_offset,
                                            &clear_destination_offset,
                                            &clear_distance,
                                            &clear_cost) < 0) {
                                        *estimated_ambiguity_blocked = 1;
                                }
                        }
                        continue;
                }
                int candidate_starts_with_reversal =
                        candidate.node_count >= 2 &&
                        candidate.reversal_count >= 1 &&
                        dispatch_track[candidate.nodes[0]].reverse ==
                                &dispatch_track[
                                        candidate.nodes[1]];
                int safe_leading_reversal =
                        (runtime->force_reverse_first ||
                         runtime->reroute_select_direction) &&
                        candidate_starts_with_reversal;
                int safe_later_reversal =
                        runtime->retarget_direction_locked &&
                        candidate.reversal_count >= 1 &&
                        !candidate_starts_with_reversal;
                if (runtime->carry_position_estimated &&
                    ((!safe_leading_reversal &&
                      !safe_later_reversal &&
                      candidate.reversal_count != 0) ||
                     !route_does_not_reenter_before_localization(
                              &candidate,
                              &runtime
                                       ->carry_ambiguity_footprint) ||
                     !initial_turnouts_clear_of_carried_ambiguity(
                              &candidate,
                              candidate_destination_offset,
                              &runtime
                                       ->carry_ambiguity_footprint,
                              runtime
                                      ->carry_confirmed_turnouts_valid ?
                              &runtime
                                       ->carry_confirmed_turnouts :
                              0))) {
                        *estimated_ambiguity_blocked = 1;
                        continue;
                }
                if (!job->provisional_prediction &&
                    job->start_index >= 0 &&
                    job->start_index <
                            TC2_TRACK_START_COUNT) {
                        if (build_candidate_prediction_plan(
                                    job, &candidate,
                                    candidate_target_offset,
                                    side,
                                    &candidate_prediction) < 0) {
                                continue;
                        }
                        candidate_prediction_valid = 1;
                }
                int candidate_is_better =
                        runtime->reroute_select_direction ?
                        (!found ||
                         candidate_distance < *path_distance ||
                         (candidate_distance == *path_distance &&
                          candidate_cost < selected_cost)) :
                        (!found || candidate_distance < *path_distance ||
                         (candidate_distance == *path_distance &&
                          candidate_cost < selected_cost));
                if (candidate_is_better) {
                        *selected = candidate;
                        *target_node = target;
                        *target_offset = candidate_target_offset;
                        *destination_route_offset =
                                candidate_destination_offset;
                        *destination_offset_value =
                                virtual_offset;
                        *destination_confirmed =
                                side_definition
                                        ->geometry_evidence ==
                                TC2_TRACK_GEOMETRY_CONFIRMED;
                        *path_distance = candidate_distance;
                        *selected_side = side;
                        selected_cost = candidate_cost;
                        if (candidate_prediction_valid) {
                                runtime->prediction_plan =
                                        candidate_prediction;
                                runtime->prediction_plan_valid =
                                        1;
                        } else {
                                util_zero_bytes(
                                        (volatile unsigned char *)
                                                &runtime
                                                        ->prediction_plan,
                                        (unsigned int)sizeof(
                                                runtime
                                                        ->prediction_plan));
                                runtime->prediction_plan_valid =
                                        0;
                        }
                        found = 1;
                }
        }
        return found ? 0 : -1;
}

static int second_sensor_after_origin(
        const track_route *route) {
        int count = 0;
        if (!route) return -1;
        for (int offset = 1;
             offset < route->node_count; ++offset) {
                if (dispatch_track[
                            route->nodes[offset]].type !=
                    NODE_SENSOR) {
                        continue;
                }
                if (++count == 2) return offset;
        }
        return -1;
}

static int choose_safe_localization_route(
        int slot,
        const unsigned char unavailable[TRACK_MAX],
        track_route *selected, int *target_node,
        int *target_offset, int *path_distance) {
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        track_route extended;
        int second;
        if (!runtime->carry_ambiguity_active ||
            !runtime->carry_confirmed_turnouts_valid ||
            runtime->carry_motion_origin_offset < 0 ||
            runtime->carry_motion_origin_offset >=
                    runtime->carry_motion_route.node_count ||
            build_route_slice(
                    &runtime->carry_motion_route,
                    runtime->carry_motion_origin_offset,
                    runtime->carry_motion_route.node_count - 1,
                    &extended) < 0 ||
            extended.reversal_count != 0) {
                return -1;
        }

        second = second_sensor_after_origin(&extended);
        for (int extension = 0;
             second < 0 && extension < 8; ++extension) {
                int before = extended.node_count;
                if (TrackExtendRouteAhead(
                            dispatch_track, &extended,
                            1000) < 0 ||
                    extended.node_count <= before) {
                        return -1;
                }
                second =
                        second_sensor_after_origin(&extended);
        }
        if (second < 0 ||
            build_route_slice(
                    &extended, 0, second, selected) < 0) {
                return -1;
        }

        int path_cost;
        int destination_route_offset;
        if (validate_and_guard_candidate(
                    unavailable, job->speed, 0, 0, selected,
                    target_offset, &destination_route_offset,
                    path_distance,
                    &path_cost) < 0 ||
            selected->reversal_count != 0 ||
            *target_offset < 1 ||
            destination_route_offset != *target_offset ||
            !route_does_not_reenter_before_localization(
                    selected,
                    &runtime->carry_ambiguity_footprint) ||
            !initial_turnouts_clear_of_carried_ambiguity(
                    selected, *target_offset,
                    &runtime->carry_ambiguity_footprint,
                    &runtime->carry_confirmed_turnouts)) {
                return -1;
        }
        (void)path_cost;
        *target_node =
                selected->nodes[*target_offset];
        return dispatch_track[*target_node].type ==
                       NODE_SENSOR ?
                0 : -1;
}

static int start_is_in_use(int start_index, int excluding_train) {
        if (start_index < 0) return 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                if (job->state == TC2_JOB_EMPTY ||
                    job->state == TC2_JOB_ARRIVED ||
                    job->train == excluding_train) {
                        continue;
                }
                /*
                 * A normal canceled train no longer occupies its original
                 * departure bay.  Its bounded static reservation—not the
                 * historical start label—is the only physical blocker.
                 */
                if (job->state == TC2_JOB_STOPPED &&
                    terminal_static_footprint_committed(slot)) {
                        continue;
                }
                if (job->start_index == start_index) return 1;
        }
        return 0;
}

static int snapshot_owned_footprint(
        int train, unsigned int expected_generation,
        int expected_destination, int required_node,
        track_route *owned) {
        track_reservation_snapshot reservation;
        if (!owned || train < 1 || train > 255 ||
            expected_generation == 0 ||
            required_node < 0 || required_node >= TRACK_MAX ||
            TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            reservation.generation_by_train[train] !=
                    expected_generation ||
            reservation.destination_by_train[train] !=
                    expected_destination) {
                return -1;
        }
        owned->node_count = 0;
        owned->distance_mm = 0;
        owned->optimization_cost_mm = 0;
        owned->reversal_count = 0;
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (reservation.owner_by_node[node] == train &&
                    append_unique_node(owned, node) < 0) {
                        return -1;
                }
        }
        return owned->node_count > 0 &&
                       route_contains_node(owned, required_node) ?
                0 : -1;
}

static int stage_job(const tc2_dispatch_request *request) {
        int provisional =
                request->type ==
                TC2_DISPATCH_MSG_STAGE_CALIBRATION;
        int force_reverse_first =
                (request->reserved &
                 TC2_DISPATCH_REQUEST_FORCE_REVERSE_FIRST) != 0;
        int operator_reroute =
                (request->reserved &
                 TC2_DISPATCH_REQUEST_OPERATOR_REROUTE) != 0;
        if (request->train < 1 || request->train > 255 ||
            request->speed < 1 || request->speed > 120 ||
            request->destination_index < 0 ||
            request->destination_index >= TC2_DISPATCH_DESTINATION_COUNT ||
            (request->type != TC2_DISPATCH_MSG_STAGE &&
             !provisional) ||
            (request->reserved &
             ~TC2_DISPATCH_REQUEST_STAGE_FLAGS) != 0 ||
            (force_reverse_first &&
             (provisional ||
              request->start_index !=
                      TC2_DISPATCH_START_CURRENT)) ||
            (operator_reroute &&
             (provisional || force_reverse_first ||
              request->start_index !=
                      TC2_DISPATCH_START_CURRENT)) ||
            (request->start_index != TC2_DISPATCH_START_CURRENT &&
             (request->start_index < 0 ||
              request->start_index >= TC2_DISPATCH_START_COUNT))) {
                return -1;
        }
        /*
         * The physically fitted calibration profile is still restricted to
         * one supervised T14/A/D7 run.  Do not let it share reservations or
         * transfer its point fit to an ordinary concurrently managed trip.
         */
        if ((provisional &&
             (request->train != 14 ||
              request->start_index != 0 ||
              request->destination_index != 6 ||
              has_any_job())) ||
            (!provisional && !operator_reroute &&
             has_provisional_job())) {
                return -1;
        }
        int slot = find_train_job(request->train);
        /*
         * Public reroute is an intent on the existing physical train, not a
         * second job and not an immediate CURRENT replacement.  Recording it
         * must not touch the live route, its owners, a turnout, or motor
         * speed.  `go` arms the intent; process_pending_retargets() then makes
         * the old train stationary and bounded before it installs a fresh
         * CURRENT plan.  The internal transactional stage below sets
         * dispatch_retarget_candidate_pre_cas and therefore bypasses this
         * intent-only entry exactly once.
         */
        if (operator_reroute &&
            !dispatch_retarget_candidate_pre_cas) {
                if (slot < 0 ||
                    dispatch_jobs[slot].state == TC2_JOB_EMPTY ||
                    dispatch_runtime[slot]
                                    .lifecycle_stop_reason ==
                            TC2_LIFECYCLE_STOP_REMOVE_PENDING) {
                        return -1;
                }
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                /*
                 * A newer operator request supersedes any older staged or
                 * armed destination.  Do not, however, forget a physical
                 * reverse which has already been sent: its settle deadline
                 * and resulting direction are facts about the train, not
                 * future authority owned by the old route.
                 */
                int reverse_pending =
                        runtime->retarget_reverse_pending;
                int reverse_ready_at_tick =
                        runtime->retarget_reverse_ready_at_tick;
                int direction_locked =
                        runtime->retarget_direction_locked;
                int direction_anchor_node =
                        runtime->retarget_direction_anchor_node;
                unsigned int direction_anchor_sequence =
                        runtime->retarget_direction_anchor_sequence;
                runtime->retarget_pending = 1;
                runtime->retarget_armed = 0;
                runtime->retarget_speed = request->speed;
                runtime->retarget_destination_index =
                        request->destination_index;
                runtime->retarget_expected_generation =
                        dispatch_jobs[slot].plan_generation;
                runtime->retarget_expected_destination =
                        dispatch_jobs[slot].target_node;
                runtime->retarget_queue_sequence = 0;
                runtime->retarget_launch_epoch = 0;
                runtime->retarget_force_reverse_first = 0;
                runtime->retarget_operator_reroute = 1;
                runtime->retarget_reverse_pending = reverse_pending;
                runtime->retarget_reverse_ready_at_tick =
                        reverse_pending ? reverse_ready_at_tick : -1;
                runtime->retarget_direction_locked = direction_locked;
                runtime->retarget_direction_anchor_node =
                        direction_anchor_node;
                runtime->retarget_direction_anchor_sequence =
                        direction_anchor_sequence;
                return 0;
        }
        int current_node = -1;
        unsigned int current_generation = 0;
        int current_destination = -1;
        int current_speed = 0;
        train_sensor_snapshot_t stage_sensors;
        unsigned int stage_attributed_sequence = 0;
        int stage_sensor_baseline_valid = 0;
        track_route carry_ambiguity;
        int carry_ambiguity_active = 0;
        int carry_position_estimated = 0;
        track_turnout_plan carry_confirmed_turnouts;
        int carry_confirmed_turnouts_valid = 0;
        track_route carry_motion_route;
        int carry_motion_origin_offset = -1;
        int carry_preorigin_distance_mm = 0;
        int carry_head_on_recovery = 0;
        int carry_last_accepted_sensor_node = -1;
        unsigned int carry_last_accepted_sensor_sequence = 0;
        int current_from_arrived = 0;
        int current_from_cancelled_block = 0;
        int carry_conflict_zone_count = 0;
        int carry_conflict_zone[TC2_CONFLICT_ZONE_COUNT];
        int carry_conflict_zone_entry[TC2_CONFLICT_ZONE_COUNT];
        int carry_conflict_zone_exit[TC2_CONFLICT_ZONE_COUNT];
        int carry_conflict_zone_exit_distance[
                TC2_CONFLICT_ZONE_COUNT];
        unsigned int carry_conflict_zone_ticket[TC2_CONFLICT_ZONE_COUNT];
        unsigned int carry_conflict_zone_route_generation[
                TC2_CONFLICT_ZONE_COUNT];
        unsigned char carry_conflict_zone_mode[TC2_CONFLICT_ZONE_COUNT];
        if (request->start_index ==
                    TC2_DISPATCH_START_CURRENT &&
            slot >= 0 &&
            dispatch_jobs[slot].state ==
                    TC2_JOB_TRAFFIC_HOLD) {
                tc2_dispatch_job_snapshot *held_job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *held_runtime =
                        &dispatch_runtime[slot];
                int now = Time();
                dispatch_retarget_runtime_backup =
                        *held_runtime;
                int health_status =
                        now >= 0 ?
                        can_health_is_safe(
                                slot, 0, now) : -1;
                /*
                 * Health sampling updates heartbeat baselines for ordinary
                 * state-machine transitions.  Staging a pending recovery is
                 * deliberately read-only, so restore those bookkeeping
                 * fields before recording only the pending intent.
                 */
                *held_runtime =
                        dispatch_retarget_runtime_backup;
                if (!held_job->hold_active ||
                    !held_job->traffic_hold_active ||
                    held_job->plan_generation == 0 ||
                    held_job->target_node < 0 ||
                    held_job->current_node < 0 ||
                    held_runtime->stop_purpose !=
                            TC2_STOP_TRAFFIC ||
                    held_runtime->traffic_hold_distance_um < 0 ||
                    held_runtime->command_speed != 0 ||
                    held_runtime->retarget_armed ||
                    now < 0 ||
                    health_status < 0) {
                        return -1;
                }
                /*
                 * Only record intent.  In particular, do not invalidate the
                 * live projection, clear the HEAD_ON/FOLLOWING latch, send a
                 * turnout command, or alter one reservation owner here.
                 */
                held_runtime->retarget_pending = 1;
                held_runtime->retarget_speed =
                        request->speed;
                held_runtime->retarget_destination_index =
                        request->destination_index;
                held_runtime
                        ->retarget_expected_generation =
                        held_job->plan_generation;
                held_runtime
                        ->retarget_expected_destination =
                        held_job->target_node;
                held_runtime->retarget_queue_sequence = 0;
                held_runtime->retarget_launch_epoch = 0;
                held_runtime->retarget_force_reverse_first =
                        force_reverse_first;
                held_runtime->retarget_operator_reroute = 0;
                held_runtime->retarget_reverse_pending = 0;
                held_runtime->retarget_reverse_ready_at_tick = -1;
                held_runtime->retarget_direction_locked = 0;
                held_runtime->retarget_direction_anchor_node = -1;
                held_runtime->retarget_direction_anchor_sequence = 0;
                return 0;
        }
        if (request->start_index == TC2_DISPATCH_START_CURRENT) {
                if (slot >= 0) {
                        current_from_arrived =
                                dispatch_jobs[slot].state ==
                                        TC2_JOB_ARRIVED;
                        current_from_cancelled_block =
                                dispatch_jobs[slot].state ==
                                                TC2_JOB_STOPPED &&
                                (dispatch_runtime[slot]
                                                 .lifecycle_stop_reason ==
                                         TC2_LIFECYCLE_STOP_OPERATOR_CANCEL ||
                                 (operator_reroute &&
                                  dispatch_runtime[slot]
                                                  .lifecycle_stop_reason ==
                                          TC2_LIFECYCLE_STOP_REROUTE)) &&
                                terminal_static_footprint_committed(slot) &&
                                !dispatch_runtime[slot]
                                                .movement_plan_active &&
                                dispatch_runtime[slot].route_valid &&
                                dispatch_jobs[slot].command_speed == 0 &&
                                dispatch_runtime[slot].command_speed == 0 &&
                                dispatch_runtime[slot]
                                                .launch_batch_token == 0 &&
                                dispatch_runtime[slot]
                                                .turnout_batch_token == 0 &&
                                dispatch_runtime[slot]
                                                .conflict_zone_batch_token ==
                                        0 &&
                                dispatch_runtime[slot]
                                                .conflict_zone_soft_batch_token ==
                                        0 &&
                                dispatch_runtime[slot]
                                                .emergency_stop_token == 0 &&
                                !dispatch_runtime[slot]
                                                .turnout_queue_pending &&
                                !dispatch_runtime[slot]
                                                .conflict_zone_plan_valid &&
                                dispatch_runtime[slot]
                                                .conflict_zone_carry_count ==
                                        0 &&
                                dispatch_runtime[slot]
                                                .conflict_zone_hard_ticket ==
                                        0 &&
                                dispatch_runtime[slot]
                                                .conflict_zone_soft_ticket ==
                                        0;
                }
                if (slot < 0 ||
                    (!current_from_arrived &&
                     !current_from_cancelled_block) ||
                    !dispatch_jobs[slot].hold_active ||
                    dispatch_jobs[slot].current_node < 0) {
                        return -1;
                }
                current_node = dispatch_jobs[slot].current_node;
                current_generation = dispatch_jobs[slot].plan_generation;
                current_destination =
                        dispatch_jobs[slot].target_node;
                current_speed = dispatch_jobs[slot].speed;
                carry_head_on_recovery =
                        dispatch_runtime[slot].stop_purpose ==
                                TC2_STOP_TRAFFIC &&
                        dispatch_runtime[slot].traffic_reason ==
                                TC2_TRAFFIC_HEAD_ON;
                if (current_generation == 0 ||
                    current_destination < 0 ||
                    can_health_is_safe(
                            slot, 0, Time()) < 0 ||
                    TrainSensorGetLatest(
                            dispatch_sensor_tid,
                            &stage_sensors) < 0) {
                        return -1;
                }
                stage_attributed_sequence =
                        stage_sensors.attributed_count;
                stage_sensor_baseline_valid = 1;
                carry_position_estimated =
                        dispatch_jobs[slot]
                                .position_estimated;
                if (snapshot_owned_footprint(
                            request->train,
                            current_generation,
                            current_destination,
                            current_node,
                            &carry_ambiguity) < 0) {
                        return -1;
                }
                carry_ambiguity_active = 1;
                tc2_dispatch_runtime *old_runtime =
                        &dispatch_runtime[slot];
                carry_last_accepted_sensor_node =
                        old_runtime->last_accepted_sensor_node;
                carry_last_accepted_sensor_sequence =
                        old_runtime->last_accepted_sensor_sequence;
                /*
                 * Preserve physical ownership before clear_runtime() erases
                 * the old route geometry.  This is bookkeeping only: no
                 * owner or waiter changes until the replacement reservation
                 * commits below.
                 */
                if (snapshot_owned_conflict_zone_carries(slot) < 0) {
                        return -1;
                }
                carry_conflict_zone_count =
                        old_runtime->conflict_zone_carry_count;
                for (int index = 0;
                     index < carry_conflict_zone_count; ++index) {
                        carry_conflict_zone[index] =
                                old_runtime->conflict_zone_carry_zone[index];
                        carry_conflict_zone_entry[index] =
                                old_runtime
                                        ->conflict_zone_carry_entry_node[index];
                        carry_conflict_zone_exit[index] =
                                old_runtime
                                        ->conflict_zone_carry_exit_node[index];
                        carry_conflict_zone_exit_distance[index] =
                                old_runtime
                                        ->conflict_zone_carry_exit_distance_mm[
                                                index];
                        carry_conflict_zone_ticket[index] =
                                old_runtime
                                        ->conflict_zone_carry_ticket[index];
                        carry_conflict_zone_route_generation[index] =
                                old_runtime
                                  ->conflict_zone_carry_route_generation[
                                          index];
                        carry_conflict_zone_mode[index] =
                                old_runtime
                                        ->conflict_zone_carry_mode[index];
                }
                if (!old_runtime->route_valid ||
                    dispatch_jobs[slot]
                            .current_route_offset < 0 ||
                    dispatch_jobs[slot]
                            .current_route_offset >=
                            old_runtime->route.node_count ||
                    (!operator_reroute &&
                     build_turnout_plan_range_checked(
                            &old_runtime->route,
                            old_runtime->leg_start_offset,
                            old_runtime->route.node_count - 1,
                            &carry_confirmed_turnouts) < 0)) {
                        return -1;
                }
                if ((force_reverse_first || operator_reroute) &&
                    carry_position_estimated &&
                    old_runtime->static_center_bounds_valid &&
                    old_runtime->monitor.confirmed_distance_mm >= 0) {
                        int64_t confirmed_um =
                                (int64_t)old_runtime->monitor
                                        .confirmed_distance_mm * 1000;
                        int64_t preorigin_um =
                                old_runtime->static_center_upper_um -
                                confirmed_um;
                        if (preorigin_um > 0 &&
                            preorigin_um <=
                                    (int64_t)0x7fffffff * 1000) {
                                carry_preorigin_distance_mm =
                                        (int)((preorigin_um + 999) / 1000);
                        }
                } else if (force_reverse_first &&
                           carry_position_estimated &&
                           dispatch_jobs[slot].destination_offset_mm > 0 &&
                           dispatch_jobs[slot].current_route_offset ==
                                   dispatch_jobs[slot]
                                           .target_route_offset) {
                        int raw_current_distance_mm;
                        if (Tc2RouteDistanceAtOffset(
                                    dispatch_track,
                                    &old_runtime->route,
                                    dispatch_jobs[slot]
                                            .current_route_offset,
                                    &raw_current_distance_mm) < 0) {
                                return -1;
                        }
                        int virtual_prefix_mm =
                                dispatch_jobs[slot]
                                        .destination_distance_mm -
                                raw_current_distance_mm;
                        /*
                         * This narrow carry is valid only for the modeled
                         * interior endpoint immediately downstream of its
                         * anchor detector.  Any other estimated hold keeps the
                         * existing ambiguity/localization path instead of
                         * inventing a negative route scalar.
                         */
                        if (virtual_prefix_mm > 0 &&
                            virtual_prefix_mm ==
                                    dispatch_jobs[slot]
                                            .destination_offset_mm) {
                                carry_preorigin_distance_mm =
                                        virtual_prefix_mm;
                        }
                }
                if (current_from_arrived &&
                    !operator_reroute &&
                    carry_position_estimated &&
                    old_runtime->stop_purpose !=
                            TC2_STOP_TRAFFIC) {
                        /*
                         * The reservation also owns braking guards and
                         * paired-turnout resources that the train cannot
                         * physically occupy.  Keep that complete reservation
                         * live until localization, but use only the travelled
                         * corridor from the last trusted sensor through the
                         * virtual endpoint as the position ambiguity set.
                         * Otherwise a virtual endpoint that crosses a turnout
                         * can falsely place the train on an adjacent protected
                         * branch and make every safe CURRENT route appear
                         * blocked.
                         */
                        int ambiguity_first =
                                old_runtime
                                        ->reservation_anchor_offset;
                        int ambiguity_last =
                                dispatch_jobs[slot]
                                        .destination_route_offset;
                        if (ambiguity_first < 0 ||
                            ambiguity_first >
                                    dispatch_jobs[slot]
                                            .current_route_offset) {
                                ambiguity_first =
                                        dispatch_jobs[slot]
                                                .current_route_offset;
                        }
                        if (ambiguity_last <
                                    dispatch_jobs[slot]
                                            .current_route_offset ||
                            ambiguity_last >=
                                    old_runtime->route.node_count ||
                            build_route_slice(
                                    &old_runtime->route,
                                    ambiguity_first,
                                    ambiguity_last,
                                    &carry_ambiguity) < 0 ||
                            !route_contains_node(
                                    &carry_ambiguity,
                                    current_node)) {
                                return -1;
                        }
                }
                carry_confirmed_turnouts_valid =
                        operator_reroute ? 0 : 1;
                carry_motion_route =
                        old_runtime->route;
                carry_motion_origin_offset =
                        current_from_cancelled_block ?
                        old_runtime->monitor.confirmed_offset :
                        dispatch_jobs[slot]
                                .current_route_offset;
        } else {
                if (start_is_in_use(request->start_index, request->train)) {
                        return -1;
                }
                if (slot >= 0) {
                        /*
                         * A CURRENT trip carries a live destination hold.
                         * Never let a later fixed-bay command overwrite that
                         * managed position and eventually replace the
                         * reservation under the physical train.
                         */
                        if (dispatch_jobs[slot].plan_generation != 0 ||
                            dispatch_jobs[slot].hold_active ||
                            dispatch_jobs[slot].start_index ==
                                    TC2_DISPATCH_START_CURRENT ||
                            (dispatch_jobs[slot].state !=
                                             TC2_JOB_STAGED &&
                             dispatch_jobs[slot].state !=
                                             TC2_JOB_WAITING)) {
                                return -1;
                        }
                }
        }
        if (slot < 0) slot = find_empty_job();
        if (slot < 0 ||
            CanTrainSetSpeed(dispatch_can_tid, request->train, 0) < 0) {
                return -1;
        }

        /*
         * A successful re-stage begins a new logical route epoch.  Invalidate
         * the prior immutable publication before clearing and rebuilding the
         * slot so stale page tokens cannot be spliced into the new route.
         */
        invalidate_projection(slot);
        clear_job(&dispatch_jobs[slot]);
        clear_runtime(&dispatch_runtime[slot]);
        dispatch_runtime[slot].conflict_zone_carry_count =
                carry_conflict_zone_count;
        for (int index = 0;
             index < carry_conflict_zone_count; ++index) {
                dispatch_runtime[slot].conflict_zone_carry_zone[index] =
                        carry_conflict_zone[index];
                dispatch_runtime[slot]
                        .conflict_zone_carry_entry_node[index] =
                        carry_conflict_zone_entry[index];
                dispatch_runtime[slot]
                        .conflict_zone_carry_exit_node[index] =
                        carry_conflict_zone_exit[index];
                dispatch_runtime[slot]
                        .conflict_zone_carry_exit_distance_mm[index] =
                        carry_conflict_zone_exit_distance[index];
                /*
                 * A CURRENT plan has a new route-distance origin.  The old
                 * physical owner remains, but its old scalar must never be
                 * compared with the new monitor.  Sensor-confirmed graph
                 * geometry will retire it safely instead.
                 */
                dispatch_runtime[slot]
                        .conflict_zone_carry_scalar_proof_valid[index] = 0;
                dispatch_runtime[slot]
                        .conflict_zone_carry_ticket[index] =
                        carry_conflict_zone_ticket[index];
                dispatch_runtime[slot]
                        .conflict_zone_carry_route_generation[index] =
                        carry_conflict_zone_route_generation[index];
                dispatch_runtime[slot]
                        .conflict_zone_carry_mode[index] =
                        carry_conflict_zone_mode[index];
        }
        /*
         * A CURRENT route may carry only proved physical occupancy.  CAN
         * batch tokens and per-action cursors belong to the old immutable
         * route generation and must never be resurrected after clear_runtime.
         */
        /* Every CURRENT/reroute plan starts a fresh CAN health epoch. */
        dispatch_jobs[slot].train = request->train;
        dispatch_jobs[slot].start_index = request->start_index;
        dispatch_jobs[slot].speed = request->speed;
        dispatch_jobs[slot].destination_index =
                request->destination_index;
        dispatch_jobs[slot].state = TC2_JOB_STAGED;
        dispatch_jobs[slot].provisional_prediction =
                provisional;
        if (provisional) {
                dispatch_jobs[slot]
                        .prediction_velocity_um_per_tick =
                        Tc2MotionProvisionalVelocityUmPerTick(
                                request->speed);
                dispatch_jobs[slot]
                        .prediction_stop_distance_um =
                        Tc2MotionProvisionalStopDistanceUm(
                                request->speed);
                dispatch_jobs[slot]
                        .prediction_stop_distance_mm =
                        Tc2MotionProvisionalStopDistanceMm(
                                request->speed);
                if (dispatch_jobs[slot]
                                .prediction_velocity_um_per_tick < 1 ||
                    dispatch_jobs[slot]
                                .prediction_stop_distance_um < 0 ||
                    dispatch_jobs[slot]
                                .prediction_stop_distance_mm < 0) {
                        clear_job(&dispatch_jobs[slot]);
                        clear_runtime(&dispatch_runtime[slot]);
                        return -1;
                }
        }
        dispatch_jobs[slot].current_node = current_node;
        dispatch_jobs[slot].plan_generation = current_generation;
        dispatch_jobs[slot].hold_active =
                request->start_index == TC2_DISPATCH_START_CURRENT;
        dispatch_runtime[slot].start_node =
                request->start_index == TC2_DISPATCH_START_CURRENT ?
                        current_node :
                        TrackFindNodeByName(
                                dispatch_track,
                                Tc2DispatchStartNodeName(
                                        request->start_index));
        if (request->start_index ==
            TC2_DISPATCH_START_CURRENT) {
                dispatch_runtime[slot].replace_plan_expected = 1;
                dispatch_runtime[slot]
                        .replace_expected_generation =
                        current_generation;
                dispatch_runtime[slot]
                        .replace_expected_destination =
                        current_destination;
                dispatch_runtime[slot]
                        .stage_attributed_sequence =
                        stage_attributed_sequence;
                dispatch_runtime[slot]
                        .stage_sensor_baseline_valid =
                        stage_sensor_baseline_valid;
                /*
                 * CURRENT replacement retires an old movement plan, not the
                 * physical localization evidence which made that replacement
                 * safe.  Raw journal sequence is deliberately not carried:
                 * only the last detector observation accepted by the old
                 * monitor may anchor a public reroute or one physical reverse.
                 */
                dispatch_runtime[slot].last_accepted_sensor_node =
                        carry_last_accepted_sensor_node;
                dispatch_runtime[slot].last_accepted_sensor_sequence =
                        carry_last_accepted_sensor_sequence;
        }
        if (carry_ambiguity_active) {
                dispatch_runtime[slot].carry_ambiguity_footprint =
                        carry_ambiguity;
                dispatch_runtime[slot].carry_ambiguity_active = 1;
                dispatch_runtime[slot].carry_position_estimated =
                        carry_position_estimated;
                dispatch_runtime[slot].carry_previous_speed =
                        current_speed;
                dispatch_runtime[slot]
                        .carry_preorigin_distance_mm =
                        carry_preorigin_distance_mm;
                if (carry_confirmed_turnouts_valid) {
                        dispatch_runtime[slot]
                                .carry_confirmed_turnouts =
                                carry_confirmed_turnouts;
                        dispatch_runtime[slot]
                                .carry_confirmed_turnouts_valid = 1;
                        dispatch_runtime[slot]
                                .carry_motion_route =
                                carry_motion_route;
                        dispatch_runtime[slot]
                                .carry_motion_origin_offset =
                                carry_motion_origin_offset;
                }
                dispatch_jobs[slot].position_estimated =
                        carry_position_estimated;
        }
        dispatch_runtime[slot].head_on_recovery_active =
                carry_head_on_recovery;
        dispatch_runtime[slot].head_on_recovery_cleared = 0;
        dispatch_runtime[slot].force_reverse_first =
                force_reverse_first;
        dispatch_runtime[slot].reroute_select_direction =
                operator_reroute;
        dispatch_runtime[slot].planned_launch_speed =
                carry_position_estimated &&
                        current_speed < request->speed ?
                current_speed : request->speed;
        return dispatch_runtime[slot].start_node >= 0 ? 0 : -1;
}

/*
 * Production-only admission boundary.  Keep stage_job generic so the route,
 * reservation, and recovery core can be exercised with synthetic train
 * addresses, but never let an uncommissioned locomotive reach that core from
 * the live server.  This wrapper is intentionally small and directly
 * testable: a rejected request cannot allocate a job, reserve track, or emit
 * speed/turnout CAN traffic because stage_job is never entered.
 */
static int production_stage_job(const tc2_dispatch_request *request) {
        if (!request ||
            !dispatch_train_is_supported(request->train)) {
                return -1;
        }
        return stage_job(request);
}

static int block_node(int node, int blocked) {
        if (node < 0 || node >= TRACK_MAX ||
            dispatch_track[node].type == NODE_NONE) {
                return -1;
        }
        int reverse = physical_reverse_index(node);
        if (blocked) {
                track_reservation_snapshot snapshot;
                train_sensor_snapshot_t sensors;
                if (TrackReservationServerSnapshot(
                            dispatch_reservation_tid, &snapshot) < 0 ||
                    TrainSensorGetLatest(
                            dispatch_sensor_tid, &sensors) < 0 ||
                    snapshot.owner_by_node[node] != 0 ||
                    (reverse >= 0 &&
                     snapshot.owner_by_node[reverse] != 0) ||
                    (node < TRAIN_SENSOR_COUNT &&
                     sensors.sensor_state[node]) ||
                    (reverse >= 0 &&
                     reverse < TRAIN_SENSOR_COUNT &&
                     sensors.sensor_state[reverse])) {
                        return -1;
                }
        }
        dispatch_blocked_by_node[node] = blocked ? 1 : 0;
        if (reverse >= 0) {
                dispatch_blocked_by_node[reverse] = blocked ? 1 : 0;
        }
        return 0;
}

static int last_sensor_after(const track_route *route, int offset) {
        int last = -1;
        for (int next = offset + 1;
             next < route->node_count; ++next) {
                if (dispatch_track[route->nodes[next]].type ==
                    NODE_SENSOR) {
                        last = next;
                }
        }
        return last;
}

static int sensor_before_offset(
        const track_route *route, int offset) {
        if (!route || offset < 1 ||
            offset > route->node_count) {
                return -1;
        }
        for (int prior = offset - 1;
             prior >= 0; --prior) {
                if (dispatch_track[
                            route->nodes[prior]].type ==
                    NODE_SENSOR) {
                        return prior;
                }
        }
        return -1;
}

static int init_leg_monitor(int slot, unsigned int baseline_sequence) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        runtime->leg_end_offset = TrackRouteMotionLegEnd(
                dispatch_track, &runtime->route,
                runtime->leg_start_offset);
        if (runtime->leg_end_offset >
            job->destination_route_offset) {
                runtime->leg_end_offset =
                        job->destination_route_offset;
        }
        if (runtime->leg_end_offset < runtime->leg_start_offset ||
            runtime->leg_end_offset >
                    job->destination_route_offset) {
                return -1;
        }
        runtime->monitor_terminal_offset = runtime->leg_end_offset;
        if (runtime->leg_end_offset ==
            job->destination_route_offset) {
                int guard_sensor = last_sensor_after(
                        &runtime->route,
                        job->destination_route_offset);
                if (guard_sensor >= 0) {
                        runtime->monitor_terminal_offset = guard_sensor;
                }
        }
        if (Tc2RouteMonitorInit(
                    dispatch_track, &runtime->route,
                    runtime->leg_start_offset,
                    runtime->monitor_terminal_offset,
                    baseline_sequence, &runtime->monitor) < 0) {
                return -1;
        }
        runtime->last_journal_sequence = baseline_sequence;
        /*
         * A CURRENT plan begins at the latest confirmed real detector.  If
         * that physical detector is also the selected destination anchor,
         * its event was necessarily consumed before this new monitor was
         * created and cannot be expected a second time.  Carry that real
         * evidence into the new generation so a reroute from A15/A16 toward
         * d1 starts the remaining bounded endpoint approach instead of
         * chasing the opposite-side A11/A12 detector.  Directed halves of
         * one detector are intentionally equivalent here; route direction
         * and turnout authority remain enforced independently.
         */
        int origin_node =
                runtime->route.nodes[runtime->leg_start_offset];
        int target_at_confirmed_current_origin =
                job->start_index == TC2_DISPATCH_START_CURRENT &&
                !runtime->localization_only &&
                job->destination_offset_mm > 0 &&
                job->target_route_offset ==
                        runtime->leg_start_offset &&
                (origin_node == job->target_node ||
                 physical_reverse_index(origin_node) ==
                        job->target_node);
        runtime->target_seen =
                target_at_confirmed_current_origin;
        runtime->target_corroborated =
                target_at_confirmed_current_origin;
        runtime->reservation_anchor_offset =
                runtime->leg_start_offset;
        runtime->pending_missing_offset = -1;
        job->current_route_offset = runtime->leg_start_offset;
        job->current_node =
                runtime->route.nodes[runtime->leg_start_offset];
        if (Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    runtime->leg_start_offset,
                    &job->confirmed_distance_mm) < 0) {
                return -1;
        }
        runtime->motion_anchor_distance_um =
                (int64_t)job->confirmed_distance_mm * 1000;
        runtime->motion_anchor_tick = -1;
        runtime->motion_anchor_from_traffic = 0;
        return 0;
}

static int effective_confirmed_distance_mm(
        const tc2_dispatch_runtime *runtime,
        int *distance_mm) {
        if (!runtime || !distance_mm) return -1;
        if (runtime->preorigin_sensor_pending) {
                if (runtime->preorigin_distance_mm <= 0) return -1;
                *distance_mm = -runtime->preorigin_distance_mm;
                return 0;
        }
        if (runtime->monitor.confirmed_distance_mm < 0) return -1;
        *distance_mm = runtime->monitor.confirmed_distance_mm;
        return 0;
}

/*
 * A stopped train has two deliberately different route scalars:
 *
 *   confirmed_distance_mm       latest real detector evidence
 *   traffic_hold_distance_um    conservative command-to-rest upper bound
 *
 * The former determines how much of the requested trip is still unobserved;
 * the latter determines whether a proposed movement-authority window can
 * contain the complete physical stop.  Keeping the distinction in one
 * helper prevents a repeated traffic stop from turning accumulated coast
 * uncertainty into false localization at the destination.
 *
 * A forced reverse can still be before route[0].  Its private upper bound is
 * negative until the origin detector fires; callers which need the ordinary
 * nonnegative route scalar must round and clamp that value to zero.
 */
static int traffic_hold_progress_bounds(
        int slot, int *trusted_progress_mm,
        int64_t *occupancy_upper_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !trusted_progress_mm || !occupancy_upper_um) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        int trusted_mm;
        if (job->destination_distance_mm < 0 ||
            effective_confirmed_distance_mm(
                    runtime, &trusted_mm) < 0) {
                return -1;
        }
        int64_t upper_um =
                runtime->preorigin_sensor_pending &&
                        runtime->preorigin_traffic_hold_valid ?
                runtime->preorigin_traffic_hold_distance_um :
                runtime->traffic_hold_distance_um;
        int64_t trusted_um = (int64_t)trusted_mm * 1000;
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        if (upper_um < trusted_um ||
            upper_um > destination_um) {
                return -1;
        }
        *trusted_progress_mm = trusted_mm;
        *occupancy_upper_um = upper_um;
        return 0;
}

static void update_next_sensor(int slot) {
        tc2_route_sensor_point next;
        tc2_route_sensor_point next_next;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (runtime->preorigin_sensor_pending) {
                int origin = runtime->leg_start_offset;
                job->next_sensor_node =
                        origin >= 0 &&
                        origin < runtime->route.node_count &&
                        dispatch_track[
                                runtime->route.nodes[origin]].type ==
                                NODE_SENSOR ?
                        runtime->route.nodes[origin] : -1;
                return;
        }
        if (!runtime->localization_only &&
            job->destination_offset_mm > 0 &&
            runtime->target_seen) {
                job->next_sensor_node = -1;
                return;
        }
        int count = Tc2RouteExpectedSensors(
                dispatch_track, &runtime->route,
                runtime->monitor.confirmed_offset,
                runtime->monitor_terminal_offset, &next, &next_next);
        (void)next_next;
        job->next_sensor_node = count > 0 ? next.node_index : -1;
}

/*
 * The physically accepted train-14 stopping curve is independent of the
 * departure siding. Every catalogued A-F -> d1-d8 trip therefore keeps the
 * requested command speed and issues zero exactly one measured
 * command-to-rest distance before the endpoint. The same curve is the
 * provisional seed for T15/T17/T18 until each locomotive is measured;
 * routing, sensor rebasing, and turnout preparation are already train
 * independent and remain specific to the selected shortest forward route.
 */
static int uses_measured_direct_stop(
        const tc2_dispatch_job_snapshot *job) {
        return job &&
                ((job->start_index >= 0 &&
                  job->start_index < TC2_DISPATCH_START_COUNT) ||
                 job->start_index == TC2_DISPATCH_START_CURRENT) &&
                job->destination_index >= 0 &&
                job->destination_index <
                        TC2_DISPATCH_DESTINATION_COUNT;
}

/* Any zero-offset endpoint is exactly at its selected physical detector. */
static int uses_exact_destination_sensor_stop(
        const tc2_dispatch_job_snapshot *job) {
        return uses_measured_direct_stop(job) &&
                job->destination_offset_mm == 0;
}

/*
 * d3 and d8 are bounded by a real detector on either physical approach. Treat
 * the first directed report from that selected boundary as terminal evidence:
 * once the locomotive has crossed the detector it must remain at speed zero,
 * rather than starting a second speed-40 virtual-offset approach.  Keep this
 * separate from uses_exact_destination_sensor_stop(); their catalogue offsets
 * are non-zero and must not relax the ordinary pre-sensor braking-anchor rule.
 */
static int destination_boundary_sensor_ends_trip(
        const tc2_dispatch_job_snapshot *job) {
        return uses_exact_destination_sensor_stop(job) ||
                (uses_measured_direct_stop(job) &&
                 (job->destination_index == 2 ||
                  job->destination_index == 7));
}

/*
 * Keep physical endpoint calibration separate from the conservative traffic
 * envelope.  After rolling-authority/traffic scheduling was enabled, the
 * latest Track-D runs of T14 from fixed bay A established a common command-100
 * correction of 120 mm. B selects the identical directed destination side,
 * final sensor, and turnout suffix for every d1-d8 route (its start prefix is
 * only 11 mm longer), so it shares the same physical endpoint calibration.
 * C/D/E share the same physical suffix from C7 onward and approach every
 * endpoint from the same catalogued side. Their direction-specific anchor
 * offset is already included in route distance, while the locomotive's
 * measured command-to-rest curve remains unchanged.
 * F approaches d1-d5/d7/d8 from the same directed sides as the accepted A/B
 * runs. Its d6 anchor is the co-located reverse sensor, so the zero endpoint
 * offset is unchanged. F therefore inherits the common T14 endpoint
 * correction but not the C/D/E-only d5 residual.
 * At command 120, d1 still overshot by 100 mm with the
 * previous 230 mm early-command correction, then the common command-120
 * calibration was advanced by another 45 mm, so d1 now commands zero 375 mm
 * earlier. Conversely d3 and d8 stopped before their final preceding sensors:
 * their short downstream offsets exposed that the extra 230 mm was wrong for
 * those endpoints; after the same latest 45 mm advance they use a 45 mm
 * correction. Other command-120 endpoints now use the provisional 275 mm
 * correction. Keep these physical corrections out of collision gaps,
 * reservations, other trains, and other start bays.
 */
static int measured_direct_stop_distance_um(
        const tc2_dispatch_job_snapshot *job, int speed) {
        int stop_um =
                Tc2MotionMeasuredStopDistanceUm(speed);
        if (stop_um < 0) return -1;
        int correction_um = 0;
        if (job && job->train == 14 &&
            job->start_index >= 0 &&
            job->start_index <= 5) {
                if (speed == 100) {
                        correction_um = 120000;
                        /*
                         * The C->d5 physical run first commanded zero at
                         * D5.  d5 is the E5/E6 detector centre, only 376 mm
                         * beyond D5 on this directed route, while T14 coasts
                         * 875 mm from command 100.  The observed settle point
                         * was therefore 500 mm beyond d5 (875 - 376, rounded
                         * by the operator). D and E share this exact suffix,
                         * so transfer the same residual only to C/D/E d5 at
                         * speed 100. A/B and every other endpoint retain
                         * their already accepted correction.
                         */
                        if (job->start_index >= 2 &&
                            job->start_index <= 4 &&
                            job->destination_index == 4) {
                                correction_um += 500000;
                        }
                } else if (speed == 120) {
                        if (job->destination_index == 0) {
                                correction_um = 375000;
                        } else if (job->destination_index != 2 &&
                                   job->destination_index != 7) {
                                correction_um = 275000;
                        } else {
                                correction_um = 45000;
                        }
                }
        }
        if (correction_um > 0) {
                if (stop_um > 0x7fffffff - correction_um) {
                        return -1;
                }
                stop_um += correction_um;
        }
        return stop_um;
}

static int measured_direct_stop_distance_mm(
        const tc2_dispatch_job_snapshot *job, int speed) {
        int stop_um =
                measured_direct_stop_distance_um(
                        job, speed);
        return stop_um < 0 ? -1 :
                (stop_um + 999) / 1000;
}

static int measured_direct_velocity_um_per_tick(
        const tc2_dispatch_job_snapshot *job, int speed) {
        (void)job;
        return Tc2MotionProvisionalVelocityUmPerTick(speed);
}

static int uses_precision_approach(
        const tc2_dispatch_job_snapshot *job) {
        return job && job->destination_index >= 0 &&
                job->destination_index <
                        TC2_DISPATCH_DESTINATION_COUNT &&
                !uses_measured_direct_stop(job);
}

static int reduce_for_anchor_stage(
        int slot, int requested_speed) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int reduced = requested_speed;

        if (reduced > job->speed) reduced = job->speed;
        if (reduced < 1) return -1;
        if (runtime->command_speed == reduced) {
                job->command_speed = reduced;
                return 0;
        }
        int command = command_train_positive_speed_with_retry(
                slot, reduced);
        if (command != 0) return command;
        if (runtime->motion_speed_ceiling <
            runtime->command_speed) {
                runtime->motion_speed_ceiling =
                        runtime->command_speed;
        }
        runtime->command_speed = reduced;
        runtime->speed_reduction_pending = 1;
        runtime->precision_approach_active = 1;
        runtime->observed_velocity_um_per_tick = -1;
        job->command_speed = reduced;
        return 0;
}

static int schedule_motion_deadlines(int slot, int now) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int confirmed_distance_mm;
        if (effective_confirmed_distance_mm(
                    runtime, &confirmed_distance_mm) < 0) {
                return -1;
        }
        int final_leg =
                runtime->leg_end_offset ==
                job->destination_route_offset;
        int point_prediction =
                final_leg &&
                !uses_measured_direct_stop(job) &&
                !(runtime->target_seen &&
                  job->destination_offset_mm > 0) &&
                (job->provisional_prediction ||
                 runtime->prediction_plan_valid);
        int braking =
                final_leg && uses_measured_direct_stop(job) ?
                        measured_direct_stop_distance_mm(
                                job,
                                runtime->command_speed) :
                point_prediction ?
                        Tc2MotionProvisionalStopDistanceMm(
                                runtime->command_speed) :
                !final_leg ?
                        Tc2MotionStopDistanceMm(
                                runtime->command_speed) :
                        Tc2MotionBrakingDistanceMm(
                                runtime->command_speed);
        int stop_distance;
        int terminal_distance;
        int stop_remaining;
        int watchdog_remaining;
        int prediction_stop_um = -1;
        int prediction_velocity_um_per_tick = -1;
        if (braking < 0 ||
            Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    runtime->monitor_terminal_offset,
                    &terminal_distance) < 0) {
                return -1;
        }
        if (final_leg) {
                stop_distance =
                        job->destination_distance_mm;
        } else if (Tc2RouteDistanceAtOffset(
                           dispatch_track, &runtime->route,
                           runtime->leg_end_offset,
                           &stop_distance) < 0) {
                return -1;
        }
        int64_t controller_progress_um =
                (int64_t)confirmed_distance_mm * 1000;
        if (uses_measured_direct_stop(job) &&
            runtime->motion_anchor_from_traffic &&
            runtime->motion_anchor_tick >= 0 &&
            runtime->motion_anchor_distance_um >
                    controller_progress_um) {
                controller_progress_um =
                        runtime->motion_anchor_distance_um;
        }
        int controller_progress_mm = confirmed_distance_mm;
        if (controller_progress_um >= 0) {
                controller_progress_mm =
                        (int)((controller_progress_um + 999) / 1000);
        }
        if (point_prediction &&
            runtime->prediction_plan_valid) {
                int64_t point_remaining_um =
                        runtime->prediction_plan
                                .corrected_endpoint_distance_um -
                        (int64_t)confirmed_distance_mm * 1000;
                if (point_remaining_um < 0 ||
                    point_remaining_um >
                            (int64_t)0x7fffffff * 1000) {
                        return -1;
                }
                stop_remaining =
                        (int)((point_remaining_um + 999) / 1000);
        } else if (uses_measured_direct_stop(job)) {
                stop_remaining =
                        stop_distance - controller_progress_mm;
        } else {
                stop_remaining = stop_distance -
                        confirmed_distance_mm;
        }
        watchdog_remaining = terminal_distance -
                confirmed_distance_mm;
        if (stop_remaining < 0 || watchdog_remaining < 0) return -1;
        int before_braking = stop_remaining > braking ?
                stop_remaining - braking : 0;
        int braking_ticks;
        if (point_prediction) {
                prediction_velocity_um_per_tick =
                        runtime->observed_velocity_um_per_tick > 0 ?
                        runtime->observed_velocity_um_per_tick :
                        Tc2MotionProvisionalVelocityUmPerTick(
                                runtime->command_speed);
                prediction_stop_um =
                        Tc2MotionStopDistanceForVelocityUm(
                                prediction_velocity_um_per_tick);
                if (prediction_stop_um < 0 ||
                    stop_remaining > 0x7fffffff / 1000) {
                        return -1;
                }
                int64_t remaining_um =
                        runtime->prediction_plan_valid ?
                        runtime->prediction_plan
                                .corrected_endpoint_distance_um -
                                (int64_t)confirmed_distance_mm * 1000 :
                        (int64_t)stop_remaining * 1000;
                int before_braking_um =
                        remaining_um >
                                        prediction_stop_um ?
                        (int)(remaining_um -
                              prediction_stop_um) :
                        0;
                braking_ticks =
                        Tc2MotionTravelTicksUmAtVelocity(
                                prediction_velocity_um_per_tick,
                                before_braking_um);
        } else if (uses_measured_direct_stop(job)) {
                /*
                 * Direct physical dispatch is a distance-domain controller.
                 * A raw interval between two detectors is not allowed to
                 * replace the calibrated command-speed velocity: curved
                 * sections, detector latency, and batched reports otherwise
                 * move the spatial zero-command point. Sensors rebase only
                 * the known route distance; the currently acknowledged
                 * command speed selects the stable velocity and
                 * command-to-rest curves.  This differs from job->speed only
                 * when a short final authority safely resumes at a lower
                 * speed whose stopping distance fits the remaining track.
                 */
                prediction_velocity_um_per_tick =
                        measured_direct_velocity_um_per_tick(
                                job, runtime->command_speed);
                prediction_stop_um =
                        measured_direct_stop_distance_um(
                                job,
                                runtime->command_speed);
                if (prediction_velocity_um_per_tick < 1 ||
                    prediction_stop_um < 0 ||
                    before_braking > 0x7fffffff / 1000) {
                        return -1;
                }
                braking_ticks =
                        Tc2MotionTravelTicksUmAtVelocity(
                                prediction_velocity_um_per_tick,
                                before_braking * 1000);
        } else {
                braking_ticks =
                        Tc2MotionFastTravelTicks(
                                runtime->command_speed,
                                before_braking);
        }
        int watchdog_ticks =
                point_prediction ||
                uses_measured_direct_stop(job) ?
                        Tc2MotionProvisionalSlowTravelTicks(
                                runtime->command_speed,
                                watchdog_remaining) :
                        Tc2MotionSlowTravelTicks(
                                runtime->command_speed,
                                watchdog_remaining);
        if (braking_ticks < 0 || watchdog_ticks < 0) return -1;
        job->braking_at_tick =
                tick_after(now, braking_ticks);
        if (point_prediction ||
            uses_measured_direct_stop(job)) {
                job->prediction_velocity_um_per_tick =
                        prediction_velocity_um_per_tick;
                job->prediction_stop_distance_um =
                        prediction_stop_um;
                job->prediction_stop_distance_mm = braking;
                job->prediction_anchor_node = job->current_node;
                job->prediction_anchor_tick = now;
                job->prediction_anchor_distance_mm =
                        uses_measured_direct_stop(job) ?
                        controller_progress_mm :
                        confirmed_distance_mm;
                job->prediction_command_at_tick =
                        job->braking_at_tick;
                job->prediction_timing_valid = 1;
                if (uses_measured_direct_stop(job)) {
                        job->estimated_distance_um =
                                controller_progress_um;
                }
        }
        job->watchdog_margin_ticks =
                Tc2MotionWatchdogMarginTicks(runtime->command_speed);
        if (runtime->leg_end_offset <
                    job->destination_route_offset &&
            runtime->approach_sent) {
                job->watchdog_margin_ticks = 5;
        }
        job->watchdog_at_tick =
                tick_after(
                        now, watchdog_ticks +
                                job->watchdog_margin_ticks);
        job->remaining_distance_mm =
                job->destination_distance_mm -
                (uses_measured_direct_stop(job) ?
                 controller_progress_mm :
                 confirmed_distance_mm);
        if (job->remaining_distance_mm < 0) {
                job->remaining_distance_mm = 0;
        }
        update_next_sensor(slot);
        return 0;
}

/*
 * Estimate physical progress on the selected route from the latest confirmed
 * route distance. The detector contributes position only. It cannot select a
 * stopping distance, directly stop a final-leg train, or replace the stable
 * command-speed velocity with one noisy sensor interval.
 */
static int measured_direct_progress_um(
        int slot, int now, int64_t *progress_um,
        int64_t *zero_command_distance_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !progress_um || !zero_command_distance_um) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!uses_measured_direct_stop(job) ||
            runtime->leg_end_offset !=
                    job->destination_route_offset ||
            job->destination_distance_mm < 0) {
                return -1;
        }
        int anchor_tick =
                runtime->motion_anchor_from_traffic ?
                runtime->motion_anchor_tick :
                runtime->last_confirmed_tick;
        int64_t anchor_distance_um =
                runtime->motion_anchor_from_traffic ?
                runtime->motion_anchor_distance_um :
                (int64_t)runtime->monitor
                        .confirmed_distance_mm * 1000;
        if (anchor_tick == -1 ||
            anchor_distance_um < 0) {
                return -1;
        }
        /*
         * A positive-speed reduction does not make the physical train obey
         * the lower velocity instantaneously.  Until the first subsequent
         * real sensor rebases motion, retain the prior command as the
         * conservative progress ceiling.  Destination correction is tracked
         * separately by destination_correction_active and never inferred just
         * because an ordinary route happens to use command speed 40.
         */
        int progress_speed = runtime->command_speed;
        if (runtime->precision_approach_active &&
            runtime->speed_reduction_pending &&
            runtime->motion_speed_ceiling > progress_speed) {
                progress_speed = runtime->motion_speed_ceiling;
        }
        int velocity =
                measured_direct_velocity_um_per_tick(
                        job, progress_speed);
        int stop_um =
                measured_direct_stop_distance_um(
                        job,
                        runtime->command_speed);
        if (velocity < 1 || stop_um < 0) return -1;

        int age = motion_tick_age(
                now, anchor_tick);
        if (age < 0) return -1;
        int64_t confirmed_um =
                anchor_distance_um;
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        int64_t estimated_um =
                confirmed_um + (int64_t)age * velocity;
        if (estimated_um < confirmed_um) return -1;
        if (runtime->precision_approach_active &&
            job->estimated_distance_um >= confirmed_um &&
            estimated_um < job->estimated_distance_um) {
                estimated_um = job->estimated_distance_um;
        }
        if (estimated_um > destination_um) {
                estimated_um = destination_um;
        }
        int64_t command_um = destination_um - stop_um;
        if (command_um < 0) command_um = 0;

        *progress_um = estimated_um;
        *zero_command_distance_um = command_um;
        return 0;
}

/*
 * Return whether the last real detector at or before the requested-speed
 * zero-command point has actually been confirmed.  A rolling traffic stop
 * carries a conservative coast upper bound for occupancy safety; that upper
 * bound is not localization evidence and must not skip every remaining
 * detector before the final braking region.
 *
 * Route order, rather than node number, defines "ahead" for both directions.
 * No detector before the command point is a valid (and uncommon) route shape,
 * so the time-domain destination controller remains usable in that case.
 */
static int destination_final_braking_anchor_confirmed(
        int slot, int64_t zero_command_distance_um,
        int *anchor_offset) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            zero_command_distance_um < 0 || !anchor_offset) {
                return -1;
        }
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            runtime->leg_start_offset < 0 ||
            runtime->leg_start_offset >= runtime->route.node_count ||
            job->destination_route_offset < runtime->leg_start_offset ||
            job->destination_route_offset >= runtime->route.node_count ||
            runtime->monitor.confirmed_offset < 0 ||
            runtime->monitor.confirmed_offset >= runtime->route.node_count) {
                return -1;
        }

        int final_anchor = -1;
        for (int offset = runtime->leg_start_offset;
             offset <= job->destination_route_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return -1;
                if (dispatch_track[node].type != NODE_SENSOR) continue;
                int distance_mm = -1;
                if (Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            offset, &distance_mm) < 0) {
                        return -1;
                }
                if ((int64_t)distance_mm * 1000 >
                    zero_command_distance_um) {
                        break;
                }
                final_anchor = offset;
        }
        *anchor_offset = final_anchor;
        return final_anchor < 0 ||
               runtime->monitor.confirmed_offset >= final_anchor;
}

/*
 * A lowercase destination is described from both physical approaches.
 * Match the physical sensor pair as well as the directed node stored in the
 * route.  Callers deliberately treat this as terminal evidence only for a
 * zero-offset endpoint; non-coincident endpoints retain their ordinary
 * sensor-anchor-plus-distance correction.
 */
static unsigned int destination_boundary_sensor_mask(
        int slot, int sensor_node) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            sensor_node < 0 || sensor_node >= TRACK_MAX ||
            dispatch_track[sensor_node].type != NODE_SENSOR) {
                return 0;
        }
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (job->destination_index < 0 ||
            job->destination_index >=
                    TC2_DISPATCH_DESTINATION_COUNT) {
                return 0;
        }

        unsigned int mask = 0;
        for (int side = 0;
             side < TC2_TRACK_DESTINATION_SIDE_COUNT; ++side) {
                const tc2_track_destination_side *definition =
                        Tc2TrackDestinationSide(
                                job->destination_index, side);
                if (!definition || !definition->anchor_sensor) continue;
                int anchor = TrackFindNodeByName(
                        dispatch_track, definition->anchor_sensor);
                if (anchor < 0 || anchor >= TRACK_MAX ||
                    dispatch_track[anchor].type != NODE_SENSOR) {
                        continue;
                }
                int reverse = physical_reverse_index(anchor);
                if (sensor_node == anchor || sensor_node == reverse) {
                        mask |= 1u << side;
                }
        }
        return mask;
}

/*
 * Return the physical approach side represented by either directed report
 * from one of the destination's two boundary detectors.  The route planner
 * normally selects the correct side up front, but a real detector report is
 * stronger evidence than that provisional choice.  In particular, a train
 * which reaches C15 on the way to d8, E9/D6 on the way to d7, or either d2
 * boundary must finish from that observed boundary; it must never continue
 * through the lowercase endpoint merely to chase the opposite-side sensor.
 */
static int destination_boundary_side_for_sensor(
        int slot, int sensor_node) {
        unsigned int mask =
                destination_boundary_sensor_mask(slot, sensor_node);
        if (mask == 0) return -1;
        for (int side = 0;
             side < TC2_TRACK_DESTINATION_SIDE_COUNT; ++side) {
                if (mask & (1u << side)) return side;
        }
        return -1;
}

static int destination_direct_stop_waits_for_real_anchor(
        int slot, int64_t zero_command_distance_um,
        int *anchor_offset) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        int anchor_ready =
                destination_final_braking_anchor_confirmed(
                        slot, zero_command_distance_um,
                        anchor_offset);
        if (anchor_ready < 0) return -1;
        /*
         * d5/d6 are detector-centre destinations.  Waiting for the target
         * detector before issuing the first zero would necessarily carry the
         * locomotive past the requested stop.  Their measured timer stop is
         * therefore allowed before the last pre-target detector; the target
         * pulse remains confirmation only, and a settled under-run may use
         * the ordinary bounded correction path without crossing its first
         * still-unconfirmed detector.
         */
        if (uses_exact_destination_sensor_stop(&dispatch_jobs[slot])) {
                return 0;
        }
        /*
         * Clock projection is never detector evidence, irrespective of why
         * the current motion interval began.  In particular, resuming after
         * a rolling-authority stop must not turn its conservative coast bound
         * into permission to skip the last real braking anchor.  The same
         * rule also covers an uninterrupted run through a detector deadzone.
         */
        return !anchor_ready;
}

static void clear_destination_anchor_seek(
        tc2_dispatch_runtime *runtime) {
        if (!runtime) return;
        runtime->destination_anchor_seek_offset = -1;
        runtime->destination_anchor_seek_generation = 0;
        runtime->destination_anchor_seek_remaining_ticks = -1;
        runtime->destination_anchor_seek_last_motion_tick = -1;
}

/*
 * Consume only time for which this train was positively commanded.  A real
 * ordered detector starts a new spatial interval; an authority/traffic stop
 * merely pauses the existing budget.  Return 1 when the conservative budget
 * is exhausted, 0 while movement may continue, and -1 for invalid geometry.
 */
static int update_destination_anchor_seek(
        int slot, int now, int final_anchor_offset,
        int *trusted_remaining_mm) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0 ||
            final_anchor_offset < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int confirmed_offset = runtime->monitor.confirmed_offset;
        int confirmed_mm = -1;
        int final_anchor_mm = -1;
        if (!runtime->route_valid || confirmed_offset < 0 ||
            confirmed_offset >= runtime->route.node_count ||
            final_anchor_offset <= confirmed_offset ||
            final_anchor_offset >= runtime->route.node_count ||
            Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    confirmed_offset, &confirmed_mm) < 0 ||
            Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    final_anchor_offset, &final_anchor_mm) < 0 ||
            final_anchor_mm <= confirmed_mm) {
                return -1;
        }

        /*
         * The clock-model zero point may lie before the last real detector
         * needed to localize the final stop.  Budget the complete physical
         * route distance to that detector, not merely the shorter distance to
         * the theoretical zero command.  Otherwise a healthy train is stopped
         * just before the detector whose observation is required to continue.
         */
        int remaining_mm = final_anchor_mm - confirmed_mm;
        if (remaining_mm < 1) return -1;
        if (trusted_remaining_mm) {
                *trusted_remaining_mm =
                        job->destination_distance_mm - confirmed_mm;
        }

        if (runtime->destination_anchor_seek_offset != confirmed_offset ||
            runtime->destination_anchor_seek_generation !=
                    job->plan_generation ||
            runtime->destination_anchor_seek_remaining_ticks < 0) {
                int budget = Tc2MotionProvisionalSlowTravelTicks(
                        job->speed, remaining_mm);
                if (budget < 1) return -1;
                if (budget > 0x7fffffff - TC2_TURNOUT_SETTLE_TICKS) {
                        return -1;
                }
                /* Leave one normal settle interval for detector delivery. */
                budget += TC2_TURNOUT_SETTLE_TICKS;
                runtime->destination_anchor_seek_offset = confirmed_offset;
                runtime->destination_anchor_seek_generation =
                        job->plan_generation;
                runtime->destination_anchor_seek_remaining_ticks = budget;
                runtime->destination_anchor_seek_last_motion_tick = now;
                return 0;
        }

        if (runtime->destination_anchor_seek_last_motion_tick < 0) {
                /* First RUNNING tick after a paused traffic/authority hold. */
                runtime->destination_anchor_seek_last_motion_tick = now;
                return runtime->destination_anchor_seek_remaining_ticks == 0;
        }
        int elapsed = motion_tick_age(
                now,
                runtime->destination_anchor_seek_last_motion_tick);
        if (elapsed < 0) return -1;
        if (elapsed >=
            runtime->destination_anchor_seek_remaining_ticks) {
                runtime->destination_anchor_seek_remaining_ticks = 0;
        } else {
                runtime->destination_anchor_seek_remaining_ticks -= elapsed;
        }
        runtime->destination_anchor_seek_last_motion_tick = now;
        return runtime->destination_anchor_seek_remaining_ticks == 0;
}

static int pause_destination_anchor_seek(
        tc2_dispatch_runtime *runtime, int now) {
        if (!runtime || now < 0) return -1;
        if (runtime->destination_anchor_seek_remaining_ticks < 0 ||
            runtime->destination_anchor_seek_last_motion_tick < 0) {
                return 0;
        }
        int elapsed = motion_tick_age(
                now,
                runtime->destination_anchor_seek_last_motion_tick);
        if (elapsed < 0) return -1;
        if (elapsed >=
            runtime->destination_anchor_seek_remaining_ticks) {
                runtime->destination_anchor_seek_remaining_ticks = 0;
        } else {
                runtime->destination_anchor_seek_remaining_ticks -= elapsed;
        }
        runtime->destination_anchor_seek_last_motion_tick = -1;
        return 0;
}

/*
 * Return a monotonic route scalar for live separation checks.  This is still
 * a calibrated model rather than an encoder, so collision thresholds use the
 * larger braking envelope and the reservation layer remains authoritative.
 * A traffic stop owns a finite coast endpoint; after settle the scalar is
 * frozen there instead of being recomputed from an old sensor on resume.
 */
static int runtime_private_motion_progress_um(
        int slot, int now, int64_t *progress_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !progress_um) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        int64_t minimum_preorigin_um =
                -(int64_t)runtime->preorigin_distance_mm * 1000;
        if (!runtime->route_valid ||
            runtime->motion_anchor_tick < 0 ||
            (runtime->motion_anchor_distance_um < 0 &&
             (!runtime->preorigin_sensor_pending ||
              runtime->preorigin_distance_mm <= 0 ||
              runtime->motion_anchor_distance_um <
                      minimum_preorigin_um))) {
                return -1;
        }
        if (job->state == TC2_JOB_TRAFFIC_HOLD ||
            job->state == TC2_JOB_REVERSING) {
                int64_t held_progress_um =
                        job->state == TC2_JOB_TRAFFIC_HOLD &&
                                runtime->preorigin_sensor_pending &&
                                runtime->preorigin_traffic_hold_valid ?
                        runtime->preorigin_traffic_hold_distance_um :
                        job->state == TC2_JOB_TRAFFIC_HOLD &&
                                runtime->traffic_hold_distance_um >= 0 ?
                        runtime->traffic_hold_distance_um :
                        runtime->motion_anchor_distance_um;
                *progress_um = held_progress_um;
                return 0;
        }

        int speed = runtime->command_speed;
        if (runtime->motion_speed_ceiling > speed) {
                speed = runtime->motion_speed_ceiling;
        }
        if (speed <= 0) speed = job->speed;
        int velocity =
                Tc2MotionProvisionalVelocityUmPerTick(speed);
        int age = motion_tick_age(
                now, runtime->motion_anchor_tick);
        if (velocity < 1 || age < 0) return -1;
        int64_t estimated =
                runtime->motion_anchor_distance_um +
                (int64_t)age * velocity;
        if (estimated <
            runtime->motion_anchor_distance_um) {
                return -1;
        }
        /*
         * Model time may predict arrival at route[0], but it is not physical
         * evidence that the pickup crossed that detector.  Until the fresh
         * origin pulse arrives, the private scalar may approach zero but
         * must not enter the ordinary positive route domain.
         */
        if (runtime->preorigin_sensor_pending && estimated > 0) {
                estimated = 0;
        }
        if ((runtime->stop_purpose == TC2_STOP_TRAFFIC ||
             job->state == TC2_JOB_CANCEL_BRAKING) &&
            ((runtime->preorigin_sensor_pending &&
              runtime->preorigin_traffic_hold_valid) ||
             runtime->traffic_hold_distance_um >= 0)) {
                int64_t hold_um =
                        runtime->preorigin_sensor_pending &&
                                runtime->preorigin_traffic_hold_valid ?
                        runtime->preorigin_traffic_hold_distance_um :
                        runtime->traffic_hold_distance_um;
                if (estimated > hold_um) estimated = hold_um;
        }
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        if (destination_um >= 0 &&
            estimated > destination_um) {
                estimated = destination_um;
        }
        *progress_um = estimated;
        return 0;
}

static int runtime_motion_progress_um(
        int slot, int now, int64_t *progress_um) {
        if (runtime_private_motion_progress_um(
                    slot, now, progress_um) < 0) {
                return -1;
        }
        /*
         * All consumers outside the motion/deadline controller operate in
         * the selected route's nonnegative scalar domain.  Until the first
         * real reverse-origin detector fires, model age is not evidence that
         * the train crossed route[0]; keep UI, authority, conflict zones and
         * pairwise traffic pinned at that origin.  The private helper above
         * retains the measured negative prefix for stop/resume bookkeeping.
         */
        if (dispatch_runtime[slot].preorigin_sensor_pending) {
                *progress_um = 0;
        }
        return 0;
}

/*
 * A turnout may sit between two detectors, so conflict-zone progression
 * cannot wait exclusively for the next sensor.  It also must not treat the
 * nominal clock projection as proof that the train has already entered the
 * turnout: doing so advances next/next-next early and can switch the wrong
 * motor while the train is still approaching the current one.
 *
 * Use the sensor-confirmed scalar as the hard lower bound and only the
 * uncertainty-discounted portion of the calibrated projection beyond it.
 * This preserves geometry-based prediction between sensors while every
 * ordered sensor observation continuously rebases the estimate.
 */
static int runtime_conflict_zone_progress_lower_bound_um(
        int slot, int now, int64_t *progress_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !progress_um) {
                return -1;
        }
        int64_t projected_um = 0;
        if (runtime_motion_progress_um(
                    slot, now, &projected_um) < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int speed = runtime->command_speed;
        if (runtime->motion_speed_ceiling > speed) {
                speed = runtime->motion_speed_ceiling;
        }
        if (speed <= 0) speed = job->speed;
        int uncertainty_mm = Tc2MotionUncertaintyMm(speed);
        if (uncertainty_mm < 0) return -1;

        int64_t lower_um = projected_um -
                (int64_t)uncertainty_mm * 1000;
        int confirmed_mm = -1;
        if (effective_confirmed_distance_mm(
                    runtime, &confirmed_mm) == 0) {
                int64_t confirmed_um = (int64_t)confirmed_mm * 1000;
                if (lower_um < confirmed_um) lower_um = confirmed_um;
        }
        if (lower_um < 0 || runtime->preorigin_sensor_pending) {
                lower_um = 0;
        }
        *progress_um = lower_um;
        return 0;
}

static int conflict_zone_settings_equal(
        const tc2_conflict_zone_setting *left,
        const tc2_conflict_zone_setting *right) {
        if (!left || !right ||
            left->action_count != right->action_count) {
                return 0;
        }
        for (int action = 0; action < left->action_count; ++action) {
                if (left->actions[action].switch_number !=
                            right->actions[action].switch_number ||
                    left->actions[action].direction !=
                            right->actions[action].direction) {
                        return 0;
                }
        }
        return 1;
}

static int conflict_zone_same_physical_node(int left, int right) {
        if (left < 0 || left >= TRACK_MAX ||
            right < 0 || right >= TRACK_MAX) {
                return 0;
        }
        return left == right || physical_reverse_index(left) == right;
}

static void clear_origin_zone_egress(
        tc2_dispatch_runtime *runtime) {
        if (!runtime) return;
        runtime->conflict_zone_origin_egress_active = 0;
        runtime->conflict_zone_origin_egress_step = -1;
        runtime->conflict_zone_origin_egress_zone =
                TC2_CONFLICT_ZONE_NONE;
        runtime->conflict_zone_origin_egress_ticket = 0;
        runtime->conflict_zone_origin_egress_route_generation = 0;
        runtime->conflict_zone_origin_egress_sequence = 0;
}

static const tc2_conflict_zone_route_stage *conflict_zone_stage_for_step(
        const tc2_conflict_zone_route_plan *plan, int step_index) {
        if (!plan || step_index < 0 || step_index >= plan->step_count) {
                return 0;
        }
        int stage_index = plan->steps[step_index].stage_index;
        if (stage_index < 0 || stage_index >= plan->stage_count) return 0;
        const tc2_conflict_zone_route_stage *stage =
                &plan->stages[stage_index];
        if (stage->member_count < 1 ||
            stage->member_count > TC2_CONFLICT_STAGE_MAX_MEMBERS) {
                return 0;
        }
        return stage;
}

static int conflict_zone_step_is_stage_first(
        const tc2_conflict_zone_route_plan *plan, int step_index) {
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(plan, step_index);
        return stage && stage->member_step[0] == step_index;
}

static int conflict_zone_stage_first_step(
        const tc2_conflict_zone_route_plan *plan, int stage_index) {
        if (!plan || stage_index < 0 || stage_index >= plan->stage_count) {
                return -1;
        }
        const tc2_conflict_zone_route_stage *stage =
                &plan->stages[stage_index];
        if (stage->member_count < 1 ||
            stage->member_count > TC2_CONFLICT_STAGE_MAX_MEMBERS) {
                return -1;
        }
        int step = stage->member_step[0];
        return step >= 0 && step < plan->step_count ? step : -1;
}

static int conflict_zone_next_stage_first_step(
        const tc2_conflict_zone_route_plan *plan, int step_index) {
        if (!plan || step_index < 0 || step_index >= plan->step_count) {
                return -1;
        }
        int stage_index = plan->steps[step_index].stage_index;
        if (stage_index < 0 || stage_index >= plan->stage_count) return -1;
        if (stage_index + 1 >= plan->stage_count) return plan->step_count;
        return conflict_zone_stage_first_step(plan, stage_index + 1);
}

static int conflict_zone_stage_contains_zone(
        const tc2_conflict_zone_route_plan *plan, int stage_first_step,
        int zone) {
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(plan, stage_first_step);
        if (!stage) return 0;
        for (int member = 0; member < stage->member_count; ++member) {
                int step = stage->member_step[member];
                if (step < 0 || step >= plan->step_count) return 0;
                if (plan->steps[step].zone == zone) return 1;
        }
        return 0;
}

/*
 * Validate the one exceptional use of an old owner ticket: after CURRENT
 * reverses, the train may leave the exact zone that still contains its
 * body.  The owner setting is the hard current-step setting; a next-next
 * prefetch is deliberately irrelevant here.
 */
static int origin_zone_egress_ready(int slot, int step_index) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_origin_egress_active ||
            step_index != runtime->conflict_zone_origin_egress_step ||
            step_index != runtime->conflict_zone_next_step ||
            !runtime->conflict_zone_plan_valid || step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index ||
            runtime->conflict_zone_origin_egress_ticket == 0 ||
            runtime->conflict_zone_origin_egress_route_generation == 0) {
                return 0;
        }
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                if (raw_step < 0 ||
                    raw_step >= runtime->conflict_zone_plan.step_count) {
                        return 0;
                }
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, step->zone,
                            &grant) <= 0 ||
                    grant.owner_train != dispatch_jobs[slot].train ||
                    grant.owner_ticket !=
                            runtime->conflict_zone_origin_egress_ticket ||
                    grant.owner_route_generation !=
                            runtime
                              ->conflict_zone_origin_egress_route_generation ||
                    grant.state != TC2_CONFLICT_ZONE_OCCUPIED ||
                    !conflict_zone_settings_equal(
                            &grant.setting, &step->setting)) {
                        return 0;
                }
        }
        return 1;
}

static int arm_origin_zone_egress(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        clear_origin_zone_egress(runtime);
        if (job->start_index != TC2_DISPATCH_START_CURRENT ||
            !runtime->force_reverse_first ||
            !runtime->conflict_zone_plan_valid ||
            runtime->conflict_zone_plan.step_count < 1) {
                return 0;
        }

        const int step_index = 0;
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) {
                return 0;
        }
        int leading_reverse =
                runtime->route.node_count > 1 &&
                dispatch_track[runtime->route.nodes[0]].reverse ==
                        &dispatch_track[runtime->route.nodes[1]];
        unsigned int cohort_ticket = 0;
        unsigned int cohort_route_generation = 0;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                if (raw_step < 0 ||
                    raw_step >= runtime->conflict_zone_plan.step_count) {
                        return -1;
                }
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                if (step->first_route_offset < 0 ||
                    step->first_route_offset >= runtime->route.node_count ||
                    step->last_route_offset < 0 ||
                    step->last_route_offset >= runtime->route.node_count) {
                        return -1;
                }
                int new_entry = runtime->route.nodes[
                        step->first_route_offset];
                int new_exit = runtime->route.nodes[
                        step->last_route_offset];
                int matched_carry = -1;
                for (int carry = 0;
                     carry < runtime->conflict_zone_carry_count; ++carry) {
                        int carry_entry =
                                runtime->conflict_zone_carry_entry_node[carry];
                        int carry_exit =
                                runtime->conflict_zone_carry_exit_node[carry];
                        int exact_reversed_span =
                                conflict_zone_same_physical_node(
                                        carry_entry, new_exit) &&
                                conflict_zone_same_physical_node(
                                        carry_exit, new_entry);
                /*
                 * A route that starts at the detector on a zone's far edge
                 * is trimmed after its mandatory leading reverse.  The new
                 * zone step can therefore collapse to the reverse turnout
                 * node (for example A12,A11,MR1 gives MR1..MR1), rather than
                 * repeating the detector-to-turnout span BR1..A12 recorded
                 * by the live owner.  This is still the same physical
                 * egress only when the carry ends at route[0], its old entry
                 * is the collapsed reverse turnout, and the new step has no
                 * second physical endpoint.  Do not relax any ticket,
                 * OCCUPIED-state, or hard-setting checks below.
                 */
                        int origin_trimmed_span =
                                leading_reverse &&
                                conflict_zone_same_physical_node(
                                        new_entry, new_exit) &&
                                conflict_zone_same_physical_node(
                                        carry_entry, new_entry) &&
                                conflict_zone_same_physical_node(
                                        carry_exit,
                                        runtime->route.nodes[0]);
                        if (runtime->conflict_zone_carry_zone[carry] !=
                                    step->zone ||
                            runtime->conflict_zone_carry_ticket[carry] == 0 ||
                            runtime
                              ->conflict_zone_carry_route_generation[carry] ==
                                    0 ||
                            (!exact_reversed_span &&
                             !origin_trimmed_span)) {
                                continue;
                        }
                        tc2_conflict_zone_grant grant;
                        if (Tc2ConflictZoneQueryGrant(
                                    &dispatch_conflict_zones, step->zone,
                                    &grant) <= 0 ||
                            grant.owner_train != job->train ||
                            grant.owner_ticket !=
                                    runtime->conflict_zone_carry_ticket[carry] ||
                            grant.owner_route_generation !=
                                    runtime
                                      ->conflict_zone_carry_route_generation[
                                              carry] ||
                            grant.state != TC2_CONFLICT_ZONE_OCCUPIED ||
                            !conflict_zone_settings_equal(
                                    &grant.setting, &step->setting) ||
                            (cohort_ticket != 0 &&
                             cohort_ticket != grant.owner_ticket) ||
                            (cohort_route_generation != 0 &&
                             cohort_route_generation !=
                                    grant.owner_route_generation)) {
                                continue;
                        }
                        cohort_ticket = grant.owner_ticket;
                        cohort_route_generation =
                                grant.owner_route_generation;
                        matched_carry = carry;
                        break;
                }
                if (matched_carry < 0) return 0;
        }
        if (cohort_ticket == 0 || cohort_route_generation == 0) return 0;
        runtime->conflict_zone_origin_egress_active = 1;
        runtime->conflict_zone_origin_egress_step = step_index;
        runtime->conflict_zone_origin_egress_zone =
                runtime->conflict_zone_plan.steps[
                        stage->member_step[0]].zone;
        runtime->conflict_zone_origin_egress_ticket = cohort_ticket;
        runtime->conflict_zone_origin_egress_route_generation =
                cohort_route_generation;
        runtime->conflict_zone_origin_egress_sequence =
                runtime->last_journal_sequence;
        return 1;
}

/*
 * A reverse-first CURRENT route can begin inside the first member of a
 * no-stop compound stage.  The train already owns that exact OCCUPIED
 * resource as physical body, so trying to acquire the whole compound stage
 * under a fresh cohort ticket can never succeed.  Preserve atomic movement
 * admission by splitting only the exact carried prefix into `next`; the
 * remaining members become the strict `nextnext` stage and must still be
 * owned, correctly set, and settled before positive speed is permitted.
 *
 * This is deliberately narrower than a general stage split.  Every carried
 * member must be the same live OCCUPIED cohort, have the exact route setting,
 * and describe the collapsed reverse egress at route[0].  The old cohort may
 * not own any resource outside the prefix.  Ordinary fixed-start routes and
 * later route occurrences retain their original atomic compound stages.
 */
static int split_exact_current_origin_stage(
        const tc2_dispatch_job_snapshot *job,
        const tc2_dispatch_runtime *runtime,
        const track_route *route,
        tc2_conflict_zone_route_plan *plan) {
        if (!job || !runtime || !route || !plan) return -1;
        if (job->start_index != TC2_DISPATCH_START_CURRENT ||
            !runtime->force_reverse_first || route->node_count < 2 ||
            dispatch_track[route->nodes[0]].reverse !=
                    &dispatch_track[route->nodes[1]] ||
            plan->stage_count < 1 || plan->step_count < 1) {
                return 0;
        }
        tc2_conflict_zone_route_stage original = plan->stages[0];
        if (original.member_count < 2 ||
            original.member_count > TC2_CONFLICT_STAGE_MAX_MEMBERS) {
                return 0;
        }

        unsigned int cohort_ticket = 0;
        unsigned int cohort_generation = 0;
        int carried_prefix = 0;
        for (int member = 0; member < original.member_count; ++member) {
                int raw_step = original.member_step[member];
                if (raw_step < 0 || raw_step >= plan->step_count) return -1;
                const tc2_conflict_zone_route_step *step =
                        &plan->steps[raw_step];
                if (step->first_route_offset < 0 ||
                    step->first_route_offset >= route->node_count ||
                    step->last_route_offset != step->first_route_offset) {
                        break;
                }
                int collapsed_node = route->nodes[
                        step->first_route_offset];
                int matched = 0;
                for (int carry = 0;
                     carry < runtime->conflict_zone_carry_count; ++carry) {
                        if (runtime->conflict_zone_carry_zone[carry] !=
                                    step->zone ||
                            runtime->conflict_zone_carry_ticket[carry] == 0 ||
                            runtime
                              ->conflict_zone_carry_route_generation[carry] ==
                                    0 ||
                            !conflict_zone_same_physical_node(
                                    runtime
                                      ->conflict_zone_carry_entry_node[carry],
                                    collapsed_node) ||
                            !conflict_zone_same_physical_node(
                                    runtime
                                      ->conflict_zone_carry_exit_node[carry],
                                    route->nodes[0])) {
                                continue;
                        }
                        tc2_conflict_zone_grant grant;
                        if (Tc2ConflictZoneQueryGrant(
                                    &dispatch_conflict_zones, step->zone,
                                    &grant) <= 0 ||
                            grant.owner_train != job->train ||
                            grant.owner_ticket !=
                                    runtime
                                      ->conflict_zone_carry_ticket[carry] ||
                            grant.owner_route_generation !=
                                    runtime
                                      ->conflict_zone_carry_route_generation[
                                              carry] ||
                            grant.state != TC2_CONFLICT_ZONE_OCCUPIED ||
                            !conflict_zone_settings_equal(
                                    &grant.setting, &step->setting) ||
                            (cohort_ticket != 0 &&
                             cohort_ticket != grant.owner_ticket) ||
                            (cohort_generation != 0 &&
                             cohort_generation !=
                                    grant.owner_route_generation)) {
                                continue;
                        }
                        cohort_ticket = grant.owner_ticket;
                        cohort_generation = grant.owner_route_generation;
                        matched = 1;
                        break;
                }
                if (!matched) break;
                ++carried_prefix;
        }
        if (carried_prefix <= 0 ||
            carried_prefix >= original.member_count) {
                return 0;
        }

        /* The immutable old cohort must be exactly the prefix being split. */
        int live_cohort_members = 0;
        for (int zone = 0; zone < TC2_CONFLICT_ZONE_COUNT; ++zone) {
                tc2_conflict_zone_grant grant;
                int query = Tc2ConflictZoneQueryGrant(
                        &dispatch_conflict_zones, zone, &grant);
                if (query < 0) return -1;
                if (query <= 0 || grant.owner_train != job->train ||
                    grant.owner_ticket != cohort_ticket ||
                    grant.owner_route_generation != cohort_generation) {
                        continue;
                }
                int belongs_to_prefix = 0;
                for (int member = 0; member < carried_prefix; ++member) {
                        int raw_step = original.member_step[member];
                        if (plan->steps[raw_step].zone == zone) {
                                belongs_to_prefix = 1;
                                break;
                        }
                }
                if (!belongs_to_prefix ||
                    grant.state != TC2_CONFLICT_ZONE_OCCUPIED) {
                        return 0;
                }
                ++live_cohort_members;
        }
        if (live_cohort_members != carried_prefix ||
            plan->stage_count >= TRACK_MAX) {
                return live_cohort_members == carried_prefix ? -1 : 0;
        }

        for (int stage_index = plan->stage_count;
             stage_index > 1; --stage_index) {
                plan->stages[stage_index] =
                        plan->stages[stage_index - 1];
        }
        tc2_conflict_zone_route_stage *carried = &plan->stages[0];
        tc2_conflict_zone_route_stage *following = &plan->stages[1];
        *carried = original;
        *following = original;
        carried->member_count = carried_prefix;
        following->member_count =
                original.member_count - carried_prefix;
        for (int member = 0;
             member < TC2_CONFLICT_STAGE_MAX_MEMBERS; ++member) {
                carried->member_step[member] = member < carried_prefix ?
                        original.member_step[member] : -1;
                following->member_step[member] =
                        member < following->member_count ?
                        original.member_step[carried_prefix + member] : -1;
        }
        int carried_first = carried->member_step[0];
        int carried_last =
                carried->member_step[carried->member_count - 1];
        int following_first = following->member_step[0];
        int following_last =
                following->member_step[following->member_count - 1];
        carried->first_route_offset =
                plan->steps[carried_first].first_route_offset;
        carried->last_route_offset =
                plan->steps[carried_last].last_route_offset;
        carried->entry_distance_mm =
                plan->steps[carried_first].entry_distance_mm;
        carried->exit_distance_mm =
                plan->steps[carried_last].exit_distance_mm;
        following->first_route_offset =
                plan->steps[following_first].first_route_offset;
        following->last_route_offset =
                plan->steps[following_last].last_route_offset;
        following->entry_distance_mm =
                plan->steps[following_first].entry_distance_mm;
        following->exit_distance_mm =
                plan->steps[following_last].exit_distance_mm;
        ++plan->stage_count;
        for (int stage_index = 0;
             stage_index < plan->stage_count; ++stage_index) {
                tc2_conflict_zone_route_stage *stage =
                        &plan->stages[stage_index];
                for (int member = 0;
                     member < stage->member_count; ++member) {
                        int raw_step = stage->member_step[member];
                        if (raw_step < 0 || raw_step >= plan->step_count) {
                                return -1;
                        }
                        plan->steps[raw_step].stage_index = stage_index;
                }
        }
        return 1;
}

static int conflict_zone_step_ready(int slot, int step_index) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_plan_valid) return 0;
        /*
         * `step_count` is the one valid exhausted cursor: every physical
         * turnout on this route has already been consumed.  Do not treat a
         * negative cursor, or a cursor beyond the end, as ready.  Those are
         * corrupted scheduler state and must remain fail-closed rather than
         * silently granting movement authority.
         */
        if (step_index == runtime->conflict_zone_plan.step_count) return 1;
        if (step_index < 0 ||
            step_index > runtime->conflict_zone_plan.step_count ||
            !conflict_zone_step_is_stage_first(
                    &runtime->conflict_zone_plan, step_index)) {
                return 0;
        }
        if (origin_zone_egress_ready(slot, step_index)) return 1;
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || runtime->conflict_zone_hard_step != step_index ||
            runtime->conflict_zone_hard_ticket == 0 ||
            runtime->conflict_zone_route_generation == 0) {
                return 0;
        }
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                if (raw_step < 0 ||
                    raw_step >= runtime->conflict_zone_plan.step_count) {
                        return 0;
                }
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, step->zone,
                            &grant) <= 0 ||
                    grant.owner_train != dispatch_jobs[slot].train ||
                    grant.owner_ticket !=
                            runtime->conflict_zone_hard_ticket ||
                    grant.owner_route_generation !=
                            runtime->conflict_zone_route_generation ||
                    !conflict_zone_settings_equal(
                            &grant.setting, &step->setting) ||
                    (grant.state != TC2_CONFLICT_ZONE_SETTLED &&
                     grant.state != TC2_CONFLICT_ZONE_OCCUPIED) ||
                    !conflict_zone_setting_matches_turnout_table(
                            &step->setting)) {
                        return 0;
                }
        }
        return 1;
}

static void fill_conflict_zone_request(
        int slot, int step_index,
        tc2_conflict_zone_request *request) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        const tc2_conflict_zone_route_step *step =
                &runtime->conflict_zone_plan.steps[step_index];
        request->train = job->train;
        request->route_generation =
                runtime->conflict_zone_route_generation;
        request->moving =
                runtime->command_speed > 0 &&
                job->state == TC2_JOB_RUNNING;
        request->track_key = step->approach_track_key;
        request->travel_direction = step->approach_direction;
        int centre_mm = job->estimated_distance_um >= 0 ?
                (int)(job->estimated_distance_um / 1000) :
                job->confirmed_distance_mm;
        request->front_rank_mm = centre_mm - step->entry_distance_mm;
        request->setting = step->setting;
}

static int fill_conflict_zone_stage_requests(
        int slot, int stage_first_step,
        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS],
        tc2_conflict_zone_request
                requests[TC2_CONFLICT_STAGE_MAX_MEMBERS]) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !zones || !requests) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan,
                        stage_first_step);
        if (!stage || stage->member_step[0] != stage_first_step) return -1;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                if (raw_step < 0 ||
                    raw_step >= runtime->conflict_zone_plan.step_count) {
                        return -1;
                }
                zones[member] =
                        runtime->conflict_zone_plan.steps[raw_step].zone;
                fill_conflict_zone_request(
                        slot, raw_step, &requests[member]);
        }
        return stage->member_count;
}

/*
 * A carry entry is an old physical traversal whose lifecycle has not yet
 * been proved complete.  Even when the new route asks for the same zone and
 * setting, its old owner ticket is not authority for the new geometry.
 */
static int conflict_zone_has_unresolved_carry(
        const tc2_dispatch_runtime *runtime, int zone) {
        if (!runtime || zone < 0 || zone >= TC2_CONFLICT_ZONE_COUNT) {
                return 0;
        }
        for (int index = 0;
             index < runtime->conflict_zone_carry_count; ++index) {
                if (runtime->conflict_zone_carry_zone[index] == zone) {
                        return 1;
                }
        }
        return 0;
}

/*
 * Rewinding a stopped survivor from its latest real detector can make an
 * immutable route step current again after projection had already moved that
 * exact traversal into the carry ledger.  The carry is this train's existing
 * physical owner, not a competing obstacle.  Reattach it only when every
 * piece of immutable identity agrees: zone, route occurrence, setting,
 * train, and ticket.  No ticket is created and no foreign/differently-routed
 * owner is weakened.
 *
 * RELEASE_DELAY is deliberately not reusable: its old traversal has already
 * proved tail-clear and must finish releasing before a fresh traversal can
 * request the zone.  Once reattached, OCCUPIED remains fail-closed and can
 * continue only with the already-confirmed direction; GRANTED/SETTING may
 * run the normal hard-next setting sequence again.
 */
static int restore_exact_current_carry_as_hard(
        int slot, int step_index) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            !runtime->conflict_zone_plan_valid ||
            step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) return -1;

        int carry_index[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        unsigned int cohort_ticket = 0;
        int queue_pending = 0;
        for (int member = 0; member < stage->member_count; ++member) {
                carry_index[member] = -1;
                int raw_step = stage->member_step[member];
                if (raw_step < 0 ||
                    raw_step >= runtime->conflict_zone_plan.step_count) {
                        return -1;
                }
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                if (step->first_route_offset < 0 ||
                    step->last_route_offset < step->first_route_offset ||
                    step->last_route_offset >= runtime->route.node_count) {
                        return -1;
                }
                int entry_node = runtime->route.nodes[
                        step->first_route_offset];
                int exit_node = runtime->route.nodes[
                        step->last_route_offset];
                for (int carry = 0;
                     carry < runtime->conflict_zone_carry_count; ++carry) {
                        if (runtime->conflict_zone_carry_zone[carry] !=
                                    step->zone ||
                            runtime->conflict_zone_carry_entry_node[carry] !=
                                    entry_node ||
                            runtime->conflict_zone_carry_exit_node[carry] !=
                                    exit_node ||
                            runtime->conflict_zone_carry_exit_distance_mm[
                                    carry] != step->exit_distance_mm ||
                            runtime->conflict_zone_carry_ticket[carry] == 0 ||
                            runtime
                              ->conflict_zone_carry_route_generation[carry] !=
                                    runtime
                                      ->conflict_zone_route_generation) {
                                continue;
                        }
                        tc2_conflict_zone_grant grant;
                        if (Tc2ConflictZoneQueryGrant(
                                    &dispatch_conflict_zones, step->zone,
                                    &grant) <= 0 ||
                            grant.owner_train != job->train ||
                            grant.owner_ticket !=
                                    runtime->conflict_zone_carry_ticket[
                                            carry] ||
                            grant.owner_route_generation !=
                                    runtime
                                      ->conflict_zone_carry_route_generation[
                                              carry] ||
                            !conflict_zone_settings_equal(
                                    &grant.setting, &step->setting)) {
                                continue;
                        }
                        if (grant.state ==
                                    TC2_CONFLICT_ZONE_RELEASE_DELAY) {
                                return 0;
                        }
                        if (grant.state != TC2_CONFLICT_ZONE_GRANTED &&
                            grant.state != TC2_CONFLICT_ZONE_SETTING &&
                            grant.state != TC2_CONFLICT_ZONE_SETTLED &&
                            grant.state != TC2_CONFLICT_ZONE_OCCUPIED) {
                                return -1;
                        }
                        if (cohort_ticket != 0 &&
                            cohort_ticket != grant.owner_ticket) {
                                return -1;
                        }
                        cohort_ticket = grant.owner_ticket;
                        queue_pending = queue_pending ||
                                grant.state ==
                                        TC2_CONFLICT_ZONE_GRANTED ||
                                grant.state ==
                                        TC2_CONFLICT_ZONE_SETTING;
                        carry_index[member] = carry;
                        break;
                }
                /* Partial reuse would create a partial physical owner stage. */
                if (carry_index[member] < 0) return 0;
        }
        if (cohort_ticket == 0) return 0;
        if (runtime->conflict_zone_hard_ticket != 0 &&
            (runtime->conflict_zone_hard_step != step_index ||
             runtime->conflict_zone_hard_ticket != cohort_ticket)) {
                return -1;
        }
        runtime->conflict_zone_hard_step = step_index;
        runtime->conflict_zone_hard_ticket = cohort_ticket;
        runtime->conflict_zone_queue_pending = queue_pending;
        runtime->conflict_zone_settle_at_tick = -1;
        reset_conflict_zone_action_cursor(runtime);
        for (int removed = 0; removed < stage->member_count; ++removed) {
                int greatest_member = -1;
                for (int member = 0; member < stage->member_count; ++member) {
                        if (carry_index[member] >= 0 &&
                            (greatest_member < 0 ||
                             carry_index[member] >
                                    carry_index[greatest_member])) {
                                greatest_member = member;
                        }
                }
                if (greatest_member < 0) return -1;
                remove_conflict_zone_carry(
                        runtime, carry_index[greatest_member]);
                carry_index[greatest_member] = -1;
        }
        return 1;
}

/* Return the first raw member step of the next route-local stage. */
static int next_conflict_zone_preparation_step(
        int slot, int hard_step) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_plan_valid || hard_step < 0 ||
            hard_step >= runtime->conflict_zone_plan.step_count) {
                return -1;
        }

        int soft_step = conflict_zone_next_stage_first_step(
                &runtime->conflict_zone_plan, hard_step);
        return soft_step >= 0 &&
                       soft_step < runtime->conflict_zone_plan.step_count ?
                soft_step : -1;
}

static int conflict_zone_lookahead_prepared(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_plan_valid) return 0;
        int hard_step = runtime->conflict_zone_next_step;
        if (hard_step < 0 ||
            hard_step > runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        if (hard_step == runtime->conflict_zone_plan.step_count) return 1;
        int soft_step =
                next_conflict_zone_preparation_step(slot, hard_step);
        if (soft_step < 0) return 1;
        if (soft_step >= runtime->conflict_zone_plan.step_count) return 0;
        const tc2_conflict_zone_route_stage *hard_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, hard_step);
        const tc2_conflict_zone_route_stage *soft_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, soft_step);
        if (!hard_stage || !soft_stage ||
            hard_stage->member_step[0] != hard_step ||
            soft_stage->member_step[0] != soft_step) {
                return 0;
        }
        /*
         * A later stage which reuses a current physical resource cannot own
         * its complete independent cohort yet.  The conservative invariant
         * therefore keeps the train stopped until the current stage releases
         * and the resource-level handoff delay permits a new exact ticket.
         */
        for (int member = 0; member < soft_stage->member_count; ++member) {
                int raw_step = soft_stage->member_step[member];
                int zone = runtime->conflict_zone_plan.steps[raw_step].zone;
                if (conflict_zone_stage_contains_zone(
                            &runtime->conflict_zone_plan,
                            hard_step, zone)) {
                        return 0;
                }
        }
        if (runtime->conflict_zone_soft_batch_token != 0 ||
            runtime->conflict_zone_soft_settle_at_tick >= 0 ||
            runtime->conflict_zone_soft_step != soft_step ||
            runtime->conflict_zone_soft_ticket == 0 ||
            runtime->conflict_zone_soft_confirmed_step != soft_step) {
                return 0;
        }
        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        tc2_conflict_zone_request
                requests[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        int count = fill_conflict_zone_stage_requests(
                slot, soft_step, zones, requests);
        if (count != soft_stage->member_count ||
            Tc2ConflictZoneIsSoftStageControlHead(
                    &dispatch_conflict_zones, zones, count,
                    dispatch_jobs[slot].train,
                    runtime->conflict_zone_route_generation,
                    runtime->conflict_zone_soft_ticket) != 1) {
                return 0;
        }
        for (int member = 0; member < soft_stage->member_count; ++member) {
                int raw_step = soft_stage->member_step[member];
                if (!conflict_zone_setting_matches_turnout_table(
                            &runtime->conflict_zone_plan.steps[raw_step]
                                     .setting)) {
                        return 0;
                }
        }
        return 1;
}

/*
 * Every positive-speed path uses the same two-layer admission rule.  Traffic
 * masks are the complete four-train safety result; next is the exact hard
 * permission/verification stage, and nextnext is the logical FIFO-head
 * preparation stage.  Every positive-speed path, including destination
 * correction, must pass this same rule.
 */
static int traffic_motion_clear(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        return !runtime->prelaunch_traffic_blocked &&
                runtime->traffic_blockers_now == 0 &&
                runtime->traffic_head_on_latches == 0;
}

static int regular_movement_gates_ready(int slot) {
        if (!traffic_motion_clear(slot)) return 0;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        return conflict_zone_step_ready(
                        slot, runtime->conflict_zone_next_step) &&
                conflict_zone_lookahead_prepared(slot);
}

/*
 * Publish the exact physical next-next request even when every motor already
 * points correctly.  The soft queue is the exclusive control right for that
 * physical group; it grants no movement authority, but without it another
 * train could change the direction before this traversal becomes `next`.
 */
static int refresh_soft_conflict_zone_request(int slot, int hard_step) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (!runtime->conflict_zone_plan_valid || hard_step < 0 ||
            hard_step >= runtime->conflict_zone_plan.step_count) {
                return 0;
        }

        int soft_step =
                next_conflict_zone_preparation_step(slot, hard_step);
        if (soft_step >= 0 &&
            soft_step < runtime->conflict_zone_plan.step_count) {
                const tc2_conflict_zone_route_stage *soft_stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan, soft_step);
                if (!soft_stage ||
                    soft_stage->member_step[0] != soft_step) {
                        return -1;
                }
                runtime->conflict_zone_soft_step = soft_step;
                /*
                 * If nextnext exists it is a standing movement condition.
                 * Queue the complete resource set immediately and keep the
                 * train stopped until every member is owned, points in the
                 * route direction, and has completed its settle interval.
                 */
                for (int member = 0;
                     member < soft_stage->member_count; ++member) {
                        int raw_step = soft_stage->member_step[member];
                        int zone = runtime->conflict_zone_plan
                                           .steps[raw_step].zone;
                        if (!conflict_zone_stage_contains_zone(
                                    &runtime->conflict_zone_plan,
                                    hard_step, zone) &&
                            !conflict_zone_has_unresolved_carry(
                                    runtime, zone)) {
                                continue;
                        }
                        /*
                         * Two occurrences of one physical group cannot be
                         * controlled concurrently by one train.  Keep the
                         * literal nextnext cursor visible, but leave it
                         * unprepared until the previous traversal releases.
                         */
                        if (Tc2ConflictZoneCancelSoft(
                                    &dispatch_conflict_zones,
                                    job->train) < 0) return -1;
                        runtime->conflict_zone_soft_ticket = 0;
                        return 0;
                }
                int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                tc2_conflict_zone_request
                        requests[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int count = fill_conflict_zone_stage_requests(
                        slot, soft_step, zones, requests);
                uint32_t soft_ticket = 0;
                if (count != soft_stage->member_count ||
                    Tc2ConflictZoneRequestSoftStage(
                            &dispatch_conflict_zones, zones, requests,
                            count, &soft_ticket) < 0 ||
                    soft_ticket == 0) {
                        return -1;
                }
                runtime->conflict_zone_soft_ticket = soft_ticket;
        } else {
                if (Tc2ConflictZoneCancelSoft(
                            &dispatch_conflict_zones,
                            job->train) < 0) return -1;
                runtime->conflict_zone_soft_step = -1;
                runtime->conflict_zone_soft_ticket = 0;
        }
        return 0;
}

/* Phase one only enqueues. Grant selection happens after every slot queued. */
static int refresh_conflict_zone_requests(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (!runtime->conflict_zone_plan_valid ||
            job->state == TC2_JOB_EMPTY ||
            runtime->conflict_zone_next_step >=
                    runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        int hard_step = runtime->conflict_zone_next_step;
        const tc2_conflict_zone_route_stage *hard_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, hard_step);
        if (!hard_stage || hard_stage->member_step[0] != hard_step ||
            runtime->conflict_zone_route_generation == 0 ||
            Tc2ConflictZonePruneStaleRequests(
                    &dispatch_conflict_zones, job->train,
                    runtime->conflict_zone_route_generation) < 0) {
                return -1;
        }
        int restored_carry =
                restore_exact_current_carry_as_hard(slot, hard_step);
        if (restored_carry < 0) return -1;
        int origin_egress =
                runtime->conflict_zone_origin_egress_active &&
                runtime->conflict_zone_origin_egress_step == hard_step;
        if (origin_egress &&
            origin_zone_egress_ready(slot, hard_step)) {
                runtime->conflict_zone_hard_step = hard_step;
                runtime->conflict_zone_hard_ticket =
                        runtime->conflict_zone_origin_egress_ticket;
        } else if (origin_egress) {
                /*
                 * Origin egress is a complete compound-stage cohort.  Looking
                 * only at the first member can hide a partially-live owner and
                 * then enqueue a fresh ticket for the remaining members.  A
                 * full old cohort which is not ready stays fail-closed; only a
                 * cohort with no live old member may fall back to fresh FIFO.
                 */
                int live_old_members = 0;
                int all_old_members_releasing = 1;
                for (int member = 0;
                     member < hard_stage->member_count; ++member) {
                        int raw_step = hard_stage->member_step[member];
                        if (raw_step < 0 ||
                            raw_step >=
                                    runtime->conflict_zone_plan.step_count) {
                                return -1;
                        }
                        int zone = runtime->conflict_zone_plan
                                           .steps[raw_step].zone;
                        tc2_conflict_zone_grant grant;
                        int query = Tc2ConflictZoneQueryGrant(
                                &dispatch_conflict_zones, zone, &grant);
                        if (query < 0) return -1;
                        if (query > 0 &&
                            grant.owner_train == job->train &&
                            grant.owner_ticket ==
                                    runtime
                                      ->conflict_zone_origin_egress_ticket &&
                            grant.owner_route_generation ==
                                    runtime
                                      ->conflict_zone_origin_egress_route_generation) {
                                ++live_old_members;
                                all_old_members_releasing =
                                        all_old_members_releasing &&
                                        grant.state ==
                                                TC2_CONFLICT_ZONE_RELEASE_DELAY;
                        }
                }
                if (live_old_members != 0 &&
                    live_old_members != hard_stage->member_count) {
                        /* A partially-live compound cohort is an invariant error. */
                        return -1;
                }
                if (live_old_members == hard_stage->member_count &&
                    !all_old_members_releasing) {
                        /* The complete old physical owner still blocks egress. */
                        return -1;
                }
                clear_origin_zone_egress(runtime);
                origin_egress = 0;
        }
        if (!origin_egress && !restored_carry) {
                for (int member = 0;
                     member < hard_stage->member_count; ++member) {
                        int raw_step = hard_stage->member_step[member];
                        int zone = runtime->conflict_zone_plan
                                           .steps[raw_step].zone;
                        if (!conflict_zone_has_unresolved_carry(
                                    runtime, zone)) {
                                continue;
                        }
                        runtime->conflict_zone_hard_step = -1;
                        runtime->conflict_zone_hard_ticket = 0;
                        if (Tc2ConflictZoneCancelHard(
                                    &dispatch_conflict_zones,
                                    job->train) < 0) {
                                return -1;
                        }
                        return refresh_soft_conflict_zone_request(
                                slot, hard_step);
                }
        }
        if (!origin_egress) {
                int owns_current_traversal =
                        runtime->conflict_zone_hard_step == hard_step &&
                        runtime->conflict_zone_hard_ticket != 0;
                for (int member = 0;
                     owns_current_traversal &&
                     member < hard_stage->member_count; ++member) {
                        int raw_step = hard_stage->member_step[member];
                        const tc2_conflict_zone_route_step *member_step =
                                &runtime->conflict_zone_plan
                                         .steps[raw_step];
                        tc2_conflict_zone_grant existing;
                        owns_current_traversal =
                                Tc2ConflictZoneQueryGrant(
                                        &dispatch_conflict_zones,
                                        member_step->zone,
                                        &existing) > 0 &&
                                existing.owner_train == job->train &&
                                existing.owner_ticket ==
                                        runtime
                                          ->conflict_zone_hard_ticket &&
                                existing.owner_route_generation ==
                                        runtime
                                          ->conflict_zone_route_generation &&
                                conflict_zone_settings_equal(
                                        &existing.setting,
                                        &member_step->setting);
                }
                if (!owns_current_traversal) {
                        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                        tc2_conflict_zone_request
                                requests[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                        int count = fill_conflict_zone_stage_requests(
                                slot, hard_step, zones, requests);
                        uint32_t hard_ticket = 0;
                        int hard_status = count ==
                                        hard_stage->member_count ?
                                Tc2ConflictZoneRequestHardStage(
                                        &dispatch_conflict_zones,
                                        zones, requests, count,
                                        &hard_ticket) : -1;
                        if (hard_status == 0 && hard_ticket != 0) {
                                runtime->conflict_zone_hard_step = hard_step;
                                runtime->conflict_zone_hard_ticket = hard_ticket;
                        } else if (hard_status < 0) {
                                return -1;
                        } else {
                                /*
                                 * A different, uncleared OCCUPIED/RELEASE
                                 * traversal cannot authorize this route
                                 * step.  The exact current ticket above is
                                 * deliberately retained until centre-exit;
                                 * otherwise the per-tick request refresh
                                 * makes a train lose its own authority while
                                 * it is physically inside the turnout.
                                 */
                                runtime->conflict_zone_hard_step = -1;
                                runtime->conflict_zone_hard_ticket = 0;
                        }
                }
        }

        return refresh_soft_conflict_zone_request(slot, hard_step);
}

static void reset_conflict_zone_action_cursor(
        tc2_dispatch_runtime *runtime) {
        if (!runtime) return;
        runtime->conflict_zone_action_step = -1;
        runtime->conflict_zone_action_index = 0;
        runtime->conflict_zone_action_ticket = 0;
}

static void reset_soft_conflict_zone_cursor(
        tc2_dispatch_runtime *runtime, int clear_confirmation) {
        if (!runtime) return;
        runtime->conflict_zone_soft_batch_token = 0;
        runtime->conflict_zone_soft_batch_step = -1;
        runtime->conflict_zone_soft_action_index = 0;
        runtime->conflict_zone_soft_settle_at_tick = -1;
        runtime->conflict_zone_soft_prefetched_step = -1;
        if (clear_confirmation) {
                runtime->conflict_zone_soft_confirmed_step = -1;
        }
}

/*
 * A soft request is not movement authority. It permits the eligible
 * next-next waiter to prepare only the concrete motor named by its route
 * action. Independent motors may be prepared while the shared physical zone
 * is occupied; hard entry remains exclusive for that whole zone. Compound
 * zones still command their real motors one at a time in route order.
 */
static int cancel_soft_conflict_zone_prefetch(int slot,
                                               int clear_confirmation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (runtime->conflict_zone_soft_batch_token != 0) {
                can_batch_status_t status;
                unsigned int token =
                        runtime->conflict_zone_soft_batch_token;
                if (CanGetBatchStatus(dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        return -1;
                }
        }
        reset_soft_conflict_zone_cursor(runtime, clear_confirmation);
        return 0;
}

/*
 * A train stopped at a rolling-authority ceiling publishes only its bounded
 * body as route reservation, but remains a resumable train. Its immutable
 * route and exact next/nextnext FIFO tickets are not movement authority and
 * are deliberately retained. A fresh bounded route window is still required
 * before positive speed, while the original queue entries prevent another
 * train from stealing or changing those turnouts during the safety stop.
 */
static int shrink_stopped_authority_to_anchor(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->rolling_authority_active ||
            runtime->traffic_reason != TC2_TRAFFIC_AUTHORITY ||
            runtime->traffic_hold_distance_um < 0 ||
            !runtime->route_valid ||
            job->current_route_offset < runtime->leg_start_offset ||
            job->current_route_offset >= runtime->route.node_count) {
                return 0;
        }

        int anchor = job->current_route_offset;
        if (update_stationary_hold(
                    slot, runtime->traffic_hold_distance_um) < 0) {
                return -1;
        }
        runtime->authority_end_offset = anchor;
        runtime->authority_center_ceiling_mm =
                (int)((runtime->traffic_hold_distance_um + 999) / 1000);
        runtime->authority_previous_end_offset = -1;
        runtime->authority_resume_pending = 0;
        runtime->authority_prefetch_active = 0;
        runtime->authority_prefetch_end_offset = -1;
        runtime->authority_prefetch_center_ceiling_mm = -1;
        runtime->authority_prefetch_settle_at_tick = -1;
        runtime->authority_prefetch_rearm_progress_mm = -1;
        runtime->reservation_anchor_offset = anchor;
        clear_authority_request(runtime);
        return 1;
}

/*
 * A safety/traffic stop freezes motion, not route memory.  Keep the exact
 * hard-next and soft-nextnext queue identities while the zero-speed command
 * settles and while the train waits.  Destination, cancel, and terminal
 * stops abandon future movement.
 */
static int traffic_stop_retains_turnout_plan(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        return runtime->conflict_zone_plan_valid &&
                runtime->stop_purpose == TC2_STOP_TRAFFIC &&
                (job->state == TC2_JOB_BRAKING ||
                 job->state == TC2_JOB_TRAFFIC_HOLD);
}

static int conflict_zone_job_command_suspended(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 1;
        if (traffic_stop_retains_turnout_plan(slot)) {
                return 0;
        }
        int state = dispatch_jobs[slot].state;
        return state == TC2_JOB_WAITING ||
               state == TC2_JOB_BRAKING ||
               state == TC2_JOB_TRAFFIC_HOLD;
}

static int soft_conflict_zone_job_can_command(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        int state = dispatch_jobs[slot].state;
        return state == TC2_JOB_PREPARING ||
               state == TC2_JOB_READY ||
               state == TC2_JOB_LAUNCHING ||
               state == TC2_JOB_RUNNING ||
               state == TC2_JOB_REVERSING ||
               state == TC2_JOB_TRAFFIC_HOLD;
}

static int soft_conflict_zone_still_eligible(int slot, int step_index) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int state = dispatch_jobs[slot].state;
        if (!runtime->conflict_zone_plan_valid || step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count ||
            state == TC2_JOB_STAGED ||
            (!soft_conflict_zone_job_can_command(slot) &&
             !traffic_stop_retains_turnout_plan(slot))) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] !=
                            runtime->conflict_zone_soft_step ||
            runtime->conflict_zone_soft_ticket == 0 ||
            runtime->conflict_zone_route_generation == 0) {
                return 0;
        }
        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        tc2_conflict_zone_request
                requests[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        int count = fill_conflict_zone_stage_requests(
                slot, stage->member_step[0], zones, requests);
        return count == stage->member_count &&
                Tc2ConflictZoneIsSoftStageControlHead(
                        &dispatch_conflict_zones, zones, count,
                        dispatch_jobs[slot].train,
                        runtime->conflict_zone_route_generation,
                        runtime->conflict_zone_soft_ticket) == 1;
}

static int conflict_zone_stage_settings_match_turnout_table(
        int slot, int stage_first_step) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan,
                        stage_first_step);
        if (!stage || stage->member_step[0] != stage_first_step) return 0;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                if (!conflict_zone_setting_matches_turnout_table(
                            &runtime->conflict_zone_plan.steps[raw_step]
                                     .setting)) {
                        return 0;
                }
        }
        return 1;
}

static int validate_soft_conflict_zone_prefetch(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int active_step = runtime->conflict_zone_soft_batch_step;
        const tc2_conflict_zone_route_stage *active_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, active_step);
        int active_stage_first = active_stage ?
                active_stage->member_step[0] : -1;
        int promoted_in_flight =
                active_stage_first >= 0 &&
                active_stage_first ==
                        runtime->conflict_zone_next_step &&
                runtime->conflict_zone_hard_step == active_stage_first &&
                runtime->conflict_zone_hard_ticket != 0;
        if ((runtime->conflict_zone_soft_batch_token != 0 ||
            runtime->conflict_zone_soft_settle_at_tick >= 0) &&
            !soft_conflict_zone_still_eligible(slot, active_step) &&
            !promoted_in_flight) {
                return cancel_soft_conflict_zone_prefetch(slot, 1);
        }
        int confirmed = runtime->conflict_zone_soft_confirmed_step;
        if (confirmed < 0) return 0;
        if (confirmed == runtime->conflict_zone_soft_step) {
                if (!soft_conflict_zone_still_eligible(
                            slot, confirmed) ||
                    !conflict_zone_stage_settings_match_turnout_table(
                            slot, confirmed)) {
                        runtime->conflict_zone_soft_confirmed_step = -1;
                        runtime->conflict_zone_soft_prefetched_step = -1;
                }
                return 0;
        }
        /*
         * A just-promoted confirmation may survive until global hard
         * arbitration.  No other cursor value is meaningful.
         */
        if (confirmed != runtime->conflict_zone_next_step ||
            runtime->conflict_zone_hard_step != confirmed ||
            runtime->conflict_zone_hard_ticket == 0) {
                runtime->conflict_zone_soft_confirmed_step = -1;
        }
        return 0;
}

static int queue_soft_conflict_zone_prefetch(int slot, int now) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int step_index = runtime->conflict_zone_soft_step;
        if (!runtime->conflict_zone_plan_valid || step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        /*
         * nextnext is preparation, not authority.  Its independent CAN
         * batch may be queued while next is still acquiring/settling its
         * hard ticket; the CAN server serializes the physical writes.  The
         * old coupling waited a full settle cycle before even starting the
         * look-ahead motor vector, which made an uncontended train brake at
         * every closely-spaced turnout (capture 69).
         */
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) return -1;
        if (!soft_conflict_zone_still_eligible(slot, step_index)) {
                return 0;
        }
        if (conflict_zone_stage_settings_match_turnout_table(
                    slot, step_index)) {
                runtime->conflict_zone_soft_prefetched_step = step_index;
                runtime->conflict_zone_soft_confirmed_step = step_index;
                return 0;
        }
        if (runtime->conflict_zone_soft_confirmed_step == step_index) {
                return 0;
        }
        if (runtime->conflict_zone_soft_batch_token != 0 ||
            runtime->conflict_zone_soft_settle_at_tick >= 0) {
                return 0;
        }
        int raw_step = -1;
        int action = -1;
        for (int member = 0;
             member < stage->member_count && raw_step < 0; ++member) {
                int candidate_step = stage->member_step[member];
                const tc2_conflict_zone_route_step *candidate =
                        &runtime->conflict_zone_plan
                                 .steps[candidate_step];
                for (int candidate_action = 0;
                     candidate_action <
                             candidate->setting.action_count;
                     ++candidate_action) {
                        if (!conflict_turnout_action_matches_table(
                                    &candidate->setting
                                             .actions[candidate_action])) {
                                raw_step = candidate_step;
                                action = candidate_action;
                                break;
                        }
                }
        }
        if (raw_step < 0 || action < 0) {
                runtime->conflict_zone_soft_prefetched_step = step_index;
                runtime->conflict_zone_soft_confirmed_step = step_index;
                runtime->conflict_zone_soft_batch_step = -1;
                runtime->conflict_zone_soft_action_index = 0;
                return 0;
        }
        const tc2_conflict_zone_route_step *step =
                &runtime->conflict_zone_plan.steps[raw_step];
        runtime->conflict_zone_soft_batch_step = raw_step;
        runtime->conflict_zone_soft_action_index = action;
        int switch_number =
                step->setting.actions[action].switch_number;
        char direction = conflict_turnout_action_direction(
                &step->setting.actions[action]);
        if (!direction) return -1;
        int token = CanSwitchBatch(
                dispatch_can_tid, &switch_number, &direction, 1);
        if (token == CAN_SEND_BUSY) return 0;
        if (token < 0) return -1;
        runtime->conflict_zone_soft_batch_token =
                token > 0 ? (unsigned int)token : 0;
        if (token == 0 &&
            record_turnout_direction(
                    switch_number, direction) < 0) {
                return -1;
        }
        runtime->conflict_zone_soft_settle_at_tick =
                token == 0 ?
                tick_after(now, TC2_TURNOUT_SETTLE_TICKS) : -1;
        return 0;
}

static int poll_soft_conflict_zone_prefetch(int slot, int now) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int step_index = runtime->conflict_zone_soft_batch_step;
        if (step_index < 0) return 0;
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        int stage_first = stage ? stage->member_step[0] : -1;
        int promoted_in_flight =
                stage_first >= 0 &&
                stage_first == runtime->conflict_zone_next_step &&
                runtime->conflict_zone_hard_step == stage_first &&
                runtime->conflict_zone_hard_ticket != 0;
        if (!soft_conflict_zone_still_eligible(slot, step_index) &&
            !promoted_in_flight) {
                return cancel_soft_conflict_zone_prefetch(slot, 1);
        }
        if (runtime->conflict_zone_soft_batch_token != 0) {
                can_batch_status_t status;
                unsigned int token =
                        runtime->conflict_zone_soft_batch_token;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        (void)cancel_soft_conflict_zone_prefetch(slot, 1);
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING) return 0;
                if (status.state != CAN_BATCH_COMPLETE ||
                    status.confirmed != status.total) {
                        reset_soft_conflict_zone_cursor(runtime, 1);
                        return 0;
                }
                const tc2_conflict_zone_route_step *confirmed_step =
                        &runtime->conflict_zone_plan.steps[step_index];
                int confirmed_action =
                        runtime->conflict_zone_soft_action_index;
                if (confirmed_action < 0 ||
                    confirmed_action >=
                            confirmed_step->setting.action_count ||
                    record_turnout_direction(
                            confirmed_step->setting
                                    .actions[confirmed_action]
                                    .switch_number,
                            conflict_turnout_action_direction(
                                    &confirmed_step->setting
                                             .actions[confirmed_action])) <
                            0) {
                        reset_soft_conflict_zone_cursor(runtime, 1);
                        return -1;
                }
                runtime->conflict_zone_soft_batch_token = 0;
                runtime->conflict_zone_soft_settle_at_tick =
                        tick_after(now, TC2_TURNOUT_SETTLE_TICKS);
                return 0;
        }
        if (runtime->conflict_zone_soft_settle_at_tick < 0 ||
            !tick_reached(now,
                    runtime->conflict_zone_soft_settle_at_tick)) {
                return 0;
        }
        runtime->conflict_zone_soft_settle_at_tick = -1;
        runtime->conflict_zone_soft_batch_step = -1;
        runtime->conflict_zone_soft_action_index = 0;
        if (stage_first >= 0 &&
            conflict_zone_stage_settings_match_turnout_table(
                    slot, stage_first)) {
                runtime->conflict_zone_soft_prefetched_step = stage_first;
                runtime->conflict_zone_soft_confirmed_step = stage_first;
        }
        return 0;
}

static int queue_owned_conflict_zone_setting(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        int stage_first = runtime->conflict_zone_next_step;
        if (!runtime->conflict_zone_plan_valid || stage_first < 0 ||
            stage_first >= runtime->conflict_zone_plan.step_count) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, stage_first);
        if (!stage || stage->member_step[0] != stage_first) return -1;
        if (runtime->conflict_zone_origin_egress_active &&
            runtime->conflict_zone_origin_egress_step == stage_first) {
                return origin_zone_egress_ready(
                        slot, stage_first) ? 0 : -1;
        }
        if (runtime->conflict_zone_hard_step != stage_first ||
            runtime->conflict_zone_hard_ticket == 0 ||
            runtime->conflict_zone_route_generation == 0) {
                return 0;
        }

        int unsettled_step = -1;
        tc2_conflict_zone_grant unsettled_grant;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, step->zone,
                            &grant) <= 0 ||
                    grant.owner_train != job->train ||
                    grant.owner_ticket !=
                            runtime->conflict_zone_hard_ticket ||
                    grant.owner_route_generation !=
                            runtime->conflict_zone_route_generation ||
                    !conflict_zone_settings_equal(
                            &grant.setting, &step->setting)) {
                        if (runtime->conflict_zone_soft_confirmed_step ==
                            stage_first) {
                                runtime->conflict_zone_soft_confirmed_step =
                                        -1;
                                runtime->conflict_zone_soft_prefetched_step =
                                        -1;
                        }
                        return 0;
                }
                if (grant.state == TC2_CONFLICT_ZONE_SETTLED ||
                    grant.state == TC2_CONFLICT_ZONE_OCCUPIED) {
                        continue;
                }
                if (grant.state != TC2_CONFLICT_ZONE_GRANTED &&
                    grant.state != TC2_CONFLICT_ZONE_SETTING) {
                        return 0;
                }
                if (unsettled_step < 0) {
                        unsettled_step = raw_step;
                        unsettled_grant = grant;
                }
        }
        if (unsettled_step < 0) {
                runtime->conflict_zone_queue_pending = 0;
                reset_conflict_zone_action_cursor(runtime);
                return 0;
        }

        const tc2_conflict_zone_route_step *step =
                &runtime->conflict_zone_plan.steps[unsettled_step];
        tc2_conflict_zone_grant grant = unsettled_grant;
        const tc2_conflict_zone_route_stage *soft_batch_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan,
                        runtime->conflict_zone_soft_batch_step);
        if (soft_batch_stage &&
            soft_batch_stage->member_step[0] == stage_first &&
            (runtime->conflict_zone_soft_batch_token != 0 ||
             runtime->conflict_zone_soft_settle_at_tick >= 0)) {
                /*
                 * The promoted nextnext batch is still confirming one member
                 * of this exact stage.  Finish it before issuing any hard
                 * duplicate; the remaining independent members keep their
                 * granted owner tickets meanwhile.
                 */
                return 0;
        }
        if (grant.state == TC2_CONFLICT_ZONE_GRANTED &&
            runtime->conflict_zone_soft_confirmed_step == stage_first &&
            conflict_zone_stage_settings_match_turnout_table(
                    slot, stage_first)) {
                /*
                 * Every member of this exact cohort was confirmed while its
                 * soft request was control-head. Promote each independent
                 * physical owner without retransmitting any motor.
                 */
                for (int member = 0;
                     member < stage->member_count; ++member) {
                        int raw_step = stage->member_step[member];
                        int zone = runtime->conflict_zone_plan
                                           .steps[raw_step].zone;
                        tc2_conflict_zone_grant member_grant;
                        if (Tc2ConflictZoneQueryGrant(
                                    &dispatch_conflict_zones, zone,
                                    &member_grant) <= 0 ||
                            member_grant.owner_train != job->train ||
                            member_grant.owner_ticket !=
                                    runtime->conflict_zone_hard_ticket) {
                                return -1;
                        }
                        if (member_grant.state ==
                                    TC2_CONFLICT_ZONE_GRANTED &&
                            Tc2ConflictZoneMarkSetting(
                                    &dispatch_conflict_zones, zone,
                                    job->train) < 0) {
                                return -1;
                        }
                        if ((member_grant.state ==
                                     TC2_CONFLICT_ZONE_GRANTED ||
                             member_grant.state ==
                                     TC2_CONFLICT_ZONE_SETTING) &&
                            Tc2ConflictZoneMarkSettled(
                                    &dispatch_conflict_zones, zone,
                                    job->train) < 0) {
                                return -1;
                        }
                }
                runtime->conflict_zone_soft_confirmed_step = -1;
                runtime->conflict_zone_soft_prefetched_step = -1;
                reset_conflict_zone_action_cursor(runtime);
                return 0;
        }
        if (grant.setting.action_count < 1 ||
            grant.setting.action_count >
                    TC2_CONFLICT_ZONE_MAX_ACTIONS) {
                return -1;
        }
        if (runtime->conflict_zone_action_step != unsettled_step ||
            runtime->conflict_zone_action_ticket !=
                    runtime->conflict_zone_hard_ticket) {
                if (runtime->conflict_zone_batch_token != 0 ||
                    runtime->conflict_zone_settle_at_tick >= 0) {
                        return -1;
                }
                runtime->conflict_zone_action_step = unsettled_step;
                runtime->conflict_zone_action_index = 0;
                runtime->conflict_zone_action_ticket =
                        runtime->conflict_zone_hard_ticket;
        }
        int action = runtime->conflict_zone_action_index;
        if (action < 0 || action > grant.setting.action_count) {
                return -1;
        }
        while (action < grant.setting.action_count &&
               conflict_turnout_action_matches_table(
                       &grant.setting.actions[action])) {
                ++action;
        }
        runtime->conflict_zone_action_index = action;
        if (action == grant.setting.action_count) {
                /*
                 * `next` still owns the exact FIFO ticket and verifies the
                 * physical-zone permission.  Its motor-setting phase is
                 * already complete because the confirmed turnout table
                 * matches this route's requested direction.  Startup values
                 * are defaults only and grant no permanent ownership.
                 */
                if (grant.state == TC2_CONFLICT_ZONE_GRANTED &&
                    Tc2ConflictZoneMarkSetting(
                            &dispatch_conflict_zones, step->zone,
                            job->train) < 0) {
                        return -1;
                }
                if (Tc2ConflictZoneMarkSettled(
                            &dispatch_conflict_zones, step->zone,
                            job->train) < 0) {
                        return -1;
                }
                reset_conflict_zone_action_cursor(runtime);
                runtime->conflict_zone_queue_pending = 1;
                return 0;
        }
        int switch_numbers[1];
        char directions[1];
        switch_numbers[0] =
                grant.setting.actions[action].switch_number;
        directions[0] = conflict_turnout_action_direction(
                &grant.setting.actions[action]);
        if (!directions[0]) return -1;
        int token = CanSwitchBatch(
                dispatch_can_tid, switch_numbers, directions,
                1);
        if (token == CAN_SEND_BUSY) {
                runtime->conflict_zone_queue_pending = 1;
                return 0;
        }
        if (token < 0) {
                return -1;
        }
        if (grant.state == TC2_CONFLICT_ZONE_GRANTED &&
            Tc2ConflictZoneMarkSetting(
                    &dispatch_conflict_zones, step->zone,
                    job->train) < 0) {
                if (token > 0) {
                        (void)CanCancelBatch(
                                dispatch_can_tid,
                                (unsigned int)token);
                }
                return -1;
        }
        runtime->conflict_zone_queue_pending = 0;
        runtime->conflict_zone_batch_token =
                token > 0 ? (unsigned int)token : 0;
        if (token == 0 &&
            record_turnout_direction(
                    switch_numbers[0], directions[0]) < 0) {
                return -1;
        }
        runtime->conflict_zone_settle_at_tick =
                token == 0 ?
                tick_after(Time(), TC2_TURNOUT_SETTLE_TICKS) : -1;
        return 0;
}

/*
 * Move the immutable look-ahead cursor only.  The next global arbitration
 * pass will grant and then physically set the new exact hard turnout.
 */
static int promote_next_conflict_zone_after_entry(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        int step_index = runtime->conflict_zone_next_step;

        if (!runtime->conflict_zone_plan_valid ||
            step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count) {
                (void)Tc2ConflictZoneCancelSoft(
                        &dispatch_conflict_zones, job->train);
                runtime->conflict_zone_soft_step = -1;
                runtime->conflict_zone_soft_ticket = 0;
                runtime->conflict_zone_soft_batch_step = -1;
                runtime->conflict_zone_soft_action_index = 0;
                runtime->conflict_zone_soft_settle_at_tick = -1;
                runtime->conflict_zone_soft_prefetched_step = -1;
                runtime->conflict_zone_soft_confirmed_step = -1;
                return 0;
        }

        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) return -1;
        int promoted_confirmation =
                runtime->conflict_zone_soft_confirmed_step == step_index &&
                soft_conflict_zone_still_eligible(slot, step_index);
        int promoted_in_flight =
                runtime->conflict_zone_soft_batch_step == step_index &&
                (runtime->conflict_zone_soft_batch_token != 0 ||
                 runtime->conflict_zone_soft_settle_at_tick >= 0);
        if (runtime->conflict_zone_soft_batch_token != 0) {
                unsigned int token =
                        runtime->conflict_zone_soft_batch_token;
                can_batch_status_t status;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        return -1;
                }
                if (status.state == CAN_BATCH_FAILED ||
                    (status.state == CAN_BATCH_COMPLETE &&
                     status.confirmed != status.total)) {
                        reset_soft_conflict_zone_cursor(runtime, 1);
                        promoted_in_flight = 0;
                }
        }
        /*
         * Do not cancel the soft request here. RequestHard promotes this
         * exact nextnext FIFO entry to next in place, retaining its ticket
         * and queue age. Its already-confirmed or in-flight motor proof also
         * remains attached to this immutable step. refresh below then queues
         * the newly exposed following step as the new nextnext.
         */
        if (!promoted_confirmation && !promoted_in_flight &&
            runtime->conflict_zone_soft_confirmed_step == step_index) {
                runtime->conflict_zone_soft_confirmed_step = -1;
                runtime->conflict_zone_soft_prefetched_step = -1;
        }
        if (refresh_conflict_zone_requests(slot) < 0) {
                return -1;
        }

        int owns_exact_ticket =
                runtime->conflict_zone_hard_step == step_index &&
                runtime->conflict_zone_hard_ticket != 0;
        for (int member = 0;
             owns_exact_ticket && member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                const tc2_conflict_zone_route_step *member_step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                tc2_conflict_zone_grant grant;
                owns_exact_ticket =
                        Tc2ConflictZoneQueryGrant(
                                &dispatch_conflict_zones,
                                member_step->zone, &grant) > 0 &&
                        grant.owner_train == job->train &&
                        grant.owner_ticket ==
                                runtime->conflict_zone_hard_ticket &&
                        grant.owner_route_generation ==
                                runtime
                                  ->conflict_zone_route_generation &&
                        conflict_zone_settings_equal(
                                &grant.setting,
                                &member_step->setting);
        }
        if (!owns_exact_ticket) return 0;

        /* A grant can only exist from a prior global pass; never fabricate it. */
        if (queue_owned_conflict_zone_setting(slot) < 0) {
                return -1;
        }
        return 0;
}

static int conflict_zone_job_can_request(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        /*
         * A public reroute whose destination is behind the train must first
         * complete its physical direction change.  The new route geometry may
         * already be installed as a fail-closed body/track reservation, but no
         * next/nextnext turnout owner, queue request, or switch command may be
         * taken from it until the reverse has mechanically settled.
         */
        if (runtime->reroute_reverse_before_resources) return 0;
        switch (job->state) {
        case TC2_JOB_PREPARING:
        case TC2_JOB_READY:
        case TC2_JOB_LAUNCHING:
        case TC2_JOB_RUNNING:
        case TC2_JOB_REVERSING:
                return 1;
        case TC2_JOB_TRAFFIC_HOLD:
                return traffic_stop_retains_turnout_plan(slot);
        default:
                return 0;
        }
}

/*
 * WAITING and non-traffic stops are physical obstacles without future route
 * intent, so they relinquish queued commands.  A traffic/safety stop is
 * deliberately excluded by conflict_zone_job_command_suspended(): it keeps
 * the complete plan and its FIFO identities and merely remains at speed zero
 * until the ordinary movement gates pass again.
 * If the train stopped before an already-granted current zone, also yield
 * that unentered owner; an OCCUPIED or position-ambiguous owner remains
 * fail-closed until real progress proves tail clearance.
 */
static int suspend_conflict_zone_command_rights(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!conflict_zone_job_command_suspended(slot)) {
                return 0;
        }

        int retain_soft = job->state == TC2_JOB_TRAFFIC_HOLD;
        if ((!retain_soft &&
             (cancel_soft_conflict_zone_prefetch(slot, 1) < 0 ||
              Tc2ConflictZoneCancelSoft(
                    &dispatch_conflict_zones, job->train) < 0)) ||
            Tc2ConflictZoneCancelHard(
                    &dispatch_conflict_zones, job->train) < 0) {
                return -1;
        }
        if (!retain_soft) {
                runtime->conflict_zone_soft_step = -1;
                runtime->conflict_zone_soft_ticket = 0;
        }

        if (runtime->conflict_zone_batch_token != 0) {
                can_batch_status_t status;
                unsigned int token = runtime->conflict_zone_batch_token;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        return -1;
                }
        }
        runtime->conflict_zone_batch_token = 0;
        runtime->conflict_zone_queue_pending = 0;
        runtime->conflict_zone_settle_at_tick = -1;
        reset_conflict_zone_action_cursor(runtime);

        int step_index = runtime->conflict_zone_hard_step;
        if (!runtime->conflict_zone_plan_valid || step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count ||
            runtime->conflict_zone_hard_ticket == 0) {
                runtime->conflict_zone_hard_step = -1;
                runtime->conflict_zone_hard_ticket = 0;
                runtime->conflict_zone_queue_pending = 0;
                return 0;
        }

        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) {
                runtime->conflict_zone_hard_step = -1;
                runtime->conflict_zone_hard_ticket = 0;
                runtime->conflict_zone_queue_pending = 0;
                reset_conflict_zone_action_cursor(runtime);
                return 0;
        }

        int64_t centre_um = runtime->traffic_hold_distance_um;
        if (centre_um < 0 && runtime->monitor.confirmed_distance_mm >= 0) {
                centre_um = (int64_t)runtime->monitor.confirmed_distance_mm *
                        1000;
        }
        tc2_conflict_zone_grant
                stage_grants[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        int stage_zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        int owned_members = 0;
        int all_owned_members_unentered = 1;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[raw_step];
                stage_zones[member] = step->zone;
                tc2_conflict_zone_grant *grant = &stage_grants[member];
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, step->zone,
                            grant) <= 0 ||
                    grant->owner_train != job->train ||
                    grant->owner_ticket !=
                            runtime->conflict_zone_hard_ticket) {
                        continue;
                }
                ++owned_members;
                if (grant->state == TC2_CONFLICT_ZONE_OCCUPIED ||
                    grant->state == TC2_CONFLICT_ZONE_RELEASE_DELAY) {
                        all_owned_members_unentered = 0;
                        continue;
                }
                int unentered =
                        grant->state == TC2_CONFLICT_ZONE_GRANTED ||
                        (centre_um >= 0 &&
                         centre_um +
                                         (int64_t)
                                                 TC2_TRAIN_HALF_LENGTH_MM *
                                                 1000 <
                                 (int64_t)(step->entry_distance_mm - 20) *
                                         1000);
                if (!unentered) {
                        all_owned_members_unentered = 0;
                }
        }
        if (owned_members == 0) {
                runtime->conflict_zone_hard_step = -1;
                runtime->conflict_zone_hard_ticket = 0;
                return 0;
        }
        /*
         * A compound stage is one cohort.  Never yield only the members
         * which appear unentered while retaining another member: that leaves
         * a partial owner cohort which can neither move nor be reacquired.
         * The central dispatcher is the sole writer, so after this complete
         * validation the following all-member release cannot race another
         * train's decision.
         */
        if (owned_members != stage->member_count) return -1;
        if (!all_owned_members_unentered) return 0;
        if (Tc2ConflictZoneYieldUnenteredStage(
                    &dispatch_conflict_zones, stage_zones,
                    stage->member_count, job->train,
                    runtime->conflict_zone_route_generation,
                    runtime->conflict_zone_hard_ticket) < 0) {
                return -1;
        }
        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        return 0;
}

enum {
        TC2_CONFLICT_CARRY_UNKNOWN = 0,
        TC2_CONFLICT_CARRY_UNENTERED = 1,
        TC2_CONFLICT_CARRY_OCCUPIED = 2,
        TC2_CONFLICT_CARRY_TAIL_CLEAR = 3
};

static void remove_conflict_zone_carry(
        tc2_dispatch_runtime *runtime, int index) {
        if (!runtime || index < 0 ||
            index >= runtime->conflict_zone_carry_count) {
                return;
        }
        int removed_origin_member =
                runtime->conflict_zone_origin_egress_active &&
                runtime->conflict_zone_carry_ticket[index] ==
                        runtime->conflict_zone_origin_egress_ticket &&
                runtime->conflict_zone_carry_route_generation[index] ==
                        runtime
                          ->conflict_zone_origin_egress_route_generation;
        int last = --runtime->conflict_zone_carry_count;
        if (index != last) {
                runtime->conflict_zone_carry_zone[index] =
                        runtime->conflict_zone_carry_zone[last];
                runtime->conflict_zone_carry_entry_node[index] =
                        runtime->conflict_zone_carry_entry_node[last];
                runtime->conflict_zone_carry_exit_node[index] =
                        runtime->conflict_zone_carry_exit_node[last];
                runtime->conflict_zone_carry_exit_distance_mm[index] =
                        runtime->conflict_zone_carry_exit_distance_mm[last];
                runtime->conflict_zone_carry_scalar_proof_valid[index] =
                        runtime->conflict_zone_carry_scalar_proof_valid[last];
                runtime->conflict_zone_carry_ticket[index] =
                        runtime->conflict_zone_carry_ticket[last];
                runtime->conflict_zone_carry_route_generation[index] =
                        runtime
                          ->conflict_zone_carry_route_generation[last];
                runtime->conflict_zone_carry_mode[index] =
                        runtime->conflict_zone_carry_mode[last];
        }
        runtime->conflict_zone_carry_zone[last] =
                TC2_CONFLICT_ZONE_NONE;
        runtime->conflict_zone_carry_entry_node[last] = -1;
        runtime->conflict_zone_carry_exit_node[last] = -1;
        runtime->conflict_zone_carry_exit_distance_mm[last] = -1;
        runtime->conflict_zone_carry_scalar_proof_valid[last] = 0;
        runtime->conflict_zone_carry_ticket[last] = 0;
        runtime->conflict_zone_carry_route_generation[last] = 0;
        runtime->conflict_zone_carry_mode[last] =
                TC2_CONFLICT_CARRY_UNKNOWN;
        if (removed_origin_member) {
                int cohort_member_remains = 0;
                for (int carry = 0;
                     carry < runtime->conflict_zone_carry_count; ++carry) {
                        if (runtime->conflict_zone_carry_ticket[carry] ==
                                    runtime
                                      ->conflict_zone_origin_egress_ticket &&
                            runtime
                              ->conflict_zone_carry_route_generation[carry] ==
                                    runtime
                                      ->conflict_zone_origin_egress_route_generation) {
                                cohort_member_remains = 1;
                                break;
                        }
                }
                if (!cohort_member_remains) {
                        clear_origin_zone_egress(runtime);
                }
        }
}

/*
 * Carry records are route-geometry evidence for one immutable owner ticket.
 * A short-corridor stage can contribute several records with that ticket;
 * they must be inspected and retired as one cohort.  Keeping this grouping
 * in the dispatcher preserves the exact entry/exit proof for each member,
 * while the conflict-zone table performs the atomic owner transition.
 */
static int collect_conflict_zone_carry_cohort(
        const tc2_dispatch_runtime *runtime, unsigned int ticket,
        unsigned int route_generation,
        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS],
        int indices[TC2_CONFLICT_STAGE_MAX_MEMBERS]) {
        if (!runtime || !zones || !indices || ticket == 0 ||
            route_generation == 0) return -1;
        int count = 0;
        for (int index = 0;
             index < runtime->conflict_zone_carry_count; ++index) {
                if (runtime->conflict_zone_carry_ticket[index] != ticket ||
                    runtime->conflict_zone_carry_route_generation[index] !=
                            route_generation) {
                        continue;
                }
                int zone = runtime->conflict_zone_carry_zone[index];
                if (zone < 0 || zone >= TC2_CONFLICT_ZONE_COUNT ||
                    count >= TC2_CONFLICT_STAGE_MAX_MEMBERS) {
                        return -1;
                }
                for (int member = 0; member < count; ++member) {
                        if (zones[member] == zone) return -1;
                }
                zones[count] = zone;
                indices[count] = index;
                ++count;
        }
        return count > 0 ? count : -1;
}

static void remove_conflict_zone_carry_cohort(
        tc2_dispatch_runtime *runtime, unsigned int ticket,
        unsigned int route_generation) {
        if (!runtime || ticket == 0 || route_generation == 0) return;
        int index = 0;
        while (index < runtime->conflict_zone_carry_count) {
                if (runtime->conflict_zone_carry_ticket[index] == ticket &&
                    runtime->conflict_zone_carry_route_generation[index] ==
                            route_generation) {
                        remove_conflict_zone_carry(runtime, index);
                        continue;
                }
                ++index;
        }
}

static int conflict_zone_carry_is_cohort_first(
        const tc2_dispatch_runtime *runtime, int index) {
        if (!runtime || index < 0 ||
            index >= runtime->conflict_zone_carry_count) {
                return 0;
        }
        unsigned int ticket =
                runtime->conflict_zone_carry_ticket[index];
        unsigned int route_generation =
                runtime->conflict_zone_carry_route_generation[index];
        for (int earlier = 0; earlier < index; ++earlier) {
                if (runtime->conflict_zone_carry_ticket[earlier] == ticket &&
                    runtime->conflict_zone_carry_route_generation[earlier] ==
                            route_generation) {
                        return 0;
                }
        }
        return ticket != 0 && route_generation != 0;
}

static int remember_conflict_zone_carry(
        tc2_dispatch_runtime *runtime, int zone,
        int entry_node, int exit_node, int exit_distance_mm,
        int scalar_proof_valid, unsigned int ticket,
        unsigned int route_generation,
        int mode) {
        if (!runtime || zone < 0 ||
            zone >= TC2_CONFLICT_ZONE_COUNT || ticket == 0 ||
            route_generation == 0) {
                return -1;
        }
        for (int index = 0;
             index < runtime->conflict_zone_carry_count; ++index) {
                if (runtime->conflict_zone_carry_zone[index] != zone) {
                        continue;
                }
                /* Preserve older geometry while the same traversal lives. */
                if (runtime->conflict_zone_carry_ticket[index] == ticket &&
                    runtime->conflict_zone_carry_route_generation[index] ==
                            route_generation) {
                        return 0;
                }
                /*
                 * One physical zone cannot have two live owner tickets.
                 * Replacing this entry would lose the exact geometry needed
                 * to release the older traversal, so fail closed instead.
                 */
                return -1;
        }
        if (runtime->conflict_zone_carry_count >=
            TC2_CONFLICT_ZONE_COUNT) {
                return -1;
        }
        int index = runtime->conflict_zone_carry_count++;
        runtime->conflict_zone_carry_zone[index] = zone;
        runtime->conflict_zone_carry_entry_node[index] = entry_node;
        runtime->conflict_zone_carry_exit_node[index] = exit_node;
        runtime->conflict_zone_carry_exit_distance_mm[index] =
                exit_distance_mm;
        runtime->conflict_zone_carry_scalar_proof_valid[index] =
                scalar_proof_valid ? 1 : 0;
        runtime->conflict_zone_carry_ticket[index] = ticket;
        runtime->conflict_zone_carry_route_generation[index] =
                route_generation;
        runtime->conflict_zone_carry_mode[index] = (unsigned char)mode;
        return 0;
}

/*
 * Snapshot, but do not release, every physical owner before a CURRENT route
 * replaces its route storage.  This pure bookkeeping step is safe to copy
 * across stage_job() and safe to roll back if the reservation CAS fails.
 */
static int snapshot_owned_conflict_zone_carries(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        for (int zone = 0; zone < TC2_CONFLICT_ZONE_COUNT; ++zone) {
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, zone, &grant) <= 0 ||
                    grant.owner_train != job->train ||
                    grant.owner_ticket == 0 ||
                    grant.state == TC2_CONFLICT_ZONE_RELEASE_DELAY) {
                        continue;
                }

                int already_recorded = 0;
                for (int carry = 0;
                     carry < runtime->conflict_zone_carry_count; ++carry) {
                        if (runtime->conflict_zone_carry_zone[carry] != zone) {
                                continue;
                        }
                        if (runtime->conflict_zone_carry_ticket[carry] !=
                                    grant.owner_ticket ||
                            runtime
                              ->conflict_zone_carry_route_generation[carry] !=
                                    grant.owner_route_generation) {
                                return -1;
                        }
                        already_recorded = 1;
                        break;
                }
                if (already_recorded) continue;

                /*
                 * The hard grant records its exact immutable route step at
                 * ticket creation.  Never recover it by nearest-distance or
                 * zone/setting matching: a route may visit the same turnout
                 * more than once with the same S/C setting.
                 */
                int old_step = runtime->conflict_zone_hard_step;
                if (runtime->conflict_zone_hard_ticket !=
                            grant.owner_ticket ||
                    old_step < 0 ||
                    !runtime->conflict_zone_plan_valid ||
                    !runtime->route_valid ||
                    old_step >= runtime->conflict_zone_plan.step_count) {
                        return -1;
                }
                const tc2_conflict_zone_route_stage *hard_stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan,
                                old_step);
                if (!hard_stage ||
                    hard_stage->member_step[0] != old_step ||
                    grant.owner_route_generation !=
                            runtime->conflict_zone_route_generation) {
                        return -1;
                }
                int owned_step = -1;
                for (int member = 0;
                     member < hard_stage->member_count; ++member) {
                        int raw_step = hard_stage->member_step[member];
                        if (raw_step < 0 ||
                            raw_step >=
                                    runtime->conflict_zone_plan.step_count) {
                                return -1;
                        }
                        if (runtime->conflict_zone_plan.steps[raw_step].zone ==
                                    zone) {
                                if (owned_step >= 0) return -1;
                                owned_step = raw_step;
                        }
                }
                if (owned_step < 0) return -1;
                int entry_node = -1;
                int exit_node = -1;
                int mode = TC2_CONFLICT_CARRY_UNKNOWN;
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[owned_step];
                if (step->first_route_offset < 0 ||
                    step->first_route_offset >= runtime->route.node_count ||
                    step->last_route_offset < 0 ||
                    step->last_route_offset >= runtime->route.node_count) {
                        return -1;
                }
                entry_node = runtime->route.nodes[
                        step->first_route_offset];
                exit_node = runtime->route.nodes[
                        step->last_route_offset];
                /*
                 * monitor.confirmed_distance_mm is advanced only by an
                 * accepted physical sensor.  job->position_estimated merely
                 * describes the continuously rendered centre position and
                 * must not suppress this hard route-scalar proof.
                 */
                int confirmed = step &&
                        runtime->monitor.confirmed_distance_mm >= 0;
                int before_entry = confirmed &&
                        runtime->monitor.confirmed_distance_mm +
                                        TC2_TRAIN_HALF_LENGTH_MM <
                                step->entry_distance_mm - 20;
                int after_exit = confirmed &&
                        runtime->monitor.confirmed_distance_mm -
                                        TC2_TRAIN_HALF_LENGTH_MM >
                                step->exit_distance_mm + 20;
                if (grant.state == TC2_CONFLICT_ZONE_GRANTED) {
                        mode = TC2_CONFLICT_CARRY_UNENTERED;
                } else if (grant.state == TC2_CONFLICT_ZONE_OCCUPIED) {
                        mode = after_exit ?
                                TC2_CONFLICT_CARRY_TAIL_CLEAR :
                                TC2_CONFLICT_CARRY_OCCUPIED;
                } else if ((grant.state ==
                                    TC2_CONFLICT_ZONE_SETTING ||
                            grant.state ==
                                    TC2_CONFLICT_ZONE_SETTLED) &&
                           before_entry) {
                        mode = TC2_CONFLICT_CARRY_UNENTERED;
                }
                if (remember_conflict_zone_carry(
                        runtime, zone, entry_node, exit_node,
                        step->exit_distance_mm, 1,
                        grant.owner_ticket,
                        grant.owner_route_generation, mode) < 0) {
                        return -1;
                }
        }
        return 0;
}

static int cancel_old_conflict_zone_batch(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        unsigned int tokens[2] = {
                runtime->conflict_zone_batch_token,
                runtime->conflict_zone_soft_batch_token
        };
        for (int index = 0; index < 2; ++index) {
                unsigned int token = tokens[index];
                if (token == 0) continue;
                can_batch_status_t status;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        return -1;
                }
        }
        runtime->conflict_zone_batch_token = 0;
        reset_soft_conflict_zone_cursor(runtime, 1);
        runtime->conflict_zone_queue_pending = 0;
        runtime->conflict_zone_settle_at_tick = -1;
        reset_conflict_zone_action_cursor(runtime);
        return 0;
}

/*
 * A stopped traffic recovery is driven exclusively by the progressive
 * conflict-zone cursor.  Any older whole-window turnout batch belongs to the
 * admission which was just invalidated and must not keep PREPARING waiting or
 * program motors beyond nextnext.
 */
static int discard_old_prelaunch_turnout_batch(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (runtime->turnout_batch_token != 0) {
                unsigned int token = runtime->turnout_batch_token;
                can_batch_status_t status;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token || status.total < 1 ||
                    status.confirmed < 0 ||
                    status.confirmed > status.total) {
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        return -1;
                }
        }
        runtime->turnout_batch_token = 0;
        runtime->turnout_queue_pending = 0;
        runtime->prelaunch_turnout_settle_at_tick = -1;
        return 0;
}

/*
 * Cancel future turnout commands without pretending the train disappeared.
 * Keep immutable route geometry only long enough to classify already-owned
 * zone tickets against the final bounded body interval.  That geometry is
 * provenance, not authority: cancel never preserves old next/nextnext motor
 * rights or an unoccupied future zone merely because it was on the old route.
 */
static int discard_future_conflict_zone_work(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state == TC2_JOB_EMPTY) return 0;

        if (snapshot_owned_conflict_zone_carries(slot) < 0 ||
            cancel_old_conflict_zone_batch(slot) < 0) {
                return -1;
        }

        /* A canceled CAN batch cannot leave the software zone in SETTING. */
        for (int zone = 0; zone < TC2_CONFLICT_ZONE_COUNT; ++zone) {
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, zone,
                            &grant) > 0 &&
                    grant.owner_train == job->train &&
                    grant.state == TC2_CONFLICT_ZONE_SETTING) {
                        if (Tc2ConflictZoneRetrySetting(
                                    &dispatch_conflict_zones,
                                    zone, job->train) < 0) {
                                return -1;
                        }
                }
        }
        if (Tc2ConflictZoneCancelTrain(
                    &dispatch_conflict_zones, job->train) < 0) {
                return -1;
        }

        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        runtime->conflict_zone_soft_ticket = 0;
        runtime->conflict_zone_hold_active = 0;
        clear_origin_zone_egress(runtime);
        return 0;
}

static int terminal_static_footprint_committed(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        return job->plan_generation != 0 &&
                job->hold_active &&
                runtime->safety_footprint.node_count > 0 &&
                runtime->static_center_bounds_valid &&
                runtime->static_center_lower_um >= 0 &&
                runtime->static_center_upper_um >=
                        runtime->static_center_lower_um;
}

/*
 * Retire only future movement authority.  The immutable route/monitor and
 * bounded safety_footprint remain as directed pose history for UI and
 * collision auditing; none of those retained fields can authorize motion
 * once movement_plan_active is clear.
 */
static void retire_future_control_fields(
        tc2_dispatch_runtime *runtime) {
        if (!runtime) return;
        /*
         * A public CURRENT reroute is a new operator command, not authority
         * belonging to the route being retired.  A train can arrive, fail
         * closed, or finish a cancel between `reroute` and `go`; terminal
         * cleanup must still discard every old next/nextnext owner without
         * silently deleting that newer command.  cancel_job() deliberately
         * clears retarget_pending before calling here, so an explicit cancel
         * still cancels an uncommitted reroute as expected.
         */
        int preserve_operator_retarget =
                runtime->retarget_pending &&
                runtime->retarget_operator_reroute;
        int preserve_physical_reverse =
                runtime->retarget_reverse_pending ||
                runtime->retarget_direction_locked;
        int saved_retarget_armed = runtime->retarget_armed;
        int saved_retarget_speed = runtime->retarget_speed;
        int saved_retarget_destination =
                runtime->retarget_destination_index;
        unsigned int saved_retarget_expected_generation =
                runtime->retarget_expected_generation;
        int saved_retarget_expected_destination =
                runtime->retarget_expected_destination;
        unsigned int saved_retarget_queue_sequence =
                runtime->retarget_queue_sequence;
        unsigned int saved_retarget_launch_epoch =
                runtime->retarget_launch_epoch;
        int saved_retarget_force_reverse_first =
                runtime->retarget_force_reverse_first;
        int saved_retarget_reverse_pending =
                runtime->retarget_reverse_pending;
        int saved_retarget_reverse_ready_at_tick =
                runtime->retarget_reverse_ready_at_tick;
        int saved_retarget_direction_locked =
                runtime->retarget_direction_locked;
        int saved_retarget_direction_anchor_node =
                runtime->retarget_direction_anchor_node;
        unsigned int saved_retarget_direction_anchor_sequence =
                runtime->retarget_direction_anchor_sequence;
        runtime->movement_plan_active = 0;
        runtime->planned_launch_speed = 0;
        runtime->rolling_authority_active = 0;
        runtime->authority_end_offset = -1;
        runtime->authority_center_ceiling_mm = -1;
        clear_authority_request(runtime);
        runtime->authority_resume_pending = 0;
        runtime->authority_prefetch_active = 0;
        runtime->authority_prefetch_end_offset = -1;
        runtime->authority_prefetch_center_ceiling_mm = -1;
        runtime->authority_prefetch_settle_at_tick = -1;
        runtime->authority_prefetch_rearm_progress_mm = -1;
        runtime->authority_previous_end_offset = -1;
        runtime->force_reverse_first = 0;
        runtime->reroute_select_direction = 0;
        runtime->prelaunch_reverse_pending = 0;
        runtime->prelaunch_reverse_ready_at_tick = -1;
        runtime->reroute_reverse_before_resources = 0;
        runtime->reverse_ready_at_tick = -1;
        runtime->reversal_phase = TC2_REVERSAL_PHASE_NONE;
        runtime->retarget_pending = 0;
        runtime->retarget_armed = 0;
        runtime->retarget_speed = 0;
        runtime->retarget_destination_index = -1;
        runtime->retarget_expected_generation = 0;
        runtime->retarget_expected_destination = -1;
        runtime->retarget_queue_sequence = 0;
        runtime->retarget_launch_epoch = 0;
        runtime->retarget_force_reverse_first = 0;
        runtime->retarget_operator_reroute = 0;
        runtime->retarget_reverse_pending = 0;
        runtime->retarget_reverse_ready_at_tick = -1;
        runtime->retarget_direction_locked = 0;
        runtime->retarget_direction_anchor_node = -1;
        runtime->retarget_direction_anchor_sequence = 0;
        runtime->destination_correction_active = 0;
        runtime->destination_correction_pending = 0;
        runtime->destination_correction_attempted = 0;
        runtime->destination_correction_deadline_tick = -1;
        runtime->destination_correction_sensor_offset = -1;
        runtime->destination_correction_reached_endpoint = 0;
        runtime->prelaunch_traffic_blocked = 0;
        if (preserve_operator_retarget) {
                runtime->retarget_pending = 1;
                runtime->retarget_armed = saved_retarget_armed;
                runtime->retarget_speed = saved_retarget_speed;
                runtime->retarget_destination_index =
                        saved_retarget_destination;
                runtime->retarget_expected_generation =
                        saved_retarget_expected_generation;
                runtime->retarget_expected_destination =
                        saved_retarget_expected_destination;
                runtime->retarget_queue_sequence =
                        saved_retarget_queue_sequence;
                runtime->retarget_launch_epoch =
                        saved_retarget_launch_epoch;
                runtime->retarget_force_reverse_first =
                        saved_retarget_force_reverse_first;
                runtime->retarget_operator_reroute = 1;
                runtime->retarget_reverse_pending =
                        saved_retarget_reverse_pending;
                runtime->retarget_reverse_ready_at_tick =
                        saved_retarget_reverse_ready_at_tick;
                runtime->retarget_direction_locked =
                        saved_retarget_direction_locked;
                runtime->retarget_direction_anchor_node =
                        saved_retarget_direction_anchor_node;
                runtime->retarget_direction_anchor_sequence =
                        saved_retarget_direction_anchor_sequence;
        } else if (preserve_physical_reverse) {
                runtime->retarget_reverse_pending =
                        saved_retarget_reverse_pending;
                runtime->retarget_reverse_ready_at_tick =
                        saved_retarget_reverse_ready_at_tick;
                runtime->retarget_direction_locked =
                        saved_retarget_direction_locked;
                runtime->retarget_direction_anchor_node =
                        saved_retarget_direction_anchor_node;
                runtime->retarget_direction_anchor_sequence =
                        saved_retarget_direction_anchor_sequence;
        }
}

/*
 * ARRIVED and operator-canceled trains are static bodies, not route
 * controllers.  Their already-committed bounded reservation is the complete
 * collision footprint.  It may block a chosen branch which physically reaches
 * the body, but it must never own an adjacent turnout, retain next/nextnext, or
 * keep an old conflict ticket merely because that turnout occurred on the old
 * route.  Release every queue/owner through the normal two-second handoff and
 * then erase the terminal train's turnout memory.  A resumable TRAFFIC_HOLD
 * never enters this function and therefore retains its immutable route and
 * both queue stages.
 */
static int retire_terminal_conflict_zone_memory(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state != TC2_JOB_ARRIVED &&
            job->state != TC2_JOB_STOPPED &&
            job->state != TC2_JOB_CANCEL_BRAKING) {
                return -1;
        }
        /*
         * Dynamic control is never released before a bounded body reservation
         * has committed.  This is the cancel/arrival handoff invariant.
         */
        if (!terminal_static_footprint_committed(slot)) {
                return -1;
        }

        Tc2ConflictZoneTick(
                &dispatch_conflict_zones, (uint32_t)now);
        /* No terminal job may leave a queued motor command behind. */
        if (cancel_old_conflict_zone_batch(slot) < 0 ||
            discard_old_prelaunch_turnout_batch(slot) < 0) {
                return -1;
        }
        if (Tc2ConflictZoneRemoveTrain(
                    &dispatch_conflict_zones,
                    job->train, 1) < 0) {
                return -1;
        }

        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        runtime->conflict_zone_soft_ticket = 0;
        runtime->conflict_zone_hold_active = 0;
        reset_conflict_zone_action_cursor(runtime);
        reset_soft_conflict_zone_cursor(runtime, 1);
        clear_origin_zone_egress(runtime);

        runtime->conflict_zone_carry_count = 0;
        runtime->carry_ambiguity_active = 0;
        runtime->conflict_zone_plan.step_count = 0;
        runtime->conflict_zone_plan.stage_count = 0;
        runtime->conflict_zone_plan_valid = 0;
        runtime->conflict_zone_next_step = 0;
        runtime->conflict_zone_route_generation = 0;
        /*
         * Keep route/current_node only as immutable directed pose history for
         * collision auditing and UI.  It is no longer an active movement
         * route and can never be reused by a positive-speed gate.
         */
        retire_future_control_fields(runtime);
        if (runtime->lifecycle_stop_reason ==
                    TC2_LIFECYCLE_STOP_NONE) {
                runtime->lifecycle_stop_reason =
                        job->state == TC2_JOB_ARRIVED ?
                        TC2_LIFECYCLE_STOP_DESTINATION :
                        TC2_LIFECYCLE_STOP_OPERATOR_CANCEL;
        }
        return 0;
}

/*
 * Restart a live survivor after the peer that caused its traffic stop became
 * a stationary block.  This is deliberately different from cancel/CURRENT:
 * the survivor keeps the same immutable route and must not turn its own
 * unentered hard-next grant into a historical carry.  Doing that made the
 * nextnext scan skip the changed SW8/SW9 direction and then launch on the
 * stale global turnout table (capture 119).
 *
 * A GRANTED/SETTING owner has not entered.  A SETTLED owner may be yielded
 * only with real sensor proof that the complete front is still before entry.
 * OCCUPIED/RELEASE_DELAY, or an uncertain SETTLED owner, remains attached to
 * the train.  In every case advisory confirmation is discarded so the next
 * preparation pass compares every upcoming motor against the live table.
 */
static int restart_conflict_zone_work_from_frozen_position(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        /*
         * A safety stop keeps the immutable route, cursor and exact hard/soft
         * FIFO identities. A peer becoming static/removed invalidates only
         * advisory motor confirmations and CAN work which was prepared under
         * the old topology. Cancel those commands, return an unentered hard
         * owner from SETTING to GRANTED, then let the ordinary scheduler
         * compare the preserved next/nextnext steps with the live turnout
         * table again. Never reconstruct position from a modelled stop point
         * and never surrender either queue ticket here.
         */
        if (job->state == TC2_JOB_EMPTY ||
            !runtime->conflict_zone_plan_valid ||
            !runtime->route_valid) {
                return -1;
        }
        if (discard_old_prelaunch_turnout_batch(slot) < 0 ||
            cancel_old_conflict_zone_batch(slot) < 0) {
                return -1;
        }
        for (int zone = 0;
             zone < TC2_CONFLICT_ZONE_COUNT; ++zone) {
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones,
                            zone, &grant) > 0 &&
                    grant.owner_train == job->train &&
                    grant.state == TC2_CONFLICT_ZONE_SETTING &&
                    Tc2ConflictZoneRetrySetting(
                            &dispatch_conflict_zones,
                            zone, job->train) < 0) {
                        return -1;
                }
        }
        return 0;

#if 0
        if (job->state == TC2_JOB_EMPTY ||
            discard_old_prelaunch_turnout_batch(slot) < 0 ||
            cancel_old_conflict_zone_batch(slot) < 0 ||
            Tc2ConflictZoneCancelHard(
                    &dispatch_conflict_zones, job->train) < 0 ||
            Tc2ConflictZoneCancelSoft(
                    &dispatch_conflict_zones, job->train) < 0) {
                return -1;
        }

        if (!runtime->conflict_zone_plan_valid ||
            runtime->monitor.confirmed_distance_mm < 0 ||
            runtime->traffic_hold_distance_um < 0) {
                return -1;
        }

        /*
         * A later real detector may rebase motion behind a conflict cursor
         * that projection already advanced.  The detector is the last physical
         * position proof, so bound the stopped centre from that detector plus
         * the fastest possible travel until the zero-speed command and the
         * complete measured braking coast.  Do not take the maximum with the
         * older motion projection: that projection is exactly what can have
         * advanced past an unobserved turnout while a traffic stop is pending
         * (data 201).
         *
         * Only a zone whose entry is beyond the complete front plus margin may
         * have its existing ticket released or a false OCCUPIED mark removed.
         * The advisory route cursor is reconstructed separately below.
         */
        int stop_distance_mm = Tc2MotionStopDistanceMm(
                runtime->traffic_resume_speed);
        int uncertainty_mm = Tc2MotionUncertaintyMm(
                runtime->traffic_resume_speed);
        int fast_velocity_tenths =
                Tc2MotionFastVelocityTenthsMmPerTick(
                        runtime->traffic_resume_speed);
        int detector_to_stop_ticks = -1;
        int zero_command_tick = runtime->motion_anchor_from_traffic ?
                runtime->motion_anchor_tick : -1;
        if (zero_command_tick >= 0 &&
            runtime->last_confirmed_tick >= 0) {
                detector_to_stop_ticks = motion_tick_age(
                        zero_command_tick,
                        runtime->last_confirmed_tick);
                if (detector_to_stop_ticks < 0 &&
                    motion_tick_age(runtime->last_confirmed_tick,
                                    zero_command_tick) >= 0) {
                        /* A detector observed during the braking coast. */
                        detector_to_stop_ticks = 0;
                }
        }
        if (stop_distance_mm < 0 || uncertainty_mm < 0 ||
            fast_velocity_tenths <= 0 || detector_to_stop_ticks < 0 ||
            runtime->traffic_hold_distance_um >
                    (int64_t)0x7fffffff * 1000) {
                return -1;
        }
        int64_t detector_travel_mm =
                ((int64_t)detector_to_stop_ticks *
                         fast_velocity_tenths + 9) / 10;
        int64_t confirmed_upper_wide =
                runtime->monitor.confirmed_distance_mm +
                detector_travel_mm + stop_distance_mm;
        if (confirmed_upper_wide > 0x7fffffff) return -1;
        int confirmed_upper_mm = (int)confirmed_upper_wide;
        if (confirmed_upper_mm >
                    0x7fffffff - uncertainty_mm -
                            TC2_TRAIN_HALF_LENGTH_MM - 20) {
                return -1;
        }
        int front_upper_mm = confirmed_upper_mm + uncertainty_mm +
                TC2_TRAIN_HALF_LENGTH_MM + 20;
        if (runtime->monitor.confirmed_offset < 0 ||
            runtime->monitor.confirmed_offset >=
                    runtime->route.node_count) {
                return -1;
        }

        /*
         * Ownership rollback and route-cursor recovery answer different
         * questions.  The conservative front bound above decides whether an
         * existing ticket may be released.  It must not decide that a turnout
         * was traversed: only an ordered real detector can advance that fact.
         *
         * Rebuild next/nextnext at the first zone whose route occurrence ends
         * after the last confirmed sensor.  Thus a detector immediately before
         * two successive turnouts recovers those turnouts as next and nextnext,
         * even if an older motion projection advanced the advisory cursor.
         * This rule is route geometry, independent of train or destination.
         */
        int rewind_step = runtime->conflict_zone_plan.step_count;
        for (int step_index = 0;
             step_index < runtime->conflict_zone_plan.step_count;
             ++step_index) {
                if (runtime->conflict_zone_plan.steps[step_index]
                            .last_route_offset >
                        runtime->monitor.confirmed_offset) {
                        rewind_step = step_index;
                        break;
                }
        }

        int hard_step = runtime->conflict_zone_hard_step;
        unsigned int hard_ticket = runtime->conflict_zone_hard_ticket;
        int preserve_hard_owner = 0;
        if (hard_ticket != 0) {
                if (!runtime->conflict_zone_plan_valid ||
                    hard_step < 0 ||
                    hard_step >= runtime->conflict_zone_plan.step_count) {
                        return -1;
                }
                const tc2_conflict_zone_route_step *step =
                        &runtime->conflict_zone_plan.steps[hard_step];
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones,
                            step->zone, &grant) <= 0 ||
                    grant.owner_train != job->train ||
                    grant.owner_ticket != hard_ticket ||
                    !conflict_zone_settings_equal(
                            &grant.setting, &step->setting)) {
                        return -1;
                }

                int frozen_proves_before_entry =
                        step->entry_distance_mm > front_upper_mm;
                int yield_unentered =
                        grant.state == TC2_CONFLICT_ZONE_GRANTED ||
                        grant.state == TC2_CONFLICT_ZONE_SETTING ||
                        (grant.state == TC2_CONFLICT_ZONE_SETTLED &&
                         frozen_proves_before_entry);
                if (yield_unentered) {
                        if (Tc2ConflictZoneYieldUnentered(
                                    &dispatch_conflict_zones,
                                    step->zone, job->train) < 0) {
                                return -1;
                        }
                } else if (frozen_proves_before_entry &&
                           (grant.state == TC2_CONFLICT_ZONE_OCCUPIED ||
                            grant.state ==
                                    TC2_CONFLICT_ZONE_RELEASE_DELAY)) {
                        if (Tc2ConflictZoneRollbackFalseEntry(
                                    &dispatch_conflict_zones,
                                    step->zone, job->train,
                                    hard_ticket) < 0) {
                                return -1;
                        }
                } else if (grant.state == TC2_CONFLICT_ZONE_SETTLED ||
                           grant.state == TC2_CONFLICT_ZONE_OCCUPIED ||
                           grant.state ==
                                   TC2_CONFLICT_ZONE_RELEASE_DELAY) {
                        preserve_hard_owner = 1;
                } else {
                        return -1;
                }
        }

        if (preserve_hard_owner && hard_step < rewind_step) {
                rewind_step = hard_step;
        }

        /*
         * Projection can also have moved older exact owners into the carry
         * ledger.  Roll back only carries whose immutable route entry is
         * still beyond the same conservative stopped-front bound.
         */
        int carry = 0;
        while (carry < runtime->conflict_zone_carry_count) {
                int carry_zone = runtime->conflict_zone_carry_zone[carry];
                unsigned int carry_ticket =
                        runtime->conflict_zone_carry_ticket[carry];
                int carry_entry_node =
                        runtime->conflict_zone_carry_entry_node[carry];
                int carry_exit_mm =
                        runtime->conflict_zone_carry_exit_distance_mm[carry];
                int carry_step = -1;
                for (int step_index = 0;
                     step_index < runtime->conflict_zone_plan.step_count;
                     ++step_index) {
                        const tc2_conflict_zone_route_step *step =
                                &runtime->conflict_zone_plan.steps[step_index];
                        if (step->zone != carry_zone ||
                            step->exit_distance_mm != carry_exit_mm ||
                            step->first_route_offset < 0 ||
                            step->first_route_offset >=
                                    runtime->route.node_count ||
                            runtime->route.nodes[step->first_route_offset] !=
                                    carry_entry_node) {
                                continue;
                        }
                        carry_step = step_index;
                        break;
                }
                if (carry_step < 0 ||
                    runtime->conflict_zone_plan.steps[carry_step]
                                    .entry_distance_mm <= front_upper_mm) {
                        ++carry;
                        continue;
                }

                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones, carry_zone,
                            &grant) <= 0 ||
                    grant.owner_train != job->train ||
                    grant.owner_ticket != carry_ticket) {
                        remove_conflict_zone_carry(runtime, carry);
                        continue;
                }
                int released = 0;
                if (grant.state == TC2_CONFLICT_ZONE_SETTING) {
                        if (Tc2ConflictZoneRetrySetting(
                                    &dispatch_conflict_zones,
                                    carry_zone, job->train) < 0) {
                                return -1;
                        }
                        grant.state = TC2_CONFLICT_ZONE_GRANTED;
                }
                if (grant.state == TC2_CONFLICT_ZONE_GRANTED ||
                    grant.state == TC2_CONFLICT_ZONE_SETTLED) {
                        released = Tc2ConflictZoneYieldUnentered(
                                &dispatch_conflict_zones,
                                carry_zone, job->train) == 0;
                } else if (grant.state == TC2_CONFLICT_ZONE_OCCUPIED ||
                           grant.state ==
                                   TC2_CONFLICT_ZONE_RELEASE_DELAY) {
                        released = Tc2ConflictZoneRollbackFalseEntry(
                                &dispatch_conflict_zones, carry_zone,
                                job->train, carry_ticket) == 0;
                }
                if (!released) return -1;
                remove_conflict_zone_carry(runtime, carry);
        }

        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_hold_active = 0;
        if (!preserve_hard_owner) {
                runtime->conflict_zone_hard_step = -1;
                runtime->conflict_zone_hard_ticket = 0;
                clear_origin_zone_egress(runtime);
        }
        if (rewind_step < runtime->conflict_zone_next_step) {
                runtime->conflict_zone_next_step = rewind_step;
        }
        return 0;
#endif
}

/*
 * A topology change can happen after a traffic-held train has already entered
 * the zero-speed PREPARING/READY recovery pipeline.  Its old launch admission
 * and turnout cursor were computed against the former moving route, so neither
 * remains valid when that route becomes a stationary block (cancel) or is
 * physically removed.  Rewind only traffic-resume jobs which have not yet sent
 * positive speed; ordinary running jobs are untouched.  An initial prelaunch
 * job changes only when it shares the same not-yet-confirmed atomic launch wave.
 */
static void restart_prearmed_stationary_survivors(
        int excluded_slot) {
        /*
         * A resume can already be in LAUNCHING while its positive-speed frame
         * is still waiting in the CAN batch.  Cancel that whole atomic wave
         * only when no member has been confirmed; every member then returns to
         * PREPARING at speed zero.  Once any positive command was confirmed,
         * the old admission has escaped into physical motion: stop the whole
         * wave through the ordinary BRAKING/AUTHORITY recovery chain while
         * preserving every healthy survivor's route and turnout cursors.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (slot == excluded_slot ||
                    job->state != TC2_JOB_LAUNCHING ||
                    runtime->launch_batch_token == 0 ||
                    !runtime->route_valid ||
                    !runtime->conflict_zone_plan_valid) {
                        continue;
                }

                unsigned int token = runtime->launch_batch_token;
                can_batch_status_t status;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.token != token || status.total < 1 ||
                    status.confirmed < 0 ||
                    status.confirmed > status.total) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (status.state == CAN_BATCH_FAILED) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (status.state != CAN_BATCH_PENDING &&
                    status.state != CAN_BATCH_COMPLETE) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }

                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }

                /*
                 * COMPLETE necessarily means that at least one positive frame
                 * escaped because a valid batch has total >= 1.  A PENDING
                 * batch reports the exact confirmed prefix.  In either case,
                 * never rewind possibly-moving trains to PREPARING.
                 */
                if (status.state == CAN_BATCH_COMPLETE ||
                    status.confirmed > 0) {
                        int now = Time();
                        if (now < 0) {
                                fail_launch_wave(
                                        token,
                                        TC2_FAILURE_CAN_HEALTH);
                                continue;
                        }
                        (void)stop_partially_confirmed_launch_wave(
                                slot, token, now);
                        continue;
                }

                for (int member = 0;
                     member < TC2_DISPATCH_MAX_JOBS; ++member) {
                        tc2_dispatch_job_snapshot *member_job =
                                &dispatch_jobs[member];
                        tc2_dispatch_runtime *member_runtime =
                                &dispatch_runtime[member];
                        if (member_runtime->launch_batch_token != token) {
                                continue;
                        }
                        member_runtime->launch_batch_token = 0;
                        member_runtime->launch_batch_index = -1;
                        member_runtime->launch_wave_tick = -1;
                        member_runtime->command_speed = 0;
                        member_runtime->motion_speed_ceiling = 0;
                        member_job->command_speed = 0;
                        member_job->launch_tick = -1;
                        member_job->ready_at_tick = -1;
                        member_runtime->ready_wave_tick = -1;
                        member_job->state = TC2_JOB_PREPARING;
                        member_runtime->prelaunch_traffic_blocked = 1;
                }
        }

        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (slot == excluded_slot ||
                    runtime->command_speed != 0 ||
                    job->command_speed != 0 ||
                    !runtime->route_valid ||
                    !runtime->conflict_zone_plan_valid ||
                    (runtime->authority_resume_pending &&
                     runtime->traffic_hold_distance_um < 0) ||
                    (job->state != TC2_JOB_PREPARING &&
                     job->state != TC2_JOB_READY)) {
                        continue;
                }
                if (restart_conflict_zone_work_from_frozen_position(
                            slot) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                        continue;
                }
                job->state = TC2_JOB_PREPARING;
                job->ready_at_tick = -1;
                runtime->ready_wave_tick = -1;
                runtime->prelaunch_traffic_blocked = 1;
        }
}

/* Apply only lifecycle transitions proved by the pre-replacement snapshot. */
static int finalize_old_conflict_zone_carries(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int index = 0;
        while (index < runtime->conflict_zone_carry_count) {
                if (!conflict_zone_carry_is_cohort_first(runtime, index)) {
                        ++index;
                        continue;
                }
                unsigned int ticket =
                        runtime->conflict_zone_carry_ticket[index];
                unsigned int carry_route_generation =
                        runtime
                          ->conflict_zone_carry_route_generation[index];
                int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int carry_indices[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                tc2_conflict_zone_grant
                        grants[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int count = collect_conflict_zone_carry_cohort(
                        runtime, ticket, carry_route_generation,
                        zones, carry_indices);
                if (count < 1) return -1;

                int live_members = 0;
                int all_release_delay = 1;
                int all_unentered = 1;
                int all_tail_clear = 1;
                unsigned int route_generation = carry_route_generation;
                for (int member = 0; member < count; ++member) {
                        int query = Tc2ConflictZoneQueryGrant(
                                &dispatch_conflict_zones, zones[member],
                                &grants[member]);
                        if (query < 0) return -1;
                        int live = query > 0 &&
                                grants[member].owner_train == job->train &&
                                grants[member].owner_ticket == ticket;
                        if (!live) {
                                all_release_delay = 0;
                                all_unentered = 0;
                                all_tail_clear = 0;
                                continue;
                        }
                        ++live_members;
                        if (route_generation !=
                                    grants[member]
                                            .owner_route_generation) {
                                return -1;
                        }
                        route_generation =
                                grants[member].owner_route_generation;
                        all_release_delay = all_release_delay &&
                                grants[member].state ==
                                        TC2_CONFLICT_ZONE_RELEASE_DELAY;
                        all_unentered = all_unentered &&
                                runtime->conflict_zone_carry_mode[
                                        carry_indices[member]] ==
                                        TC2_CONFLICT_CARRY_UNENTERED &&
                                (grants[member].state ==
                                         TC2_CONFLICT_ZONE_GRANTED ||
                                 grants[member].state ==
                                         TC2_CONFLICT_ZONE_SETTING ||
                                 grants[member].state ==
                                         TC2_CONFLICT_ZONE_SETTLED);
                        all_tail_clear = all_tail_clear &&
                                runtime->conflict_zone_carry_mode[
                                        carry_indices[member]] ==
                                        TC2_CONFLICT_CARRY_TAIL_CLEAR &&
                                grants[member].state ==
                                        TC2_CONFLICT_ZONE_OCCUPIED;
                }
                /* The old ticket is wholly gone; discard only its evidence. */
                if (live_members == 0) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                /* A partial live cohort is an invariant failure, never proof. */
                if (live_members != count || route_generation == 0) return -1;
                if (all_release_delay) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                int completed = 0;
                if (all_unentered) {
                        completed = Tc2ConflictZoneYieldUnenteredStage(
                                &dispatch_conflict_zones, zones, count,
                                job->train, route_generation, ticket) == 0;
                } else if (all_tail_clear) {
                        completed = Tc2ConflictZoneMarkTailClearStage(
                                &dispatch_conflict_zones, zones, count,
                                job->train, route_generation, ticket,
                                (uint32_t)now) == 0;
                }
                if ((all_unentered || all_tail_clear) && !completed) return -1;
                if (completed) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                ++index;
        }
        return 0;
}

static int conflict_zone_physical_distances_from(
        int start_node, int distance[TRACK_MAX]) {
        unsigned char visited[TRACK_MAX];
        if (!distance || start_node < 0 || start_node >= TRACK_MAX ||
            dispatch_track[start_node].type == NODE_NONE) {
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                distance[node] = 0x3fffffff;
                visited[node] = 0;
        }
        distance[start_node] = 0;
        for (int pass = 0; pass < TRACK_MAX; ++pass) {
                int current = -1;
                for (int node = 0; node < TRACK_MAX; ++node) {
                        if (!visited[node] &&
                            distance[node] != 0x3fffffff &&
                            (current < 0 ||
                             distance[node] < distance[current])) {
                                current = node;
                        }
                }
                if (current < 0) break;
                visited[current] = 1;
                if (dispatch_track[current].reverse) {
                        int reverse = (int)(dispatch_track[current].reverse -
                                            dispatch_track);
                        if (reverse < 0 || reverse >= TRACK_MAX) return -1;
                        if (distance[current] < distance[reverse]) {
                                distance[reverse] = distance[current];
                        }
                }
                int edges = dispatch_track[current].type == NODE_BRANCH ? 2 :
                        (dispatch_track[current].type == NODE_EXIT ||
                         dispatch_track[current].type == NODE_NONE ? 0 : 1);
                for (int direction = 0; direction < edges; ++direction) {
                        track_edge *edge =
                                &dispatch_track[current].edge[direction];
                        if (!edge->dest || edge->dist < 0) continue;
                        int next = (int)(edge->dest - dispatch_track);
                        if (next < 0 || next >= TRACK_MAX ||
                            distance[current] >
                                    0x3fffffff - edge->dist) {
                                return -1;
                        }
                        int candidate = distance[current] + edge->dist;
                        if (candidate < distance[next]) {
                                distance[next] = candidate;
                        }
                }
        }
        return 0;
}

static int process_conflict_zone_carries(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int distance[TRACK_MAX];
        int have_physical_proof =
                !job->position_estimated &&
                job->current_node >= 0 &&
                job->current_node < TRACK_MAX &&
                conflict_zone_physical_distances_from(
                        job->current_node, distance) == 0;
        int64_t progress_lower_um = 0;
        int have_motion_lower_bound =
                runtime_conflict_zone_progress_lower_bound_um(
                        slot, now, &progress_lower_um) == 0;
        int index = 0;
        while (index < runtime->conflict_zone_carry_count) {
                if (!conflict_zone_carry_is_cohort_first(runtime, index)) {
                        ++index;
                        continue;
                }
                unsigned int ticket =
                        runtime->conflict_zone_carry_ticket[index];
                unsigned int carry_route_generation =
                        runtime
                          ->conflict_zone_carry_route_generation[index];
                int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int carry_indices[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                tc2_conflict_zone_grant
                        grants[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int count = collect_conflict_zone_carry_cohort(
                        runtime, ticket, carry_route_generation,
                        zones, carry_indices);
                if (count < 1) return -1;

                int live_members = 0;
                int all_release_delay = 1;
                int all_yieldable = 1;
                int all_tail_clear = 1;
                unsigned int route_generation = carry_route_generation;
                for (int member = 0; member < count; ++member) {
                        int carry = carry_indices[member];
                        int query = Tc2ConflictZoneQueryGrant(
                                &dispatch_conflict_zones, zones[member],
                                &grants[member]);
                        if (query < 0) return -1;
                        int live = query > 0 &&
                                grants[member].owner_train == job->train &&
                                grants[member].owner_ticket == ticket;
                        if (!live) {
                                all_release_delay = 0;
                                all_yieldable = 0;
                                all_tail_clear = 0;
                                continue;
                        }
                        ++live_members;
                        if (route_generation !=
                                    grants[member]
                                            .owner_route_generation) {
                                return -1;
                        }
                        route_generation =
                                grants[member].owner_route_generation;
                        int entry =
                                runtime->conflict_zone_carry_entry_node[
                                        carry];
                        int exit =
                                runtime->conflict_zone_carry_exit_node[
                                        carry];
                        int exit_distance_mm =
                                runtime
                                  ->conflict_zone_carry_exit_distance_mm[
                                          carry];
                        int scalar_clear = exit_distance_mm >= 0 &&
                                runtime
                                  ->conflict_zone_carry_scalar_proof_valid[
                                          carry] &&
                                runtime->monitor.confirmed_distance_mm >= 0 &&
                                runtime->monitor.confirmed_distance_mm -
                                                TC2_TRAIN_HALF_LENGTH_MM >
                                        exit_distance_mm + 20;
                        int graph_clear = have_physical_proof &&
                                entry >= 0 && entry < TRACK_MAX &&
                                exit >= 0 && exit < TRACK_MAX &&
                                distance[entry] != 0x3fffffff &&
                                distance[exit] != 0x3fffffff &&
                                distance[entry] >
                                        TC2_TRAIN_HALF_LENGTH_MM + 20 &&
                                distance[exit] >
                                        TC2_TRAIN_HALF_LENGTH_MM + 20;
                        /*
                         * Missing the first detector after a turnout must
                         * not leave this train's old ticket blocking a later
                         * occurrence of that same physical resource forever.
                         * This lower bound is uncertainty-discounted and is
                         * never earlier than the latest confirmed detector;
                         * it is proof only after the complete tail and margin
                         * are beyond the old exit.
                         */
                        int motion_clear =
                                have_motion_lower_bound &&
                                exit_distance_mm >= 0 &&
                                runtime
                                  ->conflict_zone_carry_scalar_proof_valid[
                                          carry] &&
                                progress_lower_um -
                                                (int64_t)
                                                TC2_TRAIN_HALF_LENGTH_MM *
                                                        1000 >
                                        ((int64_t)exit_distance_mm + 20) *
                                                1000;
                        int clear = scalar_clear || graph_clear ||
                                motion_clear;
                        int carry_mode =
                                runtime->conflict_zone_carry_mode[carry];
                        all_release_delay = all_release_delay &&
                                grants[member].state ==
                                        TC2_CONFLICT_ZONE_RELEASE_DELAY;
                        all_yieldable = all_yieldable &&
                                (carry_mode ==
                                         TC2_CONFLICT_CARRY_UNENTERED ||
                                 (clear && carry_mode ==
                                         TC2_CONFLICT_CARRY_UNKNOWN)) &&
                                (grants[member].state ==
                                         TC2_CONFLICT_ZONE_GRANTED ||
                                 grants[member].state ==
                                         TC2_CONFLICT_ZONE_SETTING ||
                                 grants[member].state ==
                                         TC2_CONFLICT_ZONE_SETTLED);
                        all_tail_clear = all_tail_clear &&
                                (carry_mode ==
                                         TC2_CONFLICT_CARRY_TAIL_CLEAR ||
                                 (clear &&
                                  (carry_mode ==
                                           TC2_CONFLICT_CARRY_OCCUPIED ||
                                   carry_mode ==
                                           TC2_CONFLICT_CARRY_UNKNOWN))) &&
                                grants[member].state ==
                                        TC2_CONFLICT_ZONE_OCCUPIED;
                }

                /*
                 * UNKNOWN is intentionally fail-closed at replacement time:
                 * neither a raw point estimate nor elapsed nominal travel
                 * may release an old physical owner.  It must not, however,
                 * become an irrevocable deadlock.  A later real detector or
                 * the uncertainty-discounted motion lower bound farther than
                 * the complete half-body plus the 20 mm margin proves the
                 * train is outside the zone.  At that point the old traversal
                 * can be retired according to its real state.
                 */
                /*
                 * UNENTERED is already a physical proof recorded when the
                 * old owner was snapshotted: GRANTED has never admitted the
                 * train, while SETTING/SETTLED is classified UNENTERED only
                 * when the latest real detector plus the complete half-body
                 * remains before the entry boundary.  Requiring tail-clear
                 * as well is impossible for a canceled train stopped before
                 * that boundary and leaves its obsolete turnout ticket
                 * owning the zone forever.
                 *
                 * UNKNOWN and OCCUPIED remain fail-closed and still require
                 * a confirmed scalar, exact graph, or conservative motion
                 * lower-bound clearance proof.  Releasing this ticket does
                 * not release a canceled train's stationary reservation, so
                 * its physical body remains a block.
                 */
                if (live_members == 0) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                if (live_members != count || route_generation == 0) return -1;
                if (all_release_delay) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                int completed = 0;
                if (all_yieldable) {
                        completed = Tc2ConflictZoneYieldUnenteredStage(
                                &dispatch_conflict_zones, zones, count,
                                job->train, route_generation, ticket) == 0;
                } else if (all_tail_clear) {
                        completed = Tc2ConflictZoneMarkTailClearStage(
                                &dispatch_conflict_zones, zones, count,
                                job->train, route_generation, ticket,
                                (uint32_t)now) == 0;
                }
                if ((all_yieldable || all_tail_clear) && !completed) return -1;
                if (completed) {
                        remove_conflict_zone_carry_cohort(
                                runtime, ticket, carry_route_generation);
                        continue;
                }
                ++index;
        }
        return 0;
}

/*
 * A hard next and a soft next-next are deliberately separate route stages,
 * but they must not be allowed to form a hold-and-wait cycle before either
 * train has entered its hard stage.  The common case is:
 *
 *     A owns next X and waits for next-next Y
 *     B owns next Y and waits for next-next X
 *
 * If B has never received a positive-speed command, its complete hard cohort
 * is still physically unentered.  Yield that cohort atomically, discard B's
 * old future queue tickets, and let it requeue behind A after the normal
 * resource-owned two-second handoff delay.  Route, localization, body
 * reservation, and held/occupied resources are untouched.
 *
 * This is intentionally not a general deadlock breaker: once a train has
 * launched, or any member is OCCUPIED/RELEASE_DELAY, physical evidence wins
 * and the owner remains fail-closed.
 */
static int conflict_zone_stages_share_resource(
        const tc2_conflict_zone_route_plan *left_plan, int left_step,
        const tc2_conflict_zone_route_plan *right_plan, int right_step) {
        if (!left_plan || !right_plan) return 0;
        const tc2_conflict_zone_route_stage *left =
                conflict_zone_stage_for_step(left_plan, left_step);
        const tc2_conflict_zone_route_stage *right =
                conflict_zone_stage_for_step(right_plan, right_step);
        if (!left || !right || left->member_step[0] != left_step ||
            right->member_step[0] != right_step) {
                return 0;
        }
        for (int l = 0; l < left->member_count; ++l) {
                int left_raw = left->member_step[l];
                int left_zone = left_plan->steps[left_raw].zone;
                for (int r = 0; r < right->member_count; ++r) {
                        int right_raw = right->member_step[r];
                        if (left_zone == right_plan->steps[right_raw].zone) {
                                return 1;
                        }
                }
        }
        return 0;
}

static int conflict_zone_stage_owned_by_slot(
        int slot, int step, int require_yieldable) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        if (!runtime->conflict_zone_plan_valid ||
            step < 0 || step >= runtime->conflict_zone_plan.step_count ||
            runtime->conflict_zone_hard_step != step ||
            runtime->conflict_zone_hard_ticket == 0) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step);
        if (!stage || stage->member_step[0] != step) return 0;
        for (int member = 0; member < stage->member_count; ++member) {
                int raw_step = stage->member_step[member];
                tc2_conflict_zone_grant grant;
                if (Tc2ConflictZoneQueryGrant(
                            &dispatch_conflict_zones,
                            runtime->conflict_zone_plan.steps[raw_step].zone,
                            &grant) <= 0 ||
                    grant.owner_train != job->train ||
                    grant.owner_ticket !=
                            runtime->conflict_zone_hard_ticket ||
                    grant.owner_route_generation !=
                            runtime->conflict_zone_route_generation) {
                        return 0;
                }
                if (require_yieldable &&
                    grant.state != TC2_CONFLICT_ZONE_GRANTED &&
                    grant.state != TC2_CONFLICT_ZONE_SETTING &&
                    grant.state != TC2_CONFLICT_ZONE_SETTLED) {
                        return 0;
                }
        }
        return 1;
}

static int yield_prelaunch_conflict_cycle_slot(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        int hard_step = runtime->conflict_zone_hard_step;
        const tc2_conflict_zone_route_stage *hard_stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, hard_step);
        if (!hard_stage || hard_stage->member_step[0] != hard_step ||
            !conflict_zone_stage_owned_by_slot(slot, hard_step, 1)) {
                return -1;
        }

        if (runtime->conflict_zone_batch_token != 0) {
                can_batch_status_t status;
                unsigned int token = runtime->conflict_zone_batch_token;
                if (CanGetBatchStatus(dispatch_can_tid, token, &status) < 0 ||
                    status.token != token) {
                        return -1;
                }
                if (status.state == CAN_BATCH_PENDING &&
                    CanCancelBatch(dispatch_can_tid, token) < 0) {
                        return -1;
                }
        }
        if (cancel_soft_conflict_zone_prefetch(slot, 1) < 0) return -1;

        int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
        for (int member = 0; member < hard_stage->member_count; ++member) {
                int raw_step = hard_stage->member_step[member];
                zones[member] =
                        runtime->conflict_zone_plan.steps[raw_step].zone;
        }
        if (Tc2ConflictZoneYieldUnenteredStage(
                    &dispatch_conflict_zones, zones,
                    hard_stage->member_count, job->train,
                    runtime->conflict_zone_route_generation,
                    runtime->conflict_zone_hard_ticket) < 0 ||
            Tc2ConflictZoneCancelHard(
                    &dispatch_conflict_zones, job->train) < 0 ||
            Tc2ConflictZoneCancelSoft(
                    &dispatch_conflict_zones, job->train) < 0) {
                return -1;
        }

        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_soft_ticket = 0;
        runtime->conflict_zone_batch_token = 0;
        runtime->conflict_zone_queue_pending = 0;
        runtime->conflict_zone_settle_at_tick = -1;
        reset_conflict_zone_action_cursor(runtime);
        reset_soft_conflict_zone_cursor(runtime, 1);
        if (job->state == TC2_JOB_READY) {
                job->state = TC2_JOB_PREPARING;
        }
        return 0;
}

static int conflict_zone_find_slot_by_train(int train) {
        if (train <= 0) return -1;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state != TC2_JOB_EMPTY &&
                    dispatch_jobs[slot].train == train) {
                        return slot;
                }
        }
        return -1;
}

static int resolve_prelaunch_conflict_zone_cycle(void) {
        /* Prefer yielding the larger train id, without depending on slot order. */
        for (int loser_train = 255; loser_train > 0; --loser_train) {
                int loser = conflict_zone_find_slot_by_train(loser_train);
                if (loser < 0) continue;
                tc2_dispatch_job_snapshot *loser_job =
                        &dispatch_jobs[loser];
                tc2_dispatch_runtime *loser_runtime =
                        &dispatch_runtime[loser];
                if ((loser_job->state != TC2_JOB_PREPARING &&
                     loser_job->state != TC2_JOB_READY) ||
                    loser_job->launch_tick >= 0 ||
                    loser_job->command_speed != 0 ||
                    loser_runtime->command_speed != 0 ||
                    !loser_runtime->conflict_zone_plan_valid) {
                        continue;
                }
                int loser_hard = loser_runtime->conflict_zone_hard_step;
                int loser_soft = next_conflict_zone_preparation_step(
                        loser, loser_runtime->conflict_zone_next_step);
                if (loser_soft < 0 ||
                    !conflict_zone_stage_owned_by_slot(
                            loser, loser_hard, 1)) {
                        continue;
                }

                for (int peer = 0; peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                        if (peer == loser ||
                            dispatch_jobs[peer].state == TC2_JOB_EMPTY ||
                            !dispatch_runtime[peer]
                                     .conflict_zone_plan_valid) {
                                continue;
                        }
                        tc2_dispatch_runtime *peer_runtime =
                                &dispatch_runtime[peer];
                        int peer_hard =
                                peer_runtime->conflict_zone_hard_step;
                        int peer_soft = next_conflict_zone_preparation_step(
                                peer,
                                peer_runtime->conflict_zone_next_step);
                        if (peer_soft < 0 ||
                            !conflict_zone_stage_owned_by_slot(
                                    peer, peer_hard, 0)) {
                                continue;
                        }
                        int reciprocal =
                                conflict_zone_stages_share_resource(
                                        &loser_runtime
                                                 ->conflict_zone_plan,
                                        loser_hard,
                                        &peer_runtime
                                                 ->conflict_zone_plan,
                                        peer_soft) &&
                                conflict_zone_stages_share_resource(
                                        &loser_runtime
                                                 ->conflict_zone_plan,
                                        loser_soft,
                                        &peer_runtime
                                                 ->conflict_zone_plan,
                                        peer_hard);
                        if (!reciprocal) continue;
                        return yield_prelaunch_conflict_cycle_slot(loser);
                }
        }
        return 0;
}

static void process_conflict_zones(int now) {
        Tc2ConflictZoneTick(&dispatch_conflict_zones, (uint32_t)now);

        /* A stopping/stopped waiter protects its body, never future iron. */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (conflict_zone_job_command_suspended(slot) &&
                    suspend_conflict_zone_command_rights(slot) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                }
        }

        /* Phase 1: take an immutable request snapshot from every train. */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (!dispatch_runtime[slot].conflict_zone_plan_valid ||
                    !conflict_zone_job_can_request(slot)) {
                        continue;
                }
                if (refresh_conflict_zone_requests(slot) < 0) {
                        fail_job(slot, TC2_FAILURE_RESERVATION);
                }
        }

        /*
         * A traffic-held train cannot reacquire hard route authority merely
         * by waiting.  It may, however, publish its nearest next-next motor
         * request so an independent turnout (for example SW5 after SW18) is
         * already settled when the real physical blocker clears.
         */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (!runtime->conflict_zone_plan_valid ||
                    dispatch_jobs[slot].state != TC2_JOB_TRAFFIC_HOLD ||
                    conflict_zone_job_can_request(slot)) {
                        continue;
                }
                if (refresh_soft_conflict_zone_request(
                            slot, runtime->conflict_zone_next_step) < 0) {
                        fail_job(slot, TC2_FAILURE_RESERVATION);
                }
        }

        /*
         * All hard and soft intents are now visible.  Break only a proved
         * reciprocal prelaunch hold-and-wait cycle; ordinary FIFO waits and
         * every physically entered owner remain unchanged.
         */
        if (resolve_prelaunch_conflict_zone_cycle() < 0) {
                dispatch_scheduler_healthy = 0;
        }

        /*
         * A newly queued hard contender immediately revokes any advisory
         * command for the same concrete actuator. Completed confirmations
         * survive only when they are the exact step being promoted to a hard
         * ticket.
         */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state == TC2_JOB_EMPTY) continue;
                if (validate_soft_conflict_zone_prefetch(slot) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                        continue;
                }
                if (poll_soft_conflict_zone_prefetch(slot, now) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                }
        }

        /*
         * Every train's hard/next and soft/next-next intent is now visible.
         * Send compatible next-next motor preparation before granting or
         * programming hard owners. Tc2ConflictZoneCanPrefetch rejects an
         * opposed action from either request class, so this changes command
         * latency only and never grants movement authority.
         */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (soft_conflict_zone_job_can_command(slot) &&
                    queue_soft_conflict_zone_prefetch(slot, now) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                }
        }

        /* Phase 2: grant every member of one route stage, or grant none. */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                int hard_step = runtime->conflict_zone_hard_step;
                if (!runtime->conflict_zone_plan_valid ||
                    !conflict_zone_job_can_request(slot) ||
                    hard_step < 0 ||
                    hard_step >= runtime->conflict_zone_plan.step_count ||
                    runtime->conflict_zone_hard_ticket == 0) {
                        continue;
                }
                const tc2_conflict_zone_route_stage *stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan,
                                hard_step);
                int zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                tc2_conflict_zone_request
                        requests[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                int count = fill_conflict_zone_stage_requests(
                        slot, hard_step, zones, requests);
                if (!stage || stage->member_step[0] != hard_step ||
                    count != stage->member_count ||
                    Tc2ConflictZoneTryGrantStage(
                            &dispatch_conflict_zones, zones, count,
                            dispatch_jobs[slot].train,
                            runtime->conflict_zone_route_generation,
                            runtime->conflict_zone_hard_ticket) < 0) {
                        dispatch_scheduler_healthy = 0;
                }
        }

        /* Phase 3: only the ticketed hard owner may move a switch or enter. */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (job->state == TC2_JOB_EMPTY) {
                        continue;
                }
                int terminal_static_body =
                        job->state == TC2_JOB_ARRIVED ||
                        job->state == TC2_JOB_STOPPED ||
                        (job->state == TC2_JOB_CANCEL_BRAKING &&
                         terminal_static_footprint_committed(slot));
                if (terminal_static_body) {
                        /*
                         * The body reservation is already fail-closed.  A
                         * transient CAN-status error may be retried next tick;
                         * it must not make the global scheduler permanently
                         * unhealthy or release any unproved control state.
                         */
                        /*
                         * A staged CURRENT/reroute belongs to this same
                         * physical train. The old future route was already
                         * retired when the body became terminal; repeating
                         * that retirement here would erase the new request
                         * before `go` can arm it. Keep the static body while
                         * the pending route is replanned from CURRENT.
                         */
                        if (!runtime->retarget_pending) {
                                (void)retire_terminal_conflict_zone_memory(
                                        slot, now);
                        }
                        continue;
                }
                int discard_failed = 0;
                if (runtime->conflict_zone_plan_valid &&
                    (job->state == TC2_JOB_FAILED ||
                     job->state == TC2_JOB_STOP_UNCONFIRMED)) {
                        if (discard_future_conflict_zone_work(slot) < 0) {
                                dispatch_scheduler_healthy = 0;
                                discard_failed = 1;
                        }
                }
                if (process_conflict_zone_carries(slot, now) < 0) {
                        dispatch_scheduler_healthy = 0;
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                        continue;
                }
                if (discard_failed) {
                        continue;
                }
                if (!runtime->conflict_zone_plan_valid) {
                        continue;
                }
                int active = conflict_zone_job_can_request(slot);
                if (active && runtime->conflict_zone_queue_pending &&
                    queue_owned_conflict_zone_setting(slot) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                        continue;
                }
                if (active && runtime->conflict_zone_batch_token != 0) {
                        int action_step =
                                runtime->conflict_zone_action_step;
                        const tc2_conflict_zone_route_stage *action_stage =
                                conflict_zone_stage_for_step(
                                        &runtime->conflict_zone_plan,
                                        action_step);
                        tc2_conflict_zone_grant action_grant;
                        int action_ticket_valid =
                                action_step >= 0 &&
                                action_step < runtime
                                        ->conflict_zone_plan.step_count &&
                                action_stage &&
                                action_stage->member_step[0] ==
                                        runtime->conflict_zone_next_step &&
                                runtime->conflict_zone_action_ticket != 0 &&
                                runtime->conflict_zone_action_ticket ==
                                        runtime->conflict_zone_hard_ticket &&
                                Tc2ConflictZoneQueryGrant(
                                        &dispatch_conflict_zones,
                                        runtime->conflict_zone_plan
                                                .steps[action_step].zone,
                                        &action_grant) > 0 &&
                                action_grant.owner_train == job->train &&
                                action_grant.owner_ticket ==
                                        runtime
                                          ->conflict_zone_action_ticket &&
                                action_grant.state ==
                                        TC2_CONFLICT_ZONE_SETTING;
                        if (!action_ticket_valid) {
                                (void)CanCancelBatch(
                                        dispatch_can_tid,
                                        runtime->conflict_zone_batch_token);
                                runtime->conflict_zone_batch_token = 0;
                                runtime->conflict_zone_settle_at_tick = -1;
                                reset_conflict_zone_action_cursor(runtime);
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        can_batch_status_t status;
                        if (CanGetBatchStatus(
                                    dispatch_can_tid,
                                    runtime->conflict_zone_batch_token,
                                    &status) < 0 ||
                            status.token !=
                                    runtime->conflict_zone_batch_token) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        if (status.state == CAN_BATCH_FAILED) {
                                int step_index =
                                        runtime->conflict_zone_action_step;
                                if (step_index >= 0 &&
                                    step_index < runtime
                                            ->conflict_zone_plan
                                            .step_count) {
                                        int zone = runtime
                                                ->conflict_zone_plan
                                                .steps[step_index].zone;
                                        (void)Tc2ConflictZoneRetrySetting(
                                                &dispatch_conflict_zones,
                                                zone, job->train);
                                }
                                runtime->conflict_zone_batch_token = 0;
                                runtime->conflict_zone_settle_at_tick = -1;
                                runtime->conflict_zone_queue_pending = 1;
                                continue;
                        }
                        if (status.state != CAN_BATCH_COMPLETE ||
                            status.confirmed != status.total) {
                                continue;
                        }
                        const tc2_conflict_zone_route_step *confirmed_step =
                                &runtime->conflict_zone_plan
                                         .steps[action_step];
                        int confirmed_action =
                                runtime->conflict_zone_action_index;
                        if (confirmed_action < 0 ||
                            confirmed_action >=
                                    confirmed_step->setting.action_count ||
                            record_turnout_direction(
                                    confirmed_step->setting
                                            .actions[confirmed_action]
                                            .switch_number,
                                    conflict_turnout_action_direction(
                                            &confirmed_step->setting
                                                     .actions[
                                                             confirmed_action])) <
                                    0) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        runtime->conflict_zone_batch_token = 0;
                        runtime->conflict_zone_settle_at_tick =
                                tick_after(now,
                                           TC2_TURNOUT_SETTLE_TICKS);
                }
                if (active &&
                    runtime->conflict_zone_settle_at_tick >= 0 &&
                    tick_reached(now,
                        runtime->conflict_zone_settle_at_tick)) {
                        int step_index =
                                runtime->conflict_zone_action_step;
                        if (step_index >= 0 && step_index <
                            runtime->conflict_zone_plan.step_count) {
                                const tc2_conflict_zone_route_step *setting_step =
                                        &runtime->conflict_zone_plan
                                                 .steps[step_index];
                                const tc2_conflict_zone_route_stage
                                        *setting_stage =
                                                conflict_zone_stage_for_step(
                                                        &runtime
                                                                 ->conflict_zone_plan,
                                                        step_index);
                                if (!setting_stage ||
                                    setting_stage->member_step[0] !=
                                            runtime
                                              ->conflict_zone_next_step ||
                                    runtime->conflict_zone_action_ticket !=
                                            runtime
                                              ->conflict_zone_hard_ticket ||
                                    runtime->conflict_zone_action_index < 0 ||
                                    runtime->conflict_zone_action_index >=
                                            setting_step->setting
                                                    .action_count) {
                                        fail_job(slot,
                                                 TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                ++runtime->conflict_zone_action_index;
                                if (runtime->conflict_zone_action_index <
                                        setting_step->setting.action_count) {
                                        /*
                                         * Keep the shared zone in SETTING.
                                         * The next scheduler pass sends only
                                         * the next real turnout on the route;
                                         * no paired motor is synthesized.
                                         */
                                        runtime->conflict_zone_queue_pending =
                                                1;
                                        runtime->conflict_zone_settle_at_tick =
                                                -1;
                                        continue;
                                }
                                if (Tc2ConflictZoneMarkSettled(
                                            &dispatch_conflict_zones,
                                            setting_step->zone,
                                            job->train) < 0) {
                                        fail_job(slot,
                                                 TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                reset_conflict_zone_action_cursor(runtime);
                                runtime->conflict_zone_queue_pending = 1;
                        }
                        runtime->conflict_zone_settle_at_tick = -1;
                }
                if (active &&
                    runtime->conflict_zone_batch_token == 0 &&
                    runtime->conflict_zone_settle_at_tick < 0 &&
                    queue_owned_conflict_zone_setting(slot) < 0) {
                        fail_job(slot, TC2_FAILURE_TURNOUT);
                        continue;
                }
                int step_index = runtime->conflict_zone_next_step;
                int physical_zone_progress_due = 0;
                if (active && step_index >= 0 &&
                    step_index <
                            runtime->conflict_zone_plan.step_count &&
                    runtime->conflict_zone_hard_ticket != 0) {
                        const tc2_conflict_zone_route_stage *progress_stage =
                                conflict_zone_stage_for_step(
                                        &runtime->conflict_zone_plan,
                                        step_index);
                        int64_t progress_um = 0;
                        int all_settled = progress_stage != 0;
                        int all_occupied = progress_stage != 0;
                        if (progress_stage) {
                                for (int member = 0;
                                     member < progress_stage->member_count;
                                     ++member) {
                                        int raw_step = progress_stage
                                                               ->member_step[
                                                                       member];
                                        int zone = runtime
                                                           ->conflict_zone_plan
                                                           .steps[raw_step]
                                                           .zone;
                                        tc2_conflict_zone_grant grant;
                                        int owns =
                                                Tc2ConflictZoneQueryGrant(
                                                        &dispatch_conflict_zones,
                                                        zone, &grant) > 0 &&
                                                grant.owner_train ==
                                                        job->train &&
                                                grant.owner_ticket ==
                                                        runtime
                                                          ->conflict_zone_hard_ticket;
                                        all_settled = all_settled && owns &&
                                                grant.state ==
                                                        TC2_CONFLICT_ZONE_SETTLED;
                                        all_occupied = all_occupied && owns &&
                                                grant.state ==
                                                        TC2_CONFLICT_ZONE_OCCUPIED;
                                }
                        }
                        if (progress_stage &&
                            runtime_conflict_zone_progress_lower_bound_um(
                                    slot, now, &progress_um) == 0) {
                                physical_zone_progress_due =
                                        (all_settled &&
                                         progress_um +
                                                 (int64_t)
                                                         TC2_TRAIN_HALF_LENGTH_MM *
                                                         1000 >=
                                                 (int64_t)progress_stage
                                                         ->entry_distance_mm *
                                                         1000) ||
                                        (all_occupied &&
                                         progress_um >=
                                                 (int64_t)progress_stage
                                                         ->exit_distance_mm *
                                                         1000);
                        }
                }
                /*
                 * A turnout/authority stop is deliberately zero-speed.  It
                 * must leave HOLD through PREPARING, where the normal atomic
                 * arbiter reacquires and verifies hard-next plus nextnext.
                 * Requiring hard-next to be ready while still in HOLD creates
                 * a circular wait: the hold path may have yielded that exact
                 * command right, yet only PREPARING may obtain it again.
                 */
                if (active && !physical_zone_progress_due &&
                    runtime->conflict_zone_hold_active &&
                    job->state == TC2_JOB_TRAFFIC_HOLD) {
                        /*
                         * Settling the exact current turnout only proves
                         * switch authority.  It must not be mistaken for a
                         * long enough rolling reservation.  If the frozen
                         * train cannot brake inside its present window,
                         * consume the zone latch and hand the same stopped
                         * position to the ordinary FIFO authority extender.
                         * No positive-speed command is sent until that
                         * extension is committed and its launch path is
                         * confirmed.
                         */
                        if (!traffic_resume_fits_current_authority(
                                    slot,
                                    runtime->traffic_resume_speed)) {
                                int safe_resume_speed = -1;
                                int trusted_progress_mm = -1;
                                int64_t occupancy_upper_um = 0;
                                if (traffic_hold_progress_bounds(
                                            slot,
                                            &trusted_progress_mm,
                                            &occupancy_upper_um) == 0) {
                                        int64_t remaining_mm64 =
                                                (int64_t)job
                                                                ->destination_distance_mm -
                                                trusted_progress_mm;
                                        int remaining_mm =
                                                remaining_mm64 >= 0 &&
                                                        remaining_mm64 <=
                                                                0x7fffffff ?
                                                (int)remaining_mm64 : -1;
                                        safe_resume_speed =
                                                authority_resume_speed_for_window(
                                                        slot,
                                                        runtime
                                                                ->traffic_resume_speed,
                                                        remaining_mm,
                                                        runtime
                                                                ->authority_end_offset,
                                                        runtime
                                                                ->authority_center_ceiling_mm);
                                }
                                (void)occupancy_upper_um;
                                int full_authority =
                                        !runtime->rolling_authority_active ||
                                        (runtime->route_valid &&
                                         runtime->authority_end_offset >=
                                                 job
                                                         ->destination_route_offset);
                                if (full_authority &&
                                    (runtime->destination_correction_active ||
                                     runtime->destination_correction_pending) &&
                                    trusted_progress_mm >= 0 &&
                                    trusted_progress_mm <
                                            job->destination_distance_mm) {
                                        /* Resume the same correction marker;
                                         * do not try to stage it twice. */
                                        runtime->traffic_resume_speed =
                                                TC2_DESTINATION_CORRECTION_SPEED;
                                } else if (full_authority &&
                                    trusted_progress_mm >= 0 &&
                                           trusted_progress_mm <
                                                   job->destination_distance_mm) {
                                        /*
                                         * The complete suffix is already
                                         * owned, but no normal calibrated
                                         * speed can stop inside the short
                                         * scalar remainder.  This is exactly
                                         * the terminal speed-40 correction
                                         * case: re-enter PREPARING at zero,
                                         * reacquire/verify next and nextnext,
                                         * then crawl to the actual d point.
                                         */
                                        int correction_sensor =
                                                destination_correction_sensor_offset(
                                                        slot,
                                                        (int64_t)
                                                                trusted_progress_mm *
                                                                1000);
                                        int staged =
                                                stage_bounded_destination_correction(
                                                        slot,
                                                        correction_sensor);
                                        if (staged < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_INTERNAL);
                                        } else if (staged > 0) {
                                                runtime
                                                        ->conflict_zone_hold_active =
                                                        0;
                                        }
                                        continue;
                                } else if (full_authority &&
                                           safe_resume_speed > 0) {
                                        runtime->traffic_resume_speed =
                                                safe_resume_speed;
                                } else if (
                                    runtime->rolling_authority_active &&
                                    runtime->authority_end_offset >= 0 &&
                                    runtime->authority_end_offset <
                                            job->destination_route_offset) {
                                        runtime->conflict_zone_hold_active =
                                                0;
                                        runtime->traffic_reason =
                                                TC2_TRAFFIC_AUTHORITY;
                                        runtime->traffic_peer_train = 0;
                                        job->traffic_reason =
                                                TC2_TRAFFIC_AUTHORITY;
                                        job->traffic_peer_train = 0;
                                        if (begin_authority_request(
                                                    slot, now, 0) < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_INTERNAL);
                                        }
                                        continue;
                                } else {
                                        continue;
                                }
                        }
                        /*
                         * A settled hard-next proves turnout authority, not
                         * permission to move.  In particular, compatible
                         * nextnext preparation may have completed while a
                         * peer still requires this train to remain stopped.
                         * Re-enter the atomic prelaunch path and let the next
                         * all-train safety pass admit or block positive speed.
                         */
                        int staged_resume =
                                defer_traffic_resume_for_conflict_zone(
                                        slot, now);
                        if (staged_resume < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        if (staged_resume > 0) {
                                runtime->conflict_zone_hold_active = 0;
                                continue;
                        }
                }
                if (step_index < 0 || step_index >=
                    runtime->conflict_zone_plan.step_count) {
                        continue;
                }
                const tc2_conflict_zone_route_stage *stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan,
                                step_index);
                if (!stage || stage->member_step[0] != step_index ||
                    runtime->conflict_zone_hard_ticket == 0) {
                        continue;
                }

                int64_t progress_um = 0;
                int origin_egress_proved = 0;
                if (origin_zone_egress_ready(slot, step_index)) {
                        if (stage->exit_distance_mm >
                                    stage->entry_distance_mm) {
                                origin_egress_proved =
                                        runtime_conflict_zone_progress_lower_bound_um(
                                                slot, now,
                                                &progress_um) == 0 &&
                                        progress_um >=
                                                (int64_t)stage
                                                        ->exit_distance_mm *
                                                        1000;
                        } else {
                                /*
                                 * A trimmed reverse-origin step may collapse
                                 * to MR1..MR1 (entry == exit == 0).  The
                                 * projected scalar is then true at arm time,
                                 * before any movement.  Require a later
                                 * ordered sensor that advances the confirmed
                                 * route scalar instead of consuming the step
                                 * immediately.
                                 */
                                origin_egress_proved =
                                        runtime->last_journal_sequence !=
                                                runtime
                                                  ->conflict_zone_origin_egress_sequence &&
                                        runtime->monitor
                                                        .confirmed_distance_mm >
                                                stage->exit_distance_mm;
                        }
                }
                if (origin_egress_proved) {
                        /*
                         * The body already owns this physical zone.  Consume
                         * the new route cursor only after its calibrated
                         * centre reaches the route-relative exit.  Advancing
                         * at front-edge entry promoted next/next-next while
                         * the train was still traversing a compound zone and
                         * could move a later turnout underneath the train.
                         * The old carry keeps the exact ticket until a later
                         * real sensor proves tail-clear.
                         */
                        runtime->conflict_zone_next_step =
                                conflict_zone_next_stage_first_step(
                                        &runtime->conflict_zone_plan,
                                        step_index);
                        runtime->conflict_zone_hard_step = -1;
                        runtime->conflict_zone_hard_ticket = 0;
                        reset_conflict_zone_action_cursor(runtime);
                        clear_origin_zone_egress(runtime);
                        if (promote_next_conflict_zone_after_entry(slot) < 0) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                        }
                        continue;
                }
                int all_settled = 1;
                int all_occupied = 1;
                int stage_zones[TC2_CONFLICT_STAGE_MAX_MEMBERS];
                for (int member = 0;
                     member < stage->member_count; ++member) {
                        int raw_step = stage->member_step[member];
                        int zone = runtime->conflict_zone_plan
                                           .steps[raw_step].zone;
                        stage_zones[member] = zone;
                        tc2_conflict_zone_grant grant;
                        int owns = Tc2ConflictZoneQueryGrant(
                                           &dispatch_conflict_zones,
                                           zone, &grant) > 0 &&
                                grant.owner_train == job->train &&
                                grant.owner_ticket ==
                                        runtime
                                          ->conflict_zone_hard_ticket &&
                                grant.owner_route_generation ==
                                        runtime
                                          ->conflict_zone_route_generation;
                        all_settled = all_settled && owns &&
                                grant.state ==
                                        TC2_CONFLICT_ZONE_SETTLED;
                        all_occupied = all_occupied && owns &&
                                grant.state ==
                                        TC2_CONFLICT_ZONE_OCCUPIED;
                }
                if (!all_settled && !all_occupied) {
                        continue;
                }
                if (runtime_conflict_zone_progress_lower_bound_um(
                            slot, now, &progress_um) < 0) {
                        continue;
                }
                if (all_settled &&
                    progress_um +
                            (int64_t)TC2_TRAIN_HALF_LENGTH_MM * 1000 >=
                            (int64_t)stage->entry_distance_mm * 1000) {
                        /*
                         * A short no-stop stage becomes occupied atomically:
                         * no member may be handed to another train while the
                         * body is between the first and last turnout.
                         */
                        if (Tc2ConflictZoneMarkOccupiedStage(
                                    &dispatch_conflict_zones,
                                    stage_zones, stage->member_count,
                                    job->train,
                                    runtime
                                      ->conflict_zone_route_generation,
                                    runtime
                                      ->conflict_zone_hard_ticket) < 0) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        all_occupied = 1;
                }
                if ((all_occupied || all_settled) &&
                    progress_um >=
                            (int64_t)stage->exit_distance_mm * 1000) {
                        for (int member = 0;
                             member < stage->member_count; ++member) {
                                int raw_step = stage->member_step[member];
                                const tc2_conflict_zone_route_step *step =
                                        &runtime->conflict_zone_plan
                                                 .steps[raw_step];
                                int entry_node = -1;
                                int exit_node = -1;
                                if (step->first_route_offset >= 0 &&
                                    step->first_route_offset <
                                            runtime->route.node_count) {
                                        entry_node = runtime->route.nodes[
                                                step->first_route_offset];
                                }
                                if (step->last_route_offset >= 0 &&
                                    step->last_route_offset <
                                            runtime->route.node_count) {
                                        exit_node = runtime->route.nodes[
                                                step->last_route_offset];
                                }
                                if (remember_conflict_zone_carry(
                                            runtime, step->zone,
                                            entry_node, exit_node,
                                            step->exit_distance_mm, 1,
                                            runtime
                                              ->conflict_zone_hard_ticket,
                                            runtime
                                              ->conflict_zone_route_generation,
                                            TC2_CONFLICT_CARRY_OCCUPIED) <
                                    0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        all_occupied = 0;
                                        break;
                                }
                        }
                        if (!all_occupied) continue;
                        runtime->conflict_zone_next_step =
                                conflict_zone_next_stage_first_step(
                                        &runtime->conflict_zone_plan,
                                        step_index);
                        runtime->conflict_zone_hard_step = -1;
                        runtime->conflict_zone_hard_ticket = 0;
                        reset_conflict_zone_action_cursor(runtime);
                        if (promote_next_conflict_zone_after_entry(slot) < 0) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                        }
                }
        }
}

static int queue_turnout_plan_range(
        int slot, int plan_start, int plan_end) {
        track_turnout_plan plan;
        int switch_numbers[CAN_COMMAND_BATCH_MAX];
        char directions[CAN_COMMAND_BATCH_MAX];
        int count = 0;
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            plan_start < 0 || plan_end < plan_start ||
            plan_end >= runtime->route.node_count) {
                return -1;
        }
        /*
         * Once the physical-zone plan exists, only its current owner is
         * allowed to put a switch command on CAN.  The zone scheduler below
         * sends one canonical setting after a hard grant; the legacy
         * whole-leg batch must therefore become a no-op for these jobs.
         */
        if (runtime->conflict_zone_plan_valid) return 0;
        if (build_turnout_plan_range_checked(
                    &runtime->route, plan_start,
                    plan_end, &plan) < 0) {
                return -1;
        }
        for (int action = 0; action < plan.action_count; ++action) {
                if (runtime->carry_ambiguity_active &&
                    turnout_action_overlaps_footprint(
                            &plan.actions[action],
                            &runtime
                                     ->carry_ambiguity_footprint)) {
                        /*
                         * This physical resource may be beneath any one of
                         * the carried position hypotheses. The preceding
                         * final-leg batch already received its CS3
                         * confirmation, so an identical setting is reused
                         * without putting another command on the wire.
                         */
                        if (!runtime
                                     ->carry_confirmed_turnouts_valid ||
                            !turnout_action_matches_confirmed_plan(
                                    &plan.actions[action],
                                    &runtime
                                             ->carry_confirmed_turnouts)) {
                                return -1;
                        }
                        continue;
                }
                char direction =
                        Tc2TrackPhysicalTurnoutDirection(
                                plan.actions[action].direction);
                if (!direction) return -1;
                int mate = paired_turnout_mate(
                        plan.actions[action].switch_number);
                if (plan.actions[action].direction ==
                            DIR_CURVED &&
                    mate != 0) {
                        if (count >= CAN_COMMAND_BATCH_MAX) return -1;
                        switch_numbers[count] = mate;
                        directions[count++] =
                                Tc2TrackPhysicalTurnoutDirection(
                                        DIR_STRAIGHT);
                }
                if (count >= CAN_COMMAND_BATCH_MAX) return -1;
                switch_numbers[count] =
                        plan.actions[action].switch_number;
                directions[count++] = direction;
        }
        if (count == 0) return 0;
        return CanSwitchBatch(
                dispatch_can_tid, switch_numbers, directions, count);
}

static int queue_turnout_plan_for_leg(int slot) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int plan_start = runtime->leg_start_offset;
        int plan_end = runtime->leg_end_offset;
        if (runtime->rolling_authority_active &&
            runtime->authority_end_offset >=
                    runtime->leg_start_offset &&
            runtime->authority_end_offset < plan_end) {
                plan_end = runtime->authority_end_offset;
        }
        /*
         * An authority extension may run after the train has released track
         * behind it.  Reissuing the complete leg plan would then command
         * turnouts that this train no longer owns.  Include the old boundary
         * node (the connecting edge can itself be a turnout), but command
         * only the newly authorized suffix.
         */
        if (runtime->rolling_authority_active &&
            runtime->authority_resume_pending &&
            runtime->authority_previous_end_offset >= plan_start &&
            runtime->authority_previous_end_offset <= plan_end) {
                plan_start =
                        runtime->authority_previous_end_offset;
        }
        return queue_turnout_plan_range(
                slot, plan_start, plan_end);
}

static int next_leg_turnouts_clear_of_uncertain_train(int slot) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        track_turnout_plan plan;
        track_route ambiguity;
        int next_leg = runtime->leg_end_offset + 1;
        int next_end;
        int corridor_first;
        if (next_leg >= runtime->route.node_count) return 0;
        next_end = TrackRouteMotionLegEnd(
                dispatch_track, &runtime->route, next_leg);
        if (next_end >= job->destination_route_offset) {
                next_end = job->destination_route_offset;
        }
        if (next_end < next_leg ||
            build_turnout_plan_range_checked(
                    &runtime->route, next_leg, next_end, &plan) < 0) {
                return 0;
        }

        /*
         * One false report can name the exact reversal sensor.  In that
         * case the stopped train may actually be anywhere from the body-tail
         * behind the last independently confirmed point through the reported
         * sensor.  Reversing inside owned track is safe, but changing any
         * turnout in that ambiguity corridor is not.  Treat each paired
         * middle turnout as one physical resource as well.
         */
        corridor_first = footprint_tail_offset(runtime, job);
        int braking_speed =
                runtime->motion_speed_ceiling > job->speed ?
                        runtime->motion_speed_ceiling :
                        job->speed;
        int forward_overrun =
                Tc2MotionBrakingDistanceMm(braking_speed);
        if (forward_overrun < 0 ||
            build_route_slice(
                    &runtime->route, corridor_first,
                    runtime->leg_end_offset, &ambiguity) < 0 ||
            append_forward_guard_reachable(
                    &ambiguity,
                    runtime->route.nodes[
                            runtime->leg_end_offset],
                    forward_overrun) < 0 ||
            append_paired_turnout_resources(&ambiguity) < 0) {
                return 0;
        }
        for (int action = 0; action < plan.action_count; ++action) {
                int controlled =
                        plan.actions[action].switch_number;
                int controlled_mate =
                        paired_turnout_mate(controlled);
                for (int offset = 0;
                     offset < ambiguity.node_count; ++offset) {
                        int node = ambiguity.nodes[offset];
                        int number = dispatch_track[node].num;
                        if ((dispatch_track[node].type == NODE_BRANCH ||
                             dispatch_track[node].type == NODE_MERGE) &&
                            (number == controlled ||
                             number == controlled_mate ||
                             paired_turnout_mate(number) ==
                                     controlled)) {
                                return 0;
                        }
                }
        }
        return 1;
}

static int route_has_foreign_active_sensor(
        int train, const track_route *route,
        const train_sensor_snapshot_t *sensor,
        const track_reservation_snapshot *reservation) {
        for (int offset = 0; offset < route->node_count; ++offset) {
                int node = route->nodes[offset];
                if (node < TRAIN_SENSOR_COUNT &&
                    sensor->sensor_state[node] &&
                    reservation->owner_by_node[node] != train) {
                        return node;
                }
        }
        return -1;
}

static int journal_is_clean_after(
        int train, unsigned int after) {
        for (int page = 0; page < 8; ++page) {
                train_sensor_event_batch_t batch;
                if (TrainSensorGetAttributedEvents(
                            dispatch_sensor_tid, train,
                            after, &batch) < 0 ||
                    batch.lost || batch.count < 0 ||
                    batch.count >
                            TRAIN_SENSOR_EVENT_BATCH_CAPACITY) {
                        return 0;
                }
                if (batch.count > 0) return 0;
                if (!batch.has_more) return 1;
                after = batch.newest_sequence;
        }
        return 0;
}

static int prepare_waiting_job(int slot, int now) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensor;
        track_route route;
        track_route safety_footprint;
        tc2_conflict_zone_route_plan candidate_zone_plan;
        track_reservation_conflict conflict;
        unsigned int generation;
        int target = -1;
        int target_offset = -1;
        int destination_route_offset = -1;
        int destination_offset_value = 0;
        int destination_confirmed = 0;
        int path_distance = -1;
        int side = -1;
        int localization_only = 0;
        int estimated_ambiguity_blocked = 0;
        int projection_ready = 0;
        tc2_route_projection_selection projection_selection;
        tc2_prediction_request projection_request;
        track_route projection_geometry_route;
        tc2_prediction_plan projection_prediction;
        const tc2_prediction_plan *projection_prediction_source = 0;
        candidate_zone_plan.step_count = 0;
        candidate_zone_plan.stage_count = 0;
        int projection_anchor_offset = -1;
        int projection_destination_offset = -1;

        ensure_conflict_zone_table();
        candidate_zone_plan.step_count = 0;
        int rolling_authority = 0;
        int authority_end_offset = -1;
        int authority_center_ceiling_mm = -1;
        int authority_launch_speed = job->speed;
        int initial_authority_first_offset = 0;
        int initial_authority_minimum_end = 1;
        int initial_authority_progress_mm = 0;
        int leading_reversal = 0;
        track_route leading_reversal_carry;
        leading_reversal_carry.node_count = 0;
        leading_reversal_carry.distance_mm = 0;
        leading_reversal_carry.optimization_cost_mm = 0;
        leading_reversal_carry.reversal_count = 0;
        const tc2_track_destination_side *selected_side_definition = 0;
        int rolling_authority_candidate =
                (job->start_index >= 0 &&
                 job->start_index <
                         TC2_DISPATCH_START_COUNT) ||
                job->start_index ==
                        TC2_DISPATCH_START_CURRENT;
        /*
         * Route selection for every rolling-authority job ignores distant
         * managed reservations.  The exact first local window is still checked
         * atomically below, so CURRENT recovery can choose a safe shortest path
         * without a far-away train making the whole graph unavailable.
         */
        int rolling_route_selection =
                rolling_authority_candidate;
        candidate_zone_plan.step_count = 0;

        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0) {
                fail_job(slot, TC2_FAILURE_RESERVATION_SERVICE);
                return -1;
        }
        if (TrainSensorGetLatest(dispatch_sensor_tid, &sensor) < 0) {
                fail_job(slot, TC2_FAILURE_SENSOR_SERVICE);
                return -1;
        }
        /*
         * A staged train is still commanded to speed zero.  Its origin
         * detector may settle or be reported again while route planning is
         * in progress (and other managed trains may also change the global
         * sensor journal).  Neither event can be evidence that this train
         * moved out of sequence before launch.  The route is selected from
         * the fresh snapshot above, and launch_ready_jobs() establishes the
         * movement journal baseline atomically with the positive-speed CAN
         * batch.  Sensor-sequence enforcement therefore starts at launch,
         * not at staging.
         */
        /*
         * CURRENT staging preserves the ARRIVED job's CAN baseline.  A
         * turnout change between staging and planning must not become the
         * new trusted baseline, especially when an identical prior setting
         * would otherwise be reused without retransmission.
         */
        int prepare_can_health =
                can_health_is_safe(slot, 0, now);
        if (prepare_can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }
        if (prepare_can_health == TC2_CAN_HEALTH_RETRY) {
                return 1;
        }
        if (choose_shortest_available_route(
                    slot, &reservation, &sensor, &route, &target,
                    &target_offset, &destination_route_offset,
                    &destination_offset_value,
                    &destination_confirmed,
                    &path_distance, &side,
                    &estimated_ambiguity_blocked,
                    rolling_route_selection) < 0) {
                unsigned char unavailable[TRACK_MAX];
                if (!runtime->carry_ambiguity_active ||
                    !estimated_ambiguity_blocked ||
                    runtime->localization_hops >=
                            TC2_MAX_LOCALIZATION_HOPS) {
                        job->conflict_train = 0;
                        job->conflict_node = -1;
                        return 1;
                }
                build_unavailable(
                        slot, &reservation, &sensor,
                        unavailable, 0);
                if (choose_safe_localization_route(
                            slot, unavailable, &route,
                            &target, &target_offset,
                            &path_distance) < 0) {
                        job->conflict_train = 0;
                        job->conflict_node = -1;
                        return 1;
                }
                side = -1;
                localization_only = 1;
                util_zero_bytes(
                        (volatile unsigned char *)
                                &runtime->prediction_plan,
                        (unsigned int)sizeof(
                                runtime->prediction_plan));
                runtime->prediction_plan_valid = 0;
                clear_prediction_snapshot(job);
                destination_route_offset = target_offset;
                destination_offset_value = 0;
                destination_confirmed = 1;
        }
        rolling_authority =
                rolling_authority_candidate &&
                !job->provisional_prediction &&
                !localization_only;
        if (destination_route_offset > 0 &&
            Tc2ConflictZoneBuildRoutePlan(
                    dispatch_track, &route, 0,
                    destination_route_offset,
                    &candidate_zone_plan) < 0) {
                fail_job(slot, TC2_FAILURE_ROUTE);
                return -1;
        }
        if (destination_route_offset > 0 &&
            split_exact_current_origin_stage(
                    job, runtime, &route,
                    &candidate_zone_plan) < 0) {
                fail_job(slot, TC2_FAILURE_ROUTE);
                return -1;
        }
        if (rolling_authority) {
                /*
                 * The first local authority must cover both one complete
                 * conservative stop and one CAN-confirmation/turnout-settle
                 * cycle.  Otherwise a route whose first discrete boundary is
                 * only just stoppable can launch correctly, request its next
                 * suffix immediately, and still hit the old hard ceiling
                 * before that suffix becomes usable.  This was first exposed
                 * by command 120 from A and later by command 100 from C.
                 *
                 * Seed the bounded selector one prefetch lead ahead for every
                 * fixed departure.  Restricting this to A/B at speed 120 left
                 * ordinary speed-80 A/B departures with a shorter first
                 * authority than C/D/E/F and allowed their first turnout
                 * preparation to lose the race with the hard ceiling.  The
                 * selector still chooses the shortest conflict-free local
                 * prefix, so this does not restore whole-route reservation at
                 * the origin.
                 */
                if (job->start_index >= 0 &&
                    job->start_index <
                            TC2_DISPATCH_START_COUNT &&
                    uses_measured_direct_stop(job)) {
                        initial_authority_progress_mm =
                                authority_prefetch_lead_mm(
                                        job->speed);
                        if (initial_authority_progress_mm < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_ROUTE);
                                return -1;
                        }
                }
                /*
                 * F->d1/d2 at command 100/120 has no intermediate boundary
                 * that contains the requested-speed conservative stop plus
                 * the turnout-confirmation lead. Treating the complete short
                 * trip as "remote" merely downshifts launch speed (d1 was
                 * previously 94 at command 100 and 92 at command 120). For
                 * these two short high-speed trips the endpoint is the first
                 * local authority block; lower speeds and longer F routes
                 * continue to use rolling windows.
                 */
                if (job->start_index == 5 &&
                    job->destination_index <= 1 &&
                    job->speed >= 100) {
                        initial_authority_minimum_end =
                                destination_route_offset;
                }
                int initial_leg_end =
                        TrackRouteMotionLegEnd(
                                dispatch_track, &route, 0);
                if (initial_leg_end < 0 ||
                    initial_leg_end >= route.node_count) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                if (initial_leg_end == 0 &&
                    destination_route_offset > 0) {
                        if (route.node_count < 2 ||
                            dispatch_track[route.nodes[0]].reverse !=
                                    &dispatch_track[
                                            route.nodes[1]]) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        leading_reversal = 1;
                        initial_authority_first_offset = 1;
                        initial_authority_minimum_end = 2;
                }
                /*
                 * An operator reroute whose selected destination lies behind
                 * the stopped train is intentionally a two-phase transaction.
                 * Report the direction change before selecting/reserving an
                 * outbound authority window: the caller restores the bounded
                 * static body, issues and settles the physical reverse, then
                 * stages CURRENT again from the reversed directed sensor.
                 * Nothing below this point (reservation CAS, resource FIFO,
                 * or turnout CAN) is allowed to run in the probe phase.
                 */
                if (leading_reversal &&
                    runtime->reroute_select_direction &&
                    dispatch_retarget_candidate_pre_cas) {
                        return TC2_PREPARE_OPERATOR_REVERSE_REQUIRED;
                }
                int require_head_on_release_witness =
                        job->start_index ==
                                TC2_DISPATCH_START_CURRENT &&
                        runtime->head_on_recovery_active &&
                        runtime->carry_ambiguity_active;
                int requested_stop_distance =
                        Tc2MotionStopDistanceMm(job->speed);
                /*
                 * First preserve a full requested-speed bounded window for
                 * every train whose local route is uncontended.  This is what
                 * keeps the same-direction leader moving: a rear train must
                 * never shorten the leader's already-free stopping window.
                 *
                 * A fixed-start follower whose requested-speed window reaches
                 * a remotely owned next-next zone gets one second chance
                 * below: admit exactly its current hard `next` zone at the
                 * immutable requested speed.  It may traverse that zone, but
                 * the following hard gate remains closed until the leader has
                 * physically cleared it.  Do not manufacture lower-speed
                 * micro-hops for fixed starts.
                 */
                int fixed_start =
                        job->start_index >= 0 &&
                        job->start_index <
                                TC2_DISPATCH_START_COUNT;
                int allow_precision_speed_fallback =
                        !fixed_start &&
                        requested_stop_distance >= 0 &&
                        path_distance <= requested_stop_distance;
                int window_status =
                        require_head_on_release_witness ?
                        select_head_on_recovery_initial_authority(
                                &route,
                                initial_authority_first_offset,
                                initial_authority_minimum_end,
                                target_offset,
                                destination_route_offset,
                                destination_offset_value,
                                path_distance, job->speed,
                                leading_reversal ||
                                        allow_precision_speed_fallback,
                                initial_authority_progress_mm,
                                job->train,
                                &reservation, &sensor,
                                &safety_footprint,
                                &authority_end_offset,
                                &authority_center_ceiling_mm,
                                &authority_launch_speed,
                                &conflict) :
                        select_bounded_rolling_authority_window(
                                &route,
                                initial_authority_first_offset,
                                initial_authority_minimum_end,
                                target_offset,
                                destination_route_offset,
                                destination_offset_value,
                                path_distance, job->speed,
                                leading_reversal ||
                                        allow_precision_speed_fallback,
                                initial_authority_progress_mm,
                                job->train,
                                &reservation, &sensor,
                                &safety_footprint,
                                &authority_end_offset,
                                &authority_center_ceiling_mm,
                                &authority_launch_speed,
                                &conflict);
                if (window_status > 0 && fixed_start &&
                    !leading_reversal &&
                    candidate_zone_plan.step_count > 0) {
                        window_status =
                                select_initial_next_zone_window(
                                        &route,
                                        &candidate_zone_plan,
                                        initial_authority_first_offset,
                                        0,
                                        initial_authority_minimum_end,
                                        destination_route_offset,
                                        job->speed, job->train,
                                        &reservation, &sensor,
                                        &safety_footprint,
                                        &authority_end_offset,
                                        &authority_center_ceiling_mm,
                                        &conflict);
                        if (window_status == 0) {
                                authority_launch_speed =
                                        job->speed;
                        }
                }
                if (window_status == 0 &&
                    leading_reversal) {
                        int stopped_guard =
                                TC2_TRAIN_HALF_LENGTH_MM +
                                TC2_INTERSECTION_RELEASE_MARGIN_MM;
                        if (build_route_slice(
                                    &route, 0, 0,
                                    &leading_reversal_carry) < 0 ||
                            append_forward_guard_reachable(
                                    &leading_reversal_carry,
                                    route.nodes[0],
                                    stopped_guard) < 0 ||
                            append_paired_turnout_resources(
                                    &leading_reversal_carry) < 0 ||
                            append_route_nodes(
                                    &safety_footprint,
                                    &leading_reversal_carry) < 0) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        track_reservation_conflict
                                carry_conflict;
                        int carry_available =
                                authority_footprint_available(
                                        &safety_footprint,
                                        job->train,
                                        &reservation, &sensor,
                                        &carry_conflict);
                        if (carry_available > 0) {
                                job->conflict_train =
                                        carry_conflict
                                                .owner_train;
                                job->conflict_node =
                                        carry_conflict
                                                .node_index;
                                return 1;
                        }
                        if (carry_available < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_ROUTE);
                                return -1;
                        }
                }
                if (window_status > 0) {
                        job->conflict_train =
                                conflict.owner_train;
                        job->conflict_node =
                                conflict.node_index;
                        return 1;
                }
                if (window_status < 0) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
        } else {
                int active = route_has_foreign_active_sensor(
                        job->train, &route, &sensor,
                        &reservation);
                if (active >= 0) {
                        job->conflict_train = 0;
                        job->conflict_node = active;
                        return 1;
                }
                if (build_safety_footprint_for_route(
                            &route, 0, target_offset,
                            destination_route_offset,
                            destination_offset_value,
                            job->speed,
                            &safety_footprint) < 0) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
        }
        if ((runtime->carry_ambiguity_active &&
             append_route_nodes(
                     &safety_footprint,
                     &runtime->carry_ambiguity_footprint) < 0)) {
                fail_job(slot, TC2_FAILURE_ROUTE);
                return -1;
        }
        if (rolling_authority) {
                int candidate_leg_end =
                        TrackRouteMotionLegEnd(
                                dispatch_track, &route,
                                initial_authority_first_offset);
                if (candidate_leg_end > destination_route_offset) {
                        candidate_leg_end = destination_route_offset;
                }
                int overtakes_front =
                        initial_authority_overtakes_batch_front(
                                slot, &route,
                                initial_authority_first_offset,
                                candidate_leg_end,
                                authority_end_offset,
                                &safety_footprint);
                if (overtakes_front < 0) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                if (overtakes_front > 0) {
                        return 1;
                }
        }
        /*
         * Recheck immediately before the reservation CAS. A failure here
         * leaves the preceding hold and its generation byte-for-byte
         * unchanged.
         */
        prepare_can_health =
                can_health_is_safe(slot, 0, now);
        if (prepare_can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }
        if (prepare_can_health == TC2_CAN_HEALTH_RETRY) {
                return 1;
        }

        selected_side_definition =
                side >= 0 && side < 2 ?
                Tc2TrackDestinationSide(
                        job->destination_index, side) : 0;
        /*
         * Build the complete immutable UI projection before changing
         * reservation ownership. Ordinary fixed-bay A-F jobs retain their
         * authoritative prediction-backed contract. An exact CURRENT
         * continuation publishes the same selected shortest-route geometry
         * without inventing a second timing controller.
         */
        int projection_required =
                (job->start_index ==
                         TC2_DISPATCH_START_CURRENT ||
                 (job->start_index >= 0 &&
                  job->start_index <
                          TC2_DISPATCH_START_COUNT)) &&
                !localization_only;
        if (projection_required) {
                if (!selected_side_definition) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                projection_anchor_offset = target_offset;
                projection_destination_offset =
                        destination_route_offset;
                if (job->start_index ==
                            TC2_DISPATCH_START_CURRENT) {
                        projection_request.train = job->train;
                        projection_request.start_index =
                                job->start_index;
                        projection_request.destination_index =
                                job->destination_index;
                        projection_request.destination_side = side;
                        projection_request.speed = job->speed;
                        projection_request.reversal_count =
                                route.reversal_count;
                        projection_selection.selected_motion_route =
                                &route;
                        projection_selection
                                .geometry_anchor_route_offset =
                                projection_anchor_offset;
                        projection_selection
                                .physical_destination_route_offset =
                                projection_destination_offset;
                        projection_selection
                                .physical_destination_offset_mm =
                                selected_side_definition
                                        ->base_offset_mm;
                        Tc2RouteProjectionInitialize(
                                &dispatch_projection_scratch);
                        int projection_status =
                                Tc2RouteProjectionBuildCurrent(
                                    dispatch_track,
                                    &projection_selection,
                                    &projection_request,
                                    &dispatch_projection_scratch);
                        if (projection_status ==
                                    TC2_ROUTE_PROJECTION_OK) {
                                projection_status =
                                        Tc2RouteProjectionValidateCurrent(
                                            dispatch_track,
                                            &projection_selection,
                                            &projection_request,
                                            &dispatch_projection_scratch);
                        }
                        if (projection_status !=
                                    TC2_ROUTE_PROJECTION_OK) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        if ((runtime->force_reverse_first ||
                             runtime->reroute_select_direction) &&
                            runtime->carry_preorigin_distance_mm > 0 &&
                            shift_current_projection_for_preorigin(
                                    &dispatch_projection_scratch,
                                    runtime
                                            ->carry_preorigin_distance_mm) <
                                    0) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        projection_ready = 1;
                } else {
                if (job->provisional_prediction) {
                        int physical_anchor =
                                TrackFindNodeByName(
                                        dispatch_track,
                                        selected_side_definition
                                                ->anchor_sensor);
                        projection_anchor_offset = -1;
                        for (int offset = 0;
                             offset < route.node_count; ++offset) {
                                if (route.nodes[offset] ==
                                    physical_anchor) {
                                        projection_anchor_offset =
                                                offset;
                                        break;
                                }
                        }
                        if (projection_anchor_offset < 0 ||
                            route_ceiling_after_offset(
                                    &route,
                                    projection_anchor_offset,
                                    selected_side_definition
                                            ->base_offset_mm,
                                    &projection_destination_offset) < 0) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                } else if (!runtime->prediction_plan_valid) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                if (build_route_slice(
                            &route, 0,
                            projection_anchor_offset,
                            &projection_geometry_route) < 0) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                projection_request.train = job->train;
                projection_request.start_index =
                        job->start_index;
                projection_request.destination_index =
                        job->destination_index;
                projection_request.destination_side = side;
                projection_request.speed = job->speed;
                projection_request.reversal_count =
                        projection_geometry_route
                                .reversal_count;
                if (job->provisional_prediction) {
                        if (Tc2PredictionBuildPlan(
                                    dispatch_track,
                                    &projection_geometry_route,
                                    &projection_request,
                                    &projection_prediction) !=
                                        TC2_PREDICTION_OK) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        projection_prediction_source =
                                &projection_prediction;
                } else {
                        projection_prediction_source =
                                &runtime->prediction_plan;
                }
                projection_selection.selected_motion_route =
                        &route;
                projection_selection
                        .geometry_anchor_route_offset =
                        projection_anchor_offset;
                projection_selection
                        .physical_destination_route_offset =
                        projection_destination_offset;
                projection_selection
                        .physical_destination_offset_mm =
                        selected_side_definition
                                ->base_offset_mm;
                Tc2RouteProjectionInitialize(
                        &dispatch_projection_scratch);
                int projection_status =
                        Tc2RouteProjectionBuildWithPrediction(
                            dispatch_track,
                            &projection_selection,
                            &projection_request,
                            projection_prediction_source,
                            &dispatch_projection_scratch);
                if (projection_status == TC2_ROUTE_PROJECTION_OK) {
                        projection_status =
                                Tc2RouteProjectionValidateWithPrediction(
                            dispatch_track,
                            &projection_selection,
                            &projection_request,
                            projection_prediction_source,
                            &dispatch_projection_scratch);
                }
                if (projection_status !=
                            TC2_ROUTE_PROJECTION_OK) {
                        if (!job->provisional_prediction) {
                                fail_job(slot, TC2_FAILURE_ROUTE);
                                return -1;
                        }
                        /*
                         * A negative supervised correction can make the
                         * physical-OP projection require a longer audit
                         * suffix than the already conservative control-point
                         * reservation.  Visualization must never reject an
                         * otherwise valid physical calibration run; the live
                         * UI falls back to start/OP plus exact CAN flashes.
                         */
                        projection_ready = 0;
                } else {
                        projection_ready = 1;
                }
                }
        }

        int reserve = runtime->replace_plan_expected &&
                              rolling_authority ?
                TrackReservationServerReplaceWindowExpected(
                        dispatch_reservation_tid,
                        &safety_footprint, job->train,
                        runtime->replace_expected_destination,
                        runtime->replace_expected_generation,
                        target, &conflict, &generation) :
                runtime->replace_plan_expected ?
                TrackReservationServerReplacePlanExpected(
                        dispatch_reservation_tid,
                        &safety_footprint, job->train,
                        runtime->replace_expected_destination,
                        runtime->replace_expected_generation,
                        target, &conflict, &generation) :
                rolling_authority ?
                TrackReservationServerReserveWindowWithGeneration(
                        dispatch_reservation_tid,
                        &safety_footprint, job->train,
                        target, &conflict, &generation) :
                TrackReservationServerReserveWithGeneration(
                        dispatch_reservation_tid,
                        &safety_footprint, job->train, target,
                        &conflict, &generation);
        if (reserve == 1) {
                job->conflict_train = conflict.owner_train;
                job->conflict_node = conflict.node_index;
                return 1;
        }
        if (reserve < 0 || generation == 0) {
                fail_job(slot, TC2_FAILURE_RESERVATION);
                return -1;
        }

        /* The replacement reservation is authoritative from this point on. */
        dispatch_retarget_candidate_pre_cas = 0;

        /*
         * The route-reservation CAS is now committed.  Cancel any old
         * in-flight switch batch before the candidate plan can issue a CAN
         * command, then apply only old-zone transitions whose entry/exit
         * geometry was proved before stage_job() cleared that route.
         */
        if (cancel_old_conflict_zone_batch(slot) < 0) {
                fail_job(slot, TC2_FAILURE_TURNOUT);
                return -1;
        }
        if (finalize_old_conflict_zone_carries(slot, now) < 0) {
                fail_job(slot, TC2_FAILURE_TURNOUT);
                return -1;
        }
        (void)Tc2ConflictZoneCancelTrain(
                &dispatch_conflict_zones, job->train);
        runtime->route = route;
        runtime->safety_footprint = safety_footprint;
        runtime->route_valid = 1;
        runtime->movement_plan_active = 1;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_NONE;
        runtime->conflict_zone_plan = candidate_zone_plan;
        runtime->conflict_zone_plan_valid = 1;
        runtime->conflict_zone_route_generation =
                allocate_conflict_zone_route_generation();
        runtime->conflict_zone_next_step = 0;
        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        runtime->conflict_zone_soft_ticket = 0;
        runtime->conflict_zone_batch_token = 0;
        reset_soft_conflict_zone_cursor(runtime, 1);
        runtime->conflict_zone_queue_pending = 0;
        runtime->conflict_zone_settle_at_tick = -1;
        runtime->conflict_zone_hold_active = 0;
        if (Tc2ConflictZoneRegisterTrain(
                    &dispatch_conflict_zones,
                    job->train) < 0) {
                fail_job(slot, TC2_FAILURE_RESERVATION);
                return -1;
        }
        /*
         * This is evaluated only after the replacement CAS committed and
         * the old logical CAN batches were cancelled.  Therefore an origin
         * continuation is backed solely by the live physical owner ticket
         * and its exact hard setting, never by a stale batch or soft hint.
         */
        if (arm_origin_zone_egress(slot) < 0) {
                fail_job(slot, TC2_FAILURE_RESERVATION);
                return -1;
        }
        if (refresh_conflict_zone_requests(slot) < 0) {
                fail_job(slot, TC2_FAILURE_RESERVATION);
                return -1;
        }
        runtime->rolling_authority_active =
                rolling_authority;
        runtime->authority_end_offset =
                rolling_authority ?
                authority_end_offset :
                destination_route_offset;
        runtime->authority_center_ceiling_mm =
                rolling_authority ?
                authority_center_ceiling_mm :
                path_distance;
        clear_authority_request(runtime);
        runtime->authority_resume_pending = 0;
        runtime->authority_previous_end_offset = -1;
        if (leading_reversal) {
                runtime->reversal_carry_footprint =
                        leading_reversal_carry;
                runtime->reversal_carry_active = 1;
                runtime->reversal_carry_origin_offset = 1;
        }
        runtime->localization_only =
                localization_only;
        runtime->leg_start_offset = 0;
        if (runtime->planned_launch_speed <= 0 ||
            (rolling_authority &&
             authority_launch_speed <
                     runtime->planned_launch_speed)) {
                runtime->planned_launch_speed =
                        authority_launch_speed;
        }
        runtime->command_speed =
                runtime->planned_launch_speed;
        runtime->motion_speed_ceiling =
                runtime->planned_launch_speed;
        runtime->speed_reduction_pending = 0;
        runtime->precision_approach_active = 0;
        runtime->approach_sent = 0;
        runtime->target_seen = 0;
        runtime->reservation_anchor_offset = 0;
        runtime->pending_missing_offset = -1;
        job->target_node = target;
        job->target_route_offset = target_offset;
        job->destination_base_offset_mm =
                selected_side_definition ?
                selected_side_definition->base_offset_mm : 0;
        if (job->provisional_prediction &&
            job->destination_index == 6 && side == 0 &&
            selected_side_definition &&
            selected_side_definition->previous_anchor_sensor &&
            target == TrackFindNodeByName(
                    dispatch_track,
                    selected_side_definition
                            ->previous_anchor_sensor)) {
                job->destination_base_offset_mm +=
                        selected_side_definition
                                ->previous_anchor_distance_mm;
        }
        job->destination_speed_correction_mm =
                destination_offset_value -
                job->destination_base_offset_mm;
        job->destination_offset_mm =
                destination_offset_value;
        job->destination_distance_mm = path_distance;
        job->destination_route_offset =
                destination_route_offset;
        job->destination_offset_confirmed =
                destination_confirmed;
        job->selected_destination_side = side;
        job->route_distance_mm = path_distance;
        job->remaining_distance_mm = path_distance;
        job->route_reversal_count = route.reversal_count;
        job->plan_generation = generation;
        publish_prediction_snapshot(job, runtime);
        if (projection_ready) {
                if (publish_projection(
                            slot,
                            &dispatch_projection_scratch) < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        return -1;
                }
        } else {
                invalidate_projection(slot);
        }
        job->conflict_train = 0;
        job->conflict_node = -1;
        job->hold_active = 0;
        job->position_estimated =
                runtime->carry_position_estimated ? 1 : 0;
        if (init_leg_monitor(
                    slot, sensor.attributed_count) < 0) {
                fail_job(slot, TC2_FAILURE_TURNOUT);
                return -1;
        }
        if (sensor_health_is_safe(
                    slot, &sensor, 1, now) < 0) {
                fail_job(slot, TC2_FAILURE_SENSOR_SERVICE);
                return -1;
        }
        prepare_can_health =
                can_health_is_safe(slot, 0, now);
        if (prepare_can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }
        runtime->prepare_attributed_sequence =
                sensor.attributed_count;
        runtime->prepare_attribution_unavailable_count =
                sensor.attribution_unavailable_count;
        runtime->prepare_unattributed_count =
                sensor.unattributed_count;
        for (int sensor_index = 0;
             sensor_index < TRAIN_SENSOR_COUNT; ++sensor_index) {
                runtime->prepare_sensor_state[sensor_index] =
                        sensor.sensor_state[sensor_index];
        }
        /*
         * A generalized shortest path may begin with a zero-distance sensor
         * reversal. Perform that direction change while the train is still
         * stopped, then initialize the first actual motion leg before it can
         * join a launch wave.
         */
        if (runtime->leg_end_offset ==
                    runtime->leg_start_offset &&
            runtime->leg_end_offset <
                    job->destination_route_offset) {
                int next = runtime->leg_start_offset + 1;
                if (next >= runtime->route.node_count ||
                    dispatch_track[
                            runtime->route.nodes[
                                    runtime->leg_start_offset]]
                                    .reverse !=
                            &dispatch_track[
                                    runtime->route.nodes[next]]) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                /*
                 * The bounded outbound window is already reserved.  Queue
                 * and settle its turnouts first; process_preparing_jobs()
                 * sends the reverse command only after that barrier.
                 */
                runtime->prelaunch_reverse_pending = 1;
                runtime->reroute_reverse_before_resources =
                        runtime->reroute_select_direction;
                runtime->prelaunch_turnout_settle_at_tick = -1;
                runtime->prelaunch_reverse_ready_at_tick = -1;
                runtime->leg_start_offset = next;
                ++job->reversals_completed;
                ++job->current_leg;
                if (init_leg_monitor(
                            slot, sensor.attributed_count) < 0) {
                        fail_job(slot, TC2_FAILURE_ROUTE);
                        return -1;
                }
                if ((runtime->force_reverse_first ||
                     runtime->reroute_select_direction) &&
                    runtime->carry_position_estimated &&
                    runtime->carry_preorigin_distance_mm > 0) {
                        runtime->preorigin_distance_mm =
                                runtime->carry_preorigin_distance_mm;
                        runtime->preorigin_sensor_pending = 1;
                        job->confirmed_distance_mm =
                                -runtime->preorigin_distance_mm;
                        runtime->motion_anchor_distance_um =
                                -(int64_t)runtime
                                        ->preorigin_distance_mm * 1000;
                        /*
                         * The reverse command changes direction, not physical
                         * position.  Keep the published anchor on the old
                         * directed occurrence (route[0]) until the reverse
                         * origin detector is actually observed.  Publishing
                         * route[1] here made the UI claim A16 before the train
                         * had traversed the virtual d1-to-A16 prefix.
                         */
                        job->current_route_offset = 0;
                        job->current_node = runtime->route.nodes[0];
                        job->estimated_distance_um = 0;
                        update_next_sensor(slot);
                }
        }
        if (runtime->leg_start_offset ==
            job->destination_route_offset) {
                job->current_node = target;
                job->current_route_offset = target_offset;
                /*
                 * A zero-motion result still owns a newly selected
                 * final-leg/braking-extension turnout plan. Queue that plan
                 * even when no direction change was needed; otherwise a
                 * later CURRENT stage could reconstruct it from this route
                 * and mistake an unsent setting for a CS3-confirmed one.
                 * Keep the full replacement footprint until the batch
                 * completes and, when applicable, the leading reverse has
                 * mechanically settled.
                 */
                int turnout_token =
                        runtime->reroute_reverse_before_resources ? 0 :
                        queue_turnout_plan_for_leg(slot);
                if (turnout_token < 0 &&
                    turnout_token != CAN_SEND_BUSY) {
                        fail_job(
                                slot,
                                TC2_FAILURE_TURNOUT);
                        return -1;
                }
                runtime->zero_motion_arrival_pending = 1;
                runtime->zero_motion_arrival_ready_at_tick =
                        runtime
                                        ->prelaunch_reverse_ready_at_tick >=
                                        0 ?
                                runtime
                                        ->prelaunch_reverse_ready_at_tick :
                                now;
                runtime->turnout_queue_pending =
                        turnout_token == CAN_SEND_BUSY;
                runtime->turnout_batch_token =
                        turnout_token > 0 ?
                                (unsigned int)turnout_token : 0;
                if (runtime->prelaunch_reverse_pending &&
                    turnout_token == 0) {
                        runtime->prelaunch_turnout_settle_at_tick =
                                now;
                }
                job->ready_at_tick = -1;
                job->state = TC2_JOB_PREPARING;
                return 0;
        }

        int turnout_token =
                runtime->reroute_reverse_before_resources ? 0 :
                queue_turnout_plan_for_leg(slot);
        if (turnout_token < 0 &&
            turnout_token != CAN_SEND_BUSY) {
                fail_job(slot, TC2_FAILURE_TURNOUT);
                return -1;
        }
        runtime->turnout_queue_pending =
                turnout_token == CAN_SEND_BUSY;
        runtime->turnout_batch_token =
                turnout_token > 0 ?
                        (unsigned int)turnout_token : 0;
        if (runtime->prelaunch_reverse_pending &&
            turnout_token == 0) {
                runtime->prelaunch_turnout_settle_at_tick =
                        now;
        }
        runtime->ready_wave_tick = -1;
        job->ready_at_tick = -1;
        job->state = TC2_JOB_PREPARING;
        return 0;
}

/*
 * A speed command is idempotent.  The CAN server can report one transient
 * priority-command timeout while a confirmed turnout batch is retiring.
 * Treating that single timeout as a permanent trip failure strands a healthy
 * train between turnouts (D9/E11 is the reproducible case).  Retry the exact
 * same command synchronously; the caller has already proved movement
 * authority before any positive command reaches this helper.
 */
static int command_train_speed_with_retry(int train, int speed) {
        for (int attempt = 0; attempt < 3; ++attempt) {
                if (CanTrainSetSpeedPriority(
                            dispatch_can_tid, train, speed) >= 0) {
                        return 0;
                }
                if (attempt + 1 < 3) Delay(1);
        }
        return -1;
}

/*
 * Return 0 after an acknowledged positive command, 1 when a normal safety
 * gate says to remain stopped, and -1 only for a CAN/service failure.  Zero
 * commands deliberately continue to use command_train_speed_with_retry(): a
 * stop must never depend on permission to move.
 */
static int command_train_positive_speed_with_retry(
        int slot, int speed) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            speed < 1 || speed > 120) {
                return -1;
        }
        if (!can_train_move(slot)) return 1;
        return command_train_speed_with_retry(
                dispatch_jobs[slot].train, speed) < 0 ? -1 : 0;
}

static void begin_stop_with_queued_zero(
        int slot, int now, int purpose,
        int estimated_position, int trigger,
        unsigned int queued_zero_token) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int stop_speed =
                runtime->motion_speed_ceiling >
                                runtime->command_speed ?
                        runtime->motion_speed_ceiling :
                        runtime->command_speed;
        if (stop_speed <= 0) stop_speed = job->speed;
        int settle_ticks =
                Tc2MotionStopSettleTicks(stop_speed);
        if (settle_ticks < 0) {
                fail_job(slot, TC2_FAILURE_INTERNAL);
                return;
        }
        int stop_request_tick = Time();
        if (stop_request_tick < 0) {
                fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                return;
        }
        if (queued_zero_token != 0) {
                runtime->emergency_stop_token = queued_zero_token;
        } else if (command_train_speed_with_retry(job->train, 0) < 0) {
                /*
                 * A confirmed priority command can lose only its CS3
                 * acknowledgement while a turnout command is retiring.
                 * Queue the same zero as an emergency batch, retain the
                 * route/turnout state, and wait for its exact batch
                 * acknowledgement before starting the coast timer.
                 */
                int train = job->train;
                int token = CanTrainEmergencyStopBatch(
                        dispatch_can_tid, &train, 1);
                if (token <= 0) {
                        fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                        return;
                }
                runtime->emergency_stop_token =
                        (unsigned int)token;
        }
        int stop_confirmed_tick = Time();
        if (stop_confirmed_tick < 0) {
                fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                return;
        }
        if (purpose == TC2_STOP_TRAFFIC) {
                if (pause_destination_anchor_seek(
                            runtime, stop_confirmed_tick) < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        return;
                }
                int64_t command_progress_um;
                int coast_um =
                        Tc2MotionMeasuredStopDistanceUm(
                                stop_speed);
                if (coast_um < 0 ||
                    runtime_private_motion_progress_um(
                            slot, stop_confirmed_tick,
                            &command_progress_um) < 0 ||
                    command_progress_um >
                            INT64_MAX - coast_um) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        return;
                }
                int64_t hold_um =
                        command_progress_um + coast_um;
                if (runtime->preorigin_sensor_pending && hold_um > 0) {
                        hold_um = 0;
                }
                int64_t destination_um =
                        (int64_t)job
                                ->destination_distance_mm * 1000;
                if (hold_um > destination_um) {
                        hold_um = destination_um;
                }
                runtime->preorigin_traffic_hold_valid =
                        runtime->preorigin_sensor_pending;
                runtime->preorigin_traffic_hold_distance_um =
                        runtime->preorigin_sensor_pending ?
                        hold_um : 0;
                runtime->motion_anchor_distance_um =
                        command_progress_um;
                runtime->motion_anchor_tick =
                        stop_confirmed_tick;
                runtime->motion_anchor_from_traffic = 1;
                runtime->traffic_hold_distance_um =
                        runtime->preorigin_sensor_pending ?
                        0 : hold_um;
                job->traffic_hold_distance_um =
                        runtime->traffic_hold_distance_um;
                job->estimated_distance_um =
                        runtime->preorigin_sensor_pending ?
                        0 : command_progress_um;
        }
        runtime->stop_purpose = purpose;
        runtime->settle_at_tick =
                tick_after(stop_confirmed_tick, settle_ticks);
        if (runtime->command_speed > 0) {
                if (runtime->motion_speed_ceiling <
                    runtime->command_speed) {
                        runtime->motion_speed_ceiling =
                                runtime->command_speed;
                }
        }
        runtime->speed_reduction_pending = 0;
        runtime->precision_approach_active = 0;
        runtime->command_speed = 0;
        job->command_speed = 0;
        job->stop_sent_tick = stop_confirmed_tick;
        if (!job->stop_timing_valid) {
                job->stop_request_tick = stop_request_tick;
                job->stop_confirmed_tick = stop_confirmed_tick;
                job->stop_timing_valid = 1;
        }
        job->stop_trigger = trigger;
        job->position_estimated = estimated_position;
        job->braking_at_tick = -1;
        job->state = TC2_JOB_BRAKING;
        (void)now;
}

static void begin_stop(int slot, int now, int purpose,
                       int estimated_position, int trigger) {
        begin_stop_with_queued_zero(
                slot, now, purpose, estimated_position,
                trigger, 0);
}

static int traffic_effective_speed(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (job->state == TC2_JOB_TRAFFIC_HOLD ||
            job->state == TC2_JOB_REVERSING ||
            job->state == TC2_JOB_STOP_UNCONFIRMED ||
            job->state == TC2_JOB_ARRIVED ||
            job->state == TC2_JOB_STOPPED ||
            job->state == TC2_JOB_WAITING ||
            job->state == TC2_JOB_STAGED ||
            job->state == TC2_JOB_FAILED) {
                return 0;
        }
        if (job->state == TC2_JOB_PREPARING ||
            job->state == TC2_JOB_READY) {
                return 0;
        }
        int speed = runtime->command_speed;
        if (runtime->motion_speed_ceiling > speed) {
                speed = runtime->motion_speed_ceiling;
        }
        if (speed <= 0 &&
            (job->state == TC2_JOB_RUNNING ||
             job->state == TC2_JOB_BRAKING)) {
                speed = job->speed;
        }
        return speed >= 0 && speed <= 120 ? speed : -1;
}

/*
 * READY/PREPARING trains are physically stopped, but their positive planned
 * command must participate in prelaunch following admission.  Otherwise two
 * close convoy members enter the same launch batch and the 350 mm rear-only
 * rule cannot act until after both CAN speed commands were acknowledged.
 */
static int traffic_safety_evaluation_speed(int slot) {
        int speed = traffic_effective_speed(slot);
        if (speed != 0 || slot < 0 ||
            slot >= TC2_DISPATCH_MAX_JOBS) {
                return speed;
        }
        int state = dispatch_jobs[slot].state;
        if (state != TC2_JOB_PREPARING &&
            state != TC2_JOB_READY &&
            state != TC2_JOB_LAUNCHING) {
                return 0;
        }
        int planned = dispatch_runtime[slot].planned_launch_speed;
        return planned >= 1 && planned <= 120 ? planned : 0;
}

static int traffic_braking_envelope_mm(int slot) {
        int speed = traffic_effective_speed(slot);
        if (speed < 0) return -1;
        return speed == 0 ?
                0 : Tc2MotionBrakingDistanceMm(speed);
}

/*
 * Retained as an input-validity witness for the pure emergency policy.  Stop
 * distance no longer enlarges the 250 mm audit threshold; normal stopping
 * envelopes belong exclusively to each train's next physical authority.
 */
static int traffic_collision_stop_distance_mm(int slot) {
        int speed = traffic_effective_speed(slot);
        if (speed < 0) return -1;
        return speed == 0 ?
                0 : Tc2MotionStopDistanceMm(speed);
}

static int traffic_resume_fits_current_authority(
        int slot, int speed) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return 0;
        }
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];

        /*
         * An explicitly staged destination correction is already the
         * bounded fallback after the requested-speed stop has completed.
         * Applying the ordinary speed-40 command-to-rest envelope a second
         * time makes the final interval impossible to resume whenever that
         * envelope reaches the lowercase-d coordinate.  Its admissible
         * bound is instead the complete owned route to d; next/nextnext,
         * turnout settling, conflict zones and physical traffic are still
         * checked independently before any positive command is committed.
         */
        if (speed == TC2_DESTINATION_CORRECTION_SPEED &&
            (runtime->destination_correction_pending ||
             runtime->destination_correction_active)) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                int trusted_progress_mm;
                int64_t occupancy_upper_um;
                if (!runtime->route_valid ||
                    job->destination_route_offset < 0 ||
                    job->destination_route_offset >=
                            runtime->route.node_count ||
                    job->destination_distance_mm < 0 ||
                    (runtime->rolling_authority_active &&
                     runtime->authority_end_offset <
                            job->destination_route_offset) ||
                    traffic_hold_progress_bounds(
                            slot, &trusted_progress_mm,
                            &occupancy_upper_um) < 0) {
                        return 0;
                }
                (void)occupancy_upper_um;
                return trusted_progress_mm >= 0 &&
                        trusted_progress_mm <
                                job->destination_distance_mm;
        }
        return traffic_resume_fits_authority_window(
                slot, speed,
                runtime->authority_end_offset,
                runtime->authority_center_ceiling_mm);
}

static int traffic_resume_fits_authority_window(
        int slot, int speed, int authority_end_offset,
        int authority_center_ceiling_mm) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            speed < 1 || speed > 120) {
                return 0;
        }
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        int trusted_progress_mm;
        int64_t occupancy_upper_um;
        int measured_stop =
                Tc2MotionStopDistanceMm(speed);
        if (measured_stop < 0 ||
            traffic_hold_progress_bounds(
                    slot, &trusted_progress_mm,
                    &occupancy_upper_um) < 0 ||
            occupancy_upper_um >
                    INT64_MAX -
                            (int64_t)measured_stop * 1000 ||
            occupancy_upper_um +
                            (int64_t)measured_stop * 1000 >
                    (int64_t)job
                            ->destination_distance_mm * 1000) {
                return 0;
        }
        (void)trusted_progress_mm;
        if (!runtime->rolling_authority_active) return 1;
        if (!runtime->route_valid ||
            runtime->route.node_count < 2 ||
            authority_end_offset < 0 ||
            authority_end_offset >=
                    runtime->route.node_count) {
                return 0;
        }
        if (authority_end_offset >=
            job->destination_route_offset) {
                return 1;
        }
        int braking =
                Tc2MotionBrakingDistanceMm(speed);
        if (braking < 0 ||
            authority_center_ceiling_mm < 0 ||
            occupancy_upper_um >
                    INT64_MAX - (int64_t)braking * 1000) {
                return 0;
        }
        return occupancy_upper_um +
                       (int64_t)braking * 1000 <
                (int64_t)authority_center_ceiling_mm * 1000;
}

/* A same-direction following stop may resume only outside 350 mm. */
static int following_gap_safe_resume_speed(
        int maximum_speed, int gap_mm) {
        if (maximum_speed < 1 || maximum_speed > 120 ||
            gap_mm < 0) {
                return -1;
        }
        return gap_mm <=
                       TC2_TRAFFIC_FOLLOWING_CLEARANCE_MM ?
                0 : maximum_speed;
}

static int following_safe_resume_speed(
        int slot, int maximum_speed, int gap_mm) {
        if (maximum_speed < 1 || maximum_speed > 120 ||
            gap_mm < -1) {
                return -1;
        }
        int gap_limited_speed = maximum_speed;
        if (gap_mm >= 0) {
                gap_limited_speed =
                        following_gap_safe_resume_speed(
                                maximum_speed, gap_mm);
                if (gap_limited_speed < 1) {
                        return gap_limited_speed;
                }
        }
        for (int speed = gap_limited_speed;
             speed >= 1; --speed) {
                if (traffic_resume_fits_current_authority(
                            slot, speed)) {
                        return speed;
                }
        }
        return 0;
}

static int saturated_threshold_add(int left, int right) {
        if (left < 0 || right < 0) return -1;
        return left > 0x7fffffff - right ?
                0x7fffffff : left + right;
}

static void begin_traffic_stop_with_queued_zero(
        int slot, int now, int reason, int peer_train,
        int gap_mm, int stop_threshold_mm,
        int resume_threshold_mm,
        unsigned int queued_zero_token) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return;
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (job->state == TC2_JOB_TRAFFIC_HOLD ||
            (job->state == TC2_JOB_BRAKING &&
             runtime->stop_purpose == TC2_STOP_TRAFFIC)) {
                runtime->traffic_peer_train = peer_train;
                job->traffic_peer_train = peer_train;
                job->traffic_gap_mm = gap_mm;
                job->traffic_stop_threshold_mm = stop_threshold_mm;
                job->traffic_resume_threshold_mm = resume_threshold_mm;
                return;
        }
        /*
         * A rolling-authority continuation has not received a confirmed
         * positive-speed command yet.  Keep its frozen position and newly
         * acquired reservation, but prevent READY from entering a launch
         * wave.  A LAUNCHING race is handled by process_launching_jobs(),
         * which cancels and fail-stops the complete atomic wave.
         */
        if (runtime->authority_resume_pending &&
            (job->state == TC2_JOB_PREPARING ||
             job->state == TC2_JOB_READY ||
             job->state == TC2_JOB_LAUNCHING)) {
                runtime->prelaunch_traffic_blocked = 1;
                job->traffic_gap_mm = gap_mm;
                job->traffic_stop_threshold_mm =
                        stop_threshold_mm;
                job->traffic_resume_threshold_mm =
                        resume_threshold_mm;
                return;
        }
        /*
         * A destination/reversal stop already has an acknowledged zero
         * command and keeps its reservation.  Never replace that terminal
         * purpose with a resumable traffic hold.
         */
        if (job->state != TC2_JOB_RUNNING) return;
        int resume_speed = runtime->command_speed > 0 ?
                runtime->command_speed : job->speed;
        runtime->traffic_resume_speed = resume_speed;
        runtime->traffic_peer_train = peer_train;
        runtime->traffic_reason = reason;
        runtime->traffic_hold_since_tick = -1;
        job->traffic_hold_active = 1;
        job->traffic_reason = reason;
        job->traffic_peer_train = peer_train;
        job->traffic_gap_mm = gap_mm;
        job->traffic_stop_threshold_mm =
                stop_threshold_mm;
        job->traffic_resume_threshold_mm =
                resume_threshold_mm;
        begin_stop_with_queued_zero(
                slot, now, TC2_STOP_TRAFFIC, 1,
                TC2_STOP_TRIGGER_TIMER,
                queued_zero_token);
}

/*
 * Queue every zero in one highest-priority CAN batch.  The controller still
 * serializes CS3 frames, but no turnout or positive-speed command may be
 * inserted between the first and last member of this safety transaction.
 */
static int queue_atomic_traffic_stop(
        const int *slots, int count,
        unsigned int *batch_token) {
        int trains[TC2_DISPATCH_MAX_JOBS];
        if (!slots || !batch_token || count < 1 ||
            count > TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        for (int index = 0; index < count; ++index) {
                int slot = slots[index];
                if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
                    dispatch_jobs[slot].state != TC2_JOB_RUNNING) {
                        return -1;
                }
                trains[index] = dispatch_jobs[slot].train;
        }
        int token = CAN_SEND_BUSY;
        for (int attempt = 0; attempt < 3; ++attempt) {
                token = CanTrainEmergencyStopBatch(
                        dispatch_can_tid, trains, count);
                if (token != CAN_SEND_BUSY) break;
                if (attempt + 1 < 3) Delay(1);
        }
        if (token <= 0) return -1;
        *batch_token = (unsigned int)token;
        return 0;
}

/*
 * A local authority or turnout gate belongs only to the train approaching
 * that gate.  Stopping every RUNNING job here turns a short follower window
 * into a fleet-wide deadlock: the follower stops at its own MR4 ceiling and
 * prevents the independent leader from reaching the sensor that would
 * release MR12.
 *
 * Real pairwise FOLLOWING/HEAD_ON conflicts are still collected and stopped
 * atomically by process_traffic_safety().
 */
static int begin_local_authority_stop(
        int primary_slot, int now, int peer_train,
        int gap_mm, int stop_threshold_mm) {
        if (primary_slot < 0 ||
            primary_slot >= TC2_DISPATCH_MAX_JOBS ||
            dispatch_jobs[primary_slot].state !=
                    TC2_JOB_RUNNING) return 0;
        int slots[1] = {primary_slot};
        unsigned int token = 0;
        if (queue_atomic_traffic_stop(slots, 1, &token) < 0) {
                fail_job(
                        primary_slot,
                        TC2_FAILURE_CAN_SERVICE);
                return 1;
        }
        begin_traffic_stop_with_queued_zero(
                primary_slot, now,
                TC2_TRAFFIC_AUTHORITY,
                peer_train, gap_mm,
                stop_threshold_mm, -1, token);
        return 1;
}

static int resume_traffic_hold(
        int slot, int now, int expected_reason) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (job->state != TC2_JOB_TRAFFIC_HOLD ||
            runtime->stop_purpose != TC2_STOP_TRAFFIC ||
            (expected_reason != TC2_TRAFFIC_FOLLOWING &&
             expected_reason != TC2_TRAFFIC_HEAD_ON &&
             expected_reason != TC2_TRAFFIC_AUDIT &&
             expected_reason != TC2_TRAFFIC_AUTHORITY) ||
            runtime->traffic_reason != expected_reason ||
            runtime->traffic_resume_speed < 1 ||
            runtime->traffic_resume_speed > 120 ||
            runtime->traffic_hold_distance_um < 0) {
                return -1;
        }
        track_reservation_snapshot reservation;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid,
                    &reservation) < 0) {
                return -1;
        }
        if (reservation.generation_by_train[job->train] !=
                    job->plan_generation ||
            reservation.destination_by_train[job->train] !=
                    job->target_node) {
                return -1;
        }
        if (!regular_movement_gates_ready(slot) ||
            !traffic_has_movement_authority(
                    slot, &reservation) ||
            !traffic_resume_fits_current_authority(
                    slot,
                    runtime->traffic_resume_speed)) {
                /* Normal rolling-authority/turnout wait; retry next tick. */
                return 1;
        }
        int can_health = can_health_is_safe(slot, 0, now);
        if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                return -1;
        }
        if (can_health == TC2_CAN_HEALTH_RETRY) return 1;
        int resume_command =
                command_train_positive_speed_with_retry(
                        slot, runtime->traffic_resume_speed);
        if (resume_command < 0) return -1;
        if (resume_command > 0) return 1;
        int confirmed = Time();
        if (confirmed < 0) return -1;

        runtime->command_speed =
                runtime->traffic_resume_speed;
        runtime->motion_speed_ceiling =
                runtime->traffic_resume_speed;
        runtime->motion_anchor_distance_um =
                runtime->preorigin_sensor_pending &&
                        runtime->preorigin_traffic_hold_valid ?
                runtime->preorigin_traffic_hold_distance_um :
                runtime->traffic_hold_distance_um;
        runtime->motion_anchor_tick = confirmed;
        runtime->motion_anchor_from_traffic = 1;
        runtime->preorigin_traffic_hold_distance_um = 0;
        runtime->preorigin_traffic_hold_valid = 0;
        runtime->speed_reduction_pending = 0;
        runtime->precision_approach_active = 0;
        runtime->approach_sent = 0;
        runtime->stop_purpose = TC2_STOP_NONE;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_NONE;
        runtime->settle_at_tick = -1;
        runtime->traffic_hold_since_tick = -1;
        runtime->traffic_blockers_now = 0;
        runtime->traffic_head_on_latches = 0;
        runtime->traffic_peer_train = 0;
        runtime->traffic_reason = TC2_TRAFFIC_NONE;
        runtime->traffic_resume_speed = 0;
        job->command_speed = runtime->command_speed;
        job->estimated_distance_um =
                runtime->preorigin_sensor_pending ?
                0 : runtime->motion_anchor_distance_um;
        job->traffic_hold_active = 0;
        job->traffic_reason = TC2_TRAFFIC_NONE;
        job->traffic_peer_train = 0;
        job->traffic_gap_mm = -1;
        job->traffic_stop_threshold_mm = -1;
        job->traffic_resume_threshold_mm = -1;
        job->traffic_hold_distance_um = -1;
        job->hold_active = 0;
        job->state = TC2_JOB_RUNNING;
        if (schedule_motion_deadlines(slot, confirmed) < 0) {
                fail_job(slot, TC2_FAILURE_INTERNAL);
                return -1;
        }
        return 0;
}

/*
 * A dynamic collision relation can disappear before the current physical
 * turnout has finished acquiring its exact hard ticket and settling its
 * freshly re-sent setting.  That is a normal authority wait, not a CAN
 * service failure.  Preserve the frozen position and requested resume speed,
 * discard the stale peer latch, and let process_conflict_zones() prepare the
 * train only after conflict_zone_step_ready() proves the exact current hard
 * step SETTLED/OCCUPIED.  Positive speed is deliberately deferred to the
 * PREPARING/READY launch path so the complete pairwise traffic pass runs
 * after the final turnout/authority state is known.  This transition is
 * generic: it is shared by authority, HEAD_ON recovery/removal, and
 * following-hysteresis release.
 */
static int defer_traffic_resume_for_conflict_zone(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state != TC2_JOB_TRAFFIC_HOLD ||
            runtime->stop_purpose != TC2_STOP_TRAFFIC ||
            runtime->traffic_resume_speed < 1 ||
            runtime->traffic_resume_speed > 120 ||
            runtime->traffic_hold_distance_um < 0) {
                return 0;
        }
        if (runtime->traffic_blockers_now != 0 ||
            runtime->traffic_head_on_latches != 0) {
                return 1;
        }

        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            TrainSensorGetLatest(dispatch_sensor_tid, &sensors) < 0 ||
            reservation.generation_by_train[job->train] !=
                    job->plan_generation ||
            reservation.destination_by_train[job->train] !=
                    job->target_node ||
            sensor_health_is_safe(slot, &sensors, 0, now) < 0) {
                return -1;
        }
        int can_health = can_health_is_safe(slot, 0, now);
        if (can_health == TC2_CAN_HEALTH_HARD_FAIL) return -1;
        if (can_health == TC2_CAN_HEALTH_RETRY) return 1;

        if (!traffic_has_movement_authority(slot, &reservation) ||
            !traffic_resume_fits_current_authority(
                    slot, runtime->traffic_resume_speed)) {
                /* Reacquire a bounded physical window before any turnout. */
                runtime->traffic_reason = TC2_TRAFFIC_AUTHORITY;
                runtime->traffic_peer_train = 0;
                runtime->conflict_zone_hold_active = 0;
                job->traffic_reason = TC2_TRAFFIC_AUTHORITY;
                job->traffic_peer_train = 0;
                job->traffic_gap_mm = -1;
                job->traffic_stop_threshold_mm = -1;
                job->traffic_resume_threshold_mm = -1;
                if (runtime->authority_request_tick < 0 &&
                    begin_authority_request(slot, now, 0) < 0) {
                        return -1;
                }
                return 1;
        }

        /*
         * The peer/spacing condition is gone and the existing reservation is
         * sufficient.  Leave HOLD before requesting or commanding the exact
         * current hard zone.  Even when that zone is already SETTLED, use
         * PREPARING so process_traffic_safety() gets one complete pass over
         * the final current/next/nextnext state before any positive-speed
         * launch.  PREPARING then reacquires FIFO ownership when necessary,
         * verifies next, establishes bounded nextnext, and joins the ordinary
         * atomic launch path; a stopped HOLD train itself never moves iron.
         */
        runtime->authority_resume_pending = 1;
        runtime->prelaunch_traffic_blocked = 0;
        runtime->conflict_zone_hold_active = 0;
        runtime->planned_launch_speed = runtime->traffic_resume_speed;
        runtime->authority_previous_end_offset =
                runtime->authority_end_offset;
        runtime->ready_wave_tick = -1;
        runtime->prepare_attributed_sequence = sensors.attributed_count;
        runtime->prepare_attribution_unavailable_count =
                sensors.attribution_unavailable_count;
        runtime->prepare_unattributed_count = sensors.unattributed_count;
        for (int sensor_index = 0;
             sensor_index < TRAIN_SENSOR_COUNT; ++sensor_index) {
                runtime->prepare_sensor_state[sensor_index] =
                        sensors.sensor_state[sensor_index];
        }
        clear_authority_request(runtime);
        job->conflict_train = 0;
        job->conflict_node = -1;
        job->ready_at_tick = -1;
        /*
         * Do not resurrect the old whole-window turnout program here.  The
         * progressive conflict-zone FSM first verifies/acquires next and then
         * prepares only the compatible nextnext actuator.  This also ensures a
         * canceled peer cannot leave this recovery waiting on a stale CS3
         * batch token.
         */
        if (restart_conflict_zone_work_from_frozen_position(slot) < 0) {
                return -1;
        }
        job->state = TC2_JOB_PREPARING;
        return 1;
}

/*
 * Recover only from a settled destination stop whose latest confirmed real
 * detector is still before another detector on the way to the destination.
 * Route order encodes direction; select the first detector ahead of that real
 * anchor and never one beyond the destination.  A pre-stop time projection is
 * not localization evidence and must not skip an unobserved detector.
 * A missing rolling window is reacquired through the ordinary FIFO authority
 * FSM while speed remains zero; any unverified turnout is reacquired and
 * settled through PREPARING.  An intermediate real detector only reanchors
 * the same correction and advances its sensor cursor; it never terminates the
 * correction by itself.  Speed 40 is the final positioning command, and its
 * physical stopping distance is deliberately treated as negligible: zero is
 * sent at the actual lowercase-d coordinate (or its coincident destination
 * detector), never one calibrated coast distance early.
 */
static int destination_correction_stop_allowance_mm(
        int slot, int correction_sensor_offset) {
        (void)slot;
        (void)correction_sensor_offset;
        return 0;
}

static int destination_correction_sensor_offset(
        int slot, int64_t correction_start_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            correction_start_um < 0) {
                return -1;
        }
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            job->current_route_offset < 0 ||
            job->destination_route_offset <
                    job->current_route_offset ||
            job->destination_route_offset >= runtime->route.node_count ||
            job->destination_distance_mm < 0) {
                return -1;
        }

        /*
         * Route order already encodes the train's direction.  The nearest
         * usable correction detector is therefore the first real sensor
         * after the latest confirmed route offset, never the numerically
         * nearest graph node and never a sensor beyond the destination.  The
         * monotonic clock estimate controls only the bounded travel duration;
         * it is not evidence that an unobserved detector was passed.
         */
        for (int offset = job->current_route_offset + 1;
             offset <= job->destination_route_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return -1;
                if (dispatch_track[node].type != NODE_SENSOR) continue;
                int distance = -1;
                if (Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            offset, &distance) < 0) {
                        return -1;
                }
                /* A sensor beyond the user endpoint is never a correction. */
                if (distance > job->destination_distance_mm) continue;
                return offset;
        }
        return -1;
}

/*
 * A settled destination stop may discover that its final bounded correction
 * is outside the currently owned rolling window.  Do not put that train in
 * PREPARING with no authority request: PREPARING can reacquire turnout groups,
 * but only the ordinary AUTHORITY hold FSM can extend the physical route
 * reservation.  Preserve the explicit correction marker while that FIFO CAS
 * runs; after acquisition, process_preparing_jobs() revalidates next,
 * nextnext, sensor health and pairwise safety before issuing speed 40.
 */
static int defer_destination_correction_for_authority(
        int slot, int now, int correction_sensor,
        int64_t frozen_distance_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0 ||
            correction_sensor < -1 || frozen_distance_um < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int settled_destination_stop =
                job->state == TC2_JOB_BRAKING &&
                runtime->stop_purpose == TC2_STOP_DESTINATION &&
                runtime->settle_at_tick >= 0 &&
                tick_reached(now, runtime->settle_at_tick);
        int staged_correction =
                job->state == TC2_JOB_PREPARING &&
                runtime->destination_correction_pending;
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        if ((!settled_destination_stop && !staged_correction) ||
            !runtime->movement_plan_active || !runtime->route_valid ||
            !runtime->rolling_authority_active ||
            runtime->destination_correction_active ||
            runtime->command_speed != 0 || job->command_speed != 0 ||
            job->destination_distance_mm < 0 ||
            frozen_distance_um > destination_um) {
                return 0;
        }

        runtime->destination_correction_pending = 1;
        runtime->destination_correction_sensor_offset = correction_sensor;
        runtime->destination_correction_deadline_tick = -1;
        runtime->destination_correction_reached_endpoint = 0;
        runtime->traffic_hold_distance_um = frozen_distance_um;
        runtime->preorigin_traffic_hold_distance_um = 0;
        runtime->preorigin_traffic_hold_valid = 0;
        runtime->motion_anchor_distance_um = frozen_distance_um;
        runtime->motion_anchor_tick = now;
        runtime->motion_anchor_from_traffic = 1;
        runtime->traffic_resume_speed =
                TC2_DESTINATION_CORRECTION_SPEED;
        runtime->traffic_peer_train = 0;
        runtime->traffic_reason = TC2_TRAFFIC_AUTHORITY;
        runtime->traffic_hold_since_tick = now;
        runtime->stop_purpose = TC2_STOP_TRAFFIC;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_TRAFFIC;
        runtime->settle_at_tick = -1;
        runtime->planned_launch_speed =
                TC2_DESTINATION_CORRECTION_SPEED;
        runtime->authority_resume_pending = 0;
        runtime->prelaunch_traffic_blocked = 1;
        runtime->conflict_zone_hold_active = 0;
        runtime->ready_wave_tick = -1;
        runtime->command_speed = 0;
        runtime->motion_speed_ceiling = 0;
        clear_authority_request(runtime);

        job->command_speed = 0;
        job->estimated_distance_um = frozen_distance_um;
        job->remaining_distance_mm =
                frozen_distance_um < destination_um ?
                (int)(((destination_um - frozen_distance_um) + 999) /
                      1000) : 0;
        job->traffic_hold_active = 1;
        job->traffic_reason = TC2_TRAFFIC_AUTHORITY;
        job->traffic_peer_train = 0;
        job->traffic_gap_mm = -1;
        job->traffic_stop_threshold_mm = -1;
        job->traffic_resume_threshold_mm = -1;
        job->traffic_hold_distance_um = frozen_distance_um;
        job->conflict_train = 0;
        job->conflict_node = -1;
        job->ready_at_tick = -1;
        job->braking_at_tick = -1;
        job->hold_active = 1;
        job->state = TC2_JOB_TRAFFIC_HOLD;
        return begin_authority_request(slot, now, 0) < 0 ? -1 : 1;
}

/*
 * A destination correction is not an ordinary low-speed authority resume.
 * The train has already completed and settled its requested-speed stop; this
 * transition only re-arms its existing immutable route so the central
 * conflict-zone arbiter can reacquire and revalidate next plus nextnext.  No
 * positive command is sent here.  The correction helper is retried from
 * PREPARING only after the complete movement predicate is true again.
 */
static int stage_bounded_destination_correction(
        int slot, int correction_sensor) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            correction_sensor < -1) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        train_sensor_snapshot_t sensors;
        if (runtime->destination_correction_pending ||
            runtime->destination_correction_active ||
            runtime->command_speed != 0 ||
            job->command_speed != 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0 ||
            restart_conflict_zone_work_from_frozen_position(slot) < 0) {
                return -1;
        }

        runtime->destination_correction_pending = 1;
        runtime->destination_correction_sensor_offset =
                correction_sensor;
        runtime->destination_correction_deadline_tick = -1;
        runtime->destination_correction_reached_endpoint = 0;
        runtime->planned_launch_speed =
                TC2_DESTINATION_CORRECTION_SPEED;
        runtime->authority_resume_pending = 0;
        runtime->prelaunch_traffic_blocked = 1;
        runtime->ready_wave_tick = -1;
        runtime->prepare_attributed_sequence =
                sensors.attributed_count;
        runtime->prepare_attribution_unavailable_count =
                sensors.attribution_unavailable_count;
        runtime->prepare_unattributed_count =
                sensors.unattributed_count;
        for (int sensor_index = 0;
             sensor_index < TRAIN_SENSOR_COUNT; ++sensor_index) {
                runtime->prepare_sensor_state[sensor_index] =
                        sensors.sensor_state[sensor_index];
        }
        clear_authority_request(runtime);
        job->conflict_train = 0;
        job->conflict_node = -1;
        job->ready_at_tick = -1;
        job->braking_at_tick = -1;
        job->hold_active = 0;
        job->state = TC2_JOB_PREPARING;
        return 1;
}

static int begin_bounded_destination_correction(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int pending_resume =
                runtime->destination_correction_pending &&
                job->state == TC2_JOB_PREPARING;
        int settled_destination_stop =
                !runtime->destination_correction_pending &&
                job->state == TC2_JOB_BRAKING &&
                runtime->stop_purpose == TC2_STOP_DESTINATION &&
                runtime->settle_at_tick >= 0 &&
                tick_reached(now, runtime->settle_at_tick) &&
                runtime->command_speed == 0 &&
                job->command_speed == 0;
        if (runtime->destination_correction_active ||
            runtime->destination_correction_attempted ||
            runtime->localization_only || runtime->target_seen ||
            (!pending_resume && !settled_destination_stop) ||
            !runtime->route_valid ||
            runtime->monitor.confirmed_offset < 0 ||
            runtime->monitor.confirmed_offset !=
                    job->current_route_offset ||
            job->current_route_offset < 0 ||
            job->current_route_offset >= runtime->route.node_count ||
            job->current_node != runtime->route.nodes[
                    job->current_route_offset] ||
            job->current_node < 0 || job->current_node >= TRACK_MAX ||
            dispatch_track[job->current_node].type != NODE_SENSOR) {
                return 0;
        }
        int current_distance = -1;
        if (Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    job->current_route_offset, &current_distance) < 0) {
                return 0;
        }
        int64_t correction_start_um =
                (int64_t)current_distance * 1000;
        int64_t confirmed_um =
                job->confirmed_distance_mm >= 0 ?
                (int64_t)job->confirmed_distance_mm * 1000 : 0;
        if (correction_start_um < confirmed_um) {
                correction_start_um = confirmed_um;
        }
        /*
         * A time projection is not position evidence.  Every correction
         * segment starts at the latest confirmed real detector, even when the
         * pre-stop estimate claims that the train is farther ahead.  Otherwise
         * an optimistic estimate can skip the first unobserved detector and
         * permanently strand a physically short train.
         */
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        if (correction_start_um > destination_um) {
                correction_start_um = destination_um;
        }

        int correction_sensor =
                destination_correction_sensor_offset(
                        slot, correction_start_um);
        if (correction_sensor >= runtime->route.node_count ||
            (correction_sensor >= 0 &&
             correction_sensor <= job->current_route_offset)) {
                return 0;
        }

        /*
         * The final correction is bounded by the actual lowercase-d scalar
         * coordinate, not by the next detector.  A detector on the remaining
         * suffix is a real localization anchor: observing it rebases the same
         * uninterrupted speed-40 interval, while a missed detector does not
         * by itself manufacture an early destination stop.  Turnout and
         * conflict gates remain progressive and are audited every scheduler
         * tick, so this does not grant motion across an unverified boundary.
         */
        int coast_mm = destination_correction_stop_allowance_mm(
                slot, correction_sensor);
        int64_t remaining_um =
                destination_um - correction_start_um;
        if (coast_mm < 0 ||
            remaining_um <= (int64_t)coast_mm * 1000 ||
            remaining_um > (int64_t)0x7fffffff * 1000) {
                return 0;
        }
        int command_travel_mm =
                (int)((remaining_um -
                       (int64_t)coast_mm * 1000 + 999) / 1000);
        int correction_end_offset =
                job->destination_route_offset;
        /*
         * Speed 40 has zero configured command-to-rest allowance.  Its slow
         * provisional travel bound therefore represents the actual d point;
         * intermediate detector deadlines no longer split the correction
         * into stop/relaunch fragments.
         */
        int travel_ticks = Tc2MotionProvisionalSlowTravelTicks(
                TC2_DESTINATION_CORRECTION_SPEED,
                command_travel_mm);
        if (travel_ticks < 1) return 0;

        track_reservation_snapshot reservation;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0) {
                return -1;
        }
        if (reservation.generation_by_train[job->train] !=
                    job->plan_generation) {
                return -1;
        }
        if (runtime->rolling_authority_active &&
            runtime->authority_end_offset <
                    correction_end_offset) {
                return defer_destination_correction_for_authority(
                        slot, now, correction_sensor,
                        correction_start_um);
        }
        for (int offset = job->current_route_offset;
             offset <= correction_end_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return -1;
                int reverse = physical_reverse_index(node);
                if (reverse >= TRACK_MAX) return -1;
                if (reservation.owner_by_node[(unsigned int)node] !=
                            job->train ||
                    (reverse >= 0 &&
                     reservation.owner_by_node[(unsigned int)reverse] !=
                            job->train)) {
                        /*
                         * The rolling metadata above says this complete
                         * correction interval is already owned.  A missing
                         * physical node cannot be repaired by repeatedly
                         * waiting in PREPARING; it is a reservation invariant
                         * failure and positive correction motion is forbidden.
                         */
                        return -1;
                }
        }

        /*
         * Only current next/nextnext must be ready before this launch.  Later
         * groups remain progressive: sensor/progress advancement prepares
         * them and enforce_conflict_zone_gate() commands zero before their
         * boundary if ownership, direction or settle confirmation is absent.
         * Requiring every later group here would recreate whole-route turnout
         * preparation and deadlock a harmless final correction.
         */
        int correction_needs_preparation =
                !regular_movement_gates_ready(slot);

        if (correction_needs_preparation) {
                if (pending_resume) return 0;
                return stage_bounded_destination_correction(
                        slot, correction_sensor);
        }

        /* Positive correction now runs to d; sensors only re-anchor it. */
        int correction_command =
                command_train_positive_speed_with_retry(
                        slot, TC2_DESTINATION_CORRECTION_SPEED);
        if (correction_command < 0) return -1;
        if (correction_command > 0) {
                return 0;
        }

        runtime->destination_correction_active = 1;
        runtime->destination_correction_pending = 0;
        runtime->destination_correction_attempted = 1;
        runtime->destination_correction_reached_endpoint = 0;
        runtime->destination_correction_deadline_tick =
                tick_after(now, travel_ticks);
        runtime->destination_correction_sensor_offset =
                correction_sensor;
        runtime->stop_purpose = TC2_STOP_NONE;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_NONE;
        runtime->settle_at_tick = -1;
        runtime->traffic_hold_since_tick = -1;
        runtime->traffic_hold_distance_um = -1;
        runtime->traffic_peer_train = 0;
        runtime->traffic_reason = TC2_TRAFFIC_NONE;
        runtime->traffic_resume_speed = 0;
        runtime->conflict_zone_hold_active = 0;
        clear_authority_request(runtime);
        runtime->authority_resume_pending = 0;
        runtime->prelaunch_traffic_blocked = 0;
        runtime->authority_previous_end_offset = -1;
        runtime->command_speed = TC2_DESTINATION_CORRECTION_SPEED;
        runtime->motion_speed_ceiling =
                TC2_DESTINATION_CORRECTION_SPEED;
        runtime->motion_anchor_distance_um =
                correction_start_um;
        runtime->motion_anchor_tick = now;
        runtime->motion_anchor_from_traffic = 0;
        job->command_speed = TC2_DESTINATION_CORRECTION_SPEED;
        /*
         * This positive command starts a new, real-sensor-anchored motion
         * interval.  Do not let the optimistic estimate which caused the
         * preceding early stop immediately push this correction past its
         * nearest-detector boundary.
         */
        job->estimated_distance_um = correction_start_um;
        job->braking_at_tick =
                runtime->destination_correction_deadline_tick;
        job->prediction_velocity_um_per_tick =
                Tc2MotionProvisionalVelocityUmPerTick(
                        TC2_DESTINATION_CORRECTION_SPEED);
        job->prediction_anchor_tick = now;
        job->prediction_anchor_distance_mm =
                (int)((correction_start_um + 999) / 1000);
        job->prediction_command_at_tick = job->braking_at_tick;
        job->prediction_timing_valid = 1;
        job->watchdog_at_tick = -1;
        job->hold_active = 0;
        job->traffic_hold_active = 0;
        job->traffic_reason = TC2_TRAFFIC_NONE;
        job->traffic_peer_train = 0;
        job->traffic_gap_mm = -1;
        job->traffic_stop_threshold_mm = -1;
        job->traffic_resume_threshold_mm = -1;
        job->traffic_hold_distance_um = -1;
        job->state = TC2_JOB_RUNNING;
        return 1;
}

static int bounded_virtual_endpoint_remaining_um(
        int slot, int64_t *start_um, int64_t *remaining_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !start_um || !remaining_um) {
                return -1;
        }
        const tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            job->target_route_offset < 0 ||
            job->target_route_offset >= runtime->route.node_count ||
            job->destination_distance_mm < 0) {
                return -1;
        }
        int target_distance = -1;
        if (Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    job->target_route_offset, &target_distance) < 0) {
                return -1;
        }
        int64_t destination_um =
                (int64_t)job->destination_distance_mm * 1000;
        int64_t correction_start_um =
                (int64_t)target_distance * 1000;
        if (job->confirmed_distance_mm >= 0 &&
            correction_start_um <
                    (int64_t)job->confirmed_distance_mm * 1000) {
                correction_start_um =
                        (int64_t)job->confirmed_distance_mm * 1000;
        }
        if (job->estimated_distance_um >= 0 &&
            correction_start_um < job->estimated_distance_um) {
                correction_start_um = job->estimated_distance_um;
        }
        if (correction_start_um > destination_um) {
                correction_start_um = destination_um;
        }
        *start_um = correction_start_um;
        *remaining_um = destination_um - correction_start_um;
        return 0;
}

/*
 * A normal requested-speed stop, or a sensor-bounded recovery stop, may leave
 * only the calibrated virtual endpoint tail unfinished.  This helper never
 * turns an arbitrary speed-40 command into a correction: it runs solely from
 * a settled destination stop carrying the explicit correction marker, and
 * only for the still-uncovered scalar remainder inside the already verified
 * reservation/turnout interval.
 */
static int begin_bounded_virtual_endpoint_approach(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int pending_resume =
                runtime->destination_correction_pending &&
                runtime->destination_correction_sensor_offset < 0 &&
                job->state == TC2_JOB_PREPARING;
        int settled_destination_stop =
                !runtime->destination_correction_pending &&
                job->state == TC2_JOB_BRAKING &&
                runtime->stop_purpose == TC2_STOP_DESTINATION &&
                runtime->settle_at_tick >= 0 &&
                tick_reached(now, runtime->settle_at_tick) &&
                runtime->command_speed == 0 &&
                job->command_speed == 0;
        if (runtime->destination_correction_active ||
            !runtime->target_seen || runtime->localization_only ||
            (!pending_resume && !settled_destination_stop) ||
            job->destination_offset_mm <= 0 ||
            job->current_route_offset != job->target_route_offset ||
            job->destination_route_offset < job->target_route_offset ||
            job->destination_route_offset >= runtime->route.node_count) {
                return 0;
        }

        int64_t correction_start_um;
        int64_t remaining_um;
        if (bounded_virtual_endpoint_remaining_um(
                    slot, &correction_start_um,
                    &remaining_um) < 0) {
                return -1;
        }
        /* At correction speed, command zero at the destination itself. */
        int64_t coast_um = 0;
        if (remaining_um <= 0) {
                return 0;
        }
        int64_t command_travel_um = remaining_um - coast_um;
        if (command_travel_um > (int64_t)0x7fffffff * 1000) {
                return -1;
        }
        int command_travel_mm =
                (int)((command_travel_um + 999) / 1000);
        int travel_ticks = Tc2MotionProvisionalFastTravelTicks(
                TC2_DESTINATION_CORRECTION_SPEED,
                command_travel_mm);
        if (travel_ticks < 1) return 0;

        track_reservation_snapshot reservation;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            reservation.generation_by_train[job->train] !=
                    job->plan_generation) {
                return -1;
        }
        if (runtime->rolling_authority_active &&
            runtime->authority_end_offset <
                    job->destination_route_offset) {
                return defer_destination_correction_for_authority(
                        slot, now, -1, correction_start_um);
        }
        for (int offset = job->target_route_offset;
             offset <= job->destination_route_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return -1;
                int reverse = physical_reverse_index(node);
                if (reverse >= TRACK_MAX) return -1;
                if (reservation.owner_by_node[(unsigned int)node] !=
                            job->train ||
                    (reverse >= 0 &&
                     reservation.owner_by_node[(unsigned int)reverse] !=
                            job->train)) {
                        /* Metadata says this suffix is owned; a missing
                         * physical node is an invariant failure, not a
                         * PREPARING condition which can heal itself. */
                        return -1;
                }
        }
        int correction_needs_preparation =
                !regular_movement_gates_ready(slot);
        if (correction_needs_preparation && !pending_resume) {
                return stage_bounded_destination_correction(slot, -1);
        }
        for (int stage_step = runtime->conflict_zone_next_step;
             runtime->conflict_zone_plan_valid && stage_step >= 0 &&
             stage_step < runtime->conflict_zone_plan.step_count;) {
                const tc2_conflict_zone_route_stage *stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan,
                                stage_step);
                if (!stage || stage->member_step[0] != stage_step) {
                        return -1;
                }
                if (stage->first_route_offset >
                            job->destination_route_offset) {
                        break;
                }
                if (stage->last_route_offset <=
                            job->target_route_offset) {
                        stage_step = conflict_zone_next_stage_first_step(
                                &runtime->conflict_zone_plan,
                                stage_step);
                        if (stage_step < 0) return -1;
                        continue;
                }
                if (stage_step != runtime->conflict_zone_next_step) {
                        return pending_resume ? 0 :
                                stage_bounded_destination_correction(
                                        slot, -1);
                }
                if (!conflict_zone_step_ready(slot, stage_step)) {
                        correction_needs_preparation = 1;
                }
                stage_step = conflict_zone_next_stage_first_step(
                        &runtime->conflict_zone_plan, stage_step);
                if (stage_step < 0) return -1;
        }
        if (correction_needs_preparation) {
                if (pending_resume) return 0;
                return stage_bounded_destination_correction(slot, -1);
        }
        int endpoint_command =
                command_train_positive_speed_with_retry(
                        slot, TC2_DESTINATION_CORRECTION_SPEED);
        if (endpoint_command < 0) return -1;
        if (endpoint_command > 0) {
                return pending_resume ? 0 :
                        stage_bounded_destination_correction(slot, -1);
        }
        runtime->destination_correction_active = 1;
        runtime->destination_correction_pending = 0;
        runtime->destination_correction_attempted = 1;
        runtime->destination_correction_reached_endpoint = 0;
        runtime->destination_correction_deadline_tick =
                tick_after(now, travel_ticks);
        runtime->stop_purpose = TC2_STOP_NONE;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_NONE;
        runtime->settle_at_tick = -1;
        runtime->traffic_hold_since_tick = -1;
        runtime->traffic_hold_distance_um = -1;
        runtime->traffic_peer_train = 0;
        runtime->traffic_reason = TC2_TRAFFIC_NONE;
        runtime->traffic_resume_speed = 0;
        runtime->conflict_zone_hold_active = 0;
        clear_authority_request(runtime);
        runtime->authority_resume_pending = 0;
        runtime->prelaunch_traffic_blocked = 0;
        runtime->authority_previous_end_offset = -1;
        runtime->command_speed = TC2_DESTINATION_CORRECTION_SPEED;
        runtime->motion_speed_ceiling =
                TC2_DESTINATION_CORRECTION_SPEED;
        runtime->motion_anchor_distance_um =
                correction_start_um;
        runtime->motion_anchor_tick = now;
        runtime->motion_anchor_from_traffic = 0;
        job->command_speed = TC2_DESTINATION_CORRECTION_SPEED;
        job->braking_at_tick =
                runtime->destination_correction_deadline_tick;
        job->prediction_velocity_um_per_tick =
                Tc2MotionProvisionalVelocityUmPerTick(
                        TC2_DESTINATION_CORRECTION_SPEED);
        job->prediction_anchor_tick = now;
        job->prediction_anchor_distance_mm =
                (int)((correction_start_um + 999) / 1000);
        job->prediction_command_at_tick = job->braking_at_tick;
        job->prediction_timing_valid = 1;
        job->watchdog_at_tick = -1;
        job->hold_active = 0;
        job->traffic_hold_active = 0;
        job->traffic_reason = TC2_TRAFFIC_NONE;
        job->traffic_peer_train = 0;
        job->traffic_gap_mm = -1;
        job->traffic_stop_threshold_mm = -1;
        job->traffic_resume_threshold_mm = -1;
        job->traffic_hold_distance_um = -1;
        job->state = TC2_JOB_RUNNING;
        return 1;
}

/*
 * Stop with the train front 20 mm before an ungranted or unsettled turnout
 * zone.  The command is issued one braking envelope earlier; after
 * ownership and settle confirmation, the ordinary resumable traffic-hold
 * path restarts it without losing destination or speed state.
 */
static int enforce_conflict_zone_gate(int slot, int now) {
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        int step_index = runtime->conflict_zone_next_step;
        if (!runtime->conflict_zone_plan_valid || step_index < 0 ||
            step_index > runtime->conflict_zone_plan.step_count) return -1;
        if (step_index == runtime->conflict_zone_plan.step_count) return 0;
        int next_ready = conflict_zone_step_ready(slot, step_index);
        int nextnext_ready = conflict_zone_lookahead_prepared(slot);
        if (next_ready && nextnext_ready) return 0;

        /*
         * nextnext control is a standing movement condition, not permission
         * to enter only that later turnout.  Losing queue-head control means
         * another train may change the future route, so command zero now and
         * retain this train's complete plan for automatic re-evaluation.
         */
        if (!nextnext_ready) {
                int braking = traffic_braking_envelope_mm(slot);
                if (braking < 0) return -1;
                runtime->conflict_zone_hold_active = 1;
                return begin_local_authority_stop(
                        slot, now, 0, 0, braking);
        }

        const tc2_conflict_zone_route_step *step =
                &runtime->conflict_zone_plan.steps[step_index];
        int braking = traffic_braking_envelope_mm(slot);
        int64_t progress_um;
        int stop_point_mm = step->entry_distance_mm -
                TC2_TRAIN_HALF_LENGTH_MM - 20;
        if (stop_point_mm < 0) stop_point_mm = 0;
        if (braking < 0 ||
            runtime_motion_progress_um(
                    slot, now, &progress_um) < 0) {
                return -1;
        }
        if (progress_um + (int64_t)braking * 1000 <
            (int64_t)stop_point_mm * 1000) {
                return 0;
        }
        runtime->conflict_zone_hold_active = 1;
        return begin_local_authority_stop(
                slot, now, 0,
                stop_point_mm > (int)(progress_um / 1000) ?
                        stop_point_mm -
                                (int)(progress_um / 1000) : 0,
                braking);
}

/*
 * While the exact current hard zone is settled, its ticket is the permission
 * to finish that `next` traversal.  A deliberately short node window ending
 * at the same zone must therefore not issue an earlier, duplicate braking
 * command.  As soon as the cursor advances, this predicate becomes false;
 * the new next zone and the rolling extension are checked normally.
 */
static int current_next_zone_covers_authority_end(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        const tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        int step_index = runtime->conflict_zone_next_step;
        if (!runtime->rolling_authority_active ||
            !runtime->conflict_zone_plan_valid ||
            step_index < 0 ||
            step_index >= runtime->conflict_zone_plan.step_count ||
            runtime->authority_end_offset < 0) {
                return 0;
        }
        const tc2_conflict_zone_route_stage *stage =
                conflict_zone_stage_for_step(
                        &runtime->conflict_zone_plan, step_index);
        if (!stage || stage->member_step[0] != step_index) return 0;
        /*
         * The confirmed hard-zone ticket authorizes traversal through the
         * complete current physical zone.  Therefore an authority window
         * ending exactly at the zone's final route node is sufficient; it
         * must not demand an unrelated downstream node before launch.  The
         * next cursor/zone performs the following authorization check.
         */
        return runtime->authority_end_offset >=
                            stage->last_route_offset &&
                conflict_zone_step_ready(slot, step_index);
}

typedef struct {
        int valid;
        int relation;
        int rear_slot;
        int order_ambiguous;
        int gap_mm;
        int emergency_gap_mm;
        int scalar_a_mm;
        int scalar_b_mm;
} tc2_live_traffic_relation;

static uint16_t traffic_slot_bit(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        return (uint16_t)(1u << (unsigned int)slot);
}

static int traffic_slot_is_terminal_static(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        return dispatch_jobs[slot].state == TC2_JOB_ARRIVED ||
                dispatch_jobs[slot].state == TC2_JOB_STOPPED ||
                (dispatch_jobs[slot].state == TC2_JOB_CANCEL_BRAKING &&
                 terminal_static_footprint_committed(slot));
}

static int traffic_slot_has_position(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return 0;
        }
        int state = dispatch_jobs[slot].state;
        if (state == TC2_JOB_RUNNING ||
            state == TC2_JOB_BRAKING ||
            state == TC2_JOB_TRAFFIC_HOLD) {
                return 1;
        }
        if (state == TC2_JOB_CANCEL_BRAKING ||
            state == TC2_JOB_REVERSING) {
                return dispatch_runtime[slot].route_valid;
        }
        if (state == TC2_JOB_STOP_UNCONFIRMED ||
            state == TC2_JOB_ARRIVED ||
            state == TC2_JOB_STOPPED) {
                return dispatch_runtime[slot].route_valid &&
                        dispatch_jobs[slot].hold_active &&
                        dispatch_jobs[slot].current_node >= 0;
        }
        if (state == TC2_JOB_FAILED) {
                return dispatch_runtime[slot].route_valid &&
                        dispatch_jobs[slot].current_node >= 0 &&
                        dispatch_jobs[slot].estimated_distance_um >= 0;
        }
        if (state == TC2_JOB_WAITING ||
            state == TC2_JOB_STAGED) {
                return dispatch_runtime[slot].route_valid &&
                        dispatch_jobs[slot].current_node >= 0;
        }
        int prelaunch =
                state == TC2_JOB_PREPARING ||
                state == TC2_JOB_READY ||
                state == TC2_JOB_LAUNCHING;
        if (!prelaunch) return 0;
        if (dispatch_runtime[slot]
                            .authority_resume_pending &&
            dispatch_runtime[slot]
                            .traffic_hold_distance_um >= 0) {
                return 1;
        }
        /*
         * Every committed prelaunch plan represents a real speed-zero train:
         * fixed A--F jobs are at their known start cell, while CURRENT jobs
         * retain their last physical localization. Keep both in the emergency
         * obstacle audit while turnouts settle and the launch is confirmed.
         */
        return dispatch_runtime[slot].route_valid &&
                dispatch_jobs[slot].current_node >= 0;
}

static int route_prefix_distances(
        const track_route *route, int distances[TRACK_MAX]) {
        if (!route || !distances || route->node_count < 1 ||
            route->node_count > TRACK_MAX) {
                return -1;
        }
        distances[0] = 0;
        for (int offset = 1;
             offset < route->node_count; ++offset) {
                if (TrackRouteDistanceBetweenOffsets(
                            dispatch_track, route,
                            offset - 1, offset,
                            &distances[offset]) < 0 ||
                    distances[offset - 1] >
                            0x7fffffff -
                            distances[offset]) {
                        return -1;
                }
                distances[offset] +=
                        distances[offset - 1];
        }
        return 0;
}

typedef struct {
        int point_mm;
        int minimum_mm;
        int maximum_mm;
} tc2_traffic_position_envelope;

/*
 * The latest ordered sensor is a hard lower bound: a forward-moving train
 * cannot be assumed to have advanced merely because its commanded-speed
 * model says so.  Conversely, collision braking must assume that a rear
 * train is as far forward as the point prediction plus the calibrated
 * uncertainty envelope.
 */
static int runtime_traffic_position_envelope(
        int slot, int now,
        tc2_traffic_position_envelope *envelope) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !envelope) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        int64_t point_um;
        int authority_prelaunch =
                runtime->authority_resume_pending &&
                (job->state == TC2_JOB_PREPARING ||
                 job->state == TC2_JOB_READY ||
                 job->state == TC2_JOB_LAUNCHING);
        int current_prelaunch =
                !authority_prelaunch &&
                job->start_index ==
                        TC2_DISPATCH_START_CURRENT &&
                (job->state == TC2_JOB_PREPARING ||
                 job->state == TC2_JOB_READY ||
                 job->state == TC2_JOB_LAUNCHING ||
                 job->state == TC2_JOB_WAITING ||
                 job->state == TC2_JOB_STAGED);
        int fixed_prelaunch =
                !authority_prelaunch &&
                !current_prelaunch &&
                job->start_index >= 0 &&
                job->start_index <
                        TC2_DISPATCH_START_COUNT &&
                (job->state == TC2_JOB_PREPARING ||
                 job->state == TC2_JOB_READY ||
                 job->state == TC2_JOB_LAUNCHING ||
                 job->state == TC2_JOB_WAITING ||
                 job->state == TC2_JOB_STAGED);
        int reversal_wait =
                job->state == TC2_JOB_REVERSING;
        int stationary_hold =
                job->state == TC2_JOB_STOP_UNCONFIRMED ||
                job->state == TC2_JOB_ARRIVED ||
                job->state == TC2_JOB_STOPPED ||
                job->state == TC2_JOB_FAILED;
        int bounded_static_hold =
                runtime->static_center_bounds_valid &&
                runtime->static_center_lower_um >= 0 &&
                runtime->static_center_upper_um >=
                        runtime->static_center_lower_um &&
                runtime->static_center_upper_um <= INT64_MAX - 999 &&
                (job->state == TC2_JOB_CANCEL_BRAKING ||
                 job->state == TC2_JOB_ARRIVED ||
                 job->state == TC2_JOB_STOPPED);
        if (bounded_static_hold) {
                int64_t lower_mm =
                        runtime->static_center_lower_um / 1000;
                int64_t upper_mm =
                        (runtime->static_center_upper_um + 999) / 1000;
                if (lower_mm < 0 || upper_mm < lower_mm ||
                    upper_mm > 0x7fffffff) {
                        return -1;
                }
                /*
                 * cancel_stationary_center_bounds() already includes detector
                 * age, stopping distance and model uncertainty.  Reapplying
                 * uncertainty here fabricated an obstacle beyond the committed
                 * static reservation and could strand an unrelated branch.
                 */
                envelope->point_mm = (int)upper_mm;
                envelope->minimum_mm = (int)lower_mm;
                envelope->maximum_mm = (int)upper_mm;
                return 0;
        }
        if (stationary_hold) {
                point_um = runtime->traffic_hold_distance_um;
                if (point_um < 0) {
                        point_um = job->estimated_distance_um;
                }
                if (point_um < 0) return -1;
        } else if (authority_prelaunch) {
                point_um = runtime->traffic_hold_distance_um;
                if (point_um < 0) return -1;
        } else if (current_prelaunch || fixed_prelaunch) {
                if (runtime->monitor.confirmed_distance_mm < 0) {
                        return -1;
                }
                point_um =
                        (int64_t)runtime->monitor
                                .confirmed_distance_mm * 1000;
        } else if (reversal_wait) {
                point_um =
                        runtime->motion_anchor_distance_um;
                if (point_um < 0) return -1;
        } else {
                if (runtime_motion_progress_um(
                            slot, now, &point_um) < 0 ||
                    point_um < 0) {
                        return -1;
                }
        }
        /*
         * A confirmed detector is real forward progress, not merely an
         * uncertainty bound.  If calibration prediction is momentarily
         * behind it, advance the point estimate to that detector instead of
         * producing an impossible minimum > point envelope and failing both
         * trains closed as a fabricated head-on event.
         */
        if (runtime->monitor.confirmed_distance_mm >= 0 &&
            point_um <
                    (int64_t)runtime->monitor
                            .confirmed_distance_mm * 1000) {
                point_um =
                        (int64_t)runtime->monitor
                                .confirmed_distance_mm * 1000;
        }
        int speed = runtime->command_speed;
        if (runtime->motion_speed_ceiling > speed) {
                speed = runtime->motion_speed_ceiling;
        }
        if (runtime->stop_purpose == TC2_STOP_TRAFFIC &&
            runtime->traffic_resume_speed > speed) {
                speed = runtime->traffic_resume_speed;
        }
        if (speed <= 0) speed = job->speed;
        int uncertainty = Tc2MotionUncertaintyMm(speed);
        if (uncertainty < 0 ||
            point_um >
                    INT64_MAX -
                    (int64_t)uncertainty * 1000) {
                return -1;
        }
        int64_t maximum_motion_um = point_um;
        if ((authority_prelaunch || current_prelaunch ||
             fixed_prelaunch) &&
            job->state == TC2_JOB_LAUNCHING) {
                int launch_speed =
                        runtime->planned_launch_speed > 0 ?
                        runtime->planned_launch_speed :
                        runtime->traffic_resume_speed;
                int velocity =
                        Tc2MotionProvisionalVelocityUmPerTick(
                                launch_speed);
                int age = motion_tick_age(
                        now, runtime->launch_wave_tick);
                if (velocity < 1 || age < 0 ||
                    maximum_motion_um >
                            INT64_MAX -
                            (int64_t)age * velocity) {
                        return -1;
                }
                maximum_motion_um +=
                        (int64_t)age * velocity;
                int64_t destination_um =
                        (int64_t)job
                                ->destination_distance_mm * 1000;
                if (destination_um >= 0 &&
                    maximum_motion_um > destination_um) {
                        maximum_motion_um = destination_um;
                }
        }
        if (maximum_motion_um >
                    INT64_MAX -
                    (int64_t)uncertainty * 1000) {
                return -1;
        }
        int64_t maximum_um =
                maximum_motion_um +
                (int64_t)uncertainty * 1000;
        int64_t maximum_mm =
                (maximum_um + 999) / 1000;
        int minimum_mm =
                (int)(point_um / 1000) - uncertainty;
        if (minimum_mm < 0) minimum_mm = 0;
        if (!stationary_hold &&
            runtime->monitor.confirmed_distance_mm > minimum_mm) {
                minimum_mm =
                        runtime->monitor.confirmed_distance_mm;
        }
        if (minimum_mm < 0 ||
            minimum_mm > point_um / 1000 ||
            point_um / 1000 > 0x7fffffff ||
            maximum_mm > 0x7fffffff) {
                return -1;
        }
        envelope->point_mm =
                (int)(point_um / 1000);
        envelope->minimum_mm = minimum_mm;
        envelope->maximum_mm = (int)maximum_mm;
        return 0;
}

static int traffic_occupancy_overlaps_interval(
        int minimum_mm, int maximum_mm,
        int first_mm, int last_mm) {
        if (minimum_mm < 0 || maximum_mm < minimum_mm ||
            first_mm < 0 || last_mm < first_mm) {
                return 0;
        }
        int half_body = (TC2_TRAIN_BODY_MM + 1) / 2;
        int64_t occupied_first =
                (int64_t)minimum_mm - half_body;
        int64_t occupied_last =
                (int64_t)maximum_mm + half_body;
        return occupied_last >= first_mm &&
                occupied_first <= last_mm;
}

static int traffic_interval_separation_mm(
        int64_t first_minimum, int64_t first_maximum,
        int64_t second_minimum, int64_t second_maximum) {
        if (first_minimum > first_maximum ||
            second_minimum > second_maximum) {
                return -1;
        }
        int64_t separation = 0;
        if (first_maximum < second_minimum) {
                separation =
                        second_minimum - first_maximum;
        } else if (second_maximum < first_minimum) {
                separation =
                        first_minimum - second_maximum;
        }
        return separation > 0x7fffffff ?
                0x7fffffff : (int)separation;
}

static int clearance_gap_mm(int64_t center_gap_mm) {
        if (center_gap_mm <= TC2_TRAIN_BODY_MM) return 0;
        center_gap_mm -= TC2_TRAIN_BODY_MM;
        return center_gap_mm > 0x7fffffff ?
                0x7fffffff : (int)center_gap_mm;
}

/*
 * Identify an already occupied common directed corridor first.  Sensors and
 * the bounded motion envelope localize each body; the immutable route's
 * directed edges supply orientation.  Future turnout intent is deliberately
 * absent here: next/nextnext queue ownership is the normal route scheduler,
 * while this function is the emergency audit of real body occupancy.
 * Opposite edge u->v is canonically reverse(v)->reverse(u), so head-on
 * matching walks the second route in the opposite offset direction.
 */
static int live_traffic_relation_for_pair(
        int slot_a, int slot_b, int now,
        tc2_live_traffic_relation *relation) {
        if (!relation || slot_a < 0 ||
            slot_a >= TC2_DISPATCH_MAX_JOBS ||
            slot_b < 0 ||
            slot_b >= TC2_DISPATCH_MAX_JOBS ||
            slot_a == slot_b) {
                return -1;
        }
        relation->valid = 0;
        relation->relation =
                TC2_TRAFFIC_RELATION_HEAD_ON;
        relation->rear_slot = -1;
        relation->order_ambiguous = 0;
        relation->gap_mm = 0x7fffffff;
        relation->emergency_gap_mm = 0x7fffffff;
        relation->scalar_a_mm = -1;
        relation->scalar_b_mm = -1;

        tc2_dispatch_runtime *runtime_a =
                &dispatch_runtime[slot_a];
        tc2_dispatch_runtime *runtime_b =
                &dispatch_runtime[slot_b];
        if (!traffic_slot_has_position(slot_a) ||
            !traffic_slot_has_position(slot_b)) {
                return 0;
        }
        if (!runtime_a->route_valid ||
            !runtime_b->route_valid) {
                return -1;
        }
        tc2_traffic_position_envelope position_a;
        tc2_traffic_position_envelope position_b;
        if (runtime_traffic_position_envelope(
                    slot_a, now, &position_a) < 0 ||
            runtime_traffic_position_envelope(
                    slot_b, now, &position_b) < 0) {
                return -1;
        }
        int distance_a[TRACK_MAX];
        int distance_b[TRACK_MAX];
        if (route_prefix_distances(
                    &runtime_a->route, distance_a) < 0 ||
            route_prefix_distances(
                    &runtime_b->route, distance_b) < 0 ||
            runtime_a->leg_start_offset < 0 ||
            runtime_a->leg_end_offset <
                    runtime_a->leg_start_offset ||
            runtime_a->leg_end_offset >=
                    runtime_a->route.node_count ||
            runtime_b->leg_start_offset < 0 ||
            runtime_b->leg_end_offset <
                    runtime_b->leg_start_offset ||
            runtime_b->leg_end_offset >=
                    runtime_b->route.node_count) {
                return -1;
        }
        relation->scalar_a_mm = position_a.point_mm;
        relation->scalar_b_mm = position_b.point_mm;

        int best_same_gap = 0x7fffffff;
        int best_same_emergency_gap = 0x7fffffff;
        int best_same_rear = -1;
        for (int first_a = runtime_a->leg_start_offset;
             first_a < runtime_a->leg_end_offset;
             ++first_a) {
                for (int first_b =
                             runtime_b->leg_start_offset;
                     first_b < runtime_b->leg_end_offset;
                     ++first_b) {
                        if (runtime_a->route
                                            .nodes[first_a] !=
                                    runtime_b->route
                                            .nodes[first_b] ||
                            runtime_a->route
                                            .nodes[first_a + 1] !=
                                    runtime_b->route
                                            .nodes[first_b + 1]) {
                                continue;
                        }
                        if (first_a >
                                    runtime_a
                                            ->leg_start_offset &&
                            first_b >
                                    runtime_b
                                            ->leg_start_offset &&
                            runtime_a->route
                                            .nodes[first_a - 1] ==
                                    runtime_b->route
                                            .nodes[first_b - 1]) {
                                continue;
                        }
                        int last_a = first_a + 1;
                        int last_b = first_b + 1;
                        while (last_a <
                                           runtime_a
                                                   ->leg_end_offset &&
                               last_b <
                                           runtime_b
                                                   ->leg_end_offset &&
                               runtime_a->route
                                               .nodes[last_a + 1] ==
                                       runtime_b->route
                                               .nodes[last_b + 1]) {
                                ++last_a;
                                ++last_b;
                        }
                        if (!traffic_occupancy_overlaps_interval(
                                    position_a.minimum_mm,
                                    position_a.maximum_mm,
                                    distance_a[first_a],
                                    distance_a[last_a]) ||
                            !traffic_occupancy_overlaps_interval(
                                    position_b.minimum_mm,
                                    position_b.maximum_mm,
                                    distance_b[first_b],
                                    distance_b[last_b])) {
                                continue;
                        }
                        int64_t mapped_b_minimum =
                                (int64_t)distance_a[first_a] +
                                position_b.minimum_mm -
                                distance_b[first_b];
                        int64_t mapped_b_maximum =
                                (int64_t)distance_a[first_a] +
                                position_b.maximum_mm -
                                distance_b[first_b];
                        int64_t mapped_b_point =
                                (int64_t)distance_a[first_a] +
                                position_b.point_mm -
                                distance_b[first_b];
                        int64_t point_center_gap =
                                (int64_t)position_a.point_mm -
                                mapped_b_point;
                        if (point_center_gap < 0) {
                                point_center_gap =
                                        -point_center_gap;
                        }
                        int point_clearance =
                                clearance_gap_mm(
                                        point_center_gap);
                        int rear;
                        int64_t center_gap;
                        if (position_a.maximum_mm <
                            mapped_b_minimum) {
                                rear = slot_a;
                                center_gap =
                                        mapped_b_minimum -
                                        position_a.maximum_mm;
                        } else if (mapped_b_maximum <
                                   position_a.minimum_mm) {
                                rear = slot_b;
                                center_gap =
                                        position_a.minimum_mm -
                                        mapped_b_maximum;
                        } else {
                                /*
                                 * Overlapping localization envelopes do not
                                 * reverse a route's direction.  Use the two
                                 * point estimates on this exact common
                                 * directed corridor to choose the rear, then
                                 * apply a zero conservative gap.  Converting
                                 * this case to HEAD_ON permanently latched the
                                 * A->d1/B->d3 merge even though both routes
                                 * traverse MR12 in the same direction.
                                 */
                                rear = position_a.point_mm <=
                                                       mapped_b_point ?
                                        slot_a : slot_b;
                                center_gap = 0;
                        }
                        int gap = clearance_gap_mm(center_gap);
                        if (gap < best_same_gap) {
                                best_same_gap = gap;
                                best_same_emergency_gap =
                                        point_clearance;
                                best_same_rear = rear;
                        }
                }
        }

        int best_head_gap = 0x7fffffff;
        int best_head_emergency_gap = 0x7fffffff;
        for (int edge_a = runtime_a->leg_start_offset;
             edge_a < runtime_a->leg_end_offset;
             ++edge_a) {
                int node_a =
                        runtime_a->route.nodes[edge_a];
                int next_a =
                        runtime_a->route.nodes[edge_a + 1];
                int reverse_node_a =
                        physical_reverse_index(node_a);
                int reverse_next_a =
                        physical_reverse_index(next_a);
                if (reverse_node_a < 0 ||
                    reverse_next_a < 0) {
                        continue;
                }
                for (int edge_b =
                             runtime_b->leg_start_offset;
                     edge_b < runtime_b->leg_end_offset;
                     ++edge_b) {
                        if (runtime_b->route
                                            .nodes[edge_b] !=
                                    reverse_next_a ||
                            runtime_b->route
                                            .nodes[edge_b + 1] !=
                                    reverse_node_a) {
                                continue;
                        }
                        int first_a = edge_a;
                        int last_a = edge_a + 1;
                        int first_b = edge_b;
                        int last_b = edge_b + 1;
                        while (first_a >
                                           runtime_a
                                                   ->leg_start_offset &&
                               last_b <
                                           runtime_b
                                                   ->leg_end_offset &&
                               physical_reverse_index(
                                       runtime_a->route
                                               .nodes[first_a - 1]) ==
                                       runtime_b->route
                                               .nodes[last_b + 1]) {
                                --first_a;
                                ++last_b;
                        }
                        while (last_a <
                                           runtime_a
                                                   ->leg_end_offset &&
                               first_b >
                                           runtime_b
                                                   ->leg_start_offset &&
                               physical_reverse_index(
                                       runtime_a->route
                                               .nodes[last_a + 1]) ==
                                       runtime_b->route
                                               .nodes[first_b - 1]) {
                                ++last_a;
                                --first_b;
                        }
                        if (!traffic_occupancy_overlaps_interval(
                                    position_a.minimum_mm,
                                    position_a.maximum_mm,
                                    distance_a[first_a],
                                    distance_a[last_a]) ||
                            !traffic_occupancy_overlaps_interval(
                                    position_b.minimum_mm,
                                    position_b.maximum_mm,
                                    distance_b[first_b],
                                    distance_b[last_b])) {
                                continue;
                        }
                        int64_t mapped_b_minimum =
                                (int64_t)distance_a[last_a] -
                                (position_b.maximum_mm -
                                 distance_b[first_b]);
                        int64_t mapped_b_maximum =
                                (int64_t)distance_a[last_a] -
                                (position_b.minimum_mm -
                                 distance_b[first_b]);
                        int64_t mapped_b_point =
                                (int64_t)distance_a[last_a] -
                                (position_b.point_mm -
                                 distance_b[first_b]);
                        int64_t point_center_gap =
                                (int64_t)position_a.point_mm -
                                mapped_b_point;
                        if (point_center_gap < 0) {
                                point_center_gap =
                                        -point_center_gap;
                        }
                        int point_clearance =
                                clearance_gap_mm(
                                        point_center_gap);
                        int separation =
                                traffic_interval_separation_mm(
                                        position_a.minimum_mm,
                                        position_a.maximum_mm,
                                        mapped_b_minimum,
                                        mapped_b_maximum);
                        if (separation < 0) return -1;
                        int gap = clearance_gap_mm(separation);
                        if (gap < best_head_gap) {
                                best_head_gap = gap;
                                best_head_emergency_gap =
                                        point_clearance;
                        }
                }
        }

        /*
         * An exact common directed corridor is the authoritative orientation
         * witness.  A complete route may revisit the same physical nodes in
         * reverse much later; allowing that remote alias to win here caused
         * two currently co-directional trains to enter permanent HEAD_ON
         * recovery.  Use an opposite match only when no occupied common
         * directed corridor exists.
         */
        if (best_same_gap != 0x7fffffff) {
                relation->valid = 1;
                relation->order_ambiguous = 0;
                relation->relation =
                        best_same_rear == slot_a ?
                                TC2_TRAFFIC_RELATION_SAME_DIRECTION_A_REAR :
                                TC2_TRAFFIC_RELATION_SAME_DIRECTION_B_REAR;
                relation->rear_slot = best_same_rear;
                relation->gap_mm = best_same_gap;
                relation->emergency_gap_mm =
                        best_same_emergency_gap;
        } else if (best_head_gap != 0x7fffffff) {
                relation->valid = 1;
                relation->relation =
                        TC2_TRAFFIC_RELATION_HEAD_ON;
                relation->rear_slot = -1;
                relation->gap_mm = best_head_gap;
                relation->emergency_gap_mm =
                        best_head_emergency_gap;
        }
        return 0;
}

/*
 * A live reservation identity permits a stopped job to ask for its next
 * bounded window.  It is intentionally weaker than movement authority:
 * requiring the future window here would make acquiring that window
 * impossible after a conflicting train is removed.
 */
static int traffic_has_reservation_identity(
        int slot,
        const track_reservation_snapshot *reservation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !reservation) {
                return 0;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        if (job->plan_generation == 0 ||
            reservation
                            ->generation_by_train[job->train] !=
                    job->plan_generation ||
            reservation
                            ->destination_by_train[job->train] !=
                    job->target_node) {
                return 0;
        }
        return 1;
}

static int traffic_has_movement_authority(
        int slot,
        const track_reservation_snapshot *reservation) {
        if (!traffic_has_reservation_identity(slot, reservation)) {
                return 0;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->rolling_authority_active) return 1;

        /*
         * A reservation generation proves only that this train still owns
         * some nodes.  Verify the complete directed slice from the latest
         * real detector through the active hard ceiling; an unconfirmed
         * nextnext hint is deliberately excluded here.
         *
         * Do not additionally require the first detector beyond that ceiling
         * to be owned already.  That creates a circular dependency at every
         * real-sensor rebase: the running train is stopped because the next
         * detector is outside the old window before the progressive prefetch
         * which would acquire that detector is allowed to run.  Movement is
         * still bounded by authority_center_ceiling_mm below: the running
         * audit stops with the complete braking envelope inside the owned
         * slice if the nextnext extension has not settled in time.  Thus an
         * outside detector cannot be reached merely because this predicate
         * accepts the currently owned slice.
         */
        int current = runtime->monitor.confirmed_offset;
        int end = runtime->authority_end_offset;
        if (!runtime->route_valid ||
            current < runtime->leg_start_offset ||
            current < 0 || current >= runtime->route.node_count ||
            end < current || end >= runtime->route.node_count ||
            job->destination_route_offset < current ||
            job->destination_route_offset >= runtime->route.node_count) {
                return 0;
        }
        int usable_end = end < job->destination_route_offset ?
                end : job->destination_route_offset;
        for (int offset = current; offset <= usable_end; ++offset) {
                int node = runtime->route.nodes[offset];
                int reverse = physical_reverse_index(node);
                if (reservation->owner_by_node[node] != job->train ||
                    (reverse >= 0 &&
                     reservation->owner_by_node[reverse] != job->train)) {
                        return 0;
                }
        }
        return 1;
}

/*
 * A route-less canceled train has no directed geometry from which a bounded
 * body footprint can be proved.  It is therefore a global conservative
 * obstacle until the operator confirms physical removal.  This state is rare
 * (cancel during STAGED/WAIT_ROUTE), but it must never become a ghost merely
 * because no reservation generation had committed yet.
 */
static int unknown_static_block_exists_except(int ignored_slot) {
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (slot == ignored_slot) continue;
                const tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                const tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state == TC2_JOB_STOP_UNCONFIRMED &&
                    runtime->lifecycle_stop_reason ==
                            TC2_LIFECYCLE_STOP_OPERATOR_CANCEL &&
                    !runtime->route_valid) {
                        return 1;
                }
        }
        return 0;
}

static int destination_area_safe(
        int slot,
        const track_reservation_snapshot *reservation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !reservation) {
                return 0;
        }
        const tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            job->target_route_offset < 0 ||
            job->destination_route_offset <
                    job->target_route_offset ||
            job->destination_route_offset >=
                    runtime->route.node_count) {
                return 0;
        }

        int target_distance_mm;
        if (route_distance_to_offset(
                    &runtime->route,
                    job->target_route_offset,
                    &target_distance_mm) < 0) {
                return 0;
        }
        /*
         * Do not reserve or gate a far destination at departure.  A partial
         * authority footprint may contain the target detector solely as the
         * first real attribution witness beyond its center-line ceiling; in
         * that case authority_end_offset reaches target_route_offset even
         * though the train is not permitted to reach the detector.  Enable
         * the terminal guard from the actual movement ceiling instead.  Once
         * that ceiling can reach the detector (or real position evidence says
         * the train is already there), ownership through the endpoint ceiling
         * remains mandatory and atomic.
         */
        int rolling_center_reaches_target =
                runtime->rolling_authority_active &&
                runtime->authority_center_ceiling_mm >=
                        target_distance_mm;
        int correction_reaches_terminal_area =
                runtime->destination_correction_active ||
                runtime->destination_correction_pending;
        int required = !runtime->rolling_authority_active ||
                rolling_center_reaches_target ||
                job->current_route_offset >=
                        job->target_route_offset ||
                runtime->target_seen ||
                correction_reaches_terminal_area;
        if (!required) return 1;

        for (int offset = job->target_route_offset;
             offset <= job->destination_route_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return 0;
                int reverse = physical_reverse_index(node);
                if (reverse >= TRACK_MAX) return 0;
                if (reservation->owner_by_node[(unsigned int)node] !=
                            job->train ||
                    (reverse >= 0 &&
                     reservation->owner_by_node[(unsigned int)reverse] !=
                            job->train)) {
                        return 0;
                }
        }
        return 1;
}

/*
 * One authoritative movement predicate is shared by launch, resume,
 * correction, reversal, speed restoration, and the running audit.  The soft
 * nextnext ticket is an exclusive actuator-control right only; actual route
 * permission remains the node/reverse-node rolling reservation checked here.
 */
static int can_train_move_with_reservation(
        int slot,
        const track_reservation_snapshot *reservation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !reservation || !dispatch_scheduler_healthy) {
                return 0;
        }
        const tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        const tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->movement_plan_active ||
            !runtime->route_valid ||
            !runtime->conflict_zone_plan_valid ||
            job->plan_generation == 0 ||
            runtime->route.node_count < 1 ||
            runtime->route.node_count > TRACK_MAX ||
            job->current_route_offset < 0 ||
            job->current_route_offset >= runtime->route.node_count ||
            job->current_node !=
                    runtime->route.nodes[job->current_route_offset] ||
            runtime->monitor.confirmed_offset <
                    runtime->leg_start_offset ||
            runtime->monitor.confirmed_offset < 0 ||
            runtime->monitor.confirmed_offset >=
                    runtime->route.node_count ||
            runtime->monitor.confirmed_offset >
                    job->current_route_offset ||
            job->destination_route_offset <
                    job->current_route_offset ||
            job->destination_route_offset >=
                    runtime->route.node_count ||
            unknown_static_block_exists_except(slot) ||
            !regular_movement_gates_ready(slot) ||
            !traffic_has_movement_authority(slot, reservation) ||
            !destination_area_safe(slot, reservation)) {
                return 0;
        }

        /*
         * The reservation server atomically owns every directed node and its
         * reverse.  Re-check the complete live footprint here so an ordinary
         * single-track head-on corridor cannot be bypassed merely because the
         * trains currently name different turnout stages.
         */
        for (int index = 0;
             index < runtime->safety_footprint.node_count; ++index) {
                int node = runtime->safety_footprint.nodes[index];
                int reverse = physical_reverse_index(node);
                if (node < 0 || node >= TRACK_MAX ||
                    reservation->owner_by_node[node] != job->train ||
                    (reverse >= 0 &&
                     reservation->owner_by_node[reverse] != job->train)) {
                        return 0;
                }
        }
        return runtime->safety_footprint.node_count > 0;
}

static int can_train_move(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return 0;
        int now = Time();
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        if (now < 0 ||
            TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0 ||
            sensor_health_is_safe(slot, &sensors, 0, now) < 0) {
                return 0;
        }
        if (can_health_is_safe(slot, 0, now) !=
                    TC2_CAN_HEALTH_OK) {
                return 0;
        }
        return can_train_move_with_reservation(slot, &reservation);
}

static int traffic_resume_threshold_mm(
        int braking_envelope_mm) {
        return braking_envelope_mm < 0 ? -1 :
                TC2_TRAFFIC_FOLLOWING_CLEARANCE_MM;
}

static int traffic_stop_reason_priority(int reason) {
        switch (reason) {
        case TC2_TRAFFIC_HEAD_ON: return 4;
        case TC2_TRAFFIC_AUDIT: return 3;
        case TC2_TRAFFIC_AUTHORITY: return 2;
        case TC2_TRAFFIC_FOLLOWING: return 1;
        default: return 0;
        }
}

/*
 * Four trains create up to six simultaneous pair relations. Never let the
 * last inspected pair erase a stricter earlier result. For equal reasons the
 * closest physical peer is retained for diagnostics; recovery permission is
 * still determined from the complete freshly recomputed pair set.
 */
static void merge_traffic_stop_decision(
        int slot, int reason, int peer, int gap,
        int stop_limit, int resume_limit,
        int stop_reason[TC2_DISPATCH_MAX_JOBS],
        int stop_peer[TC2_DISPATCH_MAX_JOBS],
        int stop_gap[TC2_DISPATCH_MAX_JOBS],
        int stop_threshold[TC2_DISPATCH_MAX_JOBS],
        int resume_threshold[TC2_DISPATCH_MAX_JOBS]) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            reason == TC2_TRAFFIC_NONE) {
                return;
        }
        int old_priority = traffic_stop_reason_priority(stop_reason[slot]);
        int new_priority = traffic_stop_reason_priority(reason);
        int replace = new_priority > old_priority;
        if (new_priority == old_priority) {
                replace = stop_peer[slot] == 0 ||
                        (gap >= 0 &&
                         (stop_gap[slot] < 0 || gap < stop_gap[slot])) ||
                        (gap == stop_gap[slot] && peer > 0 &&
                         peer < stop_peer[slot]);
        }
        if (!replace) return;
        stop_reason[slot] = reason;
        stop_peer[slot] = peer;
        stop_gap[slot] = gap;
        stop_threshold[slot] = stop_limit;
        resume_threshold[slot] = resume_limit;
}

static void process_traffic_safety(int now) {
        int stop_reason[TC2_DISPATCH_MAX_JOBS];
        int stop_peer[TC2_DISPATCH_MAX_JOBS];
        int stop_gap[TC2_DISPATCH_MAX_JOBS];
        int stop_threshold[TC2_DISPATCH_MAX_JOBS];
        int resume_threshold[TC2_DISPATCH_MAX_JOBS];
        int resume_speed_candidate[TC2_DISPATCH_MAX_JOBS];
        int block_resume[TC2_DISPATCH_MAX_JOBS];
        int opposing_now[TC2_DISPATCH_MAX_JOBS];
        uint16_t blockers_now[TC2_DISPATCH_MAX_JOBS];
        uint16_t head_on_seen[TC2_DISPATCH_MAX_JOBS];
        track_reservation_snapshot reservation;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid,
                    &reservation) < 0) {
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (traffic_slot_has_position(slot)) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_RESERVATION_SERVICE);
                        }
                }
                return;
        }
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                stop_reason[slot] = TC2_TRAFFIC_NONE;
                stop_peer[slot] = 0;
                stop_gap[slot] = -1;
                stop_threshold[slot] = -1;
                resume_threshold[slot] = -1;
                resume_speed_candidate[slot] = 0;
                dispatch_runtime[slot]
                        .prelaunch_traffic_blocked = 0;
                block_resume[slot] = 0;
                opposing_now[slot] = 0;
                blockers_now[slot] = 0;
                head_on_seen[slot] = 0;
        }

        for (int slot_a = 0;
             slot_a < TC2_DISPATCH_MAX_JOBS; ++slot_a) {
                if (!traffic_slot_has_position(slot_a)) {
                        continue;
                }
                for (int slot_b = slot_a + 1;
                     slot_b < TC2_DISPATCH_MAX_JOBS; ++slot_b) {
                        if (!traffic_slot_has_position(slot_b)) {
                                continue;
                        }
                        tc2_live_traffic_relation relation;
                        int relation_status =
                                live_traffic_relation_for_pair(
                                        slot_a, slot_b, now,
                                        &relation);
                        if (relation_status < 0) {
                                /*
                                 * Fail closed for this sample, but do not
                                 * manufacture a permanent physical HEAD_ON
                                 * claim.  A transient audit hold is allowed
                                 * to clear after directed-edge topology and
                                 * movement authority are coherent again.
                                 */
                                merge_traffic_stop_decision(
                                        slot_a, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_b].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                merge_traffic_stop_decision(
                                        slot_b, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_a].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[slot_a] = 1;
                                block_resume[slot_b] = 1;
                                blockers_now[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                blockers_now[slot_b] |=
                                        traffic_slot_bit(slot_a);
                                continue;
                        }
                        if (!relation.valid) continue;
                        int speed_a =
                                traffic_safety_evaluation_speed(
                                        slot_a);
                        int speed_b =
                                traffic_safety_evaluation_speed(
                                        slot_b);
                        int envelope_a =
                                speed_a > 0 ?
                                Tc2MotionStopDistanceMm(speed_a) : 0;
                        int envelope_b =
                                speed_b > 0 ?
                                Tc2MotionStopDistanceMm(speed_b) : 0;
                        if (speed_a < 0 || speed_b < 0 ||
                            envelope_a < 0 ||
                            envelope_b < 0) {
                                merge_traffic_stop_decision(
                                        slot_a, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_b].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                merge_traffic_stop_decision(
                                        slot_b, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_a].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[slot_a] = 1;
                                block_resume[slot_b] = 1;
                                blockers_now[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                blockers_now[slot_b] |=
                                        traffic_slot_bit(slot_a);
                                continue;
                        }
                        tc2_traffic_safety_input input;
                        input.train_a_route_scalar_mm =
                                relation.scalar_a_mm;
                        input.train_b_route_scalar_mm =
                                relation.scalar_b_mm;
                        input.train_a_effective_speed =
                                speed_a;
                        input.train_b_effective_speed =
                                speed_b;
                        input.train_a_braking_envelope_mm =
                                envelope_a;
                        input.train_b_braking_envelope_mm =
                                envelope_b;
                        input.gap_mm =
                                relation.gap_mm;
                        input.relation =
                                (tc2_traffic_relation)
                                        relation.relation;
                        input.rear_stop_latched = 0;
                        input.rear_has_movement_authority = 1;

                        if (relation.relation ==
                            TC2_TRAFFIC_RELATION_HEAD_ON) {
                                /*
                                 * Every validated opposing/crossing relation
                                 * is a two-train block.  Neither member may
                                 * auto-resume merely because a turnout became
                                 * compatible or one local authority request
                                 * won.  A cancel/remove or a recovery reroute
                                 * must remove the opposing relation first.
                                 */
                                merge_traffic_stop_decision(
                                        slot_a, TC2_TRAFFIC_HEAD_ON,
                                        dispatch_jobs[slot_b].train,
                                        relation.emergency_gap_mm,
                                        TC2_TRAFFIC_EMERGENCY_CLEARANCE_MM,
                                        -1, stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                merge_traffic_stop_decision(
                                        slot_b, TC2_TRAFFIC_HEAD_ON,
                                        dispatch_jobs[slot_a].train,
                                        relation.emergency_gap_mm,
                                        TC2_TRAFFIC_EMERGENCY_CLEARANCE_MM,
                                        -1, stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[slot_a] = 1;
                                block_resume[slot_b] = 1;
                                opposing_now[slot_a] = 1;
                                opposing_now[slot_b] = 1;
                                blockers_now[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                blockers_now[slot_b] |=
                                        traffic_slot_bit(slot_a);
                                head_on_seen[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                head_on_seen[slot_b] |=
                                        traffic_slot_bit(slot_a);
                                continue;
                        }

                        int rear = relation.rear_slot;
                        /*
                         * A valid same-direction relation must identify one
                         * member of this exact pair.  Keep the check explicit
                         * before indexing: it is both the corrupt-relation
                         * fail-closed boundary and the range proof required
                         * by GCC's interprocedural array-bounds analysis.
                         */
                        if (rear < 0 ||
                            rear >= TC2_DISPATCH_MAX_JOBS ||
                            (rear != slot_a && rear != slot_b)) {
                                merge_traffic_stop_decision(
                                        slot_a, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_b].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                merge_traffic_stop_decision(
                                        slot_b, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_a].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[slot_a] = 1;
                                block_resume[slot_b] = 1;
                                blockers_now[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                blockers_now[slot_b] |=
                                        traffic_slot_bit(slot_a);
                                continue;
                        }
                        int front = rear == slot_a ?
                                slot_b : slot_a;
                        int rear_speed =
                                traffic_safety_evaluation_speed(rear);
                        int rear_latched =
                                dispatch_jobs[rear].state ==
                                        TC2_JOB_TRAFFIC_HOLD ||
                                (dispatch_runtime[rear]
                                                .authority_resume_pending &&
                                 (dispatch_jobs[rear].state ==
                                          TC2_JOB_PREPARING ||
                                  dispatch_jobs[rear].state ==
                                          TC2_JOB_READY ||
                                  dispatch_jobs[rear].state ==
                                          TC2_JOB_LAUNCHING));
                        int rear_envelope =
                                rear_latched ?
                                Tc2MotionStopDistanceMm(
                                        dispatch_runtime[rear]
                                                .traffic_resume_speed) :
                                rear_speed > 0 ?
                                Tc2MotionStopDistanceMm(rear_speed) : 0;
                        int rear_stop_threshold =
                                TC2_TRAFFIC_FOLLOWING_CLEARANCE_MM;
                        int rear_resume_threshold =
                                traffic_resume_threshold_mm(
                                        rear_envelope);
                        if (rear_envelope < 0 ||
                            rear_stop_threshold < 0 ||
                            rear_resume_threshold < 0) {
                                merge_traffic_stop_decision(
                                        rear, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[front].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[rear] = 1;
                                blockers_now[rear] |=
                                        traffic_slot_bit(front);
                                continue;
                        }
                        if (rear == slot_a) {
                                input
                                        .train_a_braking_envelope_mm =
                                        rear_envelope;
                                input
                                        .train_a_effective_speed =
                                        rear_latched ? 0 :
                                        rear_speed;
                        } else {
                                input
                                        .train_b_braking_envelope_mm =
                                        rear_envelope;
                                input
                                        .train_b_effective_speed =
                                        rear_latched ? 0 :
                                        rear_speed;
                        }
                        input.rear_stop_latched =
                                rear_latched;
                        input.rear_has_movement_authority =
                                traffic_has_movement_authority(
                                        rear,
                                        &reservation);
                        tc2_traffic_action action =
                                Tc2TrafficSafetyEvaluate(&input);
                        dispatch_jobs[rear].traffic_gap_mm =
                                relation.gap_mm;
                        if (action ==
                            TC2_TRAFFIC_ACTION_STOP_REAR) {
                                merge_traffic_stop_decision(
                                        rear, TC2_TRAFFIC_FOLLOWING,
                                        dispatch_jobs[front].train,
                                        relation.gap_mm,
                                        rear_stop_threshold,
                                        rear_resume_threshold,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[rear] = 1;
                                blockers_now[rear] |=
                                        traffic_slot_bit(front);
                                /*
                                 * A following-distance violation belongs to
                                 * the rear train only.  Freezing the leader
                                 * prevents the gap from opening and can turn
                                 * two otherwise one-way authority windows
                                 * into a mutual wait cycle.  The leader still
                                 * stops independently if its own next-turnout
                                 * verification, authority ceiling, or another
                                 * pairwise safety relation requires it.
                                 */
                        } else if (action ==
                                   TC2_TRAFFIC_ACTION_KEEP_HOLD) {
                                block_resume[rear] = 1;
                                blockers_now[rear] |=
                                        traffic_slot_bit(front);
                        } else if (action ==
                                   TC2_TRAFFIC_ACTION_RESUME_REAR) {
                                int safe_speed =
                                        following_safe_resume_speed(
                                                rear,
                                                dispatch_runtime[rear]
                                                        .traffic_resume_speed,
                                                relation.gap_mm);
                                if (safe_speed < 1) {
                                        block_resume[rear] = 1;
                                        blockers_now[rear] |=
                                                traffic_slot_bit(front);
                                } else if (
                                        resume_speed_candidate[rear] == 0 ||
                                        safe_speed <
                                                resume_speed_candidate[rear]) {
                                        resume_speed_candidate[rear] =
                                                safe_speed;
                                }
                        } else if (action ==
                                   TC2_TRAFFIC_ACTION_STOP_BOTH) {
                                /*
                                 * A validated same-direction relation can
                                 * never request a physical two-train stop.
                                 * Treat an impossible policy result as a
                                 * retryable audit failure instead.
                                 */
                                merge_traffic_stop_decision(
                                        slot_a, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_b].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                merge_traffic_stop_decision(
                                        slot_b, TC2_TRAFFIC_AUDIT,
                                        dispatch_jobs[slot_a].train,
                                        -1, -1, -1,
                                        stop_reason, stop_peer, stop_gap,
                                        stop_threshold, resume_threshold);
                                block_resume[slot_a] = 1;
                                block_resume[slot_b] = 1;
                                blockers_now[slot_a] |=
                                        traffic_slot_bit(slot_b);
                                blockers_now[slot_b] |=
                                        traffic_slot_bit(slot_a);
                        } else if (action !=
                                   TC2_TRAFFIC_ACTION_RESUME_REAR) {
                                block_resume[rear] = 1;
                                blockers_now[rear] |=
                                        traffic_slot_bit(front);
                        }
                }
        }

        /*
         * Commit pairwise safety as one atomic observation.  A terminal
         * static peer no longer owns an opposing travel corridor; its exact
         * reservation still remains in blockers_now when the selected route
         * physically reaches the body.  Thus an old HEAD_ON latch cannot make
         * an unrelated branch wait forever after cancel/arrival.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                uint16_t latched = (uint16_t)(
                        runtime->traffic_head_on_latches |
                        head_on_seen[slot]);
                for (int peer = 0;
                     peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                        uint16_t peer_bit = traffic_slot_bit(peer);
                        int recovery_cleared =
                                (head_on_seen[slot] & peer_bit) == 0 &&
                                dispatch_runtime[peer]
                                        .head_on_recovery_active &&
                                dispatch_runtime[peer]
                                        .head_on_recovery_cleared &&
                                !dispatch_runtime[peer]
                                        .carry_ambiguity_active;
                        if (dispatch_jobs[peer].state == TC2_JOB_EMPTY ||
                            traffic_slot_is_terminal_static(peer) ||
                            recovery_cleared) {
                                latched = (uint16_t)(latched &
                                        (uint16_t)~peer_bit);
                        }
                }
                runtime->traffic_blockers_now = blockers_now[slot];
                runtime->traffic_head_on_latches = latched;
                if (runtime->traffic_blockers_now != 0 ||
                    runtime->traffic_head_on_latches != 0) {
                        block_resume[slot] = 1;
                }
        }

        /*
         * KEEP_HOLD and an occupied opposite-direction corridor deliberately
         * do not create a second stop command for a train that is already
         * stationary.  Carry that decision into the authority prelaunch
         * gate so READY cannot accidentally interpret "no new stop" as
         * permission to launch.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                int authority_prelaunch =
                        dispatch_jobs[slot].state ==
                                TC2_JOB_PREPARING ||
                        dispatch_jobs[slot].state ==
                                TC2_JOB_READY ||
                        dispatch_jobs[slot].state ==
                                TC2_JOB_LAUNCHING;
                int reversal_prelaunch =
                        dispatch_jobs[slot].state ==
                        TC2_JOB_REVERSING;
                if (block_resume[slot] &&
                    (authority_prelaunch ||
                     reversal_prelaunch)) {
                        dispatch_runtime[slot]
                                .prelaunch_traffic_blocked = 1;
                }
        }

        /*
         * A HEAD_ON stop is tracked by a complete peer mask, never by the
         * single UI diagnostic traffic_peer_train.  Once the pairwise pass
         * has removed every current blocker and every historical latch, the
         * survivor re-enters the ordinary PREPARING path with its immutable
         * route and FIFO tickets intact.  This is the same rule for two or
         * four trains and for cancel, remove, or a proven recovery reroute.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state !=
                            TC2_JOB_TRAFFIC_HOLD ||
                    runtime->traffic_reason !=
                            TC2_TRAFFIC_HEAD_ON ||
                    runtime->stop_purpose !=
                            TC2_STOP_TRAFFIC ||
                    stop_reason[slot] !=
                            TC2_TRAFFIC_NONE ||
                    opposing_now[slot] ||
                    runtime->retarget_pending) {
                        continue;
                }
                if (runtime->traffic_head_on_latches != 0 ||
                    runtime->traffic_blockers_now != 0) {
                        block_resume[slot] = 1;
                        continue;
                }
                runtime->traffic_peer_train = 0;
                job->traffic_peer_train = 0;

                /*
                 * The survivor deliberately kept its immutable route,
                 * hard-next ticket and soft-nextnext queue position while
                 * stopped.  A topology change invalidates only the safety
                 * relation, not those cursors.  Re-enter PREPARING so both
                 * live directions and both exact control rights are checked
                 * again before any positive speed is sent.
                 */
                int zone_wait =
                        defer_traffic_resume_for_conflict_zone(slot, now);
                if (zone_wait < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (zone_wait > 0) {
                        continue;
                }

                int safe_resume_speed =
                        following_safe_resume_speed(
                                slot,
                                runtime
                                        ->traffic_resume_speed,
                                -1);
                if (safe_resume_speed < 1) {
                        if (runtime
                                            ->rolling_authority_active &&
                            runtime->authority_end_offset >= 0 &&
                            runtime->authority_end_offset <
                                    job->destination_route_offset) {
                                runtime->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                job->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                runtime->traffic_peer_train = 0;
                                job->traffic_peer_train = 0;
                                (void)begin_authority_request(
                                        slot, now, 0);
                        }
                        continue;
                }
                runtime->traffic_resume_speed =
                        safe_resume_speed;
                if (resume_traffic_hold(
                            slot, now,
                            TC2_TRAFFIC_HEAD_ON) < 0) {
                        fail_job(
                                slot,
                                TC2_FAILURE_CAN_SERVICE);
                }
        }

        int atomic_stop_slots[TC2_DISPATCH_MAX_JOBS];
        int atomic_stop_count = 0;
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (stop_reason[slot] != TC2_TRAFFIC_NONE &&
                    dispatch_jobs[slot].state == TC2_JOB_RUNNING) {
                        atomic_stop_slots[atomic_stop_count++] = slot;
                }
        }
        unsigned int atomic_stop_token = 0;
        if (atomic_stop_count > 0 &&
            queue_atomic_traffic_stop(
                    atomic_stop_slots, atomic_stop_count,
                    &atomic_stop_token) < 0) {
                for (int index = 0;
                     index < atomic_stop_count; ++index) {
                        fail_job(
                                atomic_stop_slots[index],
                                TC2_FAILURE_CAN_SERVICE);
                }
                return;
        }

        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (stop_reason[slot] ==
                    TC2_TRAFFIC_NONE) {
                        continue;
                }
                int envelope =
                        traffic_collision_stop_distance_mm(
                                slot);
                int resume = resume_threshold[slot];
                if (resume < 0 &&
                    stop_reason[slot] ==
                            TC2_TRAFFIC_FOLLOWING) {
                        resume =
                                traffic_resume_threshold_mm(
                                        envelope);
                }
                int authority_latched =
                        (dispatch_jobs[slot].state ==
                                 TC2_JOB_TRAFFIC_HOLD ||
                         (dispatch_jobs[slot].state ==
                                  TC2_JOB_BRAKING &&
                          dispatch_runtime[slot]
                                  .stop_purpose ==
                                  TC2_STOP_TRAFFIC)) &&
                        dispatch_runtime[slot]
                                .traffic_reason ==
                                TC2_TRAFFIC_AUTHORITY;
                int head_on_latched =
                        (dispatch_jobs[slot].state ==
                                 TC2_JOB_TRAFFIC_HOLD ||
                         (dispatch_jobs[slot].state ==
                                  TC2_JOB_BRAKING &&
                          dispatch_runtime[slot]
                                  .stop_purpose ==
                                  TC2_STOP_TRAFFIC)) &&
                        dispatch_runtime[slot]
                                .traffic_reason ==
                                TC2_TRAFFIC_HEAD_ON;
                begin_traffic_stop_with_queued_zero(
                        slot, now, stop_reason[slot],
                        stop_peer[slot], stop_gap[slot],
                        stop_threshold[slot], resume,
                        atomic_stop_token);
                /*
                 * Dynamic traffic may additionally block a train already
                 * stopped at an authority limit, but it must not replace the
                 * authority latch.  Otherwise the following auto-resume path
                 * could restart the train without first extending ownership
                 * and setting the newly authorized turnout.
                 */
                if (authority_latched || head_on_latched) {
                        block_resume[slot] = 1;
                        continue;
                }
                if (dispatch_jobs[slot].state ==
                            TC2_JOB_TRAFFIC_HOLD ||
                    (dispatch_jobs[slot].state ==
                             TC2_JOB_BRAKING &&
                     dispatch_runtime[slot]
                             .stop_purpose ==
                             TC2_STOP_TRAFFIC)) {
                        dispatch_runtime[slot]
                                .traffic_reason =
                                stop_reason[slot];
                        dispatch_jobs[slot]
                                .traffic_reason =
                                stop_reason[slot];
                }
        }

        /*
         * An AUDIT stop is deliberately self-clearing.  It means one sampled
         * position/topology relation was incoherent, not that an opposing
         * physical corridor was observed.  Once every pair involving this
         * train is coherent again, ordinary reservation and exact hard-next
         * turnout authority decide whether it can resume.  A real current
         * same-direction or head-on relation above keeps block_resume set and
         * therefore wins over this recovery path.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_TRAFFIC_HOLD ||
                    runtime->traffic_reason !=
                            TC2_TRAFFIC_AUDIT ||
                    stop_reason[slot] !=
                            TC2_TRAFFIC_NONE ||
                    block_resume[slot] ||
                    !traffic_has_movement_authority(
                            slot, &reservation)) {
                        continue;
                }
                int safe_speed = following_safe_resume_speed(
                        slot, runtime->traffic_resume_speed, -1);
                if (safe_speed < 1) {
                        if (runtime->rolling_authority_active &&
                            runtime->authority_end_offset >= 0 &&
                            runtime->authority_end_offset <
                                    job->destination_route_offset) {
                                runtime->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                runtime->traffic_peer_train = 0;
                                job->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                job->traffic_peer_train = 0;
                                (void)begin_authority_request(
                                        slot, now, 0);
                        }
                        continue;
                }
                runtime->traffic_resume_speed = safe_speed;
                int zone_wait =
                        defer_traffic_resume_for_conflict_zone(slot, now);
                if (zone_wait < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (zone_wait > 0) continue;
                if (resume_traffic_hold(
                            slot, now,
                            TC2_TRAFFIC_AUDIT) < 0) {
                        fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                }
        }

        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state !=
                            TC2_JOB_TRAFFIC_HOLD ||
                    dispatch_runtime[slot]
                            .traffic_reason !=
                            TC2_TRAFFIC_FOLLOWING ||
                    stop_reason[slot] !=
                            TC2_TRAFFIC_NONE ||
                    block_resume[slot]) {
                        continue;
                }
                if (!traffic_has_movement_authority(
                            slot, &reservation)) {
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        /*
                         * Spacing is now clear, but the next real detector is
                         * not.  Preserve speed zero and hand the follower to
                         * the ordinary rolling-authority CAS instead of
                         * interpreting a live generation as permission to
                         * move.  This path is pairwise and therefore extends
                         * naturally to four trains.
                         */
                        if (runtime->rolling_authority_active &&
                            runtime->authority_end_offset >= 0 &&
                            runtime->authority_end_offset <
                                    job->destination_route_offset) {
                                runtime->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                runtime->traffic_peer_train = 0;
                                job->traffic_reason =
                                        TC2_TRAFFIC_AUTHORITY;
                                job->traffic_peer_train = 0;
                                (void)begin_authority_request(
                                        slot, now, 0);
                        }
                        continue;
                }
                int maximum_resume_speed =
                        resume_speed_candidate[slot] > 0 ?
                        resume_speed_candidate[slot] :
                        dispatch_runtime[slot]
                                .traffic_resume_speed;
                int safe_resume_speed =
                        following_safe_resume_speed(
                                slot, maximum_resume_speed,
                                -1);
                if (safe_resume_speed < 1) {
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        if (!runtime
                                            ->rolling_authority_active ||
                            runtime->authority_end_offset < 0 ||
                            runtime->authority_end_offset >=
                                    job->destination_route_offset) {
                                /*
                                 * At a complete destination authority there
                                 * may be too little route left for even speed
                                 * one.  Remaining stopped is safer than
                                 * converting a valid managed trip into a
                                 * service failure or creeping past d1-d8.
                                 */
                                continue;
                        }
                        /*
                         * Keep speed zero and hand the same frozen position
                         * to the rolling-authority FSM.  It atomically
                         * extends ownership, sets the newly authorized
                         * turnouts, waits for settle, and only then restarts.
                         */
                        runtime->traffic_reason =
                                TC2_TRAFFIC_AUTHORITY;
                        job->traffic_reason =
                                TC2_TRAFFIC_AUTHORITY;
                        (void)begin_authority_request(
                                slot, now, 0);
                        continue;
                }
                dispatch_runtime[slot].traffic_resume_speed =
                        safe_resume_speed;
                int zone_wait =
                        defer_traffic_resume_for_conflict_zone(slot, now);
                if (zone_wait < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (zone_wait > 0) {
                        continue;
                }
                /*
                 * If the leader has left the common corridor, the exclusive
                 * generation-preserving reservation is sufficient movement
                 * authority.  Otherwise RESUME_REAR above already proved
                 * the 350 mm same-direction clearance boundary.
                 */
                if (resume_traffic_hold(
                            slot, now,
                            TC2_TRAFFIC_FOLLOWING) < 0) {
                        fail_job(
                                slot,
                                TC2_FAILURE_CAN_SERVICE);
                }
        }
}

/*
 * This is the admission gate for acquiring the next stopped window, not the
 * eventual movement-permission check.  A live generation/destination pair
 * is enough to enter FIFO acquisition.  Resume still goes through the full
 * physical-window, turnout, conflict-zone, and pairwise traffic checks.
 */
static int authority_dynamic_resume_is_safe(
        int slot, int now,
        const track_reservation_snapshot *reservation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !reservation ||
            dispatch_jobs[slot].state !=
                    TC2_JOB_TRAFFIC_HOLD ||
            dispatch_runtime[slot].traffic_reason !=
                    TC2_TRAFFIC_AUTHORITY ||
            !traffic_has_reservation_identity(
                    slot, reservation)) {
                return 0;
        }
        (void)now;
        return 1;
}

static int authority_request_has_priority(
        int candidate, int current) {
        if (current < 0) return 1;
        int candidate_train = dispatch_jobs[candidate].train;
        int current_train = dispatch_jobs[current].train;
        if (candidate_train != current_train) {
                return candidate_train < current_train;
        }
        return candidate < current;
}

static int authority_resume_speed_for_remaining(
        int requested_speed, int remaining_mm) {
        if (requested_speed < 1 || requested_speed > 120 ||
            remaining_mm < 0) {
                return -1;
        }
        int minimum_usable_speed =
                requested_speed < TC2_ROLLING_AUTHORITY_MIN_SPEED ?
                requested_speed : TC2_ROLLING_AUTHORITY_MIN_SPEED;
        for (int speed = requested_speed;
             speed >= minimum_usable_speed; --speed) {
                int stop =
                        Tc2MotionStopDistanceMm(speed);
                if (stop >= 0 && stop <= remaining_mm) {
                        return speed;
                }
        }
        return -1;
}

/*
 * Pick the highest ordinary rolling-authority speed which is safe in both
 * coordinate systems: the latest real-sensor remaining distance and the
 * conservative command-to-rest occupancy upper bound.  Testing only the
 * speed selected from sensor distance can strand a train forever when 80 no
 * longer fits the frozen upper bound but a lower calibrated speed does.
 */
static int authority_resume_speed_for_window(
        int slot, int requested_speed, int remaining_mm,
        int authority_end_offset,
        int authority_center_ceiling_mm) {
        if (requested_speed < 1 || requested_speed > 120 ||
            remaining_mm < 0) {
                return -1;
        }
        int minimum_usable_speed =
                requested_speed < TC2_ROLLING_AUTHORITY_MIN_SPEED ?
                requested_speed : TC2_ROLLING_AUTHORITY_MIN_SPEED;
        for (int speed = requested_speed;
             speed >= minimum_usable_speed; --speed) {
                int stop = Tc2MotionStopDistanceMm(speed);
                if (stop >= 0 && stop <= remaining_mm &&
                    traffic_resume_fits_authority_window(
                            slot, speed, authority_end_offset,
                            authority_center_ceiling_mm)) {
                        return speed;
                }
        }
        return -1;
}

static int authority_route_metadata_is_valid(int slot);

static int authority_ticket_has_active_state(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return 0;
        }
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        int state = dispatch_jobs[slot].state;
        return runtime->rolling_authority_active &&
                runtime->authority_request_tick >= 0 &&
                (state == TC2_JOB_PREPARING ||
                 state == TC2_JOB_READY ||
                 state == TC2_JOB_LAUNCHING ||
                 state == TC2_JOB_RUNNING ||
                 state == TC2_JOB_BRAKING ||
                 state == TC2_JOB_TRAFFIC_HOLD);
}

static int authority_route_metadata_is_valid(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return 0;
        }
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        int count = runtime->route.node_count;
        if (!runtime->route_valid || count < 2 ||
            count > TRACK_MAX ||
            runtime->authority_end_offset < 0 ||
            runtime->authority_end_offset >= count ||
            runtime->leg_start_offset < 0 ||
            runtime->leg_start_offset >= count ||
            runtime->leg_end_offset <
                    runtime->leg_start_offset ||
            runtime->leg_end_offset >= count ||
            job->target_route_offset < 0 ||
            job->target_route_offset >= count ||
            job->destination_route_offset <
                    job->target_route_offset ||
            job->destination_route_offset >= count ||
            job->destination_offset_mm < 0 ||
            job->destination_distance_mm < 0 ||
            job->speed < 1 || job->speed > 120) {
                return 0;
        }
        for (int offset = 0; offset < count; ++offset) {
                if (runtime->route.nodes[offset] < 0 ||
                    runtime->route.nodes[offset] >= TRACK_MAX) {
                        return 0;
                }
        }
        return 1;
}

static int authority_ticket_is_active(int slot) {
        return authority_ticket_has_active_state(slot) &&
                authority_route_metadata_is_valid(slot) &&
                dispatch_runtime[slot]
                                .authority_end_offset <
                        dispatch_jobs[slot]
                                .destination_route_offset;
}

/*
 * Test only resources newly added by this rolling extension against the
 * peer's exact next local request. Neither side consults an entire
 * destination route, so a downstream intersection cannot make a train wait
 * at an unrelated current block.
 */
static int authority_extension_overlaps_older_future(
        int candidate_slot, int older_slot,
        const track_route *candidate_extension,
        const track_reservation_snapshot *reservation) {
        if (candidate_slot < 0 ||
            candidate_slot >= TC2_DISPATCH_MAX_JOBS ||
            older_slot < 0 ||
            older_slot >= TC2_DISPATCH_MAX_JOBS ||
            candidate_slot == older_slot ||
            !candidate_extension || !reservation ||
            candidate_extension->node_count < 1 ||
            candidate_extension->node_count > TRACK_MAX) {
                return -1;
        }
        tc2_dispatch_runtime *older =
                &dispatch_runtime[older_slot];
        if (!older->authority_requested_footprint_valid) {
                /*
                 * A ticket can be created before a feasible window exists
                 * (for example while too close to the current ceiling). There
                 * is no concrete shared local resource to arbitrate yet.
                 */
                return 0;
        }
        const track_route *older_request =
                &older->authority_requested_footprint;
        if (older_request->node_count < 1 ||
            older_request->node_count > TRACK_MAX) {
                return -1;
        }

        int candidate_train =
                dispatch_jobs[candidate_slot].train;
        for (int left = 0;
             left < candidate_extension->node_count; ++left) {
                int node =
                        candidate_extension->nodes[left];
                int reverse =
                        physical_reverse_index(node);
                int already_owned =
                        reservation->owner_by_node[node] ==
                                candidate_train ||
                        (reverse >= 0 &&
                         reservation->owner_by_node[reverse] ==
                                 candidate_train);
                if (already_owned) continue;
                for (int right = 0;
                     right < older_request->node_count; ++right) {
                        int older_node =
                                older_request->nodes[right];
                        int older_reverse =
                                physical_reverse_index(
                                        older_node);
                        if (node == older_node ||
                            node == older_reverse ||
                            reverse == older_node) {
                                return 1;
                        }
                }
        }
        return 0;
}

static int route_interval_contains_physical_node(
        const track_route *route, int first_offset,
        int last_offset, int physical_node) {
        if (!route || physical_node < 0 ||
            physical_node >= TRACK_MAX ||
            first_offset < 0 || last_offset < first_offset ||
            last_offset >= route->node_count) {
                return 0;
        }
        int reverse = physical_reverse_index(physical_node);
        for (int offset = first_offset;
             offset <= last_offset; ++offset) {
                int node = route->nodes[offset];
                if (node == physical_node || node == reverse) {
                        return 1;
                }
        }
        return 0;
}

/*
 * A FIFO/convoy waiter can name another managed train as its blocker only
 * when the reservation snapshot still proves that train owns the named
 * physical node.  Checking both directed aliases makes this a statement
 * about the train body, rather than a stale route-overlap diagnostic.
 */
static int authority_waiter_is_blocked_by_occupying_candidate(
        int waiter_slot, int candidate_slot,
        const track_reservation_snapshot *reservation) {
        if (waiter_slot < 0 ||
            waiter_slot >= TC2_DISPATCH_MAX_JOBS ||
            candidate_slot < 0 ||
            candidate_slot >= TC2_DISPATCH_MAX_JOBS ||
            waiter_slot == candidate_slot || !reservation) {
                return 0;
        }
        tc2_dispatch_job_snapshot *waiter =
                &dispatch_jobs[waiter_slot];
        int candidate_train =
                dispatch_jobs[candidate_slot].train;
        int node = waiter->conflict_node;
        if (candidate_train < 1 || candidate_train > 255 ||
            waiter->conflict_train != candidate_train ||
            (unsigned int)node >= (unsigned int)TRACK_MAX) {
                return 0;
        }
        if (reservation->owner_by_node[(unsigned int)node] ==
                    candidate_train) {
                return 1;
        }
        int reverse = physical_reverse_index(node);
        return reverse >= 0 &&
               (unsigned int)reverse < (unsigned int)TRACK_MAX &&
               reservation->owner_by_node[(unsigned int)reverse] ==
                       candidate_train;
}

/*
 * FIFO orders two trains approaching a free shared resource.  It must not
 * let that ordering create a wait-for cycle with a train which is already a
 * real speed-zero obstacle inside the older train's remaining corridor.
 *
 * Let the obstacle train clear first when all three topology facts hold:
 *   1. the candidate's remaining route reaches the peer's confirmed anchor;
 *   2. the peer can leave without crossing the candidate's confirmed anchor;
 *   3. this exact extension would consume part of the peer's release route.
 *
 * This is an asymmetric physical dependency, not a train-number, start, or
 * destination priority.  Repeating it pairwise lets the free tail of an
 * arbitrary multi-train wait chain move first.  A mutual dependency is left
 * to ordinary exclusion/deadlock handling; neither train is granted merely
 * by this exception.
 */
static int authority_extension_yields_to_occupying_peer(
        int candidate_slot,
        const track_route *candidate_extension,
        const track_reservation_snapshot *reservation) {
        if (candidate_slot < 0 ||
            candidate_slot >= TC2_DISPATCH_MAX_JOBS ||
            !candidate_extension || !reservation ||
            candidate_extension->node_count < 1 ||
            candidate_extension->node_count > TRACK_MAX) {
                return -1;
        }
        tc2_dispatch_job_snapshot *candidate_job =
                &dispatch_jobs[candidate_slot];
        tc2_dispatch_runtime *candidate =
                &dispatch_runtime[candidate_slot];
        int candidate_anchor =
                candidate->monitor.confirmed_offset;
        if (candidate_anchor < 0) {
                candidate_anchor =
                        candidate_job->current_route_offset;
        }
        if (!candidate->route_valid || candidate_anchor < 0 ||
            candidate_anchor >= candidate->route.node_count ||
            candidate_job->destination_route_offset <
                    candidate_anchor ||
            candidate_job->destination_route_offset >=
                    candidate->route.node_count) {
                return 0;
        }
        int candidate_anchor_node =
                candidate->route.nodes[candidate_anchor];
        if ((unsigned int)candidate_anchor_node >=
                    (unsigned int)TRACK_MAX) {
                return -1;
        }
        int candidate_train = candidate_job->train;

        for (int peer_slot = 0;
             peer_slot < TC2_DISPATCH_MAX_JOBS; ++peer_slot) {
                if (peer_slot == candidate_slot) continue;
                tc2_dispatch_job_snapshot *peer_job =
                        &dispatch_jobs[peer_slot];
                tc2_dispatch_runtime *peer =
                        &dispatch_runtime[peer_slot];
                if (peer_job->state != TC2_JOB_TRAFFIC_HOLD ||
                    peer->traffic_reason != TC2_TRAFFIC_AUTHORITY ||
                    peer->stop_purpose != TC2_STOP_TRAFFIC ||
                    !peer->route_valid ||
                    peer_job->train < 1 || peer_job->train > 255) {
                        continue;
                }
                int peer_anchor = peer->monitor.confirmed_offset;
                if (peer_anchor < 0) {
                        peer_anchor =
                                peer_job->current_route_offset;
                }
                if (peer_anchor < 0 ||
                    peer_anchor >= peer->route.node_count ||
                    peer_job->destination_route_offset < peer_anchor ||
                    peer_job->destination_route_offset >=
                            peer->route.node_count) {
                        continue;
                }
                int peer_anchor_node =
                        peer->route.nodes[peer_anchor];
                if ((unsigned int)peer_anchor_node >=
                            (unsigned int)TRACK_MAX) {
                        return -1;
                }
                int peer_reverse =
                        physical_reverse_index(peer_anchor_node);
                unsigned int peer_anchor_index =
                        (unsigned int)peer_anchor_node;
                int peer_reverse_owner = 0;
                if (peer_reverse >= 0) {
                        if ((unsigned int)peer_reverse >=
                                    (unsigned int)TRACK_MAX) {
                                return -1;
                        }
                        peer_reverse_owner =
                                reservation->owner_by_node[
                                        (unsigned int)peer_reverse];
                }
                int peer_owns_anchor =
                        reservation->owner_by_node[peer_anchor_index] ==
                                peer_job->train ||
                        peer_reverse_owner == peer_job->train;
                if (!peer_owns_anchor ||
                    !route_interval_contains_physical_node(
                            &candidate->route,
                            candidate_anchor,
                            candidate_job
                                    ->destination_route_offset,
                            peer_anchor_node) ||
                    route_interval_contains_physical_node(
                            &peer->route, peer_anchor,
                            peer_job->destination_route_offset,
                            candidate_anchor_node)) {
                        continue;
                }

                int extension_blocks_release = 0;
                for (int offset = 0;
                     offset < candidate_extension->node_count;
                     ++offset) {
                        int node =
                                candidate_extension->nodes[offset];
                        if ((unsigned int)node >=
                                    (unsigned int)TRACK_MAX) {
                                return -1;
                        }
                        int reverse = physical_reverse_index(node);
                        unsigned int node_index =
                                (unsigned int)node;
                        int reverse_owner = 0;
                        if (reverse >= 0) {
                                if ((unsigned int)reverse >=
                                            (unsigned int)TRACK_MAX) {
                                        return -1;
                                }
                                reverse_owner =
                                        reservation->owner_by_node[
                                                (unsigned int)reverse];
                        }
                        int already_owned =
                                reservation->owner_by_node[node_index] ==
                                        candidate_train ||
                                reverse_owner == candidate_train;
                        if (already_owned) continue;
                        if (route_interval_contains_physical_node(
                                    &peer->route, peer_anchor,
                                    peer_job
                                            ->destination_route_offset,
                                    node)) {
                                extension_blocks_release = 1;
                                break;
                        }
                }
                if (!extension_blocks_release) continue;

                candidate_job->conflict_train =
                        peer_job->train;
                candidate_job->conflict_node =
                        peer_anchor_node;
                return 1;
        }
        return 0;
}

/*
 * Find the first directed corridor shared by two current motion legs and use
 * distance from each leg origin to that entrance as their immutable convoy
 * order.  This is the physical ordering established by a single `go` batch,
 * not the order in which later short-window requests happen to arrive.  On
 * Track D, A reaches the A/B MR12 corridor 11 mm before B, so A is the front
 * even when the B dispatch command was entered first.
 */
static int directed_convoy_rear_for_routes(
        int left_slot, const track_route *left_route,
        int left_leg_start, int left_leg_end,
        int right_slot, const track_route *right_route,
        int right_leg_start, int right_leg_end,
        int *rear_slot) {
        if (left_slot < 0 || left_slot >= TC2_DISPATCH_MAX_JOBS ||
            right_slot < 0 || right_slot >= TC2_DISPATCH_MAX_JOBS ||
            left_slot == right_slot || !left_route || !right_route ||
            !rear_slot) {
                return -1;
        }
        tc2_dispatch_job_snapshot *left_job =
                &dispatch_jobs[left_slot];
        tc2_dispatch_job_snapshot *right_job =
                &dispatch_jobs[right_slot];
        *rear_slot = -1;
        if (left_job->job_launch_epoch == 0 ||
            left_job->job_launch_epoch !=
                    right_job->job_launch_epoch) {
                return 0;
        }
        int left_distance[TRACK_MAX];
        int right_distance[TRACK_MAX];
        if (route_prefix_distances(
                    left_route, left_distance) < 0 ||
            route_prefix_distances(
                    right_route, right_distance) < 0 ||
            left_leg_start < 0 ||
            left_leg_end <= left_leg_start ||
            left_leg_end >= left_route->node_count ||
            right_leg_start < 0 ||
            right_leg_end <= right_leg_start ||
            right_leg_end >= right_route->node_count) {
                return -1;
        }

        int best_left = -1;
        int best_right = -1;
        int best_maximum = 0x7fffffff;
        int best_sum = 0x7fffffff;
        for (int left_edge = left_leg_start;
             left_edge < left_leg_end; ++left_edge) {
                for (int right_edge = right_leg_start;
                     right_edge < right_leg_end; ++right_edge) {
                        if (left_route->nodes[left_edge] !=
                                    right_route->nodes[right_edge] ||
                            left_route->nodes[left_edge + 1] !=
                                    right_route->nodes[right_edge + 1]) {
                                continue;
                        }
                        int left_approach =
                                left_distance[left_edge] -
                                left_distance[left_leg_start];
                        int right_approach =
                                right_distance[right_edge] -
                                right_distance[right_leg_start];
                        int maximum = left_approach > right_approach ?
                                left_approach : right_approach;
                        int sum = left_approach + right_approach;
                        if (maximum < best_maximum ||
                            (maximum == best_maximum &&
                             sum < best_sum)) {
                                best_left = left_approach;
                                best_right = right_approach;
                                best_maximum = maximum;
                                best_sum = sum;
                        }
                }
        }
        if (best_left < 0 || best_right < 0) return 0;
        if (best_left < best_right) {
                *rear_slot = right_slot;
        } else if (best_right < best_left) {
                *rear_slot = left_slot;
        } else {
                *rear_slot = sequence_before(
                                dispatch_runtime[left_slot]
                                        .queue_sequence,
                                dispatch_runtime[right_slot]
                                        .queue_sequence) ?
                        right_slot : left_slot;
        }
        return 1;
}

static int same_batch_directed_convoy_rear(
        int left_slot, int right_slot, int *rear_slot) {
        if (left_slot < 0 || left_slot >= TC2_DISPATCH_MAX_JOBS ||
            right_slot < 0 || right_slot >= TC2_DISPATCH_MAX_JOBS ||
            left_slot == right_slot || !rear_slot) {
                return -1;
        }
        tc2_dispatch_runtime *left =
                &dispatch_runtime[left_slot];
        tc2_dispatch_runtime *right =
                &dispatch_runtime[right_slot];
        if (!left->route_valid || !right->route_valid ||
            dispatch_jobs[left_slot].plan_generation == 0 ||
            dispatch_jobs[right_slot].plan_generation == 0) {
                *rear_slot = -1;
                return 0;
        }
        return directed_convoy_rear_for_routes(
                left_slot, &left->route,
                left->leg_start_offset, left->leg_end_offset,
                right_slot, &right->route,
                right->leg_start_offset, right->leg_end_offset,
                rear_slot);
}

/*
 * The initial WAITING retry is itself an authority acquisition.  It must use
 * the same physical convoy order as later rolling extensions; otherwise a
 * rear train can wait for the merge entrance to clear and then reserve a
 * distant detector which the still-moving front train has not reached yet.
 * The sensor service then attributes the front train's real pulse to the rear
 * owner and both route monitors fail in opposite directions.
 */
static int initial_authority_overtakes_batch_front(
        int candidate_slot, const track_route *candidate_route,
        int candidate_leg_start, int candidate_leg_end,
        int candidate_authority_end,
        const track_route *candidate_footprint) {
        if (candidate_slot < 0 ||
            candidate_slot >= TC2_DISPATCH_MAX_JOBS ||
            !candidate_route || !candidate_footprint ||
            candidate_leg_start < 0 ||
            candidate_leg_end <= candidate_leg_start ||
            candidate_leg_end >= candidate_route->node_count ||
            candidate_authority_end < candidate_leg_start ||
            candidate_authority_end >= candidate_route->node_count ||
            candidate_footprint->node_count < 1 ||
            candidate_footprint->node_count > TRACK_MAX) {
                return -1;
        }

        for (int peer = 0; peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                tc2_dispatch_runtime *front =
                        &dispatch_runtime[peer];
                tc2_dispatch_job_snapshot *front_job =
                        &dispatch_jobs[peer];
                if (peer == candidate_slot || !front->route_valid ||
                    front_job->plan_generation == 0) {
                        continue;
                }
                int rear = -1;
                int ordered = directed_convoy_rear_for_routes(
                        candidate_slot, candidate_route,
                        candidate_leg_start, candidate_leg_end,
                        peer, &front->route,
                        front->leg_start_offset,
                        front->leg_end_offset, &rear);
                if (ordered < 0) return -1;
                if (ordered == 0 || rear != candidate_slot) continue;

                int front_first = front->monitor.confirmed_offset;
                if (front_first < front->leg_start_offset) {
                        front_first = front->leg_start_offset;
                }
                int front_last = front->leg_end_offset <
                                                front_job
                                                        ->destination_route_offset ?
                        front->leg_end_offset :
                        front_job->destination_route_offset;
                if (front_first < 0 || front_last < front_first ||
                    front_last >= front->route.node_count) {
                        return -1;
                }

                for (int candidate_offset = candidate_leg_start;
                     candidate_offset <= candidate_authority_end;
                     ++candidate_offset) {
                        int node = candidate_route
                                           ->nodes[candidate_offset];
                        if (!route_contains_node(
                                    candidate_footprint, node)) {
                                continue;
                        }
                        for (int front_offset = front_first;
                             front_offset <= front_last;
                             ++front_offset) {
                                if (front->route.nodes[front_offset] !=
                                            node) {
                                        continue;
                                }
                                dispatch_jobs[candidate_slot]
                                        .conflict_train =
                                        front_job->train;
                                dispatch_jobs[candidate_slot]
                                        .conflict_node = node;
                                return 1;
                        }
                }
        }
        return 0;
}

static int same_batch_convoy_front_pending_launch(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        for (int peer = 0; peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                if (peer == slot ||
                    !dispatch_runtime[peer].route_valid ||
                    dispatch_jobs[peer].plan_generation == 0) {
                        continue;
                }
                int rear = -1;
                int ordered = same_batch_directed_convoy_rear(
                        slot, peer, &rear);
                if (ordered < 0) return -1;
                if (ordered == 0 || rear != slot) continue;
                int front_state = dispatch_jobs[peer].state;
                if (front_state == TC2_JOB_STAGED ||
                    front_state == TC2_JOB_WAITING ||
                    front_state == TC2_JOB_PREPARING ||
                    front_state == TC2_JOB_READY ||
                    front_state == TC2_JOB_LAUNCHING) {
                        return 1;
                }
        }
        return 0;
}

static int authority_prefetch_must_yield(
        int candidate_slot, int now,
        const track_route *candidate_extension,
        const track_reservation_snapshot *reservation) {
        int occupying_peer =
                authority_extension_yields_to_occupying_peer(
                        candidate_slot,
                        candidate_extension, reservation);
        if (occupying_peer != 0) return occupying_peer;

        int candidate_train =
                dispatch_jobs[candidate_slot].train;
        for (int peer = 0;
             peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                if (peer == candidate_slot ||
                    !authority_ticket_is_active(peer)) {
                        continue;
                }
                int overlap =
                        authority_extension_overlaps_older_future(
                                candidate_slot, peer,
                                candidate_extension,
                                reservation);
                if (overlap < 0) return -1;
                if (!overlap) continue;

                if (authority_waiter_is_blocked_by_occupying_candidate(
                            peer, candidate_slot,
                            reservation)) {
                        continue;
                }

                /*
                 * Physical same-direction order outranks train number: a
                 * rear train never receives permission to overtake a real
                 * front train. Between all other unentered overlapping
                 * local windows, lower train number is the sole global
                 * priority. This total order cannot form a four-train FIFO
                 * cycle and does not inspect complete destination routes.
                 */
                tc2_live_traffic_relation relation;
                int related = live_traffic_relation_for_pair(
                        candidate_slot, peer, now, &relation);
                if (related < 0) return -1;
                if (relation.valid && !relation.order_ambiguous &&
                    relation.relation !=
                            TC2_TRAFFIC_RELATION_HEAD_ON) {
                        if (relation.rear_slot == candidate_slot) {
                                return 1;
                        }
                        if (relation.rear_slot == peer) {
                                continue;
                        }
                }
                if (candidate_train > dispatch_jobs[peer].train) {
                        return 1;
                }
        }
        return 0;
}

/*
 * A bounded first window may require a lower launch command than requested.
 * Restore the requested speed only after a later reservation CAS has
 * committed, its turnout suffix is confirmed/settled, and the new active
 * center ceiling contains the complete conservative stop envelope.
 */
static int authority_restore_requested_speed(
        int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        (void)now;
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (job->state != TC2_JOB_RUNNING ||
            !runtime->rolling_authority_active ||
            runtime->authority_prefetch_active ||
            runtime->destination_correction_active ||
            runtime->destination_correction_pending ||
            runtime->precision_approach_active ||
            runtime->command_speed < 1 ||
            runtime->command_speed >= job->speed ||
            !regular_movement_gates_ready(slot)) {
                return 0;
        }

        /*
         * A reduced rolling-authority launch is a safety decision made from
         * the frozen real-sensor/coast bounds.  Do not undo it from the more
         * optimistic moving-time projection, and do not restore 80 merely
         * because the same window settled a few ticks later.  At least one
         * genuinely farther authority window must have been promoted, and
         * the requested speed must fit that window under the very same
         * conservative predicate used when choosing the reduced speed.
         */
        int confirmed_progress_mm;
        int requested_stop_mm =
                Tc2MotionStopDistanceMm(job->speed);
        int requested_braking_mm =
                Tc2MotionBrakingDistanceMm(job->speed);
        int prefetch_lead_mm =
                runtime->authority_end_offset <
                                job->destination_route_offset ?
                authority_prefetch_lead_mm(job->speed) : 0;
        if (runtime->authority_previous_end_offset < 0 ||
            runtime->authority_end_offset <=
                    runtime->authority_previous_end_offset ||
            /* A real detector, not elapsed low-speed time, must rebase 80. */
            runtime->motion_anchor_from_traffic ||
            effective_confirmed_distance_mm(
                    runtime, &confirmed_progress_mm) < 0 ||
            requested_stop_mm < 0 || requested_braking_mm < 0 ||
            prefetch_lead_mm < 0 ||
            confirmed_progress_mm < 0 ||
            confirmed_progress_mm >
                    job->destination_distance_mm ||
            requested_stop_mm >
                    job->destination_distance_mm -
                            confirmed_progress_mm ||
            runtime->authority_center_ceiling_mm < 0 ||
            (runtime->authority_end_offset <
                             job->destination_route_offset &&
             (requested_braking_mm >
                              0x7fffffff - prefetch_lead_mm ||
              confirmed_progress_mm >=
                              runtime->authority_center_ceiling_mm -
                                      requested_braking_mm -
                                      prefetch_lead_mm))) {
                return 0;
        }
        int64_t progress_um;
        int restore_command =
                command_train_positive_speed_with_retry(
                        slot, job->speed);
        if (restore_command < 0) return -1;
        if (restore_command > 0) return 0;
        int confirmed = Time();
        if (confirmed < 0) return -1;
        /*
         * Rebase with the old acknowledged-speed model at the confirmation
         * instant.  Updating command_speed before this calculation would
         * fabricate an acceleration jump in both collision spacing and UI.
         */
        if (runtime_motion_progress_um(
                    slot, confirmed,
                    &progress_um) < 0 ||
            progress_um < 0) {
                return -1;
        }
        runtime->motion_anchor_distance_um =
                progress_um;
        runtime->motion_anchor_tick = confirmed;
        runtime->motion_anchor_from_traffic = 0;
        runtime->command_speed = job->speed;
        runtime->motion_speed_ceiling = job->speed;
        runtime->speed_reduction_pending = 0;
        runtime->precision_approach_active = 0;
        runtime->authority_previous_end_offset = -1;
        runtime->observed_velocity_um_per_tick = -1;
        job->command_speed = job->speed;
        return schedule_motion_deadlines(
                slot, confirmed) < 0 ? -1 : 1;
}

/*
 * Stopped reversal handoff.
 *
 * The moving leg never reserves across a reversal.  Once zero speed has
 * settled at the reversal sensor, atomically replace the old window with the
 * union of (a) that incoming window and (b) one bounded outbound window.
 * No turnout or reverse command is sent until this CAS succeeds.  The
 * incoming union becomes reversal_carry and is released only after ordered
 * outbound motion places the train tail plus 200 mm beyond the sensor.
 *
 * Returns 0 after acquiring the outbound window, 1 while safely waiting for
 * a conflict/FIFO predecessor, and -1 on a deterministic/service failure.
 */
static int acquire_reversal_authority(
        int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->rolling_authority_active ||
            !runtime->route_valid ||
            runtime->stop_purpose != TC2_STOP_REVERSAL ||
            runtime->leg_end_offset <
                    runtime->leg_start_offset ||
            runtime->leg_end_offset >=
                    job->destination_route_offset) {
                return -1;
        }
        int next_leg = runtime->leg_end_offset + 1;
        if (next_leg + 1 >= runtime->route.node_count ||
            dispatch_track[
                    runtime->route.nodes[
                            runtime->leg_end_offset]]
                            .reverse !=
                    &dispatch_track[
                            runtime->route.nodes[next_leg]]) {
                return -1;
        }
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid,
                    &reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0 ||
            reservation
                            .generation_by_train[job->train] !=
                    job->plan_generation ||
            reservation
                            .destination_by_train[job->train] !=
                    job->target_node ||
            sensor_health_is_safe(
                    slot, &sensors, 0, now) < 0) {
                return -1;
        }
        int can_health = can_health_is_safe(slot, 0, now);
        if (can_health == TC2_CAN_HEALTH_HARD_FAIL) return -1;
        if (can_health == TC2_CAN_HEALTH_RETRY) return 1;
        int progress_mm;
        if (route_distance_to_offset(
                    &runtime->route, next_leg,
                    &progress_mm) < 0) {
                return -1;
        }
        int selected_speed = job->speed;
        track_route outbound;
        outbound.node_count = 0;
        outbound.distance_mm = 0;
        outbound.optimization_cost_mm = 0;
        outbound.reversal_count = 0;
        track_reservation_conflict conflict;
        int outbound_end = -1;
        int outbound_ceiling = -1;
        int selected =
                select_bounded_rolling_authority_window(
                        &runtime->route, next_leg,
                        next_leg + 1,
                        job->target_route_offset,
                        job->destination_route_offset,
                        job->destination_offset_mm,
                        job->destination_distance_mm,
                        selected_speed, 1, progress_mm,
                        job->train, &reservation, &sensors,
                        &outbound, &outbound_end,
                        &outbound_ceiling, &selected_speed,
                        &conflict);
        if (selected > 0) {
                job->conflict_train =
                        conflict.owner_train;
                job->conflict_node =
                        conflict.node_index;
                if (begin_authority_request(
                            slot, now,
                            outbound.node_count > 0 ?
                                    &outbound : 0) < 0) {
                        return -1;
                }
                return 1;
        }
        if (selected < 0 ||
            outbound_end < next_leg + 1 ||
            outbound_ceiling < progress_mm) {
                return -1;
        }

        track_route incoming =
                runtime->safety_footprint;
        if (incoming.node_count < 1 ||
            append_route_nodes(
                    &outbound, &incoming) < 0) {
                return -1;
        }
        if (begin_authority_request(
                    slot, now, &outbound) < 0) {
                return -1;
        }
        int yield =
                authority_prefetch_must_yield(
                        slot, now, &outbound,
                        &reservation);
        if (yield < 0) return -1;
        if (yield > 0) return 1;

        unsigned int generation = 0;
        int update =
                TrackReservationServerUpdateWindow(
                        dispatch_reservation_tid,
                        &outbound, job->train,
                        job->target_node,
                        job->plan_generation,
                        &conflict, &generation);
        if (update == 1) {
                job->conflict_train =
                        conflict.owner_train;
                job->conflict_node =
                        conflict.node_index;
                return 1;
        }
        if (update < 0 ||
            generation != job->plan_generation) {
                return -1;
        }

        unsigned int baseline =
                runtime->last_journal_sequence;
        runtime->reversal_carry_footprint =
                incoming;
        runtime->reversal_carry_active = 1;
        runtime->reversal_carry_origin_offset =
                next_leg;
        runtime->safety_footprint = outbound;
        runtime->authority_end_offset =
                outbound_end;
        runtime->authority_center_ceiling_mm =
                outbound_ceiling;
        runtime->authority_prefetch_active = 0;
        runtime->authority_prefetch_end_offset = -1;
        runtime->authority_prefetch_center_ceiling_mm = -1;
        runtime->authority_prefetch_settle_at_tick = -1;
        runtime->authority_prefetch_rearm_progress_mm = -1;
        clear_authority_request(runtime);
        runtime->planned_launch_speed =
                selected_speed;
        runtime->leg_start_offset = next_leg;
        ++job->reversals_completed;
        ++job->current_leg;
        if (init_leg_monitor(slot, baseline) < 0) {
                return -1;
        }
        job->conflict_train = 0;
        job->conflict_node = -1;
        return 0;
}

/*
 * Two stationary rolling-authority jobs can form a real wait-for cycle when
 * each next local window contains track still owned by the other.  This is
 * distinct from an ordinary FIFO intersection wait: neither grant can make
 * progress without first changing one physical plan.
 *
 * Promote only a mutual two-owner cycle whose live physical corridors are
 * actually opposite.  A same-direction follower can temporarily report a
 * reciprocal local-authority wait while the leader is releasing its old
 * window; relabelling that transient state as HEAD_ON permanently freezes
 * both trains and incorrectly demands operator recovery.
 *
 * The existing traffic-hold reservation remains untouched, so the operator
 * can safely:
 *   1. cancel one train, wait for STOPPED, physically remove it, then remove;
 *   2. stage a CURRENT destination for either train and let the atomic
 *      replacement choose a reverse/reroute path.
 */
static void expose_mutual_authority_deadlocks(int now) {
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_TRAFFIC_HOLD ||
                    runtime->traffic_reason !=
                            TC2_TRAFFIC_AUTHORITY ||
                    runtime->stop_purpose !=
                            TC2_STOP_TRAFFIC ||
                    job->conflict_train < 1 ||
                    job->conflict_train > 255) {
                        continue;
                }
                int peer =
                        find_train_job(job->conflict_train);
                if (peer <= slot) continue;
                tc2_dispatch_job_snapshot *peer_job =
                        &dispatch_jobs[peer];
                tc2_dispatch_runtime *peer_runtime =
                        &dispatch_runtime[peer];
                if (peer_job->state !=
                            TC2_JOB_TRAFFIC_HOLD ||
                    peer_runtime->traffic_reason !=
                            TC2_TRAFFIC_AUTHORITY ||
                    peer_runtime->stop_purpose !=
                            TC2_STOP_TRAFFIC ||
                    peer_job->conflict_train != job->train) {
                        continue;
                }

                tc2_live_traffic_relation relation;
                if (live_traffic_relation_for_pair(
                            slot, peer, now,
                            &relation) < 0 ||
                    !relation.valid ||
                    relation.order_ambiguous ||
                    relation.relation !=
                            TC2_TRAFFIC_RELATION_HEAD_ON ||
                    relation.emergency_gap_mm >=
                            TC2_TRAFFIC_EMERGENCY_CLEARANCE_MM) {
                        continue;
                }

                runtime->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                runtime->traffic_blockers_now |=
                        traffic_slot_bit(peer);
                runtime->traffic_head_on_latches |=
                        traffic_slot_bit(peer);
                runtime->traffic_peer_train =
                        peer_job->train;
                job->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                job->traffic_peer_train =
                        peer_job->train;
                peer_runtime->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                peer_runtime->traffic_blockers_now |=
                        traffic_slot_bit(slot);
                peer_runtime->traffic_head_on_latches |=
                        traffic_slot_bit(slot);
                peer_runtime->traffic_peer_train =
                        job->train;
                peer_job->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                peer_job->traffic_peer_train =
                        job->train;
        }
}

/*
 * First-arrival ordered rolling-authority extension.
 *
 * The reservation CAS happens before any turnout command.  A successful CAS
 * preserves the plan generation, replaces only the rolling footprint, and
 * then moves the stationary train through PREPARING/READY/LAUNCHING.  The
 * launch confirmation path rebases motion at the frozen coast endpoint, so
 * neither the controller nor the UI can jump back to an old sensor.
 */
static void process_authority_holds(int now) {
        unsigned char processed[TC2_DISPATCH_MAX_JOBS];
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                processed[slot] = 0;
                if (dispatch_jobs[slot].state ==
                            TC2_JOB_TRAFFIC_HOLD &&
                    dispatch_runtime[slot]
                            .traffic_reason ==
                            TC2_TRAFFIC_AUTHORITY &&
                    !dispatch_runtime[slot]
                            .conflict_zone_hold_active &&
                    dispatch_runtime[slot]
                            .authority_request_tick < 0) {
                        (void)begin_authority_request(
                                slot, now, 0);
                }
        }

        for (int pass = 0;
             pass < TC2_DISPATCH_MAX_JOBS; ++pass) {
                int oldest = -1;
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (processed[slot] ||
                            dispatch_jobs[slot].state !=
                                    TC2_JOB_TRAFFIC_HOLD ||
                            dispatch_runtime[slot]
                                    .traffic_reason !=
                                    TC2_TRAFFIC_AUTHORITY ||
                            dispatch_runtime[slot]
                                    .conflict_zone_hold_active) {
                                continue;
                        }
                        if (authority_request_has_priority(
                                    slot, oldest)) {
                                oldest = slot;
                        }
                }
                if (oldest < 0) break;
                processed[oldest] = 1;

                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[oldest];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[oldest];
                if (!authority_route_metadata_is_valid(
                            oldest)) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_ROUTE);
                        continue;
                }
                /*
                 * A turnout/intersection gate can stop a train while a
                 * rolling prefetch suffix is already reserved but not yet
                 * promoted.  Stationary recovery replaces that suffix with
                 * a fresh bounded window; carrying the old prefetch marker
                 * across the replacement makes active_end == prefetch_end
                 * and the next RUNNING pass (correctly) rejects the stale
                 * invariant.  First shrink ownership back to the confirmed
                 * active window, then take the snapshot used for this FIFO
                 * request.  This is route- and train-independent.
                 */
                if (runtime->authority_prefetch_active &&
                    abandon_authority_prefetch(oldest) < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_RESERVATION);
                        continue;
                }
                track_reservation_snapshot reservation;
                train_sensor_snapshot_t sensors;
                if (TrackReservationServerSnapshot(
                            dispatch_reservation_tid,
                            &reservation) < 0 ||
                    TrainSensorGetLatest(
                            dispatch_sensor_tid,
                            &sensors) < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_RESERVATION_SERVICE);
                        continue;
                }
                if (reservation
                                    .generation_by_train[job->train] !=
                            job->plan_generation ||
                    reservation
                                    .destination_by_train[job->train] !=
                            job->target_node) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_RESERVATION);
                        continue;
                }
                if (sensor_health_is_safe(
                            oldest, &sensors, 0, now) < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_SENSOR_SERVICE);
                        continue;
                }
                int can_health = can_health_is_safe(
                        oldest, 0, now);
                if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (can_health == TC2_CAN_HEALTH_RETRY) continue;
                if (!authority_dynamic_resume_is_safe(
                            oldest, now,
                            &reservation)) {
                        continue;
                }
                int correction_authority_end = -1;
                if (runtime->destination_correction_pending ||
                    runtime->destination_correction_active) {
                        correction_authority_end =
                                job->destination_route_offset;
                        if (correction_authority_end <
                                    job->current_route_offset ||
                            correction_authority_end >=
                                    runtime->route.node_count) {
                                fail_job(
                                        oldest,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                }
                /*
                 * Once the complete route through d is owned, a settled
                 * zero-speed train whose destination is still unconfirmed
                 * must enter the explicit scalar correction before another
                 * ordinary rolling resume is considered.  Otherwise an
                 * ordinary lower speed can win repeatedly, stop at another
                 * conservative authority boundary, and never reach the next
                 * real detector.  Staging sends no positive command: the
                 * normal PREPARING path still reacquires and verifies next,
                 * nextnext, turnout settling and all-train safety first.
                 */
                if (runtime->rolling_authority_active &&
                    runtime->authority_end_offset >=
                            (correction_authority_end >= 0 ?
                             correction_authority_end :
                             job->destination_route_offset)) {
                        int trusted_progress_mm;
                        int64_t occupancy_upper_um = 0;
                        if (traffic_hold_progress_bounds(
                                    oldest,
                                    &trusted_progress_mm,
                                    &occupancy_upper_um) < 0) {
                                fail_job(
                                        oldest,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        int64_t remaining_mm64 =
                                (int64_t)job
                                                ->destination_distance_mm -
                                trusted_progress_mm;
                        int remaining_mm =
                                remaining_mm64 >= 0 &&
                                        remaining_mm64 <= 0x7fffffff ?
                                (int)remaining_mm64 : -1;
                        int can_stage_final_correction =
                                correction_authority_end < 0 &&
                                !runtime->target_seen &&
                                !runtime
                                        ->destination_correction_attempted &&
                                !runtime
                                        ->destination_correction_pending &&
                                !runtime
                                        ->destination_correction_active &&
                                runtime->command_speed == 0 &&
                                job->command_speed == 0 &&
                                trusted_progress_mm >= 0 &&
                                trusted_progress_mm <
                                        job->destination_distance_mm &&
                                traffic_has_movement_authority(
                                        oldest, &reservation);
                        if (can_stage_final_correction) {
                                int correction_sensor =
                                        destination_correction_sensor_offset(
                                                oldest,
                                                (int64_t)
                                                                trusted_progress_mm *
                                                        1000);
                                int staged =
                                        stage_bounded_destination_correction(
                                                oldest,
                                                correction_sensor);
                                if (staged < 0) {
                                        fail_job(
                                                oldest,
                                                TC2_FAILURE_INTERNAL);
                                }
                                continue;
                        }
                        int resume_speed =
                                correction_authority_end >= 0 ?
                                (remaining_mm > 0 ?
                                 TC2_DESTINATION_CORRECTION_SPEED : -1) :
                                authority_resume_speed_for_window(
                                        oldest, job->speed, remaining_mm,
                                        runtime->authority_end_offset,
                                        runtime
                                                ->authority_center_ceiling_mm);
                        (void)occupancy_upper_um;
                        if (resume_speed < 1) {
                                continue;
                        }
                        runtime->traffic_resume_speed =
                                resume_speed;
                        int staged_resume =
                                defer_traffic_resume_for_conflict_zone(
                                        oldest, now);
                        if (staged_resume < 0) {
                                fail_job(
                                        oldest,
                                        TC2_FAILURE_INTERNAL);
                        }
                        continue;
                }
                if (!runtime->rolling_authority_active ||
                    runtime->authority_end_offset < 0 ||
                    runtime->authority_end_offset >=
                            (correction_authority_end >= 0 ?
                             correction_authority_end :
                             job->destination_route_offset) ||
                    runtime->traffic_hold_distance_um < 0 ||
                    runtime->traffic_resume_speed < 1 ||
                    runtime->traffic_resume_speed > 120) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_INTERNAL);
                        continue;
                }

                int tail =
                        footprint_tail_offset(
                                runtime, job);
                int trusted_progress_mm;
                int64_t occupancy_upper_um;
                if (traffic_hold_progress_bounds(
                            oldest, &trusted_progress_mm,
                            &occupancy_upper_um) < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_INTERNAL);
                        continue;
                }
                int occupancy_upper_mm =
                        occupancy_upper_um <= 0 ? 0 :
                        (int)((occupancy_upper_um + 999) / 1000);
                int64_t remaining_mm64 =
                        (int64_t)job->destination_distance_mm -
                        trusted_progress_mm;
                int remaining_mm =
                        remaining_mm64 >= 0 &&
                                remaining_mm64 <= 0x7fffffff ?
                        (int)remaining_mm64 : -1;
                int authority_speed =
                        correction_authority_end >= 0 ?
                        TC2_DESTINATION_CORRECTION_SPEED :
                        authority_resume_speed_for_remaining(
                                job->speed,
                                remaining_mm);
                if (tail < 0 ||
                    tail > runtime->authority_end_offset ||
                    occupancy_upper_mm < 0 ||
                    remaining_mm < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (authority_speed < 1) {
                        /*
                         * A real detector has not proved enough remaining
                         * route for any calibrated positive speed.  Preserve
                         * the stopped body and its FIFO request; this is a
                         * fail-closed localization wait, not an internal
                         * scheduler failure.
                         */
                        continue;
                }

                track_route extension;
                extension.node_count = 0;
                extension.distance_mm = 0;
                extension.optimization_cost_mm = 0;
                extension.reversal_count = 0;
                track_reservation_conflict conflict;
                int new_end = -1;
                int new_ceiling = -1;
                int selected_window_speed = -1;
                int selected =
                        select_bounded_rolling_authority_window_for_leg(
                                &runtime->route, tail,
                                runtime->leg_start_offset,
                                correction_authority_end >= 0 ?
                                        correction_authority_end :
                                        runtime
                                                        ->authority_end_offset +
                                                1,
                                job->target_route_offset,
                                job->destination_route_offset,
                                job->destination_offset_mm,
                                job->destination_distance_mm,
                                authority_speed,
                                correction_authority_end < 0,
                                occupancy_upper_mm,
                                job->train,
                                &reservation, &sensors,
                                &extension, &new_end,
                                &new_ceiling,
                                &selected_window_speed,
                                &conflict);
                if (selected > 0) {
                        job->conflict_train =
                                conflict.owner_train;
                        job->conflict_node =
                                conflict.node_index;
                        /*
                         * No bounded ordinary-speed window and no concrete
                         * owner conflict means that braking geometry, not a
                         * peer, is keeping this settled train behind its next
                         * detector.  Promote it to the same explicit final
                         * correction state.  That state first requests the
                         * complete destination suffix at speed 40 and cannot
                         * launch until the central next/nextnext and safety
                         * arbiter accepts it.  This is per-job and therefore
                         * remains valid for any number of trains/routes.
                         */
                        int can_request_final_correction =
                                correction_authority_end < 0 &&
                                conflict.node_index < 0 &&
                                conflict.owner_train == 0 &&
                                !runtime->target_seen &&
                                !runtime
                                        ->destination_correction_attempted &&
                                !runtime
                                        ->destination_correction_pending &&
                                !runtime
                                        ->destination_correction_active &&
                                runtime->command_speed == 0 &&
                                job->command_speed == 0 &&
                                trusted_progress_mm >= 0 &&
                                trusted_progress_mm <
                                        job->destination_distance_mm;
                        if (can_request_final_correction) {
                                int correction_sensor =
                                        destination_correction_sensor_offset(
                                                oldest,
                                                (int64_t)
                                                                trusted_progress_mm *
                                                        1000);
                                int staged =
                                        stage_bounded_destination_correction(
                                                oldest,
                                                correction_sensor);
                                if (staged < 0) {
                                        fail_job(
                                                oldest,
                                                TC2_FAILURE_INTERNAL);
                                }
                                continue;
                        }
                        if (begin_authority_request(
                                    oldest, now,
                                    extension.node_count > 0 ?
                                            &extension : 0) < 0) {
                                fail_job(
                                        oldest,
                                        TC2_FAILURE_INTERNAL);
                        }
                        continue;
                }
                if (selected < 0 ||
                    new_end <=
                            runtime->authority_end_offset ||
                    (correction_authority_end >= 0 &&
                     (new_end < correction_authority_end ||
                    selected_window_speed !=
                              TC2_DESTINATION_CORRECTION_SPEED)) ||
                    new_ceiling <
                            occupancy_upper_mm ||
                    selected_window_speed < 1 ||
                    selected_window_speed >
                            authority_speed) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_ROUTE);
                        continue;
                }
                if (correction_authority_end < 0 &&
                    !traffic_resume_fits_authority_window(
                            oldest, selected_window_speed,
                            new_end, new_ceiling)) {
                        /*
                         * The latest detector may leave useful route ahead
                         * while the conservative coast upper bound leaves no
                         * provable stopping room in this candidate.  Keep the
                         * train stopped and retry after stronger localization
                         * or a larger authority window; never commit a
                         * positive-speed launch from the trusted scalar alone.
                         */
                        continue;
                }
                if (begin_authority_request(
                            oldest, now,
                            &extension) < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_INTERNAL);
                        continue;
                }
                /*
                 * FIFO is local to the resources this extension would add.
                 * Comparing complete remaining routes here would make a
                 * distant merge block a train at its present authority limit
                 * even though every intervening block is free.
                 */
                int yield_to_older =
                        authority_prefetch_must_yield(
                                oldest, now, &extension,
                                &reservation);
                if (yield_to_older < 0) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_ROUTE);
                        continue;
                }
                if (yield_to_older > 0) {
                        continue;
                }

                unsigned int generation = 0;
                int update =
                        TrackReservationServerUpdateWindow(
                                dispatch_reservation_tid,
                                &extension, job->train,
                                job->target_node,
                                job->plan_generation,
                                &conflict, &generation);
                if (update == 1) {
                        job->conflict_train =
                                conflict.owner_train;
                        job->conflict_node =
                                conflict.node_index;
                        continue;
                }
                if (update < 0 ||
                    generation !=
                            job->plan_generation) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_RESERVATION);
                        continue;
                }

                int old_end =
                        runtime->authority_end_offset;
                runtime->safety_footprint =
                        extension;
                runtime->authority_previous_end_offset =
                        old_end;
                runtime->authority_end_offset =
                        new_end;
                runtime->authority_center_ceiling_mm =
                        new_ceiling;
                /*
                 * This request has acquired its exact local window.  Its FIFO
                 * turn is therefore consumed now; a later extension (and a
                 * later shared intersection) must take a fresh ticket.
                 */
                clear_authority_request(runtime);
                runtime->authority_resume_pending = 1;
                /*
                 * Admission is closed until the next complete dynamic
                 * traffic pass evaluates the frozen train against every
                 * other managed position.
                 */
                runtime->prelaunch_traffic_blocked = 1;
                runtime->traffic_resume_speed =
                        selected_window_speed;
                runtime->planned_launch_speed =
                        selected_window_speed;
                runtime->ready_wave_tick = -1;
                runtime->prepare_attributed_sequence =
                        sensors.attributed_count;
                runtime
                        ->prepare_attribution_unavailable_count =
                        sensors
                                .attribution_unavailable_count;
                runtime->prepare_unattributed_count =
                        sensors.unattributed_count;
                for (int sensor_index = 0;
                     sensor_index < TRAIN_SENSOR_COUNT;
                     ++sensor_index) {
                        runtime
                                ->prepare_sensor_state[sensor_index] =
                                sensors
                                        .sensor_state[sensor_index];
                }
                job->conflict_train = 0;
                job->conflict_node = -1;
                job->ready_at_tick = -1;

                int turnout_token =
                        queue_turnout_plan_for_leg(
                                oldest);
                if (turnout_token < 0 &&
                    turnout_token != CAN_SEND_BUSY) {
                        fail_job(
                                oldest,
                                TC2_FAILURE_TURNOUT);
                        continue;
                }
                runtime->turnout_queue_pending =
                        turnout_token == CAN_SEND_BUSY;
                runtime->turnout_batch_token =
                        turnout_token > 0 ?
                        (unsigned int)turnout_token : 0;
                job->state = TC2_JOB_PREPARING;
        }
        expose_mutual_authority_deadlocks(now);
}

/*
 * Keep at most one not-yet-usable authority window in front of a moving
 * train.  The reservation CAS may succeed while the train continues under
 * its old ceiling, but that ceiling is never promoted until every turnout in
 * the new suffix is confirmed and has completed its mechanical settle time.
 *
 * `authority_prefetch_rearm_progress_mm` prevents a stationary train from
 * chaining successful prefetches until it owns its whole route.  Rearming is
 * nevertheless early enough that a moving train can prepare the following
 * bounded window before reaching the old ceiling.
 */
static int process_running_authority_prefetch(
        int slot, int now,
        const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !reservation || !sensors) {
                return TC2_FAILURE_INTERNAL;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (job->state != TC2_JOB_RUNNING ||
            !runtime->rolling_authority_active ||
            !runtime->route_valid ||
            runtime->authority_end_offset < 0 ||
            runtime->authority_end_offset >=
                    runtime->route.node_count ||
            runtime->authority_center_ceiling_mm < 0) {
                return 0;
        }

        if (runtime->authority_prefetch_active) {
                if (runtime->authority_prefetch_end_offset <=
                            runtime->authority_end_offset ||
                    runtime->authority_prefetch_end_offset >=
                            runtime->route.node_count ||
                    runtime
                                    ->authority_prefetch_center_ceiling_mm <=
                            runtime->authority_center_ceiling_mm) {
                        return TC2_FAILURE_INTERNAL;
                }
                if (runtime->turnout_queue_pending) {
                        int queued =
                                queue_turnout_plan_range(
                                        slot,
                                        runtime
                                                ->authority_end_offset,
                                        runtime
                                                ->authority_prefetch_end_offset);
                        if (queued == CAN_SEND_BUSY) {
                                return 0;
                        }
                        if (queued < 0) {
                                return TC2_FAILURE_TURNOUT;
                        }
                        runtime->turnout_queue_pending = 0;
                        runtime->turnout_batch_token =
                                queued > 0 ?
                                (unsigned int)queued : 0;
                        runtime->authority_prefetch_settle_at_tick =
                                queued == 0 ? now : -1;
                }
                if (runtime->turnout_batch_token != 0) {
                        can_batch_status_t status;
                        unsigned int token =
                                runtime->turnout_batch_token;
                        if (CanGetBatchStatus(
                                    dispatch_can_tid, token,
                                    &status) < 0 ||
                            status.token != token ||
                            status.total < 1) {
                                return TC2_FAILURE_TURNOUT;
                        }
                        if (status.state == CAN_BATCH_FAILED) {
                                int retry =
                                        queue_turnout_plan_range(
                                                slot,
                                                runtime
                                                        ->authority_end_offset,
                                                runtime
                                                        ->authority_prefetch_end_offset);
                                if (retry == CAN_SEND_BUSY) {
                                        runtime
                                                ->turnout_batch_token = 0;
                                        runtime
                                                ->turnout_queue_pending = 1;
                                        return 0;
                                }
                                if (retry < 0) {
                                        return TC2_FAILURE_TURNOUT;
                                }
                                runtime->turnout_batch_token =
                                        retry > 0 ?
                                        (unsigned int)retry : 0;
                                runtime
                                        ->authority_prefetch_settle_at_tick =
                                        retry == 0 ? now : -1;
                                return 0;
                        }
                        if (status.state != CAN_BATCH_COMPLETE ||
                            status.confirmed != status.total) {
                                return 0;
                        }
                        runtime->turnout_batch_token = 0;
                        runtime->authority_prefetch_settle_at_tick =
                                tick_after(
                                        now,
                                        TC2_TURNOUT_SETTLE_TICKS);
                        return 0;
                }
                if (runtime->authority_prefetch_settle_at_tick < 0 ||
                    !tick_reached(
                            now,
                            runtime
                                    ->authority_prefetch_settle_at_tick)) {
                        return 0;
                }

                int old_ceiling =
                        runtime->authority_center_ceiling_mm;
                runtime->authority_previous_end_offset =
                        runtime->authority_end_offset;
                runtime->authority_end_offset =
                        runtime->authority_prefetch_end_offset;
                runtime->authority_center_ceiling_mm =
                        runtime
                                ->authority_prefetch_center_ceiling_mm;
                runtime->authority_prefetch_active = 0;
                runtime->authority_prefetch_end_offset = -1;
                runtime
                        ->authority_prefetch_center_ceiling_mm = -1;
                runtime->authority_prefetch_settle_at_tick = -1;
                runtime->authority_prefetch_rearm_progress_mm =
                        old_ceiling;
                job->conflict_train = 0;
                job->conflict_node = -1;
                clear_authority_request(runtime);
                return 0;
        }

        /*
         * A reversal sensor is the exact terminal of the current motion leg.
         * Never prefetch across it while moving; the stopped reversal
         * handoff atomically acquires the next outbound window.
         */
        if (runtime->leg_end_offset <
                    job->destination_route_offset &&
            runtime->authority_end_offset >=
                    runtime->leg_end_offset) {
                return 0;
        }

        if (runtime->authority_end_offset >=
            job->destination_route_offset) {
                return 0;
        }
        int64_t progress_um;
        int braking_envelope =
                traffic_braking_envelope_mm(slot);
        if (runtime_motion_progress_um(
                    slot, now, &progress_um) < 0 ||
            progress_um < 0 || braking_envelope < 0) {
                return TC2_FAILURE_INTERNAL;
        }
        int current_progress_mm =
                (int)((progress_um + 999) / 1000);
        int speed = traffic_effective_speed(slot);
        if (speed < 1 || speed > 120) {
                return TC2_FAILURE_INTERNAL;
        }
        /*
         * Continue prefetch at the speed which is physically still in
         * effect.  A stationary authority recovery may deliberately grant a
         * lower calibrated speed because only that stop envelope fits the
         * current local window.  Replacing it here with job->speed makes the
         * next moving prefetch reject the very window which was just granted
         * and creates a stop/lower-speed/stop loop.  The requested speed is
         * restored separately by authority_restore_requested_speed(), after
         * a farther window is committed and a real sensor has rebased the
         * train.
         */
        int selection_speed = speed;
        int prefetch_lead =
                authority_prefetch_lead_mm(speed);
        int sensor_rebase_route =
                uses_measured_direct_stop(job);
        int final_approach_suffix_required = 0;
        if (uses_measured_direct_stop(job) &&
            runtime->leg_end_offset ==
                    job->destination_route_offset &&
            runtime->authority_end_offset <
                    job->destination_route_offset) {
                int prior_sensor =
                        sensor_before_offset(
                                &runtime->route,
                                job->target_route_offset);
                final_approach_suffix_required =
                        prior_sensor >= 0 &&
                        runtime->authority_end_offset >=
                                prior_sensor;
        }
        /*
         * A detector report can legitimately rebase progress by more than
         * one scheduler tick.  On the final approach, begin the conflict-
         * checked suffix request one additional CAN/settle lead early so an
         * ordered forward report cannot jump from just before the ordinary
         * trigger to beyond the old hard braking line.
         */
        int trigger_lead = prefetch_lead;
        /*
         * Track-D can omit adjacent reports on any direct physical route. A
         * later ordered detector is still valid evidence, but can rebase
         * progress across two intervals at once. Begin every such direct-trip
         * extension three CAN/settle leads early, not only the final suffix,
         * so that a legitimate rebase remains inside confirmed movement
         * authority. Selection stays progressive, local, and conflict
         * checked; this does not reserve the whole route at departure.
         */
        if (sensor_rebase_route) {
                trigger_lead =
                        saturated_threshold_add(
                                prefetch_lead,
                                prefetch_lead);
                trigger_lead =
                        saturated_threshold_add(
                                trigger_lead,
                                prefetch_lead);
        }
        if (final_approach_suffix_required) {
                trigger_lead =
                        saturated_threshold_add(
                                prefetch_lead,
                                prefetch_lead);
                trigger_lead =
                        saturated_threshold_add(
                                trigger_lead,
                                prefetch_lead);
        }
        if (runtime->authority_prefetch_rearm_progress_mm >= 0) {
                int rearm_progress =
                        runtime
                                ->authority_prefetch_rearm_progress_mm;
                /*
                 * Rearm before the old ceiling on every route, not only the
                 * sparse/final special cases.  This is still progressive:
                 * the train must physically enter this look-ahead band, and
                 * only one bounded not-yet-usable window exists at a time.
                 * Using the full trigger lead absorbs both CAN/settle delay
                 * and a legitimate sensor rebase without reverting to a
                 * route-wide departure reservation.
                 */
                rearm_progress =
                        rearm_progress > trigger_lead ?
                        rearm_progress - trigger_lead : 0;
                if (current_progress_mm <= rearm_progress) {
                        return 0;
                }
                runtime->authority_prefetch_rearm_progress_mm = -1;
        }
        int prefetch_headroom =
                saturated_threshold_add(
                        braking_envelope,
                        trigger_lead);
        if (prefetch_headroom < 0 ||
            runtime->authority_center_ceiling_mm -
                            current_progress_mm >
                    prefetch_headroom) {
                return 0;
        }

        int tail = footprint_tail_offset(runtime, job);
        if (tail < 0 || tail > runtime->authority_end_offset) {
                return TC2_FAILURE_INTERNAL;
        }
        track_route extension;
        extension.node_count = 0;
        extension.distance_mm = 0;
        extension.optimization_cost_mm = 0;
        extension.reversal_count = 0;
        track_reservation_conflict conflict;
        int new_end = -1;
        int new_ceiling = -1;
        int selected_window_speed = -1;
        int next_window_origin =
                saturated_threshold_add(
                        runtime
                                ->authority_center_ceiling_mm,
                        prefetch_lead);
        int required_confirmation_leads =
                speed == 120 ? 3 : 2;
        for (int lead_index = 1;
             lead_index < required_confirmation_leads &&
             next_window_origin >= 0;
             ++lead_index) {
                next_window_origin =
                        saturated_threshold_add(
                                next_window_origin,
                                prefetch_lead);
        }
        if (next_window_origin < 0) {
                return TC2_FAILURE_INTERNAL;
        }
        int selected =
                select_bounded_rolling_authority_window_for_leg(
                        &runtime->route, tail,
                        runtime->leg_start_offset,
                        runtime->authority_end_offset + 1,
                        job->target_route_offset,
                        job->destination_route_offset,
                        job->destination_offset_mm,
                        job->destination_distance_mm,
                        /*
                         * Include at least a second CAN/settle lead in the
                         * requested origin before requiring a complete stop.
                         * Command 120 keeps a third lead because one scheduler
                         * sensor rebase can consume most of the first lead
                         * before the next turnout batch is queued (the
                         * observed A->d3 pause at C9/C10).
                         *
                         * A single
                         * lead left only three millimetres between the A->d3
                         * re-arm point and its next prefetch trigger; the hard
                         * E7 observation could jump across that boundary and
                         * force speed zero before another scheduler cycle.
                         * The extra confirmation lead moves the local boundary
                         * far enough ahead to absorb a detector rebase while
                         * retaining one bounded braking window and releasing
                         * the tail normally.
                         */
                        selection_speed,
                        0,
                        next_window_origin,
                        job->train, reservation, sensors,
                        &extension, &new_end, &new_ceiling,
                        &selected_window_speed,
                        &conflict);
        /*
         * Near the destination, the requested-speed braking envelope can
         * extend beyond every remaining intermediate authority boundary.
         * The bounded selector then either offers a shorter low-speed prefix
         * or has no local prefix at all, even though the clear complete
         * destination footprint is the only window that can preserve the
         * already acknowledged command speed.  A moving train cannot safely
         * apply a lower-speed envelope retroactively: try the final suffix
         * instead.  This remains rolling authority because the released tail
         * is not reacquired, and the ordinary occupancy/reservation check can
         * still reject a shared or blocked suffix.
         */
        if (final_approach_suffix_required ||
            (selected == 0 &&
             selected_window_speed < selection_speed) ||
            (selected > 0 &&
             conflict.node_index < 0)) {
                track_route final_extension;
                final_extension.node_count = 0;
                final_extension.distance_mm = 0;
                final_extension.optimization_cost_mm = 0;
                final_extension.reversal_count = 0;
                track_reservation_conflict final_conflict;
                final_conflict.node_index = -1;
                final_conflict.owner_train = 0;
                int final_end = -1;
                int final_ceiling = -1;
                int final_window_origin =
                        saturated_threshold_add(
                                current_progress_mm,
                                prefetch_lead);
                if (final_window_origin < 0) {
                        return TC2_FAILURE_INTERNAL;
                }
                int final_status =
                        select_rolling_authority_window_for_leg(
                                &runtime->route, tail,
                                runtime->leg_start_offset,
                                job->destination_route_offset,
                                job->target_route_offset,
                                job->destination_route_offset,
                                job->destination_offset_mm,
                                job->destination_distance_mm,
                                selection_speed,
                                final_window_origin,
                                job->train, reservation, sensors,
                                &final_extension, &final_end,
                                &final_ceiling,
                                &final_conflict);
                if (final_status < 0) {
                        return TC2_FAILURE_ROUTE;
                }
                if (final_status == 0 &&
                    final_end ==
                            job->destination_route_offset) {
                        extension = final_extension;
                        new_end = final_end;
                        new_ceiling = final_ceiling;
                        selected_window_speed =
                                selection_speed;
                        selected = 0;
                        conflict.node_index = -1;
                        conflict.owner_train = 0;
                }
        }
        if (selected > 0) {
                job->conflict_train =
                        conflict.owner_train;
                job->conflict_node =
                        conflict.node_index;
                if (begin_authority_request(
                            slot, now,
                            extension.node_count > 0 ?
                                    &extension : 0) < 0) {
                        return TC2_FAILURE_INTERNAL;
                }
                return 0;
        }
        if (selected < 0 ||
            new_end <= runtime->authority_end_offset ||
            new_ceiling <=
                    runtime->authority_center_ceiling_mm) {
                return TC2_FAILURE_ROUTE;
        }
        /*
         * The bounded suffix is safe only at a lower command.  Do not enlarge
         * authority using that smaller envelope while the train is still
         * moving at the old acknowledged speed.  It will stop under the
         * already-owned ceiling; the stationary authority path can then grant
         * this same bounded window and relaunch at selected_window_speed.
         */
        if (selected_window_speed < selection_speed) {
                return 0;
        }

        if (begin_authority_request(
                    slot, now, &extension) < 0) {
                return TC2_FAILURE_INTERNAL;
        }
        int yield =
                authority_prefetch_must_yield(
                        slot, now, &extension, reservation);
        if (yield < 0) {
                return TC2_FAILURE_ROUTE;
        }
        if (yield > 0) {
                return 0;
        }

        unsigned int generation = 0;
        int update =
                TrackReservationServerUpdateWindow(
                        dispatch_reservation_tid,
                        &extension, job->train,
                        job->target_node,
                        job->plan_generation,
                        &conflict, &generation);
        if (update == 1) {
                job->conflict_train =
                        conflict.owner_train;
                job->conflict_node =
                        conflict.node_index;
                return 0;
        }
        if (update < 0 ||
            generation != job->plan_generation) {
                return TC2_FAILURE_RESERVATION;
        }

        runtime->safety_footprint = extension;
        runtime->authority_prefetch_active = 1;
        runtime->authority_prefetch_end_offset = new_end;
        runtime->authority_prefetch_center_ceiling_mm =
                new_ceiling;
        runtime->authority_prefetch_settle_at_tick = -1;
        /*
         * Ownership of this exact extension has committed.  Do not carry its
         * FIFO age into a different downstream turnout.
         */
        clear_authority_request(runtime);
        int turnout_token =
                queue_turnout_plan_range(
                        slot,
                        runtime->authority_end_offset,
                        new_end);
        if (turnout_token < 0 &&
            turnout_token != CAN_SEND_BUSY) {
                return TC2_FAILURE_TURNOUT;
        }
        runtime->turnout_queue_pending =
                turnout_token == CAN_SEND_BUSY;
        runtime->turnout_batch_token =
                turnout_token > 0 ?
                (unsigned int)turnout_token : 0;
        runtime->authority_prefetch_settle_at_tick =
                turnout_token == 0 ? now : -1;
        job->conflict_train = 0;
        job->conflict_node = -1;
        return 0;
}

/*
 * If CAN/turnout confirmation cannot finish before the active braking
 * boundary, release the unused pending suffix and stop under the old active
 * authority.  The normal stationary FIFO extension path may acquire it
 * again later; no unconfirmed turnout ever enlarges movement authority.
 */
static int abandon_authority_prefetch(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->authority_prefetch_active) return 0;
        if (runtime->turnout_batch_token != 0) {
                (void)CanCancelBatch(
                        dispatch_can_tid,
                        runtime->turnout_batch_token);
        }
        track_route active;
        int tail = footprint_tail_offset(runtime, job);
        int footprint_speed =
                traffic_effective_speed(slot);
        if (tail < 0 ||
            footprint_speed < 1 ||
            build_local_authority_footprint(
                    &runtime->route, tail,
                    runtime->authority_end_offset,
                    runtime->leg_start_offset,
                    job->destination_route_offset,
                    footprint_speed, &active) < 0) {
                return -1;
        }
        if ((runtime->carry_ambiguity_active &&
             append_route_nodes(
                     &active,
                     &runtime
                              ->carry_ambiguity_footprint) < 0) ||
            (runtime->reversal_carry_active &&
             append_route_nodes(
                     &active,
                     &runtime
                              ->reversal_carry_footprint) < 0)) {
                return -1;
        }
        track_reservation_conflict conflict;
        unsigned int generation = 0;
        int update =
                TrackReservationServerUpdateWindow(
                        dispatch_reservation_tid,
                        &active, job->train,
                        job->target_node,
                        job->plan_generation,
                        &conflict, &generation);
        if (update != 0 ||
            generation != job->plan_generation) {
                return -1;
        }
        runtime->safety_footprint = active;
        runtime->authority_prefetch_active = 0;
        runtime->authority_prefetch_end_offset = -1;
        runtime->authority_prefetch_center_ceiling_mm = -1;
        runtime->authority_prefetch_settle_at_tick = -1;
        runtime->turnout_batch_token = 0;
        runtime->turnout_queue_pending = 0;
        return 0;
}

/*
 * Fixed-siding direct dispatch treats detectors as ordered localization
 * evidence, not as mandatory motion gates.  A physical Track-D capture of
 * C->d1 contained A10, C7, D8, E8, C14: B7 was absent and both E11/D10 were
 * absent between C7 and D8.  The strict monitor correctly classifies D8 as
 * farther than its one-missing lookahead, but emergency-stopping there makes
 * the train coast to C14 instead of reaching d1.
 *
 * Recover only an attributed, generation-matching sensor occurrence that is
 * monotonically ahead on the already selected motion leg and inside the
 * currently usable authority.  The caller still applies the independent
 * fastest-possible travel-time check before committing this trial state.
 * Reservation release also remains conservative: the recovered observation
 * is marked MISSING_ONE, so ownership is retained until a subsequent ordered
 * detector corroborates progress.
 */
static int recover_forward_direct_sensor_observation(
        int slot, int sensor_node,
        tc2_route_monitor *trial,
        tc2_route_observation *observation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !trial || !observation ||
            sensor_node < 0 || sensor_node >= TRACK_MAX) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!uses_measured_direct_stop(job) ||
            observation->classification !=
                    TC2_ROUTE_SENSOR_SPURIOUS ||
            dispatch_track[sensor_node].type != NODE_SENSOR ||
            runtime->monitor.confirmed_offset < 0 ||
            runtime->leg_end_offset <
                    runtime->monitor.confirmed_offset) {
                return 1;
        }

        int usable_end = runtime->leg_end_offset;
        if (runtime->rolling_authority_active &&
            runtime->authority_end_offset < usable_end) {
                usable_end = runtime->authority_end_offset;
        }
        int matched_offset = -1;
        int skipped_sensors = 0;
        for (int offset =
                     runtime->monitor.confirmed_offset + 1;
             offset <= usable_end; ++offset) {
                int node = runtime->route.nodes[offset];
                if (dispatch_track[node].type != NODE_SENSOR) {
                        continue;
                }
                if (node == sensor_node) {
                        matched_offset = offset;
                        break;
                }
                ++skipped_sensors;
        }
        /*
         * The ordinary monitor already owns the next and next-next cases.
         * Reach this recovery path only for a larger confirmed forward gap.
         */
        if (matched_offset < 0 || skipped_sensors < 2) {
                return 1;
        }

        int matched_distance = -1;
        if (Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    matched_offset, &matched_distance) < 0 ||
            matched_distance <
                    runtime->monitor.confirmed_distance_mm) {
                return -1;
        }
        observation->classification =
                TC2_ROUTE_SENSOR_MISSING_ONE;
        observation->missing = observation->expected;
        observation->matched.route_offset =
                matched_offset;
        observation->matched.node_index =
                sensor_node;
        observation->matched.distance_mm =
                matched_distance;
        observation->advance_mm =
                matched_distance -
                runtime->monitor.confirmed_distance_mm;
        trial->confirmed_offset = matched_offset;
        trial->confirmed_distance_mm = matched_distance;
        trial->missing_sensor_count = 1;
        return 0;
}

/*
 * At a zero-offset endpoint, either directed half of the coincident physical
 * detector is a valid completion report.  Its reverse-directed name can be
 * outside the ordinary next/next-next monitor window, so recover the exact
 * route occurrence only while it remains inside the train's already-owned
 * authority and physical footprint.  This grants no new movement authority
 * and releases no reservation tail.  Non-zero endpoint offsets never use
 * this exception.
 *
 * Return 0 after recovery, 1 when the report is not such a boundary, 2 when
 * it is a boundary outside usable authority, and -1 on an invariant failure.
 */
static int recover_destination_boundary_sensor_observation(
        int slot, int sensor_node,
        tc2_route_monitor *trial,
        tc2_route_observation *observation) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            !trial || !observation ||
            sensor_node < 0 || sensor_node >= TRACK_MAX) {
                return -1;
        }
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->destination_correction_active ||
            !destination_boundary_sensor_ends_trip(&dispatch_jobs[slot]) ||
            observation->classification !=
                    TC2_ROUTE_SENSOR_SPURIOUS ||
            destination_boundary_sensor_mask(slot, sensor_node) == 0) {
                return 1;
        }
        if (!runtime->route_valid ||
            runtime->monitor.confirmed_offset < 0 ||
            runtime->monitor.confirmed_offset >= runtime->route.node_count ||
            runtime->monitor_terminal_offset <
                    runtime->monitor.confirmed_offset ||
            runtime->monitor_terminal_offset >= runtime->route.node_count) {
                return -1;
        }

        int reverse_sensor = physical_reverse_index(sensor_node);
        int matched_offset = -1;
        for (int offset = runtime->monitor.confirmed_offset + 1;
             offset <= runtime->monitor_terminal_offset; ++offset) {
                int node = runtime->route.nodes[offset];
                if (node < 0 || node >= TRACK_MAX) return -1;
                if (node == sensor_node || node == reverse_sensor ||
                    physical_reverse_index(node) == sensor_node) {
                        matched_offset = offset;
                        break;
                }
        }
        if (matched_offset < 0) {
                return 2;
        }

        int owned_end = runtime->rolling_authority_active ?
                runtime->authority_end_offset :
                runtime->monitor_terminal_offset;
        int footprint_has_sensor =
                route_contains_node(
                        &runtime->safety_footprint, sensor_node) ||
                (reverse_sensor >= 0 &&
                 route_contains_node(
                         &runtime->safety_footprint, reverse_sensor));
        if (matched_offset > owned_end || !footprint_has_sensor) {
                return 2;
        }

        int matched_distance = -1;
        if (Tc2RouteDistanceAtOffset(
                    dispatch_track, &runtime->route,
                    matched_offset, &matched_distance) < 0 ||
            matched_distance < runtime->monitor.confirmed_distance_mm) {
                return -1;
        }
        observation->classification =
                TC2_ROUTE_SENSOR_MISSING_ONE;
        observation->missing = observation->expected;
        observation->matched.route_offset = matched_offset;
        observation->matched.node_index =
                runtime->route.nodes[matched_offset];
        observation->matched.distance_mm = matched_distance;
        observation->advance_mm =
                matched_distance -
                runtime->monitor.confirmed_distance_mm;
        trial->confirmed_offset = matched_offset;
        trial->confirmed_distance_mm = matched_distance;
        trial->missing_sensor_count = 1;
        return 0;
}

/*
 * A traffic stop endpoint is produced by the measured command-to-rest model;
 * it is not a second source of track position truth.  In particular, a train
 * may cross the next physical detector while the zero-speed command is still
 * coasting.  An ordered detector that is still inside the train's owned
 * authority must therefore rebase the resumable hold instead of being
 * mislabeled as a sensor-sequence failure.
 *
 * Keep this bounded by the independent motion uncertainty and by both forms
 * of authority.  A detector outside either bound remains fail-closed, so this
 * cannot turn a real reservation overrun into accepted progress.
 */
static int traffic_hold_sensor_rebase_is_safe(
        int slot, int matched_offset, int matched_node,
        int64_t sensor_distance_um) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            matched_offset < 0 || matched_node < 0 ||
            matched_node >= TRACK_MAX || sensor_distance_um < 0) {
                return 0;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (runtime->stop_purpose != TC2_STOP_TRAFFIC ||
            runtime->traffic_hold_distance_um < 0 ||
            sensor_distance_um <=
                    runtime->traffic_hold_distance_um ||
            sensor_distance_um >
                    (int64_t)job->destination_distance_mm * 1000) {
                return 0;
        }
        int stop_speed =
                runtime->traffic_resume_speed > 0 ?
                        runtime->traffic_resume_speed :
                runtime->motion_speed_ceiling > 0 ?
                        runtime->motion_speed_ceiling :
                        job->speed;
        int uncertainty_mm = Tc2MotionUncertaintyMm(stop_speed);
        if (uncertainty_mm < 0 ||
            sensor_distance_um -
                            runtime->traffic_hold_distance_um >
                    (int64_t)uncertainty_mm * 1000) {
                return 0;
        }
        if (runtime->rolling_authority_active) {
                int owned_end = runtime->authority_prefetch_active ?
                        runtime->authority_prefetch_end_offset :
                        runtime->authority_end_offset;
                if (owned_end < 0 || matched_offset > owned_end) {
                        return 0;
                }
        }
        int reverse = physical_reverse_index(matched_node);
        return route_contains_node(
                           &runtime->safety_footprint,
                           matched_node) ||
                (reverse >= 0 &&
                 route_contains_node(
                         &runtime->safety_footprint, reverse));
}

static int process_sensor_observation(
        int slot, const train_sensor_attributed_event_t *event,
        int event_tick, int action_tick) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_route_observation observation;
        tc2_route_monitor trial = runtime->monitor;
        int prior_confirmed_offset =
                runtime->monitor.confirmed_offset;
        int preorigin_event = 0;
        int deadline_anchor_tick = event_tick;
        if (event_tick < 0 || action_tick < 0) return -1;
        runtime->last_journal_sequence = event->sequence;

        if (event->generation != job->plan_generation) {
                ++job->duplicate_sensor_count;
                return 0;
        }
        if (Tc2RouteMonitorObserve(
                    dispatch_track, &runtime->route, &trial,
                    event->sensor_index, event->sequence,
                    &observation) < 0) {
                return -1;
        }
        if (observation.classification != TC2_ROUTE_SENSOR_DUPLICATE &&
            runtime->preorigin_sensor_pending) {
                int origin_offset = runtime->leg_start_offset;
                int origin_node =
                        origin_offset >= 0 &&
                                origin_offset < runtime->route.node_count ?
                        runtime->route.nodes[origin_offset] : -1;
                int reverse_origin =
                        physical_reverse_index(origin_node);
                int origin_distance_mm;
                /*
                 * Do this before the ordinary NORMAL/MISSING/SPURIOUS
                 * returns.  A loop can contain the same physical detector
                 * later, and the generic monitor is initialized as if its
                 * origin were already occupied.  While the prefix is pending,
                 * only a fresh event from the exact physical origin may
                 * consume it; stale sequence tokens remain DUPLICATE below.
                 */
                if (origin_node >= 0 &&
                    dispatch_track[origin_node].type == NODE_SENSOR &&
                    (event->sensor_index == origin_node ||
                     event->sensor_index == reverse_origin) &&
                    Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            origin_offset,
                            &origin_distance_mm) == 0) {
                        observation.classification =
                                TC2_ROUTE_SENSOR_NORMAL;
                        observation.matched.route_offset =
                                origin_offset;
                        observation.matched.node_index =
                                origin_node;
                        observation.matched.distance_mm =
                                origin_distance_mm;
                        observation.advance_mm =
                                runtime->preorigin_distance_mm;
                        trial.confirmed_offset = origin_offset;
                        trial.confirmed_distance_mm =
                                origin_distance_mm;
                        trial.missing_sensor_count =
                                runtime->monitor.missing_sensor_count;
                        trial.last_observed_node = origin_node;
                        preorigin_event = 1;
                }
        }
        if (observation.classification == TC2_ROUTE_SENSOR_DUPLICATE) {
                ++job->duplicate_sensor_count;
                runtime->monitor.last_sequence = event->sequence;
                return 0;
        }
        if (observation.classification == TC2_ROUTE_SENSOR_SPURIOUS) {
                int recovered =
                        recover_destination_boundary_sensor_observation(
                                slot, event->sensor_index,
                                &trial, &observation);
                if (recovered < 0) return -1;
                if (recovered == 2) {
                        /*
                         * A real destination boundary reported outside the
                         * already-owned correction guard.  Stop immediately
                         * but fail closed rather than extending authority.
                         */
                        runtime->monitor.last_sequence = event->sequence;
                        runtime->destination_correction_active = 0;
                        runtime->destination_correction_pending = 0;
                        runtime->destination_correction_attempted = 1;
                        runtime->destination_correction_reached_endpoint = 0;
                        runtime->destination_correction_deadline_tick = -1;
                        runtime->destination_correction_sensor_offset = -1;
                        job->braking_at_tick = -1;
                        job->prediction_command_at_tick = -1;
                        job->position_estimated = 1;
                        begin_stop(
                                slot, action_tick,
                                TC2_STOP_DESTINATION, 1,
                                TC2_STOP_TRIGGER_SENSOR);
                        return 0;
                }
                if (recovered == 1) {
                        recovered =
                                recover_forward_direct_sensor_observation(
                                        slot, event->sensor_index,
                                        &trial, &observation);
                        if (recovered < 0) return -1;
                }
                if (recovered == 0) {
                        /*
                         * Continue through the common elapsed-time,
                         * footprint, and deadline checks below.
                         */
                } else {
                runtime->monitor.last_sequence = event->sequence;
                if (runtime->carry_ambiguity_active &&
                    route_contains_node(
                            &runtime->carry_ambiguity_footprint,
                            event->sensor_index)) {
                        /*
                         * The physical train may still be catching up to
                         * the estimated CURRENT origin. Such an event never
                         * advances the new monitor or releases legacy
                         * ownership, so retaining it as non-progress
                         * evidence is safe and avoids charging a real
                         * pre-origin pulse as the one tolerated fault.
                         */
                        ++job->duplicate_sensor_count;
                        return 0;
                }
                ++job->spurious_sensor_count;
                return job->spurious_sensor_count >
                        TC2_MAX_SENSOR_SPURIOUS ? -1 : 0;
                }
        }

        /*
         * A batch can contain multiple events received at different times.
         * Plausibility must use each event's server arrival tick, not the
         * later ticker time at which this page happens to be drained.
         */
        if (runtime->last_confirmed_tick != -1 &&
            !tick_reached(
                    event_tick,
                    runtime->last_confirmed_tick)) {
                /*
                 * An attributed event received before this motion epoch (or
                 * out of order across the half-range) must never advance the
                 * route and release track behind a train that has not moved.
                 */
                return -1;
        }
        int elapsed =
                tick_age(event_tick, runtime->last_confirmed_tick);
        int motion_speed =
                runtime->speed_reduction_pending &&
                        runtime->motion_speed_ceiling > 0 ?
                        runtime->motion_speed_ceiling :
                runtime->command_speed > 0 ?
                        runtime->command_speed :
                        runtime->motion_speed_ceiling;
        if (motion_speed <= 0) motion_speed = job->speed;
        /*
         * The supervised provisional model is a point prediction for the
         * stop-command deadline, not a certified maximum train velocity.
         * Using its narrow +20% band here rejects physically valid reports
         * whenever pickup placement or the first measured run is faster
         * than that point estimate.  Sensor plausibility must retain the
         * independent conservative fast envelope used by every managed
         * trip; only schedule_motion_deadlines() may use the provisional
         * point model.
         */
        int earliest_ticks =
                Tc2MotionFastTravelTicks(
                        motion_speed,
                        observation.advance_mm);
        if (earliest_ticks < 0) return -1;
        if (runtime->last_confirmed_tick != -1 &&
            elapsed < earliest_ticks) {
                runtime->monitor.last_sequence = event->sequence;
                ++job->spurious_sensor_count;
                return job->spurious_sensor_count >
                        TC2_MAX_SENSOR_SPURIOUS ? -1 : 0;
        }

        if (!uses_measured_direct_stop(job) &&
            (job->provisional_prediction ||
             runtime->prediction_plan_valid) &&
            runtime->last_confirmed_tick != -1 &&
            elapsed > 0 && observation.advance_mm > 0) {
                int observed_velocity =
                        Tc2MotionObservedVelocityUmPerTick(
                                observation.advance_mm, elapsed);
                if (observed_velocity < 1) return -1;
                /*
                 * This is retained only for the legacy point-timing path.
                 * Measured direct dispatch deliberately never records this
                 * value: its sensors rebase position only, while the stable
                 * command-speed curve owns spatial progress and braking.
                 */
                runtime->observed_velocity_um_per_tick =
                        observed_velocity;
        }

        if (observation.classification ==
            TC2_ROUTE_SENSOR_MISSING_ONE) {
                ++job->missing_sensor_count;
                if (job->missing_sensor_count >
                            TC2_MAX_SENSOR_MISSING &&
                    !uses_measured_direct_stop(job)) {
                        return -1;
                }
                runtime->pending_missing_offset =
                        observation.matched.route_offset;
        } else {
                /*
                 * An ordinary, exactly ordered detector is the latest real
                 * localization evidence and must release the completed
                 * physical block behind it.  Keeping every normal trip one
                 * sensor behind leaves a shared detector owned forever when
                 * destination braking stops between detectors: the follower's
                 * real report is then attributed to the leader and both jobs
                 * eventually fail sensor sequencing (data 94: D9/E12).
                 *
                 * CURRENT head-on recovery and a stopped reversal are the
                 * two deliberate exceptions.  They inherit an already
                 * occupied corridor whose release requires the following
                 * ordered observation to corroborate the first outbound
                 * detector, so those ambiguity footprints retain the older
                 * anchor until their existing release witness is satisfied.
                 */
                runtime->reservation_anchor_offset =
                        runtime->carry_ambiguity_active ||
                                runtime->reversal_carry_active ?
                        prior_confirmed_offset :
                        observation.matched.route_offset;
                runtime->pending_missing_offset = -1;
        }

        runtime->monitor = trial;
        if (preorigin_event) {
                runtime->preorigin_sensor_pending = 0;
                runtime->preorigin_distance_mm = 0;
                runtime->carry_preorigin_distance_mm = 0;
                runtime->preorigin_traffic_hold_distance_um = 0;
                runtime->preorigin_traffic_hold_valid = 0;
        }
        runtime->last_confirmed_tick = event_tick;
        job->current_route_offset =
                observation.matched.route_offset;
        job->current_node = observation.matched.node_index;
        /*
         * This is the single localization commit point.  Duplicate,
         * spurious, wrong-generation, and implausibly early journal records
         * have all returned above, so only this pair may be used to rebuild a
         * CURRENT route or prove the directed pose around a physical reverse.
         */
        if (observation.matched.node_index >= 0 &&
            observation.matched.node_index < TRACK_MAX &&
            dispatch_track[observation.matched.node_index].type ==
                    NODE_SENSOR) {
                runtime->last_accepted_sensor_node =
                        observation.matched.node_index;
                runtime->last_accepted_sensor_sequence =
                        event->sequence;
        }
        job->confirmed_distance_mm =
                observation.matched.distance_mm;
        /*
         * The motion anchor is independent of the reservation anchor.  A
         * normal ordered detector advances both; only an inherited CURRENT
         * or reversal ambiguity deliberately keeps reservation release one
         * corroborated observation behind.  The motion anchor remains the
         * best monotonic scalar position used by distance control, traffic
         * spacing, and UI prediction.
         */
        runtime->motion_anchor_distance_um =
                (int64_t)observation.matched.distance_mm * 1000;
        runtime->motion_anchor_tick = event_tick;
        runtime->motion_anchor_from_traffic = 0;
        if (uses_measured_direct_stop(job) &&
            job->state == TC2_JOB_RUNNING &&
            runtime->stop_purpose != TC2_STOP_TRAFFIC) {
                /*
                 * The prior scalar was a time projection (and after a
                 * traffic stop possibly a conservative coast upper bound),
                 * not a measured centre position.  A real ordered detector
                 * is stronger evidence and is allowed to pull the motion/UI
                 * estimate back to the observed route scalar.  Without this
                 * rebase, the next scheduler tick can immediately reuse an
                 * old optimistic value and stop at the detector itself.
                 */
                job->estimated_distance_um =
                        runtime->motion_anchor_distance_um;
        }
        if (runtime->stop_purpose == TC2_STOP_TRAFFIC &&
            runtime->traffic_hold_distance_um <
                    runtime->motion_anchor_distance_um) {
                if (!traffic_hold_sensor_rebase_is_safe(
                            slot,
                            observation.matched.route_offset,
                            observation.matched.node_index,
                            runtime->motion_anchor_distance_um)) {
                        job->position_estimated = 1;
                        return -1;
                }
                runtime->traffic_hold_distance_um =
                        runtime->motion_anchor_distance_um;
                job->traffic_hold_distance_um =
                        runtime->traffic_hold_distance_um;
                if (job->estimated_distance_um <
                    runtime->motion_anchor_distance_um) {
                        job->estimated_distance_um =
                                runtime->motion_anchor_distance_um;
                }
        }
        int carried_before_update =
                runtime->carry_ambiguity_active;
        /*
         * MISSING_ONE is deliberately not corroborated yet.  Preserve the
         * exact already-owned footprint until a later ordered detector
         * confirms the forward jump; rebuilding from the older reservation
         * anchor can try to reacquire tail nodes which FIFO has legitimately
         * handed to another train.  Data 88 exposed that as T15 failing at
         * B13, after which its real E4/E5 reports became unattributed and
         * cascaded a sensor-sequence failure into T14.
         *
         * Keeping the current footprint unchanged is the conservative
         * operation: it releases nothing, acquires nothing, and grants no
         * additional movement authority.  Ordinary rolling prefetch may
         * still extend the front through its independent conflict-checked
         * CAS, and the next non-missing observation performs the normal
         * delayed tail release.
         */
        if (observation.classification !=
                    TC2_ROUTE_SENSOR_MISSING_ONE &&
            update_remaining_footprint(slot) < 0) {
                return -1;
        }
        int localized_now =
                carried_before_update &&
                !runtime->carry_ambiguity_active;
        if (runtime->speed_reduction_pending &&
            runtime->command_speed > 0) {
                /*
                 * A lower speed command is not an instantaneous physical
                 * speed bound. Keep the prior upper bound through the first
                 * independently ordered sensor, then use the new command
                 * for later-event plausibility.
                 */
                runtime->motion_speed_ceiling =
                        runtime->command_speed;
                runtime->speed_reduction_pending = 0;
        }

        /*
         * During the explicit terminal speed-40 correction, ordinary real
         * detectors only re-anchor scalar progress.  The sole exception is a
                 * terminal boundary endpoint: either directed report from its
                 * physical detector ends correction.  This includes zero-offset
                 * endpoints plus d3/d8. Other non-coincident destinations keep
                 * their original remaining-distance behavior. Turnout and authority
                 * gates remain the only earlier movement boundaries.
         */
        if (runtime->destination_correction_active) {
                int observed_distance_mm = -1;
                unsigned int boundary_mask =
                        destination_boundary_sensor_mask(
                                slot, event->sensor_index);
                int exact_boundary_seen =
                        destination_boundary_sensor_ends_trip(job) &&
                        boundary_mask != 0;
                if (Tc2RouteDistanceAtOffset(
                            dispatch_track, &runtime->route,
                            observation.matched.route_offset,
                            &observed_distance_mm) < 0 ||
                    observed_distance_mm < 0) {
                        return -1;
                }
                /*
                 * An observation past d remains invalid except for either
                 * directed report from the physical detector that coincides
                 * with a zero-offset destination.  A non-coincident endpoint
                 * still uses its real sensor only as the correction anchor
                 * and must cover the remaining distance to d.
                 */
                if (observed_distance_mm >
                            job->destination_distance_mm &&
                    !exact_boundary_seen) {
                        return -1;
                }
                if (exact_boundary_seen ||
                    observation.matched.route_offset ==
                            job->target_route_offset) {
                        runtime->target_seen = 1;
                        runtime->target_corroborated = 1;
                }

                int64_t observed_distance_um =
                        (int64_t)observed_distance_mm * 1000;
                int64_t destination_um =
                        (int64_t)job->destination_distance_mm * 1000;
                runtime->destination_correction_pending = 0;
                runtime->motion_anchor_distance_um =
                        observed_distance_um;
                runtime->motion_anchor_tick = action_tick;
                runtime->motion_anchor_from_traffic = 0;
                job->estimated_distance_um = observed_distance_um;
                job->position_estimated = 0;
                job->prediction_anchor_tick = action_tick;
                job->prediction_anchor_distance_mm =
                        observed_distance_mm;
                job->prediction_timing_valid = 1;

                int64_t remaining_um =
                        destination_um - observed_distance_um;
                job->remaining_distance_mm =
                        remaining_um > 0 ?
                        (int)((remaining_um + 999) / 1000) : 0;
                runtime->destination_correction_sensor_offset =
                        destination_correction_sensor_offset(
                                slot, observed_distance_um);
                update_next_sensor(slot);

                if (remaining_um <= 0 || exact_boundary_seen) {
                        int endpoint_estimated =
                                observed_distance_um != destination_um;
                        /*
                         * Preserve the real detector node committed above
                         * for terminal body occupancy.  Clamp only the public
                         * scalar to d so the ordinary stop-settle path enters
                         * the same ARRIVED state as every normal destination.
                         */
                        runtime->destination_correction_reached_endpoint = 1;
                        runtime->destination_correction_active = 0;
                        runtime->destination_correction_pending = 0;
                        runtime->destination_correction_deadline_tick = -1;
                        runtime->destination_correction_sensor_offset = -1;
                        job->estimated_distance_um = destination_um;
                        job->remaining_distance_mm = 0;
                        job->position_estimated = endpoint_estimated;
                        job->braking_at_tick = -1;
                        job->prediction_command_at_tick = -1;
                        job->next_sensor_node = -1;
                        begin_stop(
                                slot, action_tick,
                                TC2_STOP_DESTINATION,
                                endpoint_estimated,
                                TC2_STOP_TRIGGER_SENSOR);
                        return 0;
                }

                int remaining_mm =
                        (int)((remaining_um + 999) / 1000);
                int remaining_ticks =
                        Tc2MotionProvisionalSlowTravelTicks(
                                TC2_DESTINATION_CORRECTION_SPEED,
                                remaining_mm);
                if (remaining_ticks < 1) return -1;
                runtime->destination_correction_deadline_tick =
                        tick_after(action_tick, remaining_ticks);
                job->braking_at_tick =
                        runtime->destination_correction_deadline_tick;
                job->prediction_command_at_tick =
                        job->braking_at_tick;
                return 0;
        }

        /*
         * A d3/d8 boundary pulse proves that the train has reached the requested
         * stopping boundary.  End the trip at that real observation and retire
         * every correction flag before beginning the zero-speed settle.  In
         * particular, the BRAKING settle path must not re-enter the virtual
         * endpoint speed-40 approach after this stop.
         */
        if (!runtime->localization_only &&
            (job->destination_index == 2 ||
             job->destination_index == 7) &&
            destination_boundary_sensor_mask(
                    slot, event->sensor_index) != 0) {
                int64_t destination_um =
                        (int64_t)job->destination_distance_mm * 1000;
                runtime->target_seen = 1;
                runtime->target_corroborated = 1;
                runtime->destination_correction_active = 0;
                runtime->destination_correction_pending = 0;
                runtime->destination_correction_attempted = 1;
                runtime->destination_correction_reached_endpoint = 1;
                runtime->destination_correction_deadline_tick = -1;
                runtime->destination_correction_sensor_offset = -1;
                job->estimated_distance_um = destination_um;
                job->remaining_distance_mm = 0;
                job->position_estimated = 0;
                job->braking_at_tick = -1;
                job->prediction_command_at_tick = -1;
                job->next_sensor_node = -1;
                begin_stop(
                        slot, action_tick,
                        TC2_STOP_DESTINATION, 0,
                        TC2_STOP_TRIGGER_SENSOR);
                return job->state == TC2_JOB_FAILED ? -1 : 0;
        }

        if (!runtime->localization_only &&
            job->destination_offset_mm > 0) {
                int observed_destination_side =
                        destination_boundary_side_for_sensor(
                                slot, event->sensor_index);
                if (observed_destination_side >= 0 &&
                    observation.matched.route_offset <=
                            job->destination_route_offset &&
                    observation.matched.route_offset !=
                            job->target_route_offset) {
                        const tc2_track_destination_side *definition =
                                Tc2TrackDestinationSide(
                                        job->destination_index,
                                        observed_destination_side);
                        int observed_distance_mm = -1;
                        if (!definition ||
                            Tc2RouteDistanceAtOffset(
                                    dispatch_track, &runtime->route,
                                    observation.matched.route_offset,
                                    &observed_distance_mm) < 0 ||
                            observed_distance_mm < 0) {
                                return -1;
                        }

                        int corrected_offset_mm =
                                definition->base_offset_mm +
                                job->destination_speed_correction_mm;
                        if (corrected_offset_mm < 0 ||
                            observed_distance_mm >
                                    0x7fffffff - corrected_offset_mm) {
                                return -1;
                        }
                        job->selected_destination_side =
                                observed_destination_side;
                        job->target_node =
                                runtime->route.nodes[
                                        observation.matched.route_offset];
                        job->target_route_offset =
                                observation.matched.route_offset;
                        job->destination_base_offset_mm =
                                definition->base_offset_mm;
                        job->destination_offset_mm =
                                corrected_offset_mm;
                        job->destination_distance_mm =
                                observed_distance_mm +
                                corrected_offset_mm;
                        job->route_distance_mm =
                                job->destination_distance_mm;
                }
        }

        if (!runtime->localization_only &&
            job->destination_offset_mm > 0 &&
            observation.matched.route_offset ==
                    job->target_route_offset) {
                /*
                 * This is the physical anchor, not the destination. Rebase
                 * the exact scalar motion model here and keep RUNNING for
                 * the configured downstream offset.
                 */
                runtime->target_seen = 1;
                runtime->target_corroborated = 1;
                job->position_estimated = 1;
                if (uses_precision_approach(job) &&
                    job->destination_offset_mm > 0) {
                        /*
                         * The final timer is rebased on the physical anchor.
                         * The train was already reduced to the measured
                         * precision speed before reaching this sensor.
                         */
                        runtime->approach_sent = 0;
                        deadline_anchor_tick = action_tick;
                }
                /*
                 * No sensor represents the interior-edge destination.
                 * Once its physical anchor is confirmed, the remaining
                 * progress is timer/model based rather than another
                 * expected sensor observation.
                 */
                job->next_sensor_node = -1;
        }

        if (!runtime->localization_only &&
            job->destination_offset_mm > 0 &&
            observation.matched.route_offset >=
                    job->destination_route_offset) {
                /*
                 * A sensor at or beyond the route-node ceiling proves the
                 * train passed the interior-edge virtual stop point. Keep
                 * the complete owned guard and fail closed.
                 */
                fail_job(slot, TC2_FAILURE_SENSOR_SEQUENCE);
                return -1;
        }

        if (!runtime->localization_only &&
            job->destination_offset_mm > 0 &&
            observation.matched.route_offset ==
                    job->target_route_offset) {
                /*
                 * The directed sensor is only the localization anchor for
                 * an interior lowercase destination.  Even when the graph
                 * represents that anchor as the current motion-leg end, it
                 * must not enter the reversal/destination stop branch below.
                 * Continue at precision speed and stop only after travelling
                 * the measured downstream offset.
                 */
                if (job->state == TC2_JOB_BRAKING) {
                        return 0;
                }
                if (schedule_motion_deadlines(
                            slot, deadline_anchor_tick) < 0) {
                        return -1;
                }
                return 0;
        }

        if (job->state == TC2_JOB_BRAKING &&
            runtime->stop_purpose == TC2_STOP_DESTINATION &&
            job->destination_offset_mm == 0 &&
            runtime->target_seen &&
            observation.matched.route_offset >
                    job->target_route_offset) {
                runtime->target_corroborated = 1;
                job->position_estimated = 0;
                return 0;
        }

        if (observation.matched.route_offset >=
            runtime->leg_end_offset) {
                if (runtime->leg_end_offset <
                    job->destination_route_offset) {
                        if (observation.classification ==
                            TC2_ROUTE_SENSOR_MISSING_ONE) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_SENSOR_SEQUENCE);
                                return -1;
                        }
                        if (observation.matched.route_offset !=
                            runtime->leg_end_offset) {
                                return -1;
                        }
                        runtime->target_seen = 1;
                        begin_stop(
                                slot, action_tick,
                                TC2_STOP_REVERSAL, 1,
                                TC2_STOP_TRIGGER_SENSOR);
                } else {
                        int estimated =
                                observation.matched.route_offset >
                                        job->destination_route_offset ||
                                observation.classification ==
                                        TC2_ROUTE_SENSOR_MISSING_ONE;
                        runtime->target_seen = !estimated;
                        if (uses_exact_destination_sensor_stop(job) &&
                            !estimated &&
                            observation.matched.route_offset ==
                                    job->target_route_offset) {
                                /*
                                 * A zero-offset destination is a detector
                                 * centre, but its pulse can be too late to be
                                 * the primary zero command.
                                 * The distance controller already commanded
                                 * zero one measured stopping distance early.
                                 * This pulse confirms the physical endpoint;
                                 * only a still-positive train needs the
                                 * fail-safe zero.  Do not reset an existing
                                 * braking settle timer with a duplicate zero.
                                 */
                                runtime->target_corroborated = 1;
                                job->position_estimated = 0;
                                if (job->state == TC2_JOB_BRAKING &&
                                    runtime->command_speed == 0 &&
                                    job->command_speed == 0) {
                                        /*
                                         * The detector corroborates an
                                         * already-issued distance-domain
                                         * stop; it did not initiate that
                                         * stop.  Preserve the original
                                         * trigger and settle deadline so a
                                         * endpoint pulse during physical coast
                                         * cannot restart braking or move the
                                         * recorded zero-command point to the
                                         * detector centre.
                                         */
                                        runtime->stop_purpose =
                                                TC2_STOP_DESTINATION;
                                } else {
                                        begin_stop(
                                                slot, action_tick,
                                                TC2_STOP_DESTINATION, 0,
                                                TC2_STOP_TRIGGER_SENSOR);
                                }
                                return job->state == TC2_JOB_FAILED ? -1 : 1;
                        }
                        if (uses_measured_direct_stop(job)) {
                                /*
                                 * Virtual/calibrated endpoints retain their
                                 * distance-domain zero command. Exact
                                 * detector-centre destinations returned above.
                                 */
                                if (job->state ==
                                            TC2_JOB_BRAKING &&
                                    runtime->stop_purpose ==
                                            TC2_STOP_DESTINATION) {
                                        job->position_estimated =
                                                estimated;
                                        return 0;
                                }
                                if (schedule_motion_deadlines(
                                            slot,
                                            deadline_anchor_tick) < 0) {
                                        return -1;
                                }
                                return 0;
                        }
                        if (job->state == TC2_JOB_BRAKING &&
                            runtime->stop_purpose ==
                                    TC2_STOP_DESTINATION) {
                                job->position_estimated = estimated;
                                return 0;
                        }
                        begin_stop(slot, action_tick,
                                   TC2_STOP_DESTINATION,
                                   estimated,
                                   TC2_STOP_TRIGGER_SENSOR);
                }
                return job->state == TC2_JOB_FAILED ? -1 : 1;
        }
        if (job->state == TC2_JOB_BRAKING) {
                /*
                 * A timer-triggered destination stop can coast across
                 * ordinary sensors.  Progress still tightens the footprint,
                 * but command_speed is already zero and must never be fed
                 * back into the positive-speed deadline model.
                 */
                update_next_sensor(slot);
                return 0;
        }
        /*
         * Every exactly ordered detector is a fresh physical rebase for a
         * reduced ordinary rolling launch.  Restricting restoration to the
         * special carry-localization transition meant a train which resumed
         * at 40 could never return to its requested speed after an ordinary
         * D/E sensor, even after a farther window had settled.
         */
        if ((localized_now ||
             observation.classification !=
                    TC2_ROUTE_SENSOR_MISSING_ONE) &&
            runtime->command_speed != job->speed &&
            !runtime->precision_approach_active) {
                if (runtime->rolling_authority_active) {
                        int restored =
                                authority_restore_requested_speed(
                                        slot,
                                        deadline_anchor_tick);
                        if (restored < 0) return -1;
                        if (restored > 0) return 0;
                } else {
                        if (!regular_movement_gates_ready(slot)) {
                                return 0;
                        }
                        int restore_command =
                                command_train_positive_speed_with_retry(
                                        slot, job->speed);
                        if (restore_command < 0) return -1;
                        if (restore_command > 0) return 0;
                        runtime->command_speed = job->speed;
                        job->command_speed = job->speed;
                        runtime->motion_speed_ceiling = job->speed;
                        runtime->speed_reduction_pending = 0;
                        runtime->precision_approach_active = 0;
                }
        }
        if (schedule_motion_deadlines(
                    slot, deadline_anchor_tick) < 0) {
                return -1;
        }
        return 0;
}

static int drain_sensor_journal(int slot, int now) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        for (int page = 0; page < 8; ++page) {
                train_sensor_event_batch_t batch;
                if (TrainSensorGetAttributedEvents(
                            dispatch_sensor_tid, job->train,
                            runtime->last_journal_sequence,
                            &batch) < 0) {
                        return -2;
                }
                if (batch.lost) {
                        job->journal_lost = 1;
                        return -1;
                }
                if (batch.count < 0 ||
                    batch.count > TRAIN_SENSOR_EVENT_BATCH_CAPACITY) {
                        return -2;
                }
                for (int event = 0; event < batch.count; ++event) {
                        int status = process_sensor_observation(
                                slot, &batch.events[event],
                                batch.events[event].arrival_tick, now);
                        if (status != 0) return status;
                }
                if (!batch.has_more || batch.count == 0) return 0;
        }
        return -2;
}

static int prelaunch_failure_reason(
        int slot, const track_reservation_snapshot *reservation,
        const train_sensor_snapshot_t *sensors, int now) {
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];

        int owns_footprint = 1;
        for (int offset = 0;
             offset < runtime->safety_footprint.node_count;
             ++offset) {
                int node =
                        runtime->safety_footprint.nodes[offset];
                int physical[2] = {
                        node, physical_reverse_index(node)
                };
                for (int side = 0; side < 2; ++side) {
                        int candidate = physical[side];
                        if (candidate >= 0 &&
                            candidate < TRACK_MAX &&
                            reservation
                                            ->owner_by_node[candidate] !=
                                    job->train) {
                                owns_footprint = 0;
                        }
                }
        }
        if (reservation->generation_by_train[job->train] !=
                    job->plan_generation ||
            reservation->destination_by_train[job->train] !=
                    job->target_node ||
            !owns_footprint) {
                return TC2_FAILURE_RESERVATION;
        }
        if (sensor_health_is_safe(
                    slot, sensors, 0, now) < 0) {
                return TC2_FAILURE_SENSOR_SERVICE;
        }
        /*
         * This train is still at speed zero.  Do not compare the fresh
         * system-wide sensor counters with a staging-time snapshot here:
         * those counters legitimately change when an origin contact settles
         * or another train moves.  Reservation, localization, turnout and
         * traffic gates above remain fail-closed.  Once the positive-speed
         * batch is accepted, launch_ready_jobs() records the fresh per-train
         * sequence/counter baseline used by the normal running checks.
         */
        return TC2_FAILURE_NONE;
}

static void launch_ready_jobs(int now) {
        int slots[TC2_DISPATCH_MAX_JOBS];
        int trains[TC2_DISPATCH_MAX_JOBS];
        int speeds[TC2_DISPATCH_MAX_JOBS];
        int count = 0;
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;

        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0) {
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state == TC2_JOB_READY &&
                            tick_reached(
                                    now,
                                    dispatch_jobs[slot]
                                            .ready_at_tick)) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_SENSOR_SERVICE);
                        }
                }
                return;
        }
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (job->state != TC2_JOB_READY ||
                    !tick_reached(now, job->ready_at_tick)) {
                        continue;
                }
                if (runtime->destination_correction_pending) {
                        job->ready_at_tick = -1;
                        runtime->ready_wave_tick = -1;
                        job->state = TC2_JOB_PREPARING;
                        continue;
                }
                if (!traffic_motion_clear(slot) ||
                    !conflict_zone_step_ready(
                            slot,
                            runtime->conflict_zone_next_step)) {
                        continue;
                }
                int convoy_wait =
                        same_batch_convoy_front_pending_launch(slot);
                if (convoy_wait < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (convoy_wait > 0) continue;
                if (!conflict_zone_lookahead_prepared(slot)) {
                        /*
                         * A READY job can lose its required nextnext setting
                         * when an older hard owner legitimately changes that
                         * resource. Return it to PREPARING so the complete
                         * nextnext set is reacquired, corrected, and given a
                         * fresh mechanical-settle barrier; never launch merely
                         * because the direction changed back on this tick.
                         */
                        job->ready_at_tick = -1;
                        runtime->ready_wave_tick = -1;
                        job->state = TC2_JOB_PREPARING;
                        continue;
                }
                if (!can_train_move_with_reservation(
                            slot, &reservation)) {
                        continue;
                }
                int failure_reason =
                        prelaunch_failure_reason(
                                slot, &reservation, &sensors, now);
                if (failure_reason != TC2_FAILURE_NONE) {
                        fail_job(slot, failure_reason);
                        continue;
                }
                int can_health = can_health_is_safe(
                        slot, 0, now);
                if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                        fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (can_health == TC2_CAN_HEALTH_RETRY) continue;
                slots[count] = slot;
                trains[count] = job->train;
                speeds[count] =
                        runtime->planned_launch_speed > 0 ?
                        runtime->planned_launch_speed :
                        job->speed;
                ++count;
        }
        if (count == 0) return;

        track_reservation_snapshot final_reservation;
        train_sensor_snapshot_t final_sensors;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid,
                    &final_reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid,
                    &final_sensors) < 0) {
                for (int index = 0; index < count; ++index) {
                        fail_job(
                                slots[index],
                                TC2_FAILURE_SENSOR_SERVICE);
                }
                return;
        }
        for (int index = 0; index < count; ++index) {
                int slot = slots[index];
                if (!can_train_move_with_reservation(
                            slot, &final_reservation)) {
                        /* No positive command has been queued yet. */
                        return;
                }
                int failure_reason =
                        prelaunch_failure_reason(
                                slot, &final_reservation,
                                &final_sensors, now);
                if (failure_reason != TC2_FAILURE_NONE) {
                        for (int failed = 0;
                             failed < count; ++failed) {
                                fail_job(
                                        slots[failed], failure_reason);
                        }
                        return;
                }
        }
        sensors = final_sensors;

        /*
         * One atomic queue request defines the launch wave.  The CAN server
         * then serializes the frames and waits for each CS3 response, as the
         * Märklin protocol requires, without making slot order change the
         * scheduler's admission/launch decision.
         */
        int batch_token = CanTrainSetSpeedBatch(
                dispatch_can_tid, trains, speeds, count);
        if (batch_token == CAN_SEND_BUSY) {
                return;
        }
        if (batch_token <= 0) {
                for (int index = 0; index < count; ++index) {
                        fail_job(
                                slots[index],
                                TC2_FAILURE_CAN_HEALTH);
                }
                return;
        }
        int launch_tick = now;

        for (int index = 0; index < count; ++index) {
                int slot = slots[index];
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                runtime->command_speed =
                        runtime->planned_launch_speed > 0 ?
                        runtime->planned_launch_speed :
                        job->speed;
                job->command_speed = runtime->command_speed;
                runtime->motion_speed_ceiling =
                        runtime->command_speed;
                runtime->speed_reduction_pending = 0;
                runtime->approach_sent = 0;
                runtime->launch_batch_token =
                        (unsigned int)batch_token;
                runtime->launch_batch_index = index;
                runtime->launch_wave_tick = launch_tick;
                job->launch_tick = -1;
                job->launch_skew_ticks = -1;
                job->launch_attributed_sequence =
                        sensors.attributed_count;
                runtime->last_journal_sequence =
                        job->launch_attributed_sequence;
                runtime->monitor.last_sequence =
                        job->launch_attributed_sequence;
                if (!runtime->authority_resume_pending) {
                        runtime->last_confirmed_tick = -1;
                }
                job->launch_attribution_unavailable_count =
                        sensors.attribution_unavailable_count;
                runtime->launch_train_attribution_failure =
                        sensors.attribution_failure_by_train[job->train];
                runtime->launch_unattributed_count =
                        sensors.unattributed_count;
                runtime->unattributed_spurious_tolerated = 0;
                job->ready_at_tick = -1;
                job->state = TC2_JOB_LAUNCHING;
        }
}

static void fail_launch_wave(unsigned int token, int reason) {
        if (token == 0) return;
        (void)CanCancelBatch(dispatch_can_tid, token);
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                int state = dispatch_jobs[slot].state;
                if (runtime->launch_batch_token != token ||
                    (state != TC2_JOB_LAUNCHING &&
                     state != TC2_JOB_RUNNING)) {
                        continue;
                }
                runtime->launch_batch_token = 0;
                fail_job(slot, reason);
        }
}

static void process_launching_jobs(int now) {
        train_sensor_snapshot_t sensors;
        track_reservation_snapshot reservation;
        int have_launching = 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state ==
                    TC2_JOB_LAUNCHING) {
                        have_launching = 1;
                        break;
                }
        }
        if (!have_launching) return;
        if (TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0 ||
            TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0) {
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state ==
                            TC2_JOB_LAUNCHING) {
                                fail_launch_wave(
                                        dispatch_runtime[slot]
                                                .launch_batch_token,
                                        TC2_FAILURE_SENSOR_SERVICE);
                        }
                }
                return;
        }
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_LAUNCHING) continue;

                can_batch_status_t status;
                unsigned int token = runtime->launch_batch_token;
                if (!can_train_move_with_reservation(
                            slot, &reservation) ||
                    reservation.generation_by_train[job->train] !=
                            job->plan_generation ||
                    reservation.destination_by_train[job->train] !=
                            job->target_node) {
                        fail_launch_wave(
                                token,
                                TC2_FAILURE_RESERVATION);
                        continue;
                }
                if (token == 0 ||
                    CanGetBatchStatus(
                            dispatch_can_tid, token, &status) < 0 ||
                    status.total < 1 ||
                    runtime->launch_batch_index < 0 ||
                    runtime->launch_batch_index >= status.total) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (sensor_health_is_safe(
                            slot, &sensors, 0, now) < 0) {
                        fail_launch_wave(
                                token, TC2_FAILURE_SENSOR_SERVICE);
                        continue;
                }
                int can_health = can_health_is_safe(slot, 0, now);
                if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (status.state == CAN_BATCH_FAILED) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (status.confirmed <=
                    runtime->launch_batch_index) {
                        /* A stale heartbeat is retryable while unconfirmed. */
                        continue;
                }
                /*
                 * A successful exact batch-status query confirming this
                 * train is stronger evidence than a delayed notifier
                 * heartbeat.  The positive command may already be physical,
                 * so enter RUNNING and let its recoverable health gate stop
                 * it if the notifier remains stale.
                 */

                job->state = TC2_JOB_RUNNING;
                runtime->lifecycle_stop_reason =
                        TC2_LIFECYCLE_STOP_NONE;
                job->launch_tick = now;
                job->launch_skew_ticks =
                        tick_age(
                                now,
                                runtime->launch_wave_tick);
                if (runtime->authority_resume_pending) {
                        if (runtime->traffic_hold_distance_um < 0) {
                                fail_launch_wave(
                                        token,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        runtime->motion_anchor_distance_um =
                                runtime->preorigin_sensor_pending &&
                                        runtime
                                                ->preorigin_traffic_hold_valid ?
                                runtime
                                        ->preorigin_traffic_hold_distance_um :
                                runtime
                                        ->traffic_hold_distance_um;
                        runtime->motion_anchor_tick = now;
                        runtime->motion_anchor_from_traffic = 1;
                        runtime->preorigin_traffic_hold_distance_um = 0;
                        runtime->preorigin_traffic_hold_valid = 0;
                        runtime->stop_purpose =
                                TC2_STOP_NONE;
                        runtime->traffic_reason =
                                TC2_TRAFFIC_NONE;
                        runtime->traffic_peer_train = 0;
                        runtime->traffic_hold_since_tick = -1;
                        /*
                         * A successful local extension consumed its ticket at
                         * reservation commit.  Keep the cleared state here so
                         * the next downstream window gets a new arrival order.
                         */
                        clear_authority_request(runtime);
                        runtime->authority_resume_pending = 0;
                        runtime->prelaunch_traffic_blocked = 0;
                        runtime->authority_previous_end_offset =
                                -1;
                        runtime->traffic_resume_speed = 0;
                        runtime->traffic_hold_distance_um = -1;
                        job->traffic_hold_active = 0;
                        job->traffic_reason =
                                TC2_TRAFFIC_NONE;
                        job->traffic_peer_train = 0;
                        job->traffic_gap_mm = -1;
                        job->traffic_stop_threshold_mm = -1;
                        job->traffic_resume_threshold_mm = -1;
                        job->traffic_hold_distance_um = -1;
                        job->hold_active = 0;
                } else {
                        int confirmed_distance_mm;
                        if (effective_confirmed_distance_mm(
                                    runtime,
                                    &confirmed_distance_mm) < 0) {
                                fail_launch_wave(
                                        token,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        runtime->last_confirmed_tick = now;
                        runtime->motion_anchor_distance_um =
                                (int64_t)confirmed_distance_mm * 1000;
                        runtime->motion_anchor_tick = now;
                        runtime->motion_anchor_from_traffic = 0;
                }
                if (schedule_motion_deadlines(
                            slot, now) < 0) {
                        fail_launch_wave(
                                token,
                                TC2_FAILURE_INTERNAL);
                        continue;
                }
                /*
                 * If confirmation was delayed, running processing below
                 * receives the real current tick and immediately catches an
                 * already-due braking/watchdog deadline.
                 */
                (void)now;
        }

        /*
         * Keep every confirmed member attached to its launch wave until all
         * members have passed their post-confirmation initialization.  If a
         * later member fails, fail_launch_wave() can then still stop the
         * earlier RUNNING members instead of leaving a partial batch moving.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                unsigned int token =
                        dispatch_runtime[slot]
                                .launch_batch_token;
                if (token == 0 ||
                    dispatch_jobs[slot].state !=
                            TC2_JOB_RUNNING) {
                        continue;
                }
                int first_for_token = 1;
                int still_launching = 0;
                for (int peer = 0;
                     peer < TC2_DISPATCH_MAX_JOBS; ++peer) {
                        if (peer < slot &&
                            dispatch_runtime[peer]
                                            .launch_batch_token ==
                                    token) {
                                first_for_token = 0;
                                break;
                        }
                        if (dispatch_runtime[peer]
                                            .launch_batch_token ==
                                    token &&
                            dispatch_jobs[peer].state ==
                                    TC2_JOB_LAUNCHING) {
                                still_launching = 1;
                        }
                }
                if (!first_for_token || still_launching) {
                        continue;
                }
                can_batch_status_t status;
                if (CanGetBatchStatus(
                            dispatch_can_tid, token,
                            &status) < 0 ||
                    status.state != CAN_BATCH_COMPLETE) {
                        continue;
                }
                for (int member = 0;
                     member < TC2_DISPATCH_MAX_JOBS;
                     ++member) {
                        if (dispatch_runtime[member]
                                            .launch_batch_token ==
                                    token &&
                            dispatch_jobs[member].state ==
                                    TC2_JOB_RUNNING) {
                                dispatch_runtime[member]
                                        .launch_batch_token = 0;
                        }
                }
        }
}

static void process_preparing_jobs(int now) {
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        int have_preparing = 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state ==
                    TC2_JOB_PREPARING) {
                        have_preparing = 1;
                        break;
                }
        }
        if (!have_preparing) return;

        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0) {
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state ==
                            TC2_JOB_PREPARING) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_SENSOR_SERVICE);
                        }
                }
                return;
        }

        /*
         * PREPARING handles only the bounded initial movement window (and a
         * possible leading reverse).  Later independent turnouts are sent by
         * the moving nextnext cursor; the next cursor separately verifies
         * direction and real conflict ownership before passage.
         */
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_PREPARING) continue;

                if (reservation.generation_by_train[job->train] !=
                            job->plan_generation) {
                        fail_job(slot, TC2_FAILURE_RESERVATION);
                        continue;
                }
                if (sensor_health_is_safe(
                            slot, &sensors, 0, now) < 0) {
                        fail_job(slot, TC2_FAILURE_SENSOR_SERVICE);
                        continue;
                }
                /*
                 * PREPARING is a zero-speed state.  Origin-contact settling
                 * and sensor events produced by other managed trains must
                 * not turn this stopped train into a sensor-sequence
                 * failure.  The accepted launch batch rebases all movement
                 * sensor counters immediately before RUNNING.
                 */
                int can_health = can_health_is_safe(slot, 0, now);
                if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                        fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (can_health == TC2_CAN_HEALTH_RETRY) continue;

                if (runtime->reroute_reverse_before_resources) {
                        if (runtime->prelaunch_reverse_pending) {
                                /* The reverse pass below owns this transition. */
                                continue;
                        }
                        if (runtime->prelaunch_reverse_ready_at_tick < 0 ||
                            !tick_reached(
                                    now,
                                    runtime
                                            ->prelaunch_reverse_ready_at_tick)) {
                                continue;
                        }
                        runtime->reroute_reverse_before_resources = 0;
                        int queued = queue_turnout_plan_for_leg(slot);
                        if (queued == CAN_SEND_BUSY) {
                                runtime->turnout_queue_pending = 1;
                                continue;
                        }
                        if (queued < 0) {
                                fail_job(slot, TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        runtime->turnout_batch_token =
                                queued > 0 ? (unsigned int)queued : 0;
                        if (queued > 0) continue;
                }

                if (runtime->turnout_queue_pending) {
                        int queued =
                                queue_turnout_plan_for_leg(slot);
                        if (queued == CAN_SEND_BUSY) {
                                continue;
                        }
                        if (queued < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        runtime->turnout_queue_pending = 0;
                        runtime->turnout_batch_token =
                                queued > 0 ?
                                        (unsigned int)queued : 0;
                        if (queued > 0) continue;
                        if (runtime->prelaunch_reverse_pending) {
                                runtime
                                        ->prelaunch_turnout_settle_at_tick =
                                        now;
                        }
                }

                if (runtime->turnout_batch_token != 0) {
                        can_batch_status_t status;
                        if (CanGetBatchStatus(
                                    dispatch_can_tid,
                                    runtime->turnout_batch_token,
                                    &status) < 0 ||
                            status.token !=
                                    runtime->turnout_batch_token ||
                            status.total < 1) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_TURNOUT);
                                continue;
                        }
                        if (status.state == CAN_BATCH_FAILED) {
                                /*
                                 * Priority braking/reverse commands
                                 * deliberately preempt speculative turnout
                                 * traffic without incrementing CAN failure
                                 * health. Requeue the idempotent plan; a real
                                 * transport fault was already caught by the
                                 * health gate above.
                                 */
                                int retry =
                                        queue_turnout_plan_for_leg(
                                                slot);
                                if (retry == CAN_SEND_BUSY) {
                                        runtime
                                                ->turnout_batch_token = 0;
                                        runtime
                                                ->turnout_queue_pending = 1;
                                        continue;
                                }
                                if (retry < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                runtime->turnout_batch_token =
                                        (unsigned int)retry;
                                if (retry != 0) continue;
                                if (runtime
                                            ->prelaunch_reverse_pending) {
                                        runtime
                                                ->prelaunch_turnout_settle_at_tick =
                                                now;
                                }
                        }
                        if (status.state != CAN_BATCH_COMPLETE ||
                            (runtime->turnout_batch_token != 0 &&
                             status.confirmed != status.total)) {
                                continue;
                        }
                        runtime->turnout_batch_token = 0;
                        if (runtime->prelaunch_reverse_pending) {
                                runtime
                                        ->prelaunch_turnout_settle_at_tick =
                                        tick_after(
                                                now,
                                                TC2_TURNOUT_SETTLE_TICKS);
                        }
                }
        }

        /*
         * A zero-physical-distance plan has no speed batch, but it remains
         * non-arrived until its turnout batch is confirmed and any leading
         * direction change has settled. Keep it out of READY promotion.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_PREPARING ||
                    !runtime->zero_motion_arrival_pending ||
                    runtime->turnout_queue_pending ||
                    runtime->turnout_batch_token != 0 ||
                    runtime->prelaunch_reverse_pending ||
                    (runtime
                                     ->prelaunch_reverse_ready_at_tick >=
                             0 &&
                     !tick_reached(
                             now,
                             runtime
                                     ->prelaunch_reverse_ready_at_tick)) ||
                    runtime
                            ->zero_motion_arrival_ready_at_tick < 0 ||
                    !tick_reached(
                            now,
                            runtime
                                    ->zero_motion_arrival_ready_at_tick)) {
                        continue;
                }
                /*
                 * Zero physical motion is still a terminal arrival.  The
                 * destination position is already exact, so atomically
                 * replace every rolling/carry reservation with the bounded
                 * body before dropping future turnout control.  Retaining a
                 * carry here made an ARRIVED train continue owning an old
                 * switch indefinitely.
                 */
                if (update_arrival_hold(slot) < 0) {
                        fail_job(
                                slot,
                                TC2_FAILURE_RESERVATION);
                        continue;
                }
                runtime->zero_motion_arrival_pending = 0;
                runtime->zero_motion_arrival_ready_at_tick = -1;
                retire_future_control_fields(runtime);
                runtime->lifecycle_stop_reason =
                        TC2_LIFECYCLE_STOP_DESTINATION;
                job->ready_at_tick = -1;
                job->state = TC2_JOB_ARRIVED;
                (void)retire_terminal_conflict_zone_memory(slot, now);
        }

        /*
         * A leading zero-distance reversal follows the same safe ordering as
         * an in-route reversal: reserve the outbound window, confirm and
         * mechanically settle every turnout, then reverse, wait for the
         * direction change to settle, and only afterwards enter READY.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_PREPARING ||
                    !runtime->prelaunch_reverse_pending ||
                    runtime->turnout_queue_pending ||
                    runtime->turnout_batch_token != 0 ||
                    runtime
                                    ->prelaunch_turnout_settle_at_tick <
                            0 ||
                    !tick_reached(
                            now,
                            runtime
                                    ->prelaunch_turnout_settle_at_tick)) {
                        continue;
                }
                if (CanTrainReversePriority(
                            dispatch_can_tid,
                            job->train) < 0) {
                        fail_job(
                                slot,
                                TC2_FAILURE_CAN_SERVICE);
                        continue;
                }
                int confirmed = Time();
                if (confirmed < 0) {
                        fail_job(
                                slot,
                                TC2_FAILURE_CAN_SERVICE);
                        continue;
                }
                runtime->prelaunch_reverse_pending = 0;
                runtime->prelaunch_turnout_settle_at_tick = -1;
                runtime->prelaunch_reverse_ready_at_tick =
                        tick_after(
                                confirmed,
                                TC2_REVERSE_SETTLE_TICKS);
                if (runtime
                            ->zero_motion_arrival_pending &&
                    !tick_reached(
                            runtime
                                    ->zero_motion_arrival_ready_at_tick,
                            runtime
                                    ->prelaunch_reverse_ready_at_tick)) {
                        runtime
                                ->zero_motion_arrival_ready_at_tick =
                                runtime
                                        ->prelaunch_reverse_ready_at_tick;
                }
        }

        /*
         * Mechanical settling is local to the turnout resources required by
         * this job.  A disjoint PREPARING peer from the same `go` epoch must
         * not form a batch-wide barrier: it may still be waiting for a remote
         * nextnext resource that this train neither uses nor conflicts with.
         * Real coupling remains in the per-resource FIFO grants, the hard and
         * soft stage checks above, and the central traffic-safety pass before
         * launch.
         */
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_PREPARING ||
                    !regular_movement_gates_ready(slot) ||
                    runtime->zero_motion_arrival_pending ||
                    runtime->prelaunch_reverse_pending ||
                    (runtime->prelaunch_reverse_ready_at_tick >= 0 &&
                     !tick_reached(
                             now,
                             runtime
                                     ->prelaunch_reverse_ready_at_tick)) ||
                    runtime->turnout_queue_pending ||
                    runtime->turnout_batch_token != 0) {
                        continue;
                }

                if (runtime->destination_correction_pending) {
                        /*
                         * This zero-speed job is not a normal launch wave.
                         * Recheck the frozen sensor journal and exact rolling
                         * reservation after next/nextnext have settled, then
                         * let the bounded correction helper create its own
                         * endpoint deadline and active marker.  It must
                         * never fall through to planned_launch_speed as an
                         * unbounded ordinary speed-40 resume.
                         */
                        int failure_reason =
                                prelaunch_failure_reason(
                                        slot, &reservation,
                                        &sensors, now);
                        if (failure_reason != TC2_FAILURE_NONE) {
                                fail_job(slot, failure_reason);
                                continue;
                        }
                        /*
                         * A missing intermediate detector is represented by
                         * sensor_offset == -1, but that does not mean the
                         * route has already reached its final real anchor.
                         * `target_seen` is the state boundary: before it, keep
                         * retrying the same bounded correction all the way to
                         * the d coordinate; only after it may the explicit
                         * post-anchor virtual-endpoint phase run.
                         */
                        int correction = !runtime->target_seen ?
                                begin_bounded_destination_correction(
                                        slot, now) :
                                begin_bounded_virtual_endpoint_approach(
                                        slot, now);
                        if (correction < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                        }
                        continue;
                }

                int ready_tick = tick_after(
                        now, TC2_TURNOUT_SETTLE_TICKS);
                if (runtime->prelaunch_reverse_ready_at_tick >= 0 &&
                    !tick_reached(
                            ready_tick,
                            runtime
                                    ->prelaunch_reverse_ready_at_tick)) {
                        ready_tick =
                                runtime
                                        ->prelaunch_reverse_ready_at_tick;
                }
                runtime->ready_wave_tick = ready_tick;
                job->ready_at_tick = ready_tick;
                job->state = TC2_JOB_READY;
                dispatch_batch_ready_at_tick = ready_tick;
        }
}

static void process_running_jobs(int now) {
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        int have_running = 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (dispatch_jobs[slot].state == TC2_JOB_RUNNING ||
                    dispatch_jobs[slot].state == TC2_JOB_BRAKING) {
                        have_running = 1;
                        break;
                }
        }
        if (!have_running) return;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0 ||
            TrainSensorGetLatest(dispatch_sensor_tid, &sensors) < 0) {
                for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state ==
                                    TC2_JOB_RUNNING ||
                            dispatch_jobs[slot].state ==
                                    TC2_JOB_BRAKING) {
                                fail_job(slot, TC2_FAILURE_SENSOR_SERVICE);
                        }
                }
                return;
        }

        int unexpected_unattributed = 0;
        unsigned int unattributed_delta = 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if ((dispatch_jobs[slot].state ==
                            TC2_JOB_RUNNING ||
                     dispatch_jobs[slot].state ==
                            TC2_JOB_BRAKING) &&
                    sensors.unattributed_count !=
                            dispatch_runtime[slot]
                                    .launch_unattributed_count) {
                        unsigned int delta =
                                sensors.unattributed_count -
                                dispatch_runtime[slot]
                                        .launch_unattributed_count;
                        if (delta != 1 ||
                            dispatch_runtime[slot]
                                    .unattributed_spurious_tolerated ||
                            dispatch_jobs[slot]
                                    .spurious_sensor_count >=
                                    TC2_MAX_SENSOR_SPURIOUS) {
                                unexpected_unattributed = 1;
                                break;
                        }
                        unattributed_delta = delta;
                }
        }
        if (!unexpected_unattributed && unattributed_delta == 1) {
                /*
                 * A single rising report outside every reservation is the
                 * one globally unattributed spurious event that TC2 must
                 * tolerate. Consume it for every train that was moving in
                 * this observation window; a second such event is no longer
                 * ambiguous and fails the whole active set closed.
                 */
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state !=
                                    TC2_JOB_RUNNING &&
                            dispatch_jobs[slot].state !=
                                    TC2_JOB_BRAKING) {
                                continue;
                        }
                        if (sensors.unattributed_count !=
                            dispatch_runtime[slot]
                                    .launch_unattributed_count) {
                                dispatch_runtime[slot]
                                        .launch_unattributed_count =
                                        sensors.unattributed_count;
                                dispatch_runtime[slot]
                                        .unattributed_spurious_tolerated =
                                        1;
                                ++dispatch_jobs[slot]
                                          .spurious_sensor_count;
                        }
                }
        }
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if ((dispatch_jobs[slot].state ==
                            TC2_JOB_RUNNING ||
                     dispatch_jobs[slot].state ==
                            TC2_JOB_BRAKING) &&
                    sensors.unattributed_count !=
                            dispatch_runtime[slot]
                                    .launch_unattributed_count) {
                        unexpected_unattributed = 1;
                        break;
                }
        }
        if (unexpected_unattributed) {
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (dispatch_jobs[slot].state ==
                                    TC2_JOB_RUNNING ||
                            dispatch_jobs[slot].state ==
                                    TC2_JOB_BRAKING) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_SENSOR_SEQUENCE);
                        }
                }
                return;
        }

        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (job->state != TC2_JOB_RUNNING &&
                    job->state != TC2_JOB_BRAKING) {
                        continue;
                }
                if (reservation.generation_by_train[job->train] !=
                            job->plan_generation) {
                        fail_job(slot, TC2_FAILURE_RESERVATION);
                        continue;
                }
                if (sensor_health_is_safe(
                            slot, &sensors, 0, now) < 0) {
                        fail_job(slot, TC2_FAILURE_SENSOR_SERVICE);
                        continue;
                }
                if (sensors.attribution_unavailable_count !=
                            job->launch_attribution_unavailable_count ||
                    sensors.attribution_failure_by_train[job->train] !=
                            runtime
                                    ->launch_train_attribution_failure) {
                        fail_job(slot, TC2_FAILURE_SENSOR_SEQUENCE);
                        continue;
                }
                int can_health = can_health_is_safe(
                        slot, 0, now);
                if (can_health == TC2_CAN_HEALTH_HARD_FAIL) {
                        fail_job(slot, TC2_FAILURE_CAN_HEALTH);
                        continue;
                }
                if (can_health == TC2_CAN_HEALTH_RETRY) {
                        /*
                         * A delayed controller-wide notifier heartbeat is a
                         * recoverable loss of movement permission.  Stop a
                         * moving train through the ordinary authority-hold
                         * FSM; a train already braking has a zero command in
                         * flight and only needs to wait for fresh evidence.
                         */
                        if (job->state == TC2_JOB_RUNNING) {
                                (void)begin_local_authority_stop(
                                        slot, now,
                                        job->conflict_train,
                                        -1, -1);
                        }
                        continue;
                }
                int journal = drain_sensor_journal(slot, now);
                if (journal < 0) {
                        fail_job(
                                slot,
                                journal == -1 ||
                                        job->journal_lost ?
                                TC2_FAILURE_SENSOR_SEQUENCE :
                                TC2_FAILURE_SENSOR_SERVICE);
                        continue;
                }
                if (job->state != TC2_JOB_RUNNING) continue;

                /*
                 * nextnext is preparation, whereas can_train_move() is the
                 * next/permission audit.  Let the bounded rolling prefetch
                 * request or settle one future suffix before applying that
                 * strict movement audit.  The prefetch itself grants no
                 * movement: can_train_move(), conflict-zone verification and
                 * the hard braking ceiling below still run before this train
                 * may continue.  This ordering removes the B13->D2 circular
                 * wait without preparing the whole route at departure.
                 */
                if (!runtime->destination_correction_active) {
                        int prefetch_failure =
                                process_running_authority_prefetch(
                                        slot, now,
                                        &reservation, &sensors);
                        if (prefetch_failure !=
                            TC2_FAILURE_NONE) {
                                fail_job(slot, prefetch_failure);
                                continue;
                        }
                }

                /*
                 * A prior positive command is not perpetual permission.
                 * Re-evaluate the same route/localization, next, nextnext,
                 * node-pair, destination, and traffic gates every tick.  A
                 * lost gate stops only this approaching train; pairwise
                 * HEAD_ON handling remains the atomic two-train stop below.
                 */
                if (!can_train_move(slot)) {
                        int envelope =
                                traffic_braking_envelope_mm(slot);
                        (void)begin_local_authority_stop(
                                slot, now, job->conflict_train,
                                -1, envelope);
                        continue;
                }

                if (runtime->destination_correction_active) {
                        /*
                         * Correction is still positive motion. Revalidate
                         * the same exact next and nextnext resource sets on
                         * every scheduler tick; losing either gate stops the
                         * crawl before its bounded detector/endpoint.
                         */
                        int correction_gate =
                                enforce_conflict_zone_gate(slot, now);
                        if (correction_gate < 0) {
                                fail_job(slot, TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        if (correction_gate > 0) {
                                /*
                                 * The safety stop suspends, but does not turn
                                 * this explicitly bounded correction into an
                                 * ordinary speed-40 trip.  Keep its active
                                 * marker and exact detector/endpoint boundary;
                                 * the stopped authority/traffic FSM will
                                 * reacquire that same boundary and revalidate
                                 * next plus nextnext before resuming it.
                                 */
                                continue;
                        }
                        int64_t correction_progress_um;
                        if (job->destination_distance_mm < 0 ||
                            runtime_motion_progress_um(
                                    slot, now,
                                    &correction_progress_um) < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        int64_t confirmed_um =
                                (int64_t)job->confirmed_distance_mm *
                                1000;
                        if (correction_progress_um < confirmed_um) {
                                correction_progress_um = confirmed_um;
                        }
                        if (job->estimated_distance_um >
                            correction_progress_um) {
                                correction_progress_um =
                                        job->estimated_distance_um;
                        }
                        int64_t destination_um =
                                (int64_t)job
                                        ->destination_distance_mm *
                                1000;
                        if (correction_progress_um > destination_um) {
                                correction_progress_um = destination_um;
                        }
                        job->estimated_distance_um =
                                correction_progress_um;
                        int64_t remaining_um =
                                destination_um -
                                correction_progress_um;
                        job->remaining_distance_mm =
                                remaining_um > 0 ?
                                (int)((remaining_um + 999) / 1000) :
                                0;
                        /*
                         * A correction detector is only a stronger position
                         * anchor.  Its absence is not a timer stop: continue
                         * the monotonic speed-40 projection until the actual
                         * lowercase-d coordinate, while the movement gates
                         * above remain valid on every scheduler tick.
                         */
                        if (correction_progress_um >= destination_um) {
                                runtime
                                        ->destination_correction_reached_endpoint =
                                        1;
                                runtime->destination_correction_active = 0;
                                runtime->destination_correction_pending = 0;
                                runtime->destination_correction_deadline_tick =
                                        -1;
                                runtime->destination_correction_sensor_offset =
                                        -1;
                                begin_stop(
                                        slot, now,
                                        TC2_STOP_DESTINATION, 1,
                                        TC2_STOP_TRIGGER_TIMER);
                        }
                        continue;
                }

                int zone_gate =
                        enforce_conflict_zone_gate(slot, now);
                if (zone_gate < 0) {
                        fail_job(slot, TC2_FAILURE_INTERNAL);
                        continue;
                }
                if (zone_gate > 0) continue;

                /*
                 * Prefetch above may promote a farther settled window, but
                 * preparation must never issue a positive-speed command.
                 * Restore a previously reduced command only after the fresh
                 * full movement predicate and the exact conflict-zone gate
                 * have both succeeded on this scheduler tick.
                 */
                if (authority_restore_requested_speed(
                            slot, now) < 0) {
                        fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                        continue;
                }

                /*
                 * A partial rolling authority is a hard movement limit, not
                 * merely reservation metadata.  Issue speed zero while the
                 * complete conservative braking envelope still fits before
                 * the train-center ceiling.  begin_stop() records the
                 * measured coast endpoint for a monotonic UI hold; the
                 * larger envelope here is what keeps the physical body out
                 * of the unowned block.
                 */
                if (runtime->rolling_authority_active &&
                    runtime->authority_end_offset >= 0 &&
                    runtime->authority_end_offset <
                            job->destination_route_offset &&
                    !current_next_zone_covers_authority_end(slot) &&
                    !(runtime->leg_end_offset <
                                      job
                                              ->destination_route_offset &&
                      runtime->authority_end_offset >=
                              runtime->leg_end_offset)) {
                        int64_t progress_um;
                        int braking_envelope =
                                traffic_braking_envelope_mm(
                                        slot);
                        int64_t ceiling_um =
                                (int64_t)runtime
                                        ->authority_center_ceiling_mm *
                                1000;
                        if (runtime
                                            ->authority_center_ceiling_mm <
                                    0 ||
                            braking_envelope < 0 ||
                            runtime_motion_progress_um(
                                    slot, now,
                                    &progress_um) < 0 ||
                            progress_um < 0 ||
                            progress_um >
                                    INT64_MAX -
                                    (int64_t)braking_envelope *
                                            1000) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        if (progress_um +
                                    (int64_t)braking_envelope *
                                            1000 >=
                            ceiling_um) {
                                if (abandon_authority_prefetch(
                                            slot) < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_RESERVATION);
                                        continue;
                                }
                                int64_t gap_um =
                                        ceiling_um -
                                        progress_um;
                                int gap_mm =
                                        gap_um > 0 ?
                                        (int)((gap_um + 999) /
                                              1000) : 0;
                                (void)begin_local_authority_stop(
                                        slot, now,
                                        job->conflict_train,
                                        gap_mm,
                                        braking_envelope);
                                if (job->state ==
                                            TC2_JOB_BRAKING &&
                                    runtime->stop_purpose ==
                                            TC2_STOP_TRAFFIC &&
                                    runtime->traffic_reason ==
                                            TC2_TRAFFIC_AUTHORITY &&
                                    runtime
                                                    ->authority_request_tick <
                                            0) {
                                        (void)begin_authority_request(
                                                slot, now, 0);
                                }
                                continue;
                        }
                }

                int direct_final_leg =
                        uses_measured_direct_stop(job) &&
                        runtime->leg_end_offset ==
                                job->destination_route_offset;
                if (direct_final_leg &&
                    !runtime->approach_sent) {
                        int64_t progress_um;
                        int64_t command_um;
                        if (measured_direct_progress_um(
                                    slot, now, &progress_um,
                                    &command_um) < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        /*
                         * Within one sensor-anchored motion interval the
                         * controller remains monotonic.  An ordered detector
                         * reached after a traffic hold explicitly rebases
                         * job->estimated_distance_um in the sensor handler,
                         * so this clamp cannot preserve an older optimistic
                         * coast bound across that stronger observation.
                         */
                        int64_t confirmed_um =
                                job->confirmed_distance_mm >= 0 ?
                                (int64_t)job
                                        ->confirmed_distance_mm * 1000 :
                                0;
                        if (progress_um < confirmed_um) {
                                progress_um = confirmed_um;
                        }
                        if (progress_um < job->estimated_distance_um) {
                                progress_um = job->estimated_distance_um;
                        }
                        int64_t destination_um =
                                (int64_t)job
                                        ->destination_distance_mm * 1000;
                        if (progress_um > destination_um) {
                                progress_um = destination_um;
                        }
                        job->estimated_distance_um =
                                progress_um;
                        int64_t remaining_um =
                                destination_um - progress_um;
                        job->remaining_distance_mm =
                                remaining_um > 0 ?
                                (int)((remaining_um + 999) /
                                      1000) : 0;
                        int final_anchor_offset = -1;
                        int wait_for_real_anchor =
                                destination_direct_stop_waits_for_real_anchor(
                                        slot, command_um,
                                        &final_anchor_offset);
                        if (wait_for_real_anchor < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        int anchor_seek_expired = 0;
                        if (wait_for_real_anchor) {
                                int trusted_remaining_mm = -1;
                                anchor_seek_expired =
                                        update_destination_anchor_seek(
                                                slot, now,
                                                final_anchor_offset,
                                                &trusted_remaining_mm);
                                if (anchor_seek_expired < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                if (trusted_remaining_mm >
                                    job->remaining_distance_mm) {
                                        job->remaining_distance_mm =
                                                trusted_remaining_mm;
                                }
                        } else {
                                clear_destination_anchor_seek(runtime);
                        }
                        if (anchor_seek_expired) {
                                runtime->approach_sent = 1;
                                begin_stop(
                                        slot, now,
                                        TC2_STOP_DESTINATION, 1,
                                        TC2_STOP_TRIGGER_TIMER);
                                continue;
                        }
                        if (progress_um >= command_um &&
                            !wait_for_real_anchor) {
                                /*
                                 * This is the ordinary requested-speed stop.
                                 * Speed 40 is not a universal approach stage:
                                 * it is reserved for a later, explicitly
                                 * marked correction after this zero command
                                 * has physically settled and the destination
                                 * remains unconfirmed.  The >= crossing is
                                 * intentional because tick-domain progress
                                 * need not equal the threshold exactly.
                                 */
                                runtime->approach_sent = 1;
                                begin_stop(
                                        slot, now,
                                        TC2_STOP_DESTINATION, 1,
                                        TC2_STOP_TRIGGER_TIMER);
                                continue;
                        }

                        if (progress_um >= command_um &&
                            wait_for_real_anchor) {
                                /*
                                 * A clock/coast projection reached the timer
                                 * threshold before the final real braking
                                 * anchor did.  Keep normal requested speed
                                 * under the already-checked authority,
                                 * turnout and safety gates.  Any ordered
                                 * detector rebases this interval; an omitted
                                 * adjacent detector or short deadzone must not
                                 * turn the middle of the route into a speed-40
                                 * correction or an immediate destination
                                 * stop.
                                 *
                                 * The positive-motion budget maintained above
                                 * provides the fail-closed bound from the
                                 * latest real detector to the requested-speed
                                 * zero point.  It is deliberately not the
                                 * distance to merely the next detector
                                 * (data2002 missed that adjacent report), and
                                 * traffic-hold time pauses rather than resets
                                 * it.  This never grants authority across an
                                 * unverified turnout or conflict boundary.
                                 */
                                job->braking_at_tick = -1;
                                job->prediction_timing_valid = 0;
                        } else {

                                /*
                                 * Publish the next distance crossing for
                                 * inspection and watchdog diagnostics.
                                 * Correctness comes from the progress
                                 * comparison above on every scheduler tick,
                                 * not from this timestamp.
                                 */
                                int velocity =
                                        measured_direct_velocity_um_per_tick(
                                                job,
                                                runtime->command_speed);
                                int64_t until_command_um =
                                        command_um - progress_um;
                                if (velocity < 1 ||
                                    until_command_um < 0 ||
                                    until_command_um > 0x7fffffff) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                int ticks =
                                        Tc2MotionTravelTicksUmAtVelocity(
                                                velocity,
                                                (int)until_command_um);
                                if (ticks < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                job->braking_at_tick =
                                        tick_after(now, ticks);
                                job->prediction_velocity_um_per_tick =
                                        velocity;
                                job->prediction_anchor_tick = now;
                                job->prediction_anchor_distance_mm =
                                        (int)((progress_um + 999) / 1000);
                                job->prediction_command_at_tick =
                                        job->braking_at_tick;
                                job->prediction_timing_valid = 1;
                        }
                }

                if (!direct_final_leg &&
                    !runtime->approach_sent &&
                    tick_reached(now, job->braking_at_tick)) {
                        int purpose =
                                runtime->leg_end_offset <
                                                job
                                                        ->destination_route_offset ?
                                        TC2_STOP_REVERSAL :
                                        TC2_STOP_DESTINATION;
                        if (purpose == TC2_STOP_DESTINATION &&
                            uses_precision_approach(job) &&
                            !runtime->target_seen &&
                            runtime->command_speed >
                                    TC2_PRECISION_APPROACH_SPEED) {
                                /*
                                 * Do not turn an unobserved point estimate
                                 * into a final stop. Slow enough to acquire
                                 * the physical anchor, then let the sensor
                                 * handler rebase the crawl timer.
                                 */
                                int reduced = reduce_for_anchor_stage(
                                        slot,
                                        TC2_PRECISION_APPROACH_SPEED);
                                if (reduced < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_CAN_SERVICE);
                                        continue;
                                }
                                if (reduced > 0) {
                                        int envelope =
                                                traffic_braking_envelope_mm(
                                                        slot);
                                        (void)begin_local_authority_stop(
                                                slot, now,
                                                job->conflict_train,
                                                -1, envelope);
                                        continue;
                                }
                                if (schedule_motion_deadlines(
                                            slot, now) < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                continue;
                        }
                        runtime->approach_sent = 1;
                        if (purpose == TC2_STOP_REVERSAL) {
                                /*
                                 * At this fast-bound deadline the train is
                                 * at most its calibrated stopping distance
                                 * before the reversal sensor. Command zero
                                 * now. The larger reserved braking guard
                                 * includes model uncertainty beyond that
                                 * sensor, while observations remain live
                                 * during coast and can still prove the
                                 * reversal point before the speed-derived
                                 * settle deadline. Starting a second timer
                                 * from the old sensor would double-count
                                 * distance and is forbidden.
                                 */
                                begin_stop(
                                        slot, now,
                                        TC2_STOP_REVERSAL, 1,
                                        TC2_STOP_TRIGGER_TIMER);
                        } else {
                                begin_stop(
                                        slot, now, purpose, 1,
                                        TC2_STOP_TRIGGER_TIMER);
                        }
                        continue;
                }
                if (job->watchdog_at_tick >= 0 &&
                    tick_reached(now, job->watchdog_at_tick)) {
                        /*
                         * A detector deadline is localization evidence, not
                         * movement authority.  In particular, next-next is
                         * only an opportunistic turnout pre-switch and a
                         * late detector must not manufacture a zero-speed
                         * command when the current hard turnout is owned and
                         * traffic safety reports no conflict.
                         *
                         * Keep the route, destination, command speed, hard
                         * turnout ticket, and reservation intact.  Mark the
                         * position estimated and disarm this one prediction;
                         * the next ordered physical detector rebases motion
                         * and schedule_motion_deadlines() arms a fresh
                         * diagnostic deadline.  Real authority, next-turnout
                         * FIFO, head-on/following safety, CAN health, and the
                         * destination controller continue to fail/stop by
                         * their own independent checks above.
                         */
                        job->position_estimated = 1;
                        job->watchdog_at_tick = -1;
                }
        }
}

static int accept_unattributed_for_job(
        int slot,
        const train_sensor_snapshot_t *sensors) {
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        unsigned int delta =
                sensors->unattributed_count -
                runtime->launch_unattributed_count;
        if (delta == 0) return 0;
        if (delta != 1 ||
            runtime->unattributed_spurious_tolerated ||
            job->spurious_sensor_count >=
                    TC2_MAX_SENSOR_SPURIOUS) {
                return -1;
        }
        runtime->launch_unattributed_count =
                sensors->unattributed_count;
        runtime->unattributed_spurious_tolerated = 1;
        ++job->spurious_sensor_count;
        return 0;
}

static int reversing_preflight_failure(int slot, int now) {
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        track_reservation_snapshot reservation;
        train_sensor_snapshot_t sensors;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid,
                    &reservation) < 0 ||
            TrainSensorGetLatest(
                    dispatch_sensor_tid, &sensors) < 0) {
                return TC2_FAILURE_SENSOR_SERVICE;
        }
        if (reservation.generation_by_train[job->train] !=
                    job->plan_generation) {
                return TC2_FAILURE_RESERVATION;
        }
        if (sensor_health_is_safe(
                    slot, &sensors, 0, now) < 0) {
                return TC2_FAILURE_SENSOR_SERVICE;
        }
        if (sensors.attribution_unavailable_count !=
                    job->launch_attribution_unavailable_count ||
            sensors.attribution_failure_by_train[job->train] !=
                    runtime->launch_train_attribution_failure ||
            accept_unattributed_for_job(slot, &sensors) < 0 ||
            !journal_is_clean_after(
                    job->train,
                    runtime->last_journal_sequence)) {
                return TC2_FAILURE_SENSOR_SEQUENCE;
        }
        return TC2_FAILURE_NONE;
}

static int restage_after_localization(int slot, int now) {
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        if (job->provisional_prediction) return -1;
        tc2_dispatch_request request;
        int train = job->train;
        int speed = job->speed;
        int destination = job->destination_index;
        int force_reverse_first =
                dispatch_runtime[slot].force_reverse_first;
        int operator_reroute =
                dispatch_runtime[slot].reroute_select_direction;
        int localization_hops =
                dispatch_runtime[slot].localization_hops + 1;
        unsigned int launch_epoch =
                job->job_launch_epoch;
        clear_request(&request, TC2_DISPATCH_MSG_STAGE);
        request.train = train;
        request.start_index =
                TC2_DISPATCH_START_CURRENT;
        request.speed = speed;
        request.destination_index = destination;
        request.reserved = force_reverse_first ?
                TC2_DISPATCH_REQUEST_FORCE_REVERSE_FIRST :
                (operator_reroute ?
                 TC2_DISPATCH_REQUEST_OPERATOR_REROUTE : 0);
        /*
         * The localization leg has already committed its exact stationary
         * body.  Retire its old next/nextnext queue entries before stage_job()
         * replaces the route; otherwise the new CURRENT route can inherit a
         * stale owner that no longer corresponds to its first turnout.
         */
        if (localization_hops > TC2_MAX_LOCALIZATION_HOPS ||
            retire_terminal_conflict_zone_memory(slot, now) < 0 ||
            stage_job(&request) < 0) return -1;
        int restaged = find_train_job(train);
        if (restaged != slot) return -1;
        dispatch_jobs[slot].state = TC2_JOB_WAITING;
        dispatch_jobs[slot].queue_sequence =
                ++dispatch_queue_sequence;
        dispatch_jobs[slot].job_launch_epoch =
                launch_epoch;
        dispatch_runtime[slot].queue_sequence =
                dispatch_jobs[slot].queue_sequence;
        dispatch_runtime[slot].wait_since_tick = now;
        dispatch_runtime[slot].launch_epoch =
                launch_epoch;
        dispatch_runtime[slot].localization_hops =
                localization_hops;
        return 0;
}

static void process_braking_and_reversing(int now) {
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
                if (job->state == TC2_JOB_BRAKING &&
                    runtime->emergency_stop_token != 0) {
                        can_batch_status_t status;
                        int result = CanGetBatchStatus(
                                dispatch_can_tid,
                                runtime->emergency_stop_token,
                                &status);
                        /*
                         * A status-query timeout says nothing about whether
                         * CS3 already accepted the queued zero.  Preserve the
                         * token and poll it again instead of issuing duplicate
                         * emergency stops on every dispatcher tick.
                         */
                        if (result < 0) {
                                continue;
                        }
                        if (result == 0 &&
                            status.token ==
                                    runtime->emergency_stop_token &&
                            status.state == CAN_BATCH_PENDING) {
                                continue;
                        }
                        if (result == 0 &&
                            status.token ==
                                    runtime->emergency_stop_token &&
                            status.state == CAN_BATCH_COMPLETE) {
                                int stop_speed =
                                        runtime->motion_speed_ceiling > 0 ?
                                        runtime->motion_speed_ceiling :
                                        job->speed;
                                int settle_ticks =
                                        Tc2MotionStopSettleTicks(
                                                stop_speed);
                                if (settle_ticks < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                runtime->emergency_stop_token = 0;
                                runtime->settle_at_tick =
                                        tick_after(now, settle_ticks);
                                job->stop_confirmed_tick = now;
                                continue;
                        }

                        /* Keep the trip stopped and retry only the zero. */
                        int train = job->train;
                        int token = CanTrainEmergencyStopBatch(
                                dispatch_can_tid, &train, 1);
                        if (token > 0) {
                                runtime->emergency_stop_token =
                                        (unsigned int)token;
                        }
                        continue;
                }
                if (job->state == TC2_JOB_CANCEL_BRAKING &&
                    tick_reached(now, runtime->settle_at_tick)) {
                        job->estimated_distance_um =
                                runtime->traffic_hold_distance_um;
                        job->state = TC2_JOB_STOPPED;
                        job->stop_sent_tick = now;
                } else if (job->state == TC2_JOB_BRAKING &&
                    tick_reached(now, runtime->settle_at_tick)) {
                        if (runtime->stop_purpose ==
                            TC2_STOP_DESTINATION) {
                                /*
                                 * The dedicated speed-40 controller has
                                 * already reached the actual lowercase-d
                                 * scalar.  Intermediate detector loss is not
                                 * an arrival veto here: keep the position
                                 * explicitly estimated, convert the physical
                                 * body to the ordinary ARRIVED hold, and
                                 * retire only future route/turnout control.
                                 */
                                if (runtime
                                            ->destination_correction_reached_endpoint) {
                                        job->position_estimated = 1;
                                        if (update_arrival_hold(slot) < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_RESERVATION);
                                                continue;
                                        }
                                        runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_DESTINATION;
                                        retire_future_control_fields(runtime);
                                        job->state = TC2_JOB_ARRIVED;
                                        job->remaining_distance_mm = 0;
                                        job->next_sensor_node = -1;
                                        (void)retire_terminal_conflict_zone_memory(
                                                slot, now);
                                        continue;
                                }
                                if (!runtime->localization_only &&
                                    job->destination_offset_mm > 0) {
                                        int correction_coast_arrival = 0;
                                        /*
                                         * First complete the requested-speed
                                         * stop.  Only after it has settled do
                                         * we decide whether a real-sensor or
                                         * virtual-endpoint tail remains.  A
                                         * positive speed 40 below is therefore
                                         * an explicit bounded correction, not
                                         * an ordinary low-speed route command.
                                         */
                                        if (!runtime->target_seen) {
                                                int correction =
                                                        begin_bounded_destination_correction(
                                                                slot, now);
                                                if (correction > 0) {
                                                        continue;
                                                }
                                                if (correction < 0) {
                                                        fail_job(
                                                                slot,
                                                                TC2_FAILURE_INTERNAL);
                                                        continue;
                                                }
                                        }
                                        if (runtime->target_seen &&
                                            ((job->stop_trigger ==
                                                              TC2_STOP_TRIGGER_SENSOR) ||
                                             (job->stop_trigger ==
                                                              TC2_STOP_TRIGGER_TIMER &&
                                              !runtime
                                                       ->destination_correction_attempted))) {
                                                int endpoint_approach =
                                                        begin_bounded_virtual_endpoint_approach(
                                                                slot, now);
                                                if (endpoint_approach > 0) {
                                                        continue;
                                                }
                                                if (endpoint_approach < 0) {
                                                        fail_job(
                                                                slot,
                                                                TC2_FAILURE_INTERNAL);
                                                        continue;
                                                }
                                                if (endpoint_approach == 0) {
                                                        int64_t correction_start_um;
                                                        int64_t correction_remaining_um;
                                                        correction_coast_arrival =
                                                                bounded_virtual_endpoint_remaining_um(
                                                                        slot,
                                                                        &correction_start_um,
                                                                        &correction_remaining_um) == 0 &&
                                                                correction_remaining_um <= 0;
                                                }
                                        }
                                        if ((job->stop_trigger !=
                                                     TC2_STOP_TRIGGER_TIMER &&
                                             !correction_coast_arrival) ||
                                            !runtime->target_seen) {
                                                job->position_estimated = 1;
                                                job->hold_active = 1;
                                                runtime->destination_correction_active = 0;
                                                runtime->destination_correction_pending = 0;
                                                runtime->destination_correction_deadline_tick = -1;
                                                runtime->destination_correction_sensor_offset = -1;
                                                runtime->movement_plan_active = 0;
                                                runtime->command_speed = 0;
                                                runtime->motion_speed_ceiling = 0;
                                                job->command_speed = 0;
                                                runtime->lifecycle_stop_reason =
                                                        TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                                job->state =
                                                        TC2_JOB_STOP_UNCONFIRMED;
                                                continue;
                                        }
                                        job->position_estimated = 1;
                                        if (update_arrival_hold(slot) < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_RESERVATION);
                                                continue;
                                        }
                                        runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_DESTINATION;
                                        retire_future_control_fields(runtime);
                                        job->state = TC2_JOB_ARRIVED;
                                        job->remaining_distance_mm = 0;
                                        job->next_sensor_node = -1;
                                        (void)retire_terminal_conflict_zone_memory(
                                                slot, now);
                                        continue;
                                }
                                /*
                                 * A braking timer is only a conservative
                                 * command deadline; it is not evidence that
                                 * the train reached the destination.  If
                                 * the last confirmed route point is still
                                 * before the selected destination, retain
                                 * the complete remaining reservation and
                                 * the last confirmed progress/next sensor.
                                 * The operator must use cancel/remove
                                 * before the train or reservation can leave
                                 * this fail-closed hold.
                                 *
                                 * Progress at or beyond the target keeps
                                 * the existing estimated-arrival recovery:
                                 * it covers an exact target pulse awaiting
                                 * corroboration and the one-missing-sensor
                                 * case where an ordered guard observation
                                 * already proved passage beyond the target.
                                 */
                                if (job->current_route_offset <
                                    job->target_route_offset) {
                                        int correction =
                                                begin_bounded_destination_correction(
                                                        slot, now);
                                        if (correction > 0) {
                                                continue;
                                        }
                                        if (correction < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_INTERNAL);
                                                continue;
                                        }
                                        job->position_estimated = 1;
                                        job->hold_active = 1;
                                        runtime->movement_plan_active = 0;
                                        runtime->command_speed = 0;
                                        runtime->motion_speed_ceiling = 0;
                                        job->command_speed = 0;
                                        runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        job->state =
                                                TC2_JOB_STOP_UNCONFIRMED;
                                        continue;
                                }
                                int continue_after_localization =
                                        runtime
                                                ->localization_only;
                                if (!runtime->target_corroborated) {
                                        /*
                                         * An expected target report can be
                                         * the single false sensor report.
                                         * Until a later ordered sensor has
                                         * corroborated it, retain the
                                         * anchor-based remaining route. A
                                         * CURRENT continuation must carry
                                         * this complete ambiguity into its
                                         * next atomic plan replacement.
                                         */
                                        job->position_estimated = 1;
                                        job->hold_active = 1;
                                        runtime->movement_plan_active = 0;
                                        runtime->command_speed = 0;
                                        runtime->motion_speed_ceiling = 0;
                                        job->command_speed = 0;
                                        runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        job->state =
                                                TC2_JOB_STOP_UNCONFIRMED;
                                        continue;
                                }
                                int hold_status =
                                        update_arrival_hold(slot);
                                if (hold_status < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_RESERVATION);
                                } else {
                                        retire_future_control_fields(runtime);
                                        runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_DESTINATION;
                                        job->state = TC2_JOB_ARRIVED;
                                        job->remaining_distance_mm = 0;
                                        job->next_sensor_node = -1;
                                        if (continue_after_localization &&
                                            restage_after_localization(
                                                    slot, now) < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_ROUTE);
                                        } else if (!continue_after_localization) {
                                                (void)retire_terminal_conflict_zone_memory(
                                                        slot, now);
                                        }
                                }
                        } else if (runtime->stop_purpose ==
                                   TC2_STOP_TRAFFIC) {
                                /*
                                 * Keep the exact route reservation and the
                                 * destination controller alive.  Unlike an
                                 * ARRIVED hold, this stop is resumable and
                                 * must freeze at the modeled coast endpoint
                                 * rather than jump back to the last sensor.
                                 */
                                if (runtime
                                            ->traffic_hold_distance_um <
                                    0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_INTERNAL);
                                        continue;
                                }
                                runtime
                                        ->motion_anchor_distance_um =
                                        runtime->preorigin_sensor_pending &&
                                                runtime
                                                        ->preorigin_traffic_hold_valid ?
                                        runtime
                                                ->preorigin_traffic_hold_distance_um :
                                        runtime
                                                ->traffic_hold_distance_um;
                                runtime->motion_anchor_tick = now;
                                runtime->motion_anchor_from_traffic = 1;
                                runtime->traffic_hold_since_tick =
                                        now;
                                job->estimated_distance_um =
                                        runtime->preorigin_sensor_pending ?
                                        0 : runtime
                                                ->motion_anchor_distance_um;
                                int64_t remaining_um =
                                        (int64_t)job
                                                ->destination_distance_mm *
                                                1000 -
                                        job->estimated_distance_um;
                                job->remaining_distance_mm =
                                        remaining_um > 0 ?
                                        (int)((remaining_um + 999) /
                                              1000) : 0;
                                job->hold_active = 1;
                                job->traffic_hold_active = 1;
                                runtime->lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_TRAFFIC;
                                job->state =
                                        TC2_JOB_TRAFFIC_HOLD;
                                if (runtime->traffic_reason ==
                                            TC2_TRAFFIC_AUTHORITY &&
                                    shrink_stopped_authority_to_anchor(
                                            slot) < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_RESERVATION);
                                }
                        } else if (runtime->stop_purpose ==
                                   TC2_STOP_REVERSAL) {
                                if (!runtime->target_seen ||
                                    !next_leg_turnouts_clear_of_uncertain_train(
                                            slot)) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_SENSOR_SEQUENCE);
                                        continue;
                                }
                                if (runtime
                                            ->rolling_authority_active) {
                                        int acquired =
                                                acquire_reversal_authority(
                                                        slot,
                                                        now);
                                        if (acquired > 0) {
                                                /*
                                                 * Speed is already zero and
                                                 * the complete incoming
                                                 * authority remains owned.
                                                 * Retry in FIFO order without
                                                 * touching a turnout or the
                                                 * direction bit.
                                                 */
                                                continue;
                                        }
                                        if (acquired < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_RESERVATION);
                                                continue;
                                        }
                                } else {
                                        int next_leg =
                                                runtime
                                                        ->leg_end_offset +
                                                1;
                                        if (next_leg >=
                                                    runtime
                                                            ->route
                                                            .node_count ||
                                            dispatch_track[
                                                runtime
                                                        ->route
                                                        .nodes[
                                                            runtime
                                                                    ->leg_end_offset]]
                                                            .reverse !=
                                                    &dispatch_track[
                                                        runtime
                                                                ->route
                                                                .nodes[
                                                                    next_leg]]) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_ROUTE);
                                                continue;
                                        }
                                        runtime->leg_start_offset =
                                                next_leg;
                                        ++job->reversals_completed;
                                        ++job->current_leg;
                                        if (init_leg_monitor(
                                                    slot,
                                                    runtime
                                                            ->last_journal_sequence) <
                                            0 ||
                                            update_remaining_footprint(
                                                    slot) < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_TURNOUT);
                                                continue;
                                        }
                                }
                                int turnout_token =
                                        queue_turnout_plan_for_leg(slot);
                                if (turnout_token < 0 &&
                                    turnout_token !=
                                            CAN_SEND_BUSY) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                runtime->turnout_queue_pending =
                                        turnout_token ==
                                                CAN_SEND_BUSY;
                                runtime->turnout_batch_token =
                                        turnout_token > 0 ?
                                                (unsigned int)
                                                turnout_token :
                                                0;
                                runtime->reverse_ready_at_tick =
                                        turnout_token == 0 ?
                                        now :
                                        -1;
                                runtime->reversal_phase =
                                        TC2_REVERSAL_PHASE_TURNOUT;
                                runtime->stop_purpose = TC2_STOP_NONE;
                                job->state = TC2_JOB_REVERSING;
                        } else {
                                fail_job(slot, TC2_FAILURE_INTERNAL);
                        }
                } else if (job->state == TC2_JOB_REVERSING) {
                        int can_health =
                                can_health_is_safe(slot, 0, now);
                        if (can_health ==
                                    TC2_CAN_HEALTH_HARD_FAIL) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_CAN_HEALTH);
                                continue;
                        }
                        if (can_health == TC2_CAN_HEALTH_RETRY) {
                                /* Remain at confirmed zero speed. */
                                continue;
                        }
                        int preflight_failure =
                                reversing_preflight_failure(
                                        slot, now);
                        if (preflight_failure != TC2_FAILURE_NONE) {
                                fail_job(slot, preflight_failure);
                                continue;
                        }
                        if (runtime->turnout_queue_pending) {
                                int queued =
                                        queue_turnout_plan_for_leg(
                                                slot);
                                if (queued == CAN_SEND_BUSY) {
                                        continue;
                                }
                                if (queued < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                runtime->turnout_queue_pending = 0;
                                runtime->turnout_batch_token =
                                        queued > 0 ?
                                                (unsigned int)queued :
                                                0;
                                if (queued == 0) {
                                        runtime
                                                ->reverse_ready_at_tick =
                                                now;
                                } else {
                                        continue;
                                }
                        }
                        if (runtime->turnout_batch_token != 0) {
                                can_batch_status_t status;
                                if (CanGetBatchStatus(
                                            dispatch_can_tid,
                                            runtime
                                                    ->turnout_batch_token,
                                            &status) < 0 ||
                                    status.token !=
                                            runtime
                                                    ->turnout_batch_token) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_TURNOUT);
                                        continue;
                                }
                                if (status.state == CAN_BATCH_FAILED) {
                                        int retry =
                                                queue_turnout_plan_for_leg(
                                                        slot);
                                        if (retry ==
                                            CAN_SEND_BUSY) {
                                                runtime
                                                    ->turnout_batch_token =
                                                    0;
                                                runtime
                                                    ->turnout_queue_pending =
                                                    1;
                                                continue;
                                        }
                                        if (retry < 0) {
                                                fail_job(
                                                        slot,
                                                        TC2_FAILURE_TURNOUT);
                                                continue;
                                        }
                                        runtime->turnout_batch_token =
                                                (unsigned int)retry;
                                        if (retry == 0) {
                                                runtime
                                                        ->reverse_ready_at_tick =
                                                        now;
                                        }
                                        continue;
                                }
                                if (status.state !=
                                    CAN_BATCH_COMPLETE) {
                                        continue;
                                }
                                runtime->turnout_batch_token = 0;
                                runtime->reverse_ready_at_tick =
                                        tick_after(
                                                now,
                                                TC2_TURNOUT_SETTLE_TICKS);
                                continue;
                        }
                        if (runtime->reverse_ready_at_tick < 0 ||
                            !tick_reached(
                                    now,
                                    runtime
                                            ->reverse_ready_at_tick)) {
                                continue;
                        }
                        if (runtime->reversal_phase ==
                            TC2_REVERSAL_PHASE_TURNOUT) {
                                if (CanTrainReversePriority(
                                            dispatch_can_tid,
                                            job->train) < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_CAN_SERVICE);
                                        continue;
                                }
                                int reverse_confirmed =
                                        Time();
                                if (reverse_confirmed < 0) {
                                        fail_job(
                                                slot,
                                                TC2_FAILURE_CAN_SERVICE);
                                        continue;
                                }
                                /*
                                 * The same physical detector has two directed
                                 * track nodes.  Reverse changes that directed
                                 * localization exactly once; leaving the old
                                 * half here makes a later CURRENT reroute
                                 * reverse the anchor a second time.
                                 */
                                int accepted_sensor =
                                        runtime->last_accepted_sensor_node;
                                int reversed_sensor =
                                        physical_reverse_index(
                                                accepted_sensor);
                                if (accepted_sensor >= 0 &&
                                    accepted_sensor < TRACK_MAX &&
                                    reversed_sensor >= 0 &&
                                    reversed_sensor < TRACK_MAX &&
                                    dispatch_track[accepted_sensor].type ==
                                            NODE_SENSOR &&
                                    dispatch_track[reversed_sensor].type ==
                                            NODE_SENSOR) {
                                        runtime->last_accepted_sensor_node =
                                                reversed_sensor;
                                }
                                runtime->reversal_phase =
                                        TC2_REVERSAL_PHASE_SETTLE;
                                runtime->reverse_ready_at_tick =
                                        tick_after(
                                                reverse_confirmed,
                                                TC2_REVERSE_SETTLE_TICKS);
                                continue;
                        }
                        if (runtime->reversal_phase !=
                            TC2_REVERSAL_PHASE_SETTLE) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_INTERNAL);
                                continue;
                        }
                        /*
                         * Reversal is only a change of travel direction; it is
                         * not a second launch authority.  Re-enter motion
                         * through the same three gates as every other zero-speed
                         * start: exact hard ownership and confirmed direction
                         * for `next`, logical FIFO control plus confirmed
                         * preparation for `nextnext`, and the complete traffic
                         * safety pass.  This prevents a reversed train from
                         * bypassing a queue simply because its reverse-settle
                         * timer completed first.
                         */
                        if (!regular_movement_gates_ready(slot)) {
                                continue;
                        }
                        int launch_speed =
                                runtime
                                                ->planned_launch_speed >
                                        0 ?
                                runtime
                                        ->planned_launch_speed :
                                job->speed;
                        int launch_command =
                                command_train_positive_speed_with_retry(
                                        slot, launch_speed);
                        if (launch_command < 0) {
                                fail_job(slot,
                                         TC2_FAILURE_CAN_SERVICE);
                                continue;
                        }
                        if (launch_command > 0) continue;
                        int motion_confirmed_tick = Time();
                        if (motion_confirmed_tick < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_CAN_SERVICE);
                                continue;
                        }
                        runtime->command_speed = launch_speed;
                        job->command_speed = launch_speed;
                        runtime->motion_speed_ceiling =
                                launch_speed;
                        runtime->speed_reduction_pending = 0;
                        runtime->precision_approach_active = 0;
                        runtime->approach_sent = 0;
                        runtime->last_confirmed_tick =
                                motion_confirmed_tick;
                        runtime->motion_anchor_distance_um =
                                (int64_t)runtime->monitor
                                        .confirmed_distance_mm * 1000;
                        runtime->motion_anchor_tick =
                                motion_confirmed_tick;
                        runtime->motion_anchor_from_traffic = 0;
                        runtime->reversal_phase =
                                TC2_REVERSAL_PHASE_NONE;
                        runtime->reverse_ready_at_tick = -1;
                        job->state = TC2_JOB_RUNNING;
                        runtime->lifecycle_stop_reason =
                                TC2_LIFECYCLE_STOP_NONE;
                        if (schedule_motion_deadlines(
                                    slot,
                                    motion_confirmed_tick) < 0) {
                                fail_job(slot, TC2_FAILURE_INTERNAL);
                        }
                }
        }
}

static void process_stop_retries(void) {
        int trains[TC2_DISPATCH_MAX_JOBS];
        int slots[TC2_DISPATCH_MAX_JOBS];
        int retry_count = 0;
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state != TC2_JOB_FAILED ||
                    !job->needs_stop_retry) {
                        continue;
                }
                if (runtime->emergency_stop_token != 0) {
                        can_batch_status_t status;
                        int batch_result = CanGetBatchStatus(
                                dispatch_can_tid,
                                runtime->emergency_stop_token,
                                &status);
                        if (batch_result == 0 &&
                            status.state == CAN_BATCH_PENDING) {
                                continue;
                        }
                        if (batch_result == 0 &&
                            status.token ==
                                    runtime
                                            ->emergency_stop_token &&
                            status.state == CAN_BATCH_COMPLETE) {
                                runtime->emergency_stop_token = 0;
                                job->needs_stop_retry = 0;
                                continue;
                        }
                        runtime->emergency_stop_token = 0;
                }
                trains[retry_count] = job->train;
                slots[retry_count] = slot;
                ++retry_count;
        }
        if (retry_count == 0) return;
        int token = CanTrainEmergencyStopBatch(
                dispatch_can_tid, trains, retry_count);
        if (token <= 0) return;
        for (int index = 0; index < retry_count; ++index) {
                dispatch_runtime[slots[index]]
                        .emergency_stop_token =
                        (unsigned int)token;
        }
}

static int has_active_motion_job(void) {
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                int state = dispatch_jobs[slot].state;
                if (state == TC2_JOB_LAUNCHING ||
                    state == TC2_JOB_RUNNING ||
                    state == TC2_JOB_BRAKING ||
                    state == TC2_JOB_REVERSING ||
                    state == TC2_JOB_CANCEL_BRAKING ||
                    (state == TC2_JOB_FAILED &&
                     dispatch_jobs[slot].needs_stop_retry)) {
                        return 1;
                }
        }
        return 0;
}

static int collect_active_trains(int *trains, int capacity) {
        int count = 0;
        if (!trains || capacity < 1) return 0;
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS &&
             count < capacity; ++slot) {
                int state = dispatch_jobs[slot].state;
                if (state == TC2_JOB_LAUNCHING ||
                    state == TC2_JOB_RUNNING ||
                    state == TC2_JOB_BRAKING ||
                    state == TC2_JOB_REVERSING ||
                    state == TC2_JOB_CANCEL_BRAKING ||
                    (state == TC2_JOB_FAILED &&
                     dispatch_jobs[slot].needs_stop_retry)) {
                        trains[count++] =
                                dispatch_jobs[slot].train;
                }
        }
        return count;
}

static int supervisor_observe(
        unsigned int heartbeat, int logical_time,
        unsigned int *last_heartbeat, int *last_logical_time,
        int *stall_events, int active) {
        if (!last_heartbeat || !last_logical_time ||
            !stall_events) {
                return 1;
        }
        if (!active) {
                *last_heartbeat = heartbeat;
                *last_logical_time = logical_time;
                *stall_events = 0;
                return 0;
        }
        /*
         * The dispatch heartbeat is advanced by the request loop itself and
         * is the authoritative liveness signal.  Time() is allowed to repeat
         * across several fast observations, especially while a compound
         * turnout zone is sending and settling independent motor commands;
         * treating either unchanged value as a stall caused healthy routes
         * through SW5/SW7, SW153/SW154, or SW155/SW156 to be
         * emergency-stopped.
         */
        if (heartbeat == *last_heartbeat) {
                ++*stall_events;
        } else {
                *stall_events = 0;
        }
        *last_heartbeat = heartbeat;
        *last_logical_time = logical_time;
        if (*stall_events >= TC2_SUPERVISOR_STALL_EVENTS) {
                *stall_events = 0;
                return 1;
        }
        return 0;
}

static int supervisor_wall_stalled(
        unsigned long long now_usec,
        unsigned long long last_dispatch_progress_usec,
        int active) {
        if (!active) return 0;
        /*
         * A late safety-task wakeup says only that this observer did not run
         * on time; it is not evidence that dispatch stopped making progress.
         * Treating the observer's own scheduling latency as a dispatcher
         * failure caused healthy single-train trips to be emergency-stopped
         * and permanently reported as watchdog failures.  Only dispatcher
         * progress is authoritative here; supervisor_observe() independently
         * checks the logical heartbeat below.
         */
        return now_usec - last_dispatch_progress_usec >
                TC2_SUPERVISOR_STALL_USEC;
}

void Tc2DispatchSafetyTask(void) {
        unsigned int last_heartbeat = dispatch_heartbeat;
        int last_logical_time = dispatch_last_logical_time;
        int stall_events = 0;
        int stop_latched = 0;
        unsigned long long retry_at_usec = 0;
        for (;;) {
                if (AwaitEvent(EVENT_TIMER) < 0) continue;
                unsigned long long now_usec = timer_get_usec();
                int active = has_active_motion_job();
                if (!active) {
                        /*
                         * The dispatcher has consumed the previous trip (or
                         * all motion completed), so a later independent stall
                         * may be reported.  Reset through supervisor_observe
                         * as well, keeping its heartbeat baseline coherent.
                         */
                        stop_latched = 0;
                        retry_at_usec = 0;
                        (void)supervisor_observe(
                                dispatch_heartbeat,
                                dispatch_last_logical_time,
                                &last_heartbeat,
                                &last_logical_time,
                                &stall_events, 0);
                        continue;
                }
                if (stop_latched) {
                        /* One physical emergency-stop batch per stall. */
                        continue;
                }
                int stalled = supervisor_wall_stalled(
                        now_usec, dispatch_last_progress_usec, active);
                if (!stalled && !supervisor_observe(
                            dispatch_heartbeat,
                            dispatch_last_logical_time,
                            &last_heartbeat,
                            &last_logical_time,
                            &stall_events, active)) {
                        continue;
                }
                int trains[TC2_DISPATCH_MAX_JOBS];
                int count = collect_active_trains(
                        trains, TC2_DISPATCH_MAX_JOBS);
                if (count > 0 && now_usec >= retry_at_usec) {
                        int token = CanTrainEmergencyStopBatch(
                                dispatch_can_tid, trains, count);
                        if (token < 0) {
                                /*
                                 * A busy CAN queue is not permission to emit
                                 * one zero every timer interrupt.  Retry at a
                                 * bounded cadence while the dispatcher is
                                 * still genuinely stalled.
                                 */
                                retry_at_usec = now_usec +
                                        TC2_SUPERVISOR_RETRY_USEC;
                                continue;
                        }
                        dispatch_supervisor_trip = 1;
                        stop_latched = 1;
                        retry_at_usec = 0;
                }
        }
}

static void process_waiting_jobs(int now) {
        unsigned char processed[TC2_DISPATCH_MAX_JOBS];
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                processed[slot] = 0;
                if (dispatch_jobs[slot].state == TC2_JOB_WAITING) {
                        dispatch_jobs[slot].wait_age_ticks =
                                tick_age(
                                        now,
                                        dispatch_runtime[slot]
                                                .wait_since_tick);
                }
        }
        for (int pass = 0; pass < TC2_DISPATCH_MAX_JOBS; ++pass) {
                int oldest = -1;
                for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (processed[slot] ||
                            dispatch_jobs[slot].state !=
                                    TC2_JOB_WAITING) {
                                continue;
                        }
                        if (oldest < 0 ||
                            sequence_before(
                                    dispatch_jobs[slot]
                                            .queue_sequence,
                                    dispatch_jobs[oldest]
                                            .queue_sequence)) {
                                oldest = slot;
                        }
                }
                if (oldest < 0) break;
                processed[oldest] = 1;
                (void)prepare_waiting_job(oldest, now);
        }
        process_preparing_jobs(now);
        /*
         * Routes and their hard/soft cursors become visible only during the
         * preparation pass above.  Re-run the all-job admission gate before
         * constructing a launch wave, so front.next == rear.nextnext can
         * hold the rear at speed zero on the very first batch.
         */
        process_traffic_safety(now);
        launch_ready_jobs(now);
}

static int retarget_request_is_older(
        int candidate, int current) {
        if (current < 0) return 1;
        unsigned int candidate_sequence =
                dispatch_runtime[candidate]
                        .retarget_queue_sequence;
        unsigned int current_sequence =
                dispatch_runtime[current]
                        .retarget_queue_sequence;
        if (candidate_sequence != current_sequence) {
                return sequence_before(
                        candidate_sequence,
                        current_sequence);
        }
        return dispatch_jobs[candidate].train <
                dispatch_jobs[current].train;
}

static void clear_pending_retarget(
        tc2_dispatch_runtime *runtime) {
        if (!runtime) return;
        /*
         * Clearing an intent cannot undo a reverse already acknowledged by
         * the locomotive.  Keep that directed-pose phase until a replacement
         * route successfully commits it (or the physical train is removed).
         */
        int physical_reverse_pending =
                runtime->retarget_reverse_pending;
        int physical_reverse_ready_at_tick =
                runtime->retarget_reverse_ready_at_tick;
        int physical_direction_locked =
                runtime->retarget_direction_locked;
        int physical_direction_anchor_node =
                runtime->retarget_direction_anchor_node;
        unsigned int physical_direction_anchor_sequence =
                runtime->retarget_direction_anchor_sequence;
        int preserve_physical_reverse =
                physical_reverse_pending || physical_direction_locked;
        runtime->retarget_pending = 0;
        runtime->retarget_armed = 0;
        runtime->retarget_speed = 0;
        runtime->retarget_destination_index = -1;
        runtime->retarget_expected_generation = 0;
        runtime->retarget_expected_destination = -1;
        runtime->retarget_queue_sequence = 0;
        runtime->retarget_launch_epoch = 0;
        runtime->retarget_force_reverse_first = 0;
        runtime->retarget_operator_reroute = 0;
        runtime->retarget_reverse_pending = 0;
        runtime->retarget_reverse_ready_at_tick = -1;
        runtime->retarget_direction_locked = 0;
        runtime->retarget_direction_anchor_node = -1;
        runtime->retarget_direction_anchor_sequence = 0;
        if (preserve_physical_reverse) {
                runtime->retarget_reverse_pending =
                        physical_reverse_pending;
                runtime->retarget_reverse_ready_at_tick =
                        physical_reverse_ready_at_tick;
                runtime->retarget_direction_locked =
                        physical_direction_locked;
                runtime->retarget_direction_anchor_node =
                        physical_direction_anchor_node;
                runtime->retarget_direction_anchor_sequence =
                        physical_direction_anchor_sequence;
        }
}

static void restore_pending_retarget(
        tc2_dispatch_runtime *runtime,
        int speed, int destination,
        unsigned int expected_generation,
        int expected_destination,
        unsigned int queue_sequence,
        unsigned int launch_epoch,
        int force_reverse_first,
        int operator_reroute,
        int reverse_pending,
        int reverse_ready_at_tick,
        int direction_locked,
        int direction_anchor_node,
        unsigned int direction_anchor_sequence) {
        if (!runtime) return;
        runtime->retarget_pending = 1;
        runtime->retarget_armed = 1;
        runtime->retarget_speed = speed;
        runtime->retarget_destination_index = destination;
        runtime->retarget_expected_generation = expected_generation;
        runtime->retarget_expected_destination = expected_destination;
        runtime->retarget_queue_sequence = queue_sequence;
        runtime->retarget_launch_epoch = launch_epoch;
        runtime->retarget_force_reverse_first = force_reverse_first;
        runtime->retarget_operator_reroute = operator_reroute;
        runtime->retarget_reverse_pending = reverse_pending;
        runtime->retarget_reverse_ready_at_tick = reverse_ready_at_tick;
        runtime->retarget_direction_locked = direction_locked;
        runtime->retarget_direction_anchor_node =
                direction_anchor_node;
        runtime->retarget_direction_anchor_sequence =
                direction_anchor_sequence;
}

/*
 * A replacement reservation can commit before projection/CAN preparation
 * finishes.  At that point old route metadata must not be restored, but the
 * physical train still needs the same bounded zero-speed body from which the
 * operator requested the reroute.  Reinstall only that measured body under
 * the generation which actually committed; all candidate future authority is
 * discarded and the durable CURRENT request will be evaluated again.
 */
static int recover_post_cas_public_retarget_body(
        int slot, unsigned int generation,
        int destination, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS ||
            generation == 0 || destination < 0 ||
            destination >= TRACK_MAX || now < 0) {
                return -1;
        }

        int train = dispatch_jobs[slot].train;
        const track_route *body =
                &dispatch_retarget_runtime_backup.safety_footprint;
        if (train <= 0 ||
            dispatch_retarget_job_backup.train != train ||
            body->node_count <= 0 ||
            !dispatch_retarget_runtime_backup
                     .static_center_bounds_valid ||
            dispatch_retarget_runtime_backup
                            .static_center_lower_um < 0 ||
            dispatch_retarget_runtime_backup
                            .static_center_upper_um <
                    dispatch_retarget_runtime_backup
                            .static_center_lower_um ||
            dispatch_retarget_job_backup.current_node < 0 ||
            dispatch_retarget_job_backup.current_node >= TRACK_MAX ||
            !stationary_window_contains_physical_node(
                    body,
                    dispatch_retarget_job_backup.current_node)) {
                return -1;
        }

        track_reservation_conflict conflict;
        conflict.node_index = -1;
        conflict.owner_train = 0;
        unsigned int same_generation = 0;
        int status = TrackReservationServerUpdateWindow(
                dispatch_reservation_tid, body, train,
                destination, generation, &conflict,
                &same_generation);
        if (status != 0 || same_generation != generation) {
                dispatch_jobs[slot].conflict_train =
                        conflict.owner_train;
                dispatch_jobs[slot].conflict_node =
                        conflict.node_index;
                return -1;
        }

        dispatch_jobs[slot] = dispatch_retarget_job_backup;
        dispatch_runtime[slot] = dispatch_retarget_runtime_backup;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        job->plan_generation = generation;
        job->target_node = destination;
        job->state = TC2_JOB_STOPPED;
        job->command_speed = 0;
        job->hold_active = 1;
        job->ready_at_tick = -1;
        job->braking_at_tick = -1;
        job->failure_reason = TC2_FAILURE_NONE;
        job->stop_trigger = TC2_STOP_TRIGGER_NONE;
        job->needs_stop_retry = 0;
        runtime->command_speed = 0;
        runtime->motion_speed_ceiling = 0;
        runtime->movement_plan_active = 0;
        runtime->lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_REROUTE;

        /*
         * The candidate's future zone work was retired by fail_job().  The
         * restored body owns no old next/nextnext ticket; a cleanup failure
         * keeps it stopped but must not destroy the operator's request.
         */
        if (retire_terminal_conflict_zone_memory(slot, now) < 0) {
                dispatch_scheduler_healthy = 0;
        }
        invalidate_projection(slot);
        return 0;
}

/*
 * Commit an armed CURRENT recovery as one dispatcher transaction.
 *
 * stage_job()/prepare_waiting_job() are reused under this single-writer
 * server, but the live hold, projection, and runtime are copied aside first.
 * Until ReplacePlanExpected succeeds the reservation table is unchanged; a
 * route conflict restores the old slot byte-for-byte.  Once the generation
 * advances, stale route/control metadata is never restored.  A failed public
 * reroute may only reinstall the saved bounded physical body, and only after
 * a generation-checked reservation shrink under the new identity succeeds.
 */
static void process_pending_retargets(int now) {
        unsigned char processed[TC2_DISPATCH_MAX_JOBS];
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                processed[slot] = 0;
        }
        for (int pass = 0;
             pass < TC2_DISPATCH_MAX_JOBS; ++pass) {
                int oldest = -1;
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        if (processed[slot] ||
                            !dispatch_runtime[slot]
                                    .retarget_pending ||
                            !dispatch_runtime[slot]
                                    .retarget_armed) {
                                continue;
                        }
                        if (retarget_request_is_older(
                                    slot, oldest)) {
                                oldest = slot;
                        }
                }
                if (oldest < 0) break;
                processed[oldest] = 1;

                tc2_dispatch_job_snapshot *held_job =
                        &dispatch_jobs[oldest];
                tc2_dispatch_runtime *held_runtime =
                        &dispatch_runtime[oldest];
                int retarget_speed =
                        held_runtime->retarget_speed;
                int retarget_destination =
                        held_runtime
                                ->retarget_destination_index;
                int retarget_force_reverse_first =
                        held_runtime
                                ->retarget_force_reverse_first;
                int retarget_operator_reroute =
                        held_runtime
                                ->retarget_operator_reroute;
                int retarget_reverse_pending =
                        held_runtime->retarget_reverse_pending;
                int retarget_reverse_ready_at_tick =
                        held_runtime->retarget_reverse_ready_at_tick;
                int retarget_direction_locked =
                        held_runtime->retarget_direction_locked;
                int retarget_direction_anchor_node =
                        held_runtime->retarget_direction_anchor_node;
                unsigned int retarget_direction_anchor_sequence =
                        held_runtime->retarget_direction_anchor_sequence;
                int retarget_confirmed_start_node = -1;
                int retarget_reversed_start_node = -1;
                unsigned int expected_generation =
                        held_runtime
                                ->retarget_expected_generation;
                int expected_destination =
                        held_runtime
                                ->retarget_expected_destination;
                unsigned int queue_sequence =
                        held_runtime
                                ->retarget_queue_sequence;
                unsigned int launch_epoch =
                        held_runtime
                                ->retarget_launch_epoch;
                if (held_job->plan_generation !=
                            expected_generation ||
                    held_job->target_node !=
                            expected_destination) {
                        if (retarget_operator_reroute &&
                            held_job->state != TC2_JOB_EMPTY &&
                            held_runtime->lifecycle_stop_reason !=
                                    TC2_LIFECYCLE_STOP_REMOVE_PENDING) {
                                /*
                                 * The physical train is the identity of a
                                 * public reroute.  A newer sensor-derived
                                 * static-body generation must not make the
                                 * command disappear; rebind the CAS guard to
                                 * the current fail-closed object and continue.
                                 */
                                expected_generation =
                                        held_job->plan_generation;
                                expected_destination =
                                        held_job->target_node;
                                held_runtime
                                        ->retarget_expected_generation =
                                        expected_generation;
                                held_runtime
                                        ->retarget_expected_destination =
                                        expected_destination;
                        } else {
                                clear_pending_retarget(held_runtime);
                                continue;
                        }
                }
                if (retarget_speed < 1 ||
                    retarget_speed > 120 ||
                    retarget_destination < 0 ||
                    retarget_destination >=
                            TC2_DISPATCH_DESTINATION_COUNT) {
                        clear_pending_retarget(held_runtime);
                        continue;
                }

                if (retarget_operator_reroute) {
                        int trusted_static =
                                (held_job->state == TC2_JOB_ARRIVED ||
                                 held_job->state == TC2_JOB_STOPPED) &&
                                held_job->command_speed == 0 &&
                                held_runtime->command_speed == 0 &&
                                held_runtime->route_valid &&
                                held_job->current_node >= 0 &&
                                terminal_static_footprint_committed(oldest);
                        if (!held_runtime->route_valid ||
                            held_job->current_node < 0 ||
                            !cancel_anchor_is_trusted(oldest)) {
                                /*
                                 * Reroute never fabricates localization.  Keep
                                 * both the physical train and the request
                                 * fail-stopped until a real sensor re-establishes
                                 * a trusted directed pose.  Silently clearing
                                 * the armed intent here made a later sensor
                                 * confirmation impossible to recover from.
                                 */
                                held_runtime->lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                continue;
                        }
                        if (held_job->state ==
                                    TC2_JOB_CANCEL_BRAKING) {
                                continue;
                        }
                        if (held_job->state == TC2_JOB_REVERSING) {
                                /*
                                 * Finish the existing route's complete reversal
                                 * bookkeeping before beginning an operator
                                 * reroute.  A settle timer alone is not enough:
                                 * the ordinary FSM also advances its directed
                                 * route cursor and held-resource boundary.
                                 */
                                continue;
                        }
                        if (!trusted_static) {
                                int train = held_job->train;
                                int stopped = cancel_job(train);
                                if (find_train_job(train) != oldest) {
                                        continue;
                                }
                                held_runtime = &dispatch_runtime[oldest];
                                restore_pending_retarget(
                                        held_runtime,
                                        retarget_speed,
                                        retarget_destination,
                                        expected_generation,
                                        expected_destination,
                                        queue_sequence,
                                        launch_epoch,
                                        retarget_force_reverse_first,
                                        1,
                                        retarget_reverse_pending,
                                        retarget_reverse_ready_at_tick,
                                        retarget_direction_locked,
                                        retarget_direction_anchor_node,
                                        retarget_direction_anchor_sequence);
                                held_runtime->lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_REROUTE;
                                /*
                                 * cancel_job() either committed a bounded
                                 * zero-speed body or left the old fail-closed
                                 * control intact.  In both cases retry only on
                                 * a later scheduler tick.
                                 */
                                (void)stopped;
                                continue;
                        }
                        if (normalize_operator_reroute_static_hold(
                                    oldest) < 0) {
                                continue;
                        }
                        if (retire_terminal_conflict_zone_memory(
                                    oldest, now) < 0) {
                                continue;
                        }
                        /*
                         * Terminal retirement deliberately clears all future
                         * work.  Reroute intent is not old future work: restore
                         * it (and its pre-route reverse phase) immediately so
                         * temporary FIFO conflicts keep retrying.
                         */
                        restore_pending_retarget(
                                held_runtime,
                                retarget_speed,
                                retarget_destination,
                                expected_generation,
                                expected_destination,
                                queue_sequence,
                                launch_epoch,
                                retarget_force_reverse_first,
                                1,
                                retarget_reverse_pending,
                                retarget_reverse_ready_at_tick,
                                retarget_direction_locked,
                                retarget_direction_anchor_node,
                                retarget_direction_anchor_sequence);
                        held_runtime->lifecycle_stop_reason =
                                TC2_LIFECYCLE_STOP_REROUTE;
                        /*
                         * A reverse acknowledgement records the opposite
                         * directed node of one accepted physical detector.
                         * Raw journal traffic is irrelevant here: duplicates,
                         * spurious reports, and another train's events may all
                         * advance it.  Only a newer accepted localization for
                         * this train can invalidate the saved reverse pose.
                         */
                        int accepted_sensor_node =
                                held_runtime->last_accepted_sensor_node;
                        int accepted_reverse_node =
                                physical_reverse_index(
                                        accepted_sensor_node);
                        int accepted_direction_anchor =
                                held_runtime->retarget_reverse_pending ?
                                accepted_reverse_node :
                                accepted_sensor_node;
                        if ((held_runtime->retarget_reverse_pending ||
                             held_runtime->retarget_direction_locked) &&
                            (accepted_sensor_node < 0 ||
                             accepted_sensor_node >= TRACK_MAX ||
                             dispatch_track[accepted_sensor_node].type !=
                                     NODE_SENSOR ||
                             held_runtime->retarget_direction_anchor_node < 0 ||
                             held_runtime->retarget_direction_anchor_node >=
                                     TRACK_MAX ||
                             dispatch_track[
                                     held_runtime
                                             ->retarget_direction_anchor_node]
                                             .type != NODE_SENSOR ||
                             accepted_direction_anchor !=
                                     held_runtime
                                             ->retarget_direction_anchor_node ||
                             held_runtime->retarget_direction_anchor_sequence !=
                                     held_runtime
                                             ->last_accepted_sensor_sequence)) {
                                held_runtime->lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                continue;
                        }
                        if (held_runtime->retarget_reverse_pending) {
                                if (held_runtime
                                                    ->retarget_reverse_ready_at_tick <
                                            0) {
                                        /*
                                         * The reverse CAN acknowledgement is
                                         * the physical fact.  If the immediate
                                         * clock read failed, start a complete
                                         * settle interval on this later valid
                                         * scheduler tick instead of forgetting
                                         * the reverse or waiting forever.
                                         */
                                        held_runtime
                                                ->retarget_reverse_ready_at_tick =
                                                tick_after(
                                                        now,
                                                        TC2_REVERSE_SETTLE_TICKS);
                                        retarget_reverse_ready_at_tick =
                                                held_runtime
                                                        ->retarget_reverse_ready_at_tick;
                                }
                                if (held_runtime
                                                    ->retarget_reverse_ready_at_tick <
                                            0 ||
                                    !tick_reached(
                                            now,
                                            held_runtime
                                                    ->retarget_reverse_ready_at_tick)) {
                                        continue;
                                }
                                int reversed = held_runtime
                                        ->retarget_direction_anchor_node;
                                if (reversed < 0 ||
                                    reversed >= TRACK_MAX ||
                                    dispatch_track[reversed].type !=
                                            NODE_SENSOR) {
                                        held_runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        continue;
                                }
                                /*
                                 * Reverse changes directed pose, never physical
                                 * occupancy.  Keep current_node and the bounded
                                 * body reservation untouched; the second-stage
                         * CURRENT candidate starts from the directed real
                         * sensor captured when reverse was acknowledged and
                         * carries the stopped pre-origin distance separately.
                                 */
                                held_runtime->retarget_reverse_pending = 0;
                                held_runtime->retarget_reverse_ready_at_tick =
                                        -1;
                                held_runtime->retarget_direction_locked = 1;
                                held_runtime->last_accepted_sensor_node =
                                        reversed;
                                accepted_sensor_node = reversed;
                                retarget_reverse_pending = 0;
                                retarget_reverse_ready_at_tick = -1;
                                retarget_direction_locked = 1;
                                retarget_direction_anchor_node = reversed;
                                retarget_direction_anchor_sequence =
                                        held_runtime
                                                ->retarget_direction_anchor_sequence;
                        }
                        /*
                         * Before any reverse, direction selection starts at
                         * the latest confirmed real detector.  Once reverse
                         * is acknowledged, the saved directed anchor is the
                         * only route origin: later old-route monitor events
                         * must not apply physical_reverse_index() a second
                         * time.  current_node remains only the occupancy pose.
                         */
                        int fixed_departure_origin =
                                !held_runtime->retarget_reverse_pending &&
                                !held_runtime->retarget_direction_locked &&
                                cancel_anchor_is_trusted(oldest) &&
                                held_job->current_node >= 0 &&
                                held_job->current_node < TRACK_MAX &&
                                dispatch_track[held_job->current_node].type ==
                                        NODE_ENTER;
                        retarget_confirmed_start_node =
                                retarget_direction_anchor_node >= 0 ?
                                retarget_direction_anchor_node :
                                (accepted_sensor_node >= 0 &&
                                 accepted_sensor_node < TRACK_MAX &&
                                 dispatch_track[accepted_sensor_node].type ==
                                         NODE_SENSOR ?
                                 accepted_sensor_node :
                                 (fixed_departure_origin ?
                                  held_job->current_node : -1));
                        if (retarget_confirmed_start_node < 0 ||
                            retarget_confirmed_start_node >= TRACK_MAX ||
                            (dispatch_track[
                                     retarget_confirmed_start_node].type !=
                                     NODE_SENSOR &&
                             !fixed_departure_origin)) {
                                held_runtime->lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                continue;
                        }
                        if (held_runtime->retarget_direction_locked) {
                                retarget_reversed_start_node =
                                        retarget_direction_anchor_node;
                                if (retarget_reversed_start_node < 0 ||
                                    dispatch_track[
                                            retarget_reversed_start_node].type !=
                                            NODE_SENSOR) {
                                        held_runtime->lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        continue;
                                }
                        }
                } else if (held_job->state !=
                                   TC2_JOB_TRAFFIC_HOLD ||
                           held_runtime->stop_purpose !=
                                   TC2_STOP_TRAFFIC ||
                           held_runtime->traffic_hold_distance_um < 0) {
                        clear_pending_retarget(held_runtime);
                        continue;
                }

                /*
                 * The candidate preparation below may call fail_job() before
                 * its reservation CAS.  A memory rollback can restore the
                 * old job, zone owner, and FIFO tickets, but it cannot
                 * resurrect a CAN batch that fail_job() canceled in the CAN
                 * server.  Let the normal conflict-zone poll finish any old
                 * hard/soft batch first.  The request remains armed and is
                 * retried on the next scheduler tick; the train is already
                 * stopped under the live traffic hold throughout this wait.
                 */
                if (held_runtime->conflict_zone_batch_token != 0 ||
                    held_runtime->conflict_zone_soft_batch_token != 0 ||
                    held_runtime->conflict_zone_settle_at_tick >= 0) {
                        continue;
                }

                /*
                 * Capture old physical-zone geometry while localization is
                 * still trustworthy.  The temporary estimated ARRIVED view
                 * below must not downgrade an already proved entry/exit
                 * relationship to an ambiguous synthetic carry.
                 */
                if (snapshot_owned_conflict_zone_carries(oldest) < 0) {
                        dispatch_scheduler_healthy = 0;
                        continue;
                }
                dispatch_retarget_job_backup =
                        dispatch_jobs[oldest];
                dispatch_retarget_runtime_backup =
                        dispatch_runtime[oldest];
                dispatch_retarget_projection_backup =
                        dispatch_projection_publications[oldest];
                dispatch_retarget_conflict_zone_backup =
                        dispatch_conflict_zones;

                tc2_dispatch_request request;
                request.type = TC2_DISPATCH_MSG_STAGE;
                request.train = held_job->train;
                request.start_index =
                        TC2_DISPATCH_START_CURRENT;
                request.speed = retarget_speed;
                request.destination_index =
                        retarget_destination;
                request.node_index = -1;
                request.projection_serial = 0;
                request.projection_generation = 0;
                request.projection_launch_epoch = 0;
                request.projection_first_waypoint = -1;
                request.reserved = retarget_operator_reroute ?
                        TC2_DISPATCH_REQUEST_OPERATOR_REROUTE :
                        (retarget_force_reverse_first ?
                         TC2_DISPATCH_REQUEST_FORCE_REVERSE_FIRST : 0);

                /*
                 * This temporary ARRIVED view is not externally observable:
                 * the server cannot receive another request until the
                 * transaction returns.  Ordinary traffic recovery carries its
                 * entered old owners; public reroute has already reduced the
                 * old plan to the bounded physical body, so the same snapshot
                 * cannot resurrect old next/nextnext control.
                 */
                dispatch_jobs[oldest].state =
                        TC2_JOB_ARRIVED;
                dispatch_jobs[oldest].hold_active = 1;
                dispatch_jobs[oldest].position_estimated = 1;
                dispatch_retarget_candidate_pre_cas = 1;
                int staged = stage_job(&request);
                int prepared = -1;
                if (staged == 0) {
                        if (retarget_operator_reroute) {
                                /*
                                 * stage_job() first snapshots the old bounded
                                 * body through current_node.  Only after that
                                 * physical snapshot exists may route selection
                                 * use the latest real detector as CURRENT.
                                 * Before the one allowed reverse it compares
                                 * both directions; after settle it is pinned to
                                 * the reversed detector and cannot immediately
                                 * reverse back.
                                 */
                                dispatch_runtime[oldest]
                                        .reroute_select_direction =
                                        !retarget_direction_locked;
                                dispatch_runtime[oldest]
                                        .retarget_direction_locked =
                                        retarget_direction_locked;
                                dispatch_runtime[oldest].start_node =
                                        retarget_direction_locked ?
                                        retarget_reversed_start_node :
                                        retarget_confirmed_start_node;
                        }
                        dispatch_jobs[oldest].state =
                                TC2_JOB_WAITING;
                        dispatch_jobs[oldest]
                                .job_launch_epoch =
                                launch_epoch;
                        dispatch_jobs[oldest]
                                .queue_sequence =
                                queue_sequence;
                        dispatch_runtime[oldest]
                                .queue_sequence =
                                queue_sequence;
                        dispatch_runtime[oldest]
                                .launch_epoch =
                                launch_epoch;
                        dispatch_runtime[oldest]
                                .wait_since_tick = now;
                        prepared =
                                prepare_waiting_job(
                                        oldest, now);
                }
                dispatch_retarget_candidate_pre_cas = 0;
                if (staged == 0 && prepared == 0) {
                        /*
                         * The new CURRENT route has consumed both pieces of
                         * pre-route direction state.  Leaving
                         * reroute_select_direction set on a forward reroute
                         * makes a later localization restage look like a new
                         * public reroute and can schedule another direction
                         * probe against an already committed route.
                         */
                        dispatch_runtime[oldest]
                                .reroute_select_direction = 0;
                        dispatch_runtime[oldest]
                                .retarget_direction_locked = 0;
                        dispatch_runtime[oldest]
                                .retarget_direction_anchor_node = -1;
                        dispatch_runtime[oldest]
                                .retarget_direction_anchor_sequence = 0;
                        continue;
                }

                track_reservation_snapshot after;
                int have_after =
                        TrackReservationServerSnapshot(
                                dispatch_reservation_tid,
                                &after) == 0;
                int old_plan_still_authoritative =
                        have_after &&
                        after.generation_by_train[
                                request.train] ==
                                expected_generation &&
                        after.destination_by_train[
                                request.train] ==
                                expected_destination;
                if (old_plan_still_authoritative) {
                        int candidate_conflict_train =
                                dispatch_jobs[oldest]
                                        .conflict_train;
                        int candidate_conflict_node =
                                dispatch_jobs[oldest]
                                        .conflict_node;
                        int candidate_failure_reason =
                                staged == 0 && prepared < 0 ?
                                dispatch_jobs[oldest]
                                        .failure_reason :
                                TC2_FAILURE_NONE;
                        dispatch_jobs[oldest] =
                                dispatch_retarget_job_backup;
                        dispatch_runtime[oldest] =
                                dispatch_retarget_runtime_backup;
                        dispatch_projection_publications[oldest] =
                                dispatch_retarget_projection_backup;
                        dispatch_conflict_zones =
                                dispatch_retarget_conflict_zone_backup;
                        dispatch_jobs[oldest].conflict_train =
                                candidate_conflict_train;
                        dispatch_jobs[oldest].conflict_node =
                                candidate_conflict_node;
                        if (retarget_operator_reroute &&
                            prepared ==
                                    TC2_PREPARE_OPERATOR_REVERSE_REQUIRED) {
                                /*
                                 * The direction probe is side-effect free up
                                 * to the reservation CAS.  We are now back on
                                 * the original bounded body, so issue exactly
                                 * one reverse and retain the same armed intent
                                 * while its mechanical direction settles.
                                 */
                                restore_pending_retarget(
                                        &dispatch_runtime[oldest],
                                        retarget_speed,
                                        retarget_destination,
                                        expected_generation,
                                        expected_destination,
                                        queue_sequence,
                                        launch_epoch,
                                        retarget_force_reverse_first,
                                        1, 0, -1, 0,
                                        -1, 0);
                                dispatch_runtime[oldest]
                                                .lifecycle_stop_reason =
                                        TC2_LIFECYCLE_STOP_REROUTE;
                                dispatch_jobs[oldest].conflict_train = 0;
                                dispatch_jobs[oldest].conflict_node = -1;
                                if (dispatch_jobs[oldest].command_speed != 0 ||
                                    dispatch_runtime[oldest].command_speed != 0) {
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        continue;
                                }
                                int reverse_anchor_node =
                                        physical_reverse_index(
                                                retarget_confirmed_start_node);
                                if (retarget_confirmed_start_node < 0 ||
                                    reverse_anchor_node < 0 ||
                                    reverse_anchor_node >= TRACK_MAX ||
                                    dispatch_track[
                                            retarget_confirmed_start_node].type !=
                                            NODE_SENSOR ||
                                    dispatch_track[reverse_anchor_node].type !=
                                            NODE_SENSOR) {
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                                        continue;
                                }
                                if (CanTrainReversePriority(
                                            dispatch_can_tid,
                                            request.train) < 0) {
                                        /* Keep the zero-speed request armed. */
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_REROUTE;
                                        continue;
                                }
                                int reverse_confirmed = Time();
                                if (reverse_confirmed < 0) {
                                        /*
                                         * Reverse was acknowledged and cannot
                                         * be rolled back.  Retain that physical
                                         * phase with an unknown deadline; a
                                         * later valid tick establishes a full
                                         * settle delay before route planning.
                                         */
                                        dispatch_runtime[oldest]
                                                .retarget_reverse_pending = 1;
                                        dispatch_runtime[oldest]
                                                .retarget_reverse_ready_at_tick =
                                                -1;
                                        dispatch_runtime[oldest]
                                                .retarget_direction_locked = 0;
                                        dispatch_runtime[oldest]
                                                .retarget_direction_anchor_node =
                                                reverse_anchor_node;
                                        dispatch_runtime[oldest]
                                                .retarget_direction_anchor_sequence =
                                                dispatch_runtime[oldest]
                                                        .last_accepted_sensor_sequence;
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_REROUTE;
                                        continue;
                                }
                                dispatch_runtime[oldest]
                                                .retarget_reverse_pending = 1;
                                dispatch_runtime[oldest]
                                                .retarget_reverse_ready_at_tick =
                                        tick_after(
                                                reverse_confirmed,
                                                TC2_REVERSE_SETTLE_TICKS);
                                dispatch_runtime[oldest]
                                                .retarget_direction_locked = 0;
                                dispatch_runtime[oldest]
                                                .retarget_direction_anchor_node =
                                        reverse_anchor_node;
                                dispatch_runtime[oldest]
                                                .retarget_direction_anchor_sequence =
                                        dispatch_runtime[oldest]
                                                .last_accepted_sensor_sequence;
                                continue;
                        }
                        if (staged < 0 || prepared < 0) {
                                /*
                                 * The byte-for-byte rollback restored the
                                 * bounded zero-speed body and armed request.
                                 * A public reroute is durable operator intent:
                                 * route availability, localization, or a
                                 * transient internal admission failure may
                                 * delay it but may not silently cancel it.
                                 * Internal automatic traffic retargets retain
                                 * their older deterministic-failure policy.
                                 */
                                if (retarget_operator_reroute) {
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                candidate_failure_reason ==
                                                        TC2_FAILURE_SENSOR_SEQUENCE ?
                                                TC2_LIFECYCLE_STOP_UNCONFIRMED :
                                                TC2_LIFECYCLE_STOP_REROUTE;
                                } else if (candidate_failure_reason ==
                                                   TC2_FAILURE_ROUTE ||
                                           candidate_failure_reason ==
                                                   TC2_FAILURE_SENSOR_SEQUENCE ||
                                           candidate_failure_reason ==
                                                   TC2_FAILURE_INTERNAL) {
                                        clear_pending_retarget(
                                                &dispatch_runtime[oldest]);
                                } else {
                                        dispatch_runtime[oldest]
                                                        .lifecycle_stop_reason =
                                                TC2_LIFECYCLE_STOP_REROUTE;
                                }
                        }
                        continue;
                }

                /*
                 * The CAS may have committed before a later projection/CAN
                 * failure.  Keep that new fail-closed job.  If the snapshot
                 * itself is unavailable, rolling back would risk pairing an
                 * old generation with new ownership, so retain the new state
                 * and emergency-stop it.
                 */
                unsigned int retry_generation =
                        have_after ?
                        after.generation_by_train[request.train] :
                        dispatch_jobs[oldest].plan_generation;
                int retry_destination =
                        have_after ?
                        after.destination_by_train[request.train] :
                        dispatch_jobs[oldest].target_node;
                /*
                 * Candidate fail_job() calls made while the transaction flag
                 * was set were intentionally memory-only.  The CAS is now
                 * authoritative, so execute a real fail-closed stop and retire
                 * any candidate future CAN/conflict work before retrying.
                 */
                fail_job(
                        oldest,
                        have_after ?
                        TC2_FAILURE_INTERNAL :
                        TC2_FAILURE_RESERVATION_SERVICE);
                int public_retry_allowed =
                        retarget_operator_reroute &&
                        dispatch_jobs[oldest].state != TC2_JOB_EMPTY &&
                        dispatch_runtime[oldest]
                                        .lifecycle_stop_reason !=
                                TC2_LIFECYCLE_STOP_REMOVE_PENDING;
                if (public_retry_allowed) {
                        /*
                         * A post-CAS projection/CAN failure invalidates this
                         * candidate, not the operator's destination.  If the
                         * replacement generation is known, atomically shrink
                         * it back to the saved bounded body before retrying.
                         * Never pair the new owner generation with an old
                         * route or future next/nextnext cursor.
                         */
                        int body_recovered =
                                have_after &&
                                recover_post_cas_public_retarget_body(
                                        oldest, retry_generation,
                                        retry_destination, now) == 0;
                        restore_pending_retarget(
                                &dispatch_runtime[oldest],
                                retarget_speed,
                                retarget_destination,
                                retry_generation,
                                retry_destination,
                                queue_sequence,
                                launch_epoch,
                                retarget_force_reverse_first,
                                1,
                                retarget_reverse_pending,
                                retarget_reverse_ready_at_tick,
                                retarget_direction_locked,
                                retarget_direction_anchor_node,
                                retarget_direction_anchor_sequence);
                        int trusted_failed_candidate =
                                dispatch_runtime[oldest].route_valid &&
                                dispatch_jobs[oldest].current_node >= 0 &&
                                cancel_anchor_is_trusted(oldest);
                        dispatch_runtime[oldest]
                                        .lifecycle_stop_reason =
                                body_recovered ||
                                        trusted_failed_candidate ?
                                TC2_LIFECYCLE_STOP_REROUTE :
                                TC2_LIFECYCLE_STOP_UNCONFIRMED;
                } else {
                        clear_pending_retarget(
                                &dispatch_runtime[oldest]);
                }
        }
}

/*
 * A cancel can arrive before route admission produced any trustworthy
 * geometry (STAGED/WAIT_ROUTE, or an admission failure).  Never invent a
 * body interval from an unconfirmed start and never leave the old queue
 * entries alive.  The resulting STOP_UNCONFIRMED job is deliberately a
 * global conservative obstacle, recognized by
 * unknown_static_block_exists_except(), until the operator confirms physical
 * removal.  This is the only route-less lifecycle state which can survive a
 * cancel.
 */
static int retire_route_less_cancel_control(int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state != TC2_JOB_STOP_UNCONFIRMED ||
            runtime->lifecycle_stop_reason !=
                    TC2_LIFECYCLE_STOP_OPERATOR_CANCEL ||
            runtime->route_valid) {
                return -1;
        }

        retire_future_control_fields(runtime);
        if (cancel_old_conflict_zone_batch(slot) < 0 ||
            discard_old_prelaunch_turnout_batch(slot) < 0 ||
            TC2_DISPATCH_CONFLICT_ZONE_REMOVE_TRAIN(
                    &dispatch_conflict_zones, job->train, 1) < 0) {
                return -1;
        }
        runtime->launch_batch_token = 0;
        runtime->launch_batch_index = -1;
        runtime->launch_wave_tick = -1;
        runtime->conflict_zone_hard_step = -1;
        runtime->conflict_zone_soft_step = -1;
        runtime->conflict_zone_hard_ticket = 0;
        runtime->conflict_zone_soft_ticket = 0;
        runtime->conflict_zone_hold_active = 0;
        reset_conflict_zone_action_cursor(runtime);
        reset_soft_conflict_zone_cursor(runtime, 1);
        clear_origin_zone_egress(runtime);
        runtime->conflict_zone_carry_count = 0;
        runtime->carry_ambiguity_active = 0;
        runtime->conflict_zone_plan.step_count = 0;
        runtime->conflict_zone_plan.stage_count = 0;
        runtime->conflict_zone_plan_valid = 0;
        runtime->conflict_zone_next_step = 0;
        runtime->conflict_zone_route_generation = 0;
        return 0;
}

static int cancel_job(int train) {
        int slot = find_train_job(train);
        if (slot < 0) return -1;
        int now = Time();
        if (now < 0) return -1;
        /* Start every relinquished-control delay at this command's time. */
        Tc2ConflictZoneTick(
                &dispatch_conflict_zones, (uint32_t)now);
        dispatch_runtime[slot].retarget_pending = 0;
        dispatch_runtime[slot].retarget_armed = 0;
        if (dispatch_jobs[slot].state ==
                    TC2_JOB_STOP_UNCONFIRMED &&
            dispatch_runtime[slot].lifecycle_stop_reason ==
                    TC2_LIFECYCLE_STOP_OPERATOR_CANCEL &&
            !dispatch_runtime[slot].route_valid) {
                return retire_route_less_cancel_control(slot, now);
        }
        if (dispatch_jobs[slot].state ==
                    TC2_JOB_CANCEL_BRAKING ||
            dispatch_jobs[slot].state == TC2_JOB_STOPPED) {
                if (!terminal_static_footprint_committed(slot) ||
                    retire_terminal_conflict_zone_memory(slot, now) < 0) {
                        return -1;
                }
                process_traffic_safety(now);
                restart_prearmed_stationary_survivors(slot);
                process_conflict_zones(now);
                process_authority_holds(now);
                process_conflict_zones(now);
                return 0;
        }
        int stop_speed =
                dispatch_runtime[slot].motion_speed_ceiling >
                                dispatch_runtime[slot].command_speed ?
                        dispatch_runtime[slot].motion_speed_ceiling :
                        dispatch_runtime[slot].command_speed;
        if (stop_speed <= 0) {
                stop_speed = dispatch_jobs[slot].speed;
        }
        int settle_ticks =
                Tc2MotionStopSettleTicks(stop_speed);
        /*
         * Establish a conservative motion anchor and queue the atomic wave
         * zero before measuring the cancel body.  Otherwise a target whose
         * positive frame escaped while it still appeared LAUNCHING would be
         * measured at its old detector and its static footprint could be
         * committed behind the physical train.
         */
        int partial_launch_stop =
                rewind_unconfirmed_launch_wave_for_remove(slot);
        if (partial_launch_stop < 0) return -1;
        int64_t cancel_progress_um = 0;
        if (now >= 0 &&
            runtime_motion_progress_um(
                    slot, now, &cancel_progress_um) < 0) {
                cancel_progress_um =
                        dispatch_runtime[slot].route_valid &&
                                dispatch_runtime[slot]
                                                .monitor
                                                .confirmed_distance_mm >=
                                        0 ?
                        (int64_t)dispatch_runtime[slot]
                                        .monitor
                                        .confirmed_distance_mm *
                                1000 :
                        0;
        }
        int cancel_coast_um =
                Tc2MotionMeasuredStopDistanceUm(stop_speed);
        if (dispatch_runtime[slot].turnout_batch_token != 0) {
                (void)CanCancelBatch(
                        dispatch_can_tid,
                        dispatch_runtime[slot]
                                .turnout_batch_token);
                dispatch_runtime[slot].turnout_batch_token = 0;
        }
        dispatch_runtime[slot].turnout_queue_pending = 0;
        if (now < 0 || settle_ticks < 0 ||
            cancel_coast_um < 0 ||
            cancel_progress_um < 0 ||
            cancel_progress_um >
                    INT64_MAX - cancel_coast_um) {
                /* Preserve the live FIFO/reservation if no safe body bound exists. */
                return -1;
        }
        int stop_request_tick = Time();
        if (stop_request_tick < 0 ||
            command_train_speed_with_retry(train, 0) < 0) {
                /*
                 * A partial launch has already been externally stopped and
                 * cannot be rolled back into its old positive wave.  Keep the
                 * target fail-stopped if its dedicated cancel acknowledgement
                 * is unavailable; healthy peers remain recoverable holds.
                 */
                if (partial_launch_stop > 0) {
                        fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                }
                return -1;
        }
        /* The target's dedicated acknowledged zero supersedes its wave token. */
        dispatch_runtime[slot].emergency_stop_token = 0;
        int stop_confirmed_tick = Time();
        if (stop_confirmed_tick < 0) {
                if (partial_launch_stop > 0) {
                        fail_job(slot, TC2_FAILURE_CAN_SERVICE);
                }
                return -1;
        }
        if (!dispatch_runtime[slot].route_valid ||
            dispatch_jobs[slot].plan_generation == 0) {
                invalidate_projection(slot);
                retire_future_control_fields(
                        &dispatch_runtime[slot]);
                dispatch_runtime[slot].lifecycle_stop_reason =
                        TC2_LIFECYCLE_STOP_OPERATOR_CANCEL;
                dispatch_runtime[slot].command_speed = 0;
                dispatch_runtime[slot].motion_speed_ceiling = 0;
                dispatch_runtime[slot].settle_at_tick = -1;
                dispatch_jobs[slot].command_speed = 0;
                dispatch_jobs[slot].state =
                        TC2_JOB_STOP_UNCONFIRMED;
                dispatch_jobs[slot].position_estimated = 1;
                dispatch_jobs[slot].hold_active = 1;
                dispatch_jobs[slot].ready_at_tick = -1;
                dispatch_jobs[slot].braking_at_tick = -1;
                dispatch_jobs[slot].needs_stop_retry = 0;
                dispatch_jobs[slot].stop_sent_tick =
                        stop_confirmed_tick;
                dispatch_jobs[slot].stop_request_tick =
                        stop_request_tick;
                dispatch_jobs[slot].stop_confirmed_tick =
                        stop_confirmed_tick;
                dispatch_jobs[slot].stop_timing_valid = 1;
                return retire_route_less_cancel_control(
                        slot, stop_confirmed_tick);
        }
        int64_t stationary_lower_um = -1;
        int64_t stationary_upper_um = -1;
        if (cancel_stationary_center_bounds(
                    slot, stop_speed, stop_confirmed_tick,
                    &stationary_lower_um,
                    &stationary_upper_um) < 0) {
                return -1;
        }
        int64_t cancel_endpoint_um =
                cancel_progress_um + cancel_coast_um;
        /*
         * Cancel is a physical stop, not destination correction.  Its possible
         * coast may pass the old destination and must never be clipped to it.
         */
        invalidate_projection(slot);
        dispatch_runtime[slot].motion_anchor_distance_um =
                cancel_progress_um;
        dispatch_runtime[slot].motion_anchor_tick =
                stop_confirmed_tick;
        dispatch_runtime[slot].motion_anchor_from_traffic = 1;
        dispatch_runtime[slot].traffic_hold_distance_um =
                cancel_endpoint_um;
        dispatch_runtime[slot].launch_batch_token = 0;
        dispatch_runtime[slot].launch_batch_index = -1;
        dispatch_runtime[slot].launch_wave_tick = -1;
        dispatch_runtime[slot].command_speed = 0;
        if (dispatch_runtime[slot].motion_speed_ceiling <
            stop_speed) {
                dispatch_runtime[slot].motion_speed_ceiling =
                        stop_speed;
        }
        dispatch_jobs[slot].command_speed = 0;
        dispatch_jobs[slot].estimated_distance_um =
                cancel_progress_um;
        dispatch_jobs[slot].state = TC2_JOB_CANCEL_BRAKING;
        dispatch_jobs[slot].ready_at_tick = -1;
        dispatch_jobs[slot].braking_at_tick = -1;
        dispatch_jobs[slot].needs_stop_retry = 0;
        dispatch_jobs[slot].stop_sent_tick =
                stop_confirmed_tick;
        if (!dispatch_jobs[slot].stop_timing_valid) {
                dispatch_jobs[slot].stop_request_tick =
                        stop_request_tick;
                dispatch_jobs[slot].stop_confirmed_tick =
                        stop_confirmed_tick;
                dispatch_jobs[slot].stop_timing_valid = 1;
        }
        dispatch_runtime[slot].settle_at_tick =
                tick_after(stop_confirmed_tick, settle_ticks);
        /*
         * Safe lifecycle order is strict and generic for every train/route:
         * zero confirmed -> bounded static body CAS -> retire every dynamic
         * hard/soft owner through the two-second handoff.  Releasing FIFO work
         * before the CAS made the stopped train disappear from control while
         * its physical body was still on the layout.
         */
        if (update_cancel_stationary_hold(
                    slot, stationary_lower_um,
                    stationary_upper_um) < 0) {
                /* Keep the old logical owner fail-closed; never call fail_job(). */
                return -1;
        }
        dispatch_jobs[slot].estimated_distance_um = stationary_upper_um;
        retire_future_control_fields(&dispatch_runtime[slot]);
        dispatch_runtime[slot].lifecycle_stop_reason =
                TC2_LIFECYCLE_STOP_OPERATOR_CANCEL;
        if (retire_terminal_conflict_zone_memory(
                    slot, stop_confirmed_tick) < 0) {
                /* The static body is safe; a later tick retries owner retirement. */
                return -1;
        }
        /*
         * The canceled train is now a different topology object: a stationary
         * block with no future turnout commands. Recompute the complete
         * traffic relation first; survivors which become PREPARING then
         * invalidate advisory motor proofs and revalidate their preserved
         * next/nextnext before the conflict scheduler may arm a launch.
         */
        process_traffic_safety(stop_confirmed_tick);
        restart_prearmed_stationary_survivors(slot);
        process_conflict_zones(stop_confirmed_tick);
        process_authority_holds(stop_confirmed_tick);
        process_conflict_zones(stop_confirmed_tick);
        return 0;
}

/*
 * A remove commits a real topology change: one physical obstacle and all of
 * its reservations are gone. Re-arm each surviving authority hold without
 * first releasing the survivor's own previous/current/next physical guard.
 * Its next successful reservation CAS atomically replaces that stationary
 * window; there must never be a gap in which the train body is unprotected.
 * This is independent of train number and route. Other live trains remain in
 * the global tables and can still reject the new window.
 */
static int rearm_survivor_after_block_remove(
        int slot, int now) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS || now < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (job->state != TC2_JOB_TRAFFIC_HOLD ||
            runtime->stop_purpose != TC2_STOP_TRAFFIC ||
            runtime->traffic_reason != TC2_TRAFFIC_AUTHORITY ||
            runtime->traffic_hold_distance_um < 0 ||
            !runtime->rolling_authority_active ||
            !runtime->route_valid ||
            job->current_route_offset < runtime->leg_start_offset ||
            job->current_route_offset >= runtime->route.node_count) {
                return 0;
        }

        /*
         * Keep safety_footprint, authority_end_offset and any physical carry
         * intact. process_authority_holds() either abandons an unused
         * prefetch safely or replaces this complete window atomically.
         */
        runtime->authority_resume_pending = 0;
        runtime->conflict_zone_hold_active = 0;
        clear_authority_request(runtime);
        return begin_authority_request(slot, now, 0);
}

static void clear_removed_traffic_slot_from_survivors(
        int removed_slot) {
        uint16_t removed = traffic_slot_bit(removed_slot);
        if (removed == 0) return;
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                if (slot == removed_slot) continue;
                dispatch_runtime[slot].traffic_blockers_now =
                        (uint16_t)(
                                dispatch_runtime[slot]
                                        .traffic_blockers_now &
                                (uint16_t)~removed);
                dispatch_runtime[slot].traffic_head_on_latches =
                        (uint16_t)(
                                dispatch_runtime[slot]
                                        .traffic_head_on_latches &
                                (uint16_t)~removed);
        }
}

/*
 * A physically removed train can be named by several independent survivor
 * latches.  Reservation/conflict ownership is released first; then this
 * reconciliation pass removes stale reservation-conflict diagnostics and
 * lets the ordinary traffic FSM decide whether each survivor may resume,
 * must acquire fresh turnout authority, or must remain stopped for another
 * live train.  In particular, do not special-case a train number or route.
 *
 * A survivor still coasting to a TC2_STOP_TRAFFIC hold cannot resume yet, but
 * it must not retain a peer-specific latch for a train which no longer
 * exists.  Transfer only that survivor to the ordinary AUTHORITY hold.  The
 * frozen stop point, route reservation, turnout gate, destination, and resume
 * speed remain intact; after braking settles, the normal conflict-zone and
 * rolling-authority FSMs decide when it may move.  References belonging to a
 * different live peer are never touched.
 */
static void reconcile_survivors_after_remove(
        int removed_train, int now) {
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                if (job->state == TC2_JOB_EMPTY) continue;
                int removed_was_traffic_peer =
                        runtime->traffic_peer_train == removed_train ||
                        job->traffic_peer_train == removed_train;
                if (job->conflict_train == removed_train) {
                        job->conflict_train = 0;
                        job->conflict_node = -1;
                }
                /* UI peer fields are diagnostic only; masks drive recovery. */
                if (runtime->traffic_peer_train == removed_train) {
                        runtime->traffic_peer_train = 0;
                }
                if (job->traffic_peer_train == removed_train) {
                        job->traffic_peer_train = 0;
                }
                /*
                 * A survivor can still be physically coasting when its named
                 * traffic peer is removed.  It must finish that acknowledged
                 * zero-speed stop, but the vanished pair relation must not
                 * remain as a permanent HEAD_ON/FOLLOWING latch.  Transfer
                 * the in-flight stop to the ordinary authority state; after
                 * settle the central arbiter will reacquire the complete
                 * rolling window and revalidate next/nextnext before any
                 * positive command.  A different live peer is left intact
                 * and will be rediscovered by the pairwise pass below.
                 */
                if (removed_was_traffic_peer &&
                    job->state == TC2_JOB_BRAKING &&
                    runtime->stop_purpose == TC2_STOP_TRAFFIC) {
                        runtime->traffic_reason =
                                TC2_TRAFFIC_AUTHORITY;
                        job->traffic_reason =
                                TC2_TRAFFIC_AUTHORITY;
                }
        }

        if (now >= 0) {
                /*
                 * Recompute every pair before deciding who may wake.  The
                 * complete masks—not whichever peer happened to be printed
                 * in the UI—then say whether each survivor is still blocked.
                 */
                process_traffic_safety(now);
                /*
                 * The safety pass is what converts a newly-unblocked HOLD
                 * survivor to PREPARING. Restart after that transition so a
                 * remove cannot leave it using a pre-removal motor proof.
                 */
                restart_prearmed_stationary_survivors(-1);
                for (int slot = 0;
                     slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        if (job->state != TC2_JOB_TRAFFIC_HOLD ||
                            runtime->stop_purpose != TC2_STOP_TRAFFIC ||
                            runtime->traffic_reason !=
                                    TC2_TRAFFIC_AUTHORITY ||
                            runtime->traffic_blockers_now != 0 ||
                            runtime->traffic_head_on_latches != 0) {
                                continue;
                        }
                        if (rearm_survivor_after_block_remove(
                                    slot, now) < 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_RESERVATION);
                        }
                }
                /*
                 * Removal has already committed both ownership releases.
                 * Drive the ordinary FIFO/authority machinery immediately;
                 * no branch below grants motion by itself.
                 */
                process_braking_and_reversing(now);
                process_conflict_zones(now);
                process_authority_holds(now);
                process_conflict_zones(now);
                process_traffic_safety(now);
        }
}

/*
 * A partially confirmed positive-speed wave cannot be rewound to READY: any
 * member may already have moved, including a later member whose confirmation
 * has not yet been observed by this task.  Stop the complete wave in one
 * emergency batch.  Every member first enters the ordinary BRAKING state so
 * the shared zero acknowledgement and coast settle are observed before any
 * further positive command is possible.
 *
 * The cancel/remove target continues its operator lifecycle in the caller.
 * Every other member keeps its immutable route, destination, reservation and
 * next/nextnext conflict-zone cursors.  It becomes a resumable AUTHORITY hold
 * after the zero settles and can move again only through the central
 * reservation, turnout and can_train_move() gates.  A topology operation on
 * one train must never turn healthy batch peers into permanent FAILED jobs.
 */
static int stop_partially_confirmed_launch_wave(
        int target_slot, unsigned int launch_token,
        int now) {
        if (target_slot < 0 ||
            target_slot >= TC2_DISPATCH_MAX_JOBS ||
            launch_token == 0 || now < 0) {
                return -1;
        }

        int members[TC2_DISPATCH_MAX_JOBS];
        int trains[TC2_DISPATCH_MAX_JOBS];
        int member_count = 0;
        int target_found = 0;
        for (int slot = 0;
             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                int state = dispatch_jobs[slot].state;
                if (dispatch_runtime[slot].launch_batch_token !=
                            launch_token ||
                    (state != TC2_JOB_LAUNCHING &&
                     state != TC2_JOB_RUNNING)) {
                        continue;
                }
                members[member_count] = slot;
                trains[member_count] = dispatch_jobs[slot].train;
                ++member_count;
                if (slot == target_slot) target_found = 1;
        }
        if (!target_found || member_count < 1) return -1;

        int zero_token = CAN_SEND_BUSY;
        for (int attempt = 0; attempt < 3; ++attempt) {
                zero_token = CanTrainEmergencyStopBatch(
                        dispatch_can_tid, trains, member_count);
                if (zero_token != CAN_SEND_BUSY) break;
                if (attempt + 1 < 3) Delay(1);
        }
        if (zero_token <= 0) {
                fail_launch_wave(
                        launch_token, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }

        for (int index = 0; index < member_count; ++index) {
                int slot = members[index];
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                int resume_speed = runtime->command_speed > 0 ?
                        runtime->command_speed :
                        runtime->planned_launch_speed > 0 ?
                        runtime->planned_launch_speed :
                        job->speed;
                int confirmed_distance_mm = 0;
                int was_launching = job->state == TC2_JOB_LAUNCHING;
                if (!runtime->route_valid ||
                    !runtime->movement_plan_active ||
                    resume_speed < 1 || resume_speed > 120 ||
                    (was_launching &&
                     !runtime->authority_resume_pending &&
                     effective_confirmed_distance_mm(
                             runtime,
                             &confirmed_distance_mm) < 0) ||
                    (was_launching &&
                     runtime->authority_resume_pending &&
                     runtime->traffic_hold_distance_um < 0) ||
                    (!was_launching &&
                     runtime->motion_anchor_tick < 0)) {
                        fail_launch_wave(
                                launch_token,
                                TC2_FAILURE_INTERNAL);
                        return -1;
                }

                /*
                 * Treat every not-yet-initialized LAUNCHING member as a
                 * possible escaped command.  The batch's common launch tick
                 * is the conservative start of motion; a detector remains
                 * the only position anchor.
                 */
                if (was_launching) {
                        runtime->motion_anchor_distance_um =
                                runtime->authority_resume_pending ?
                                runtime->preorigin_sensor_pending &&
                                        runtime
                                                ->preorigin_traffic_hold_valid ?
                                runtime
                                        ->preorigin_traffic_hold_distance_um :
                                runtime->traffic_hold_distance_um :
                                (int64_t)confirmed_distance_mm * 1000;
                        runtime->motion_anchor_tick =
                                runtime->launch_wave_tick >= 0 ?
                                runtime->launch_wave_tick : now;
                        runtime->motion_anchor_from_traffic =
                                runtime->authority_resume_pending;
                        /*
                         * The train was stationary at this detector scalar
                         * until the common launch tick.  Preserve that tick
                         * as the cancel body's conservative detector-age
                         * origin; launch_ready_jobs() intentionally cleared
                         * last_confirmed_tick before the batch was observed.
                         */
                        if (!runtime->authority_resume_pending) {
                                runtime->last_confirmed_tick =
                                        runtime->motion_anchor_tick;
                        }
                }

                runtime->launch_batch_token = 0;
                runtime->launch_batch_index = -1;
                runtime->launch_wave_tick = -1;
                runtime->traffic_resume_speed = resume_speed;
                runtime->traffic_peer_train = 0;
                runtime->traffic_reason = TC2_TRAFFIC_AUTHORITY;
                runtime->traffic_hold_since_tick = -1;
                runtime->prelaunch_traffic_blocked = 1;
                job->launch_tick = -1;
                job->ready_at_tick = -1;
                job->traffic_hold_active = 1;
                job->traffic_reason = TC2_TRAFFIC_AUTHORITY;
                job->traffic_peer_train = 0;
                job->traffic_gap_mm = -1;
                job->traffic_stop_threshold_mm = -1;
                job->traffic_resume_threshold_mm = -1;

                begin_stop_with_queued_zero(
                        slot, now, TC2_STOP_TRAFFIC, 1,
                        TC2_STOP_TRIGGER_TIMER,
                        (unsigned int)zero_token);
                if (job->state != TC2_JOB_BRAKING ||
                    runtime->stop_purpose != TC2_STOP_TRAFFIC ||
                    runtime->emergency_stop_token !=
                            (unsigned int)zero_token) {
                        return -1;
                }
        }
        return 1;
}

/*
 * A shared launch batch is atomic only until its first speed command is
 * confirmed.  Before that point a remove may cancel the batch and return all
 * surviving members to PREPARING.  Once a positive frame may have escaped,
 * stop the complete wave as recoverable traffic holds; never continue only a
 * subset and never discard a healthy survivor's movement plan.  Status/cancel
 * RPC failures remain fail-stop because the physical command state is then
 * unobservable.
 */
static int rewind_unconfirmed_launch_wave_for_remove(int slot) {
        if (slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return -1;
        tc2_dispatch_runtime *target_runtime =
                &dispatch_runtime[slot];
        unsigned int token = target_runtime->launch_batch_token;
        if ((dispatch_jobs[slot].state != TC2_JOB_LAUNCHING &&
             dispatch_jobs[slot].state != TC2_JOB_RUNNING) ||
            token == 0) {
                return 0;
        }

        can_batch_status_t status;
        if (CanGetBatchStatus(dispatch_can_tid, token, &status) < 0 ||
            status.token != token || status.total < 1 ||
            status.confirmed < 0 || status.confirmed > status.total) {
                fail_launch_wave(token, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }
        if (status.state == CAN_BATCH_COMPLETE) {
                return 0;
        }
        if (status.state == CAN_BATCH_FAILED) {
                fail_launch_wave(token, TC2_FAILURE_CAN_HEALTH);
                return 0;
        }
        if (status.state != CAN_BATCH_PENDING ||
            CanCancelBatch(dispatch_can_tid, token) < 0) {
                fail_launch_wave(token, TC2_FAILURE_CAN_HEALTH);
                return -1;
        }

        if (status.confirmed != 0) {
                int now = Time();
                if (now < 0) {
                        fail_launch_wave(
                                token, TC2_FAILURE_CAN_HEALTH);
                        return -1;
                }
                return stop_partially_confirmed_launch_wave(
                        slot, token, now);
        }

        for (int member = 0;
             member < TC2_DISPATCH_MAX_JOBS; ++member) {
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[member];
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[member];
                if (runtime->launch_batch_token != token) continue;
                runtime->launch_batch_token = 0;
                runtime->launch_batch_index = -1;
                runtime->launch_wave_tick = -1;
                runtime->command_speed = 0;
                runtime->motion_speed_ceiling = 0;
                job->command_speed = 0;
                job->launch_tick = -1;
                job->ready_at_tick = -1;
                runtime->ready_wave_tick = -1;
                if (member != slot &&
                    job->state == TC2_JOB_LAUNCHING) {
                        job->state = TC2_JOB_PREPARING;
                        runtime->prelaunch_traffic_blocked = 1;
                }
        }
        return 0;
}

static int reservation_release_is_confirmed(int train) {
        if (train < 1 || train > 255) return -1;
        track_reservation_snapshot reservation;
        if (TrackReservationServerSnapshot(
                    dispatch_reservation_tid, &reservation) < 0) {
                return -1;
        }
        if (reservation.destination_by_train[train] != -1) return 0;
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (reservation.owner_by_node[node] == train) return 0;
        }
        return 1;
}

static int remove_job(int train) {
        int slot = find_train_job(train);
        if (slot < 0) return -1;
        int now = Time();
        if (now < 0) return -1;
        Tc2ConflictZoneTick(
                &dispatch_conflict_zones, (uint32_t)now);

        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        int already_pending =
                runtime->lifecycle_stop_reason ==
                        TC2_LIFECYCLE_STOP_REMOVE_PENDING;

        /*
         * remove is the operator's assertion that the physical train has
         * been lifted from the layout.  External CAN cancellation and the
         * reservation-server release cannot be rolled back across tasks, so
         * removal is a monotonic, idempotent convergence rather than a fake
         * byte-for-byte transaction.  A failed attempt leaves a zero-speed
         * tombstone and the next remove retries only unfinished phases.
         */
        if (!already_pending) {
                int partial_launch_stop =
                        rewind_unconfirmed_launch_wave_for_remove(slot);
                if (partial_launch_stop < 0) {
                        return -1;
                }
                if (command_train_speed_with_retry(train, 0) < 0) {
                        if (partial_launch_stop > 0) {
                                fail_job(
                                        slot,
                                        TC2_FAILURE_CAN_SERVICE);
                        }
                        return -1;
                }
                /* Physical zero is independently acknowledged for removal. */
                runtime->emergency_stop_token = 0;
                invalidate_projection(slot);
                retire_future_control_fields(runtime);
                runtime->lifecycle_stop_reason =
                        TC2_LIFECYCLE_STOP_REMOVE_PENDING;
                runtime->command_speed = 0;
                runtime->motion_speed_ceiling = 0;
                runtime->remove_zone_cleanup_complete = 0;
                runtime->remove_reservation_release_complete = 0;
                job->command_speed = 0;
                job->state = TC2_JOB_STOP_UNCONFIRMED;
                job->position_estimated = 1;
                job->ready_at_tick = -1;
                job->braking_at_tick = -1;
                job->needs_stop_retry = 0;
        }

        /* No pending turnout command may survive the tombstone. */
        if (cancel_old_conflict_zone_batch(slot) < 0 ||
            discard_old_prelaunch_turnout_batch(slot) < 0) {
                return -1;
        }
        if (!runtime->remove_zone_cleanup_complete) {
                if (TC2_DISPATCH_CONFLICT_ZONE_REMOVE_TRAIN(
                            &dispatch_conflict_zones, train, 1) < 0) {
                        return -1;
                }
                runtime->remove_zone_cleanup_complete = 1;
        }
        if (!runtime->remove_reservation_release_complete) {
                int release_status = TrackReservationServerRelease(
                        dispatch_reservation_tid, train);
                int confirmed = reservation_release_is_confirmed(train);
                if (confirmed != 1) {
                        /*
                         * A transport error may mean the server committed
                         * but its reply was lost.  Snapshot is the only
                         * authoritative completion proof; retry is safe
                         * because server-side release is idempotent.
                         */
                        (void)release_status;
                        return -1;
                }
                runtime->remove_reservation_release_complete = 1;
        }
        clear_removed_traffic_slot_from_survivors(slot);
        invalidate_projection(slot);
        clear_job(&dispatch_jobs[slot]);
        clear_runtime(&dispatch_runtime[slot]);
        reconcile_survivors_after_remove(train, now);
        return 0;
}

static void fill_turnout_plan_snapshot(
        int slot, tc2_dispatch_job_snapshot *job) {
        if (!job || slot < 0 || slot >= TC2_DISPATCH_MAX_JOBS) return;

        job->turnout_plan_step_count = 0;
        job->turnout_plan_action_count = 0;
        job->next_turnout_action_count = 0;
        job->next_next_turnout_action_count = 0;
        for (int action = 0;
             action < TC2_DISPATCH_TURNOUT_ACTIONS_PER_STEP; ++action) {
                job->next_turnout_switch[action] = -1;
                job->next_turnout_direction[action] = 0;
                job->next_next_turnout_switch[action] = -1;
                job->next_next_turnout_direction[action] = 0;
        }

        const tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (!runtime->conflict_zone_plan_valid ||
            job->state == TC2_JOB_EMPTY ||
            job->state == TC2_JOB_FAILED ||
            job->state == TC2_JOB_CANCEL_BRAKING ||
            job->state == TC2_JOB_STOPPED ||
            job->state == TC2_JOB_STOP_UNCONFIRMED ||
            job->state == TC2_JOB_ARRIVED) {
                /*
                 * A stationary terminal train is a physical block only.
                 * Arrival/cancel retirement removes every future turnout
                 * request and starts the resource-owned handoff delay for any
                 * control it can safely release.  Only the bounded body
                 * reservation remains collision-relevant, so no next or
                 * nextnext action is published from this terminal snapshot.
                 */
                return;
        }

        job->turnout_plan_step_count =
                runtime->conflict_zone_plan.stage_count;
        for (int step_index = 0;
             step_index < runtime->conflict_zone_plan.step_count;
             ++step_index) {
                const tc2_conflict_zone_setting *setting =
                        &runtime->conflict_zone_plan.steps[step_index]
                                 .setting;
                job->turnout_plan_action_count +=
                        setting->action_count;
        }

        int step_index = runtime->conflict_zone_next_step;

        /*
         * Publish literal physical next and nextnext steps.  Do not hide an
         * already-correct motor: its direction still matters and its queue
         * control is still required.  A compound physical group publishes
         * all of its exact route actions under the one shared FIFO ticket.
         */
        for (int lookahead = 0; lookahead < 2; ++lookahead) {
                if (step_index < 0 ||
                    step_index >=
                            runtime->conflict_zone_plan.step_count) {
                        break;
                }
                const tc2_conflict_zone_route_stage *stage =
                        conflict_zone_stage_for_step(
                                &runtime->conflict_zone_plan,
                                step_index);
                if (!stage || stage->member_step[0] != step_index) break;
                int count = 0;
                for (int member = 0;
                     member < stage->member_count; ++member) {
                        int raw_step = stage->member_step[member];
                        const tc2_conflict_zone_setting *setting =
                                &runtime->conflict_zone_plan
                                         .steps[raw_step].setting;
                        for (int member_action = 0;
                             member_action < setting->action_count &&
                             count <
                                     TC2_DISPATCH_TURNOUT_ACTIONS_PER_STEP;
                             ++member_action) {
                                const tc2_conflict_turnout_action *action =
                                        &setting->actions[member_action];
                                char direction =
                                        action->direction ==
                                                        TC2_CONFLICT_TURNOUT_CURVED ?
                                                'C' : 'S';
                                if (lookahead == 0) {
                                        job->next_turnout_switch[count] =
                                                action->switch_number;
                                        job->next_turnout_direction[count] =
                                                direction;
                                } else {
                                        job->next_next_turnout_switch[count] =
                                                action->switch_number;
                                        job->next_next_turnout_direction[count] =
                                                direction;
                                }
                                ++count;
                        }
                }
                if (lookahead == 0) {
                        job->next_turnout_action_count = count;
                } else {
                        job->next_next_turnout_action_count = count;
                }
                step_index = conflict_zone_next_stage_first_step(
                        &runtime->conflict_zone_plan, step_index);
        }
}

static void fill_snapshot(tc2_dispatch_snapshot *snapshot) {
        snapshot->job_count = 0;
        snapshot->launch_epoch = dispatch_launch_epoch;
        snapshot->blocked_physical_count =
                count_blocked_physical();
        snapshot->batch_ready_at_tick =
                dispatch_batch_ready_at_tick;
        snapshot->scheduler_healthy =
                dispatch_scheduler_healthy;
        for (int node = 0; node < TRACK_MAX; ++node) {
                snapshot->blocked_by_node[node] =
                        dispatch_blocked_by_node[node];
        }
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                snapshot->jobs[slot] = dispatch_jobs[slot];
                fill_turnout_plan_snapshot(slot, &snapshot->jobs[slot]);
                if (dispatch_jobs[slot].state != TC2_JOB_EMPTY) {
                        ++snapshot->job_count;
                }
        }
}

/*
 * The scheduling core is defined below in small, independently testable
 * helpers. Keeping the IPC shell complete here also keeps MODE_TC2 builds
 * linkable while the state-machine helpers remain single-writer server state.
 */
static int initialize_turnout_batch(
        const int *switches, const char *directions, int count) {
        if (!switches || !directions || count < 1 ||
            count > CAN_COMMAND_BATCH_MAX) {
                return -1;
        }
        int token = CAN_SEND_BUSY;
        for (int attempt = 0; attempt < 3; ++attempt) {
                token = CanSwitchBatch(
                        dispatch_can_tid, switches, directions, count);
                if (token != CAN_SEND_BUSY) break;
                if (attempt + 1 < 3) Delay(1);
        }
        if (token < 0) return -1;
        if (token > 0) {
                int complete = 0;
                for (int tick = 0;
                     tick < TC2_STARTUP_TURNOUT_TIMEOUT_TICKS;
                     ++tick) {
                        can_batch_status_t status;
                        if (CanGetBatchStatus(
                                    dispatch_can_tid,
                                    (unsigned int)token,
                                    &status) < 0 ||
                            status.token != (unsigned int)token) {
                                return -1;
                        }
                        if (status.state == CAN_BATCH_FAILED) return -1;
                        if (status.state == CAN_BATCH_COMPLETE) {
                                if (status.total != count ||
                                    status.confirmed != count) {
                                        return -1;
                                }
                                complete = 1;
                                break;
                        }
                        Delay(1);
                }
                if (!complete) return -1;
        }
        for (int index = 0; index < count; ++index) {
                if (record_turnout_direction(
                            switches[index], directions[index]) < 0) {
                        return -1;
                }
        }
        return 0;
}

static int initialize_all_turnouts(void) {
        int switches[CAN_COMMAND_BATCH_MAX];
        char directions[CAN_COMMAND_BATCH_MAX];
        int count = 0;
        for (int switch_number = 1;
             switch_number <= 18; ++switch_number) {
                switches[count] = switch_number;
                char startup =
                        startup_turnout_direction(switch_number);
                directions[count++] = startup ? startup : 'S';
                if (count == CAN_COMMAND_BATCH_MAX) {
                        if (initialize_turnout_batch(
                                    switches, directions, count) < 0) {
                                return -1;
                        }
                        count = 0;
                }
        }
        for (int switch_number = 153;
             switch_number <= 156; ++switch_number) {
                switches[count] = switch_number;
                directions[count++] = 'S';
        }
        if (count > 0 &&
            initialize_turnout_batch(
                    switches, directions, count) < 0) {
                return -1;
        }
        /* Do not admit motion until the last initialized points settle. */
        return Delay(TC2_TURNOUT_SETTLE_TICKS) < 0 ? -1 : 0;
}

static void dispatch_server_core(void);

void Tc2DispatchTickerTask(void) {
        int parent = MyParentTid();
        tc2_dispatch_request request;
        tc2_dispatch_reply reply;
        clear_request(&request, TC2_DISPATCH_MSG_TICK);
        int elapsed = 0;
        for (;;) {
                if (AwaitEvent(EVENT_TIMER) < 0) continue;
                ++elapsed;
                if (elapsed < TC2_DISPATCH_TICK_TICKS) continue;
                elapsed = 0;
                (void)Send(
                        parent, (const char *)&request,
                        sizeof(request), (char *)&reply,
                        sizeof(reply));
        }
}

void Tc2DispatchServerTask(void) {
        dispatch_server_core();
}

static void dispatch_server_core(void) {
        tc2_dispatch_request request;
        tc2_dispatch_reply reply;
        tc2_dispatch_snapshot snapshot;
        tc2_dispatch_blocked_snapshot blocked_snapshot;
        tc2_dispatch_projection_header projection_header;
        tc2_dispatch_projection_page projection_page;
        int sender;

        init_trackb(dispatch_track);
        initialize_conflict_zone_table();
        int catalog_ok =
                Tc2TrackCatalogValidate(dispatch_track) == 0;
        /*
         * Keep this bounded clear in the same separate translation-unit
         * helper used for prepare_sensor_state.  GCC 12's AArch64 -O3 bounds
         * analysis otherwise reports a false one-past-end
         * -Wstringop-overflow for the valid TRACK_MAX-byte initialization.
         */
        util_zero_bytes(dispatch_blocked_by_node,
                        (unsigned int)sizeof(
                                dispatch_blocked_by_node));
        for (int slot = 0; slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                clear_job(&dispatch_jobs[slot]);
                clear_runtime(&dispatch_runtime[slot]);
                initialize_projection_publication(slot);
        }
        Tc2RouteProjectionInitialize(
                &dispatch_projection_scratch);
        dispatch_projection_serial = 0;
        dispatch_launch_epoch = 0;
        dispatch_queue_sequence = 0;
        dispatch_batch_ready_at_tick = -1;
        dispatch_scheduler_healthy = 0;
        dispatch_heartbeat = 0;
        dispatch_can_heartbeat_valid = 0;
        dispatch_can_tx_heartbeat = 0;
        dispatch_can_rx_heartbeat = 0;
        dispatch_can_tx_heartbeat_tick = -1;
        dispatch_can_rx_heartbeat_tick = -1;
        dispatch_last_logical_time = -1;
        dispatch_supervisor_trip = 0;
        dispatch_last_progress_usec = timer_get_usec();
        int register_status =
                RegisterAs(TC2_DISPATCH_SERVER_NAME);
        dispatch_can_tid = WhoIs(CAN_SERVER_NAME);
        dispatch_sensor_tid = WhoIs(TRAIN_SENSOR_SERVER_NAME);
        dispatch_reservation_tid =
                WhoIs(TRACK_RESERVATION_SERVER_NAME);
        int ticker_tid = Create(
                TC2_DISPATCH_TICKER_PRIORITY,
                Tc2DispatchTickerTask);
        int safety_tid = Create(3, Tc2DispatchSafetyTask);
        int turnout_authority_status =
                CanRegisterTurnoutAuthority(dispatch_can_tid);
        train_sensor_snapshot_t startup_sensor;
        track_reservation_snapshot startup_reservation;
        can_health_t startup_can;
        int clock_tick = Time();
        int startup_sensor_ok =
                wait_for_sensor_startup(
                        dispatch_sensor_tid,
                        &startup_sensor,
                        TC2_SENSOR_STARTUP_MAX_ATTEMPTS);
        int startup_reservation_ok =
                TrackReservationServerSnapshot(
                        dispatch_reservation_tid,
                        &startup_reservation) == 0;
        int startup_can_ok =
                CanGetHealth(dispatch_can_tid, &startup_can) == 0 &&
                startup_can.hw_ready;
        if (startup_can_ok) {
                dispatch_unexpected_turnout_changes =
                        startup_can.turnout_changes;
        }
        dispatch_scheduler_healthy =
                scheduler_dependencies_healthy(
                        register_status, dispatch_can_tid,
                        dispatch_sensor_tid,
                        dispatch_reservation_tid, ticker_tid,
                        safety_tid) &&
                clock_tick >= 0 && startup_sensor_ok &&
                startup_reservation_ok && startup_can_ok &&
                turnout_authority_status == 0 &&
                catalog_ok;
        if (dispatch_scheduler_healthy) {
                /*
                 * Establish one atomic, known-stopped startup state for every
                 * TC2 locomotive before accepting any dispatch request.  Set
                 * every turnout S except the commissioned startup defaults
                 * 1S/2S/3C/4S/12C, then publish only confirmed values into
                 * the dispatcher-wide turnout table.  The route arbiter may
                 * later change every one of these logical turnouts while it
                 * owns the corresponding compound physical resource set.
                 */
                int startup_trains[] = {14, 15, 17, 18};
                if (CanTrainEmergencyStopBatch(
                            dispatch_can_tid, startup_trains,
                            (int)(sizeof(startup_trains) /
                                  sizeof(startup_trains[0]))) < 0 ||
                    initialize_all_turnouts() < 0) {
                        dispatch_scheduler_healthy = 0;
                }
        }
        if (clock_tick >= 0) {
                dispatch_last_logical_time = clock_tick;
        }

        for (;;) {
                int length = Receive(&sender, (char *)&request,
                                     sizeof(request));
                reply.status = -1;
                reply.affected = 0;
                if (length != (int)sizeof(request)) {
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                        continue;
                }

                int recovery_reroute_intent =
                        request.type == TC2_DISPATCH_MSG_STAGE &&
                        request.start_index ==
                                TC2_DISPATCH_START_CURRENT &&
                        (request.reserved &
                         TC2_DISPATCH_REQUEST_OPERATOR_REROUTE) != 0;
                int allowed_while_unhealthy =
                        request.type == TC2_DISPATCH_MSG_SNAPSHOT ||
                        request.type == TC2_DISPATCH_MSG_CANCEL ||
                        request.type == TC2_DISPATCH_MSG_REMOVE ||
                        request.type ==
                                TC2_DISPATCH_MSG_BLOCKED_SNAPSHOT ||
                        request.type ==
                                TC2_DISPATCH_MSG_IS_MANAGED ||
                        request.type ==
                                TC2_DISPATCH_MSG_PROJECTION_HEADER ||
                        request.type ==
                                TC2_DISPATCH_MSG_PROJECTION_PAGE ||
                        request.type == TC2_DISPATCH_MSG_TICK ||
                        recovery_reroute_intent;
                if (!dispatch_scheduler_healthy &&
                    !allowed_while_unhealthy) {
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                        continue;
                }

                if (request.type == TC2_DISPATCH_MSG_STAGE ||
                    request.type ==
                            TC2_DISPATCH_MSG_STAGE_CALIBRATION) {
                        /*
                         * Reject before stage_job can reserve track or any
                         * later state can enqueue speed/turnout CAN traffic.
                         * CURRENT reroutes use this same message path, so the
                         * fleet contract applies uniformly to first dispatch
                         * and recovery dispatch.
                         */
                        reply.status = production_stage_job(&request);
                        reply.affected = reply.status == 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_START_ALL) {
                        int now = Time();
                        if (now >= 0) {
                                ++dispatch_launch_epoch;
                                if (dispatch_launch_epoch == 0) {
                                        ++dispatch_launch_epoch;
                                }
                                for (int slot = 0;
                                     slot < TC2_DISPATCH_MAX_JOBS;
                                     ++slot) {
                                        if (dispatch_runtime[slot]
                                                    .retarget_pending &&
                                            !dispatch_runtime[slot]
                                                    .retarget_armed) {
                                                if (dispatch_jobs[slot].state ==
                                                            TC2_JOB_EMPTY ||
                                                    dispatch_runtime[slot]
                                                                    .lifecycle_stop_reason ==
                                                            TC2_LIFECYCLE_STOP_REMOVE_PENDING) {
                                                        clear_pending_retarget(
                                                                &dispatch_runtime[slot]);
                                                        continue;
                                                }
                                                /*
                                                 * Sensor attribution, arrival,
                                                 * and a fail-closed stop may
                                                 * legitimately restage the live
                                                 * reservation after `reroute`
                                                 * was typed.  Bind an operator
                                                 * command to that current safe
                                                 * body when `go` arms it; the
                                                 * destination/speed intent is
                                                 * newer than the retired route.
                                                 */
                                                if (dispatch_runtime[slot]
                                                            .retarget_operator_reroute) {
                                                        dispatch_runtime[slot]
                                                                .retarget_expected_generation =
                                                                dispatch_jobs[slot]
                                                                        .plan_generation;
                                                        dispatch_runtime[slot]
                                                                .retarget_expected_destination =
                                                                dispatch_jobs[slot]
                                                                        .target_node;
                                                }
                                                ++dispatch_queue_sequence;
                                                if (dispatch_queue_sequence ==
                                                    0) {
                                                        ++dispatch_queue_sequence;
                                                }
                                                dispatch_runtime[slot]
                                                        .retarget_armed = 1;
                                                dispatch_runtime[slot]
                                                        .retarget_queue_sequence =
                                                        dispatch_queue_sequence;
                                                dispatch_runtime[slot]
                                                        .retarget_launch_epoch =
                                                        dispatch_launch_epoch;
                                                ++reply.affected;
                                                continue;
                                        }
                                        if (dispatch_jobs[slot].state !=
                                            TC2_JOB_STAGED) {
                                                continue;
                                        }
                                        dispatch_jobs[slot].state =
                                                TC2_JOB_WAITING;
                                        dispatch_jobs[slot]
                                                .job_launch_epoch =
                                                dispatch_launch_epoch;
                                        ++dispatch_queue_sequence;
                                        if (dispatch_queue_sequence == 0) {
                                                ++dispatch_queue_sequence;
                                        }
                                        dispatch_jobs[slot]
                                                .queue_sequence =
                                                dispatch_queue_sequence;
                                        dispatch_runtime[slot]
                                                .queue_sequence =
                                                dispatch_queue_sequence;
                                        dispatch_runtime[slot]
                                                .launch_epoch =
                                                dispatch_launch_epoch;
                                        dispatch_runtime[slot]
                                                .wait_since_tick = now;
                                        ++reply.affected;
                                }
                        }
                        reply.status = reply.affected > 0 ? 0 : -1;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_CANCEL) {
                        reply.status = cancel_job(request.train);
                        reply.affected = reply.status == 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_REMOVE) {
                        reply.status = remove_job(request.train);
                        reply.affected = reply.status == 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_BLOCK) {
                        reply.status =
                                block_node(request.node_index, 1);
                        reply.affected = reply.status == 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_UNBLOCK) {
                        reply.status =
                                block_node(request.node_index, 0);
                        reply.affected = reply.status == 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_IS_MANAGED) {
                        reply.status =
                                find_train_job(request.train) >= 0 ?
                                1 : 0;
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_SNAPSHOT) {
                        fill_snapshot(&snapshot);
                        Reply(sender, (const char *)&snapshot,
                              sizeof(snapshot));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_BLOCKED_SNAPSHOT) {
                        blocked_snapshot.blocked_physical_count =
                                count_blocked_physical();
                        for (int node = 0; node < TRACK_MAX; ++node) {
                                blocked_snapshot.blocked_by_node[node] =
                                        dispatch_blocked_by_node[node];
                        }
                        Reply(sender,
                              (const char *)&blocked_snapshot,
                              sizeof(blocked_snapshot));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_PROJECTION_HEADER) {
                        (void)projection_header_for_train(
                                request.train,
                                &projection_header);
                        Reply(sender,
                              (const char *)&projection_header,
                              sizeof(projection_header));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_PROJECTION_PAGE) {
                        (void)projection_page_for_train(
                                request.train,
                                request.projection_serial,
                                request.projection_generation,
                                request.projection_launch_epoch,
                                request.projection_first_waypoint,
                                &projection_page);
                        Reply(sender,
                              (const char *)&projection_page,
                              sizeof(projection_page));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_DEMO_TURNOUT_BATCH) {
                        int switches[4];
                        char directions[4];
                        int ordinary_jobs = 0;
                        int count = request.train;
                        for (int slot = 0;
                             slot < TC2_DISPATCH_MAX_JOBS; ++slot) {
                                if (dispatch_jobs[slot].state !=
                                    TC2_JOB_EMPTY) {
                                        ordinary_jobs = 1;
                                        break;
                                }
                        }
                        switches[0] = request.start_index;
                        switches[1] = request.speed;
                        switches[2] = request.destination_index;
                        switches[3] = request.node_index;
                        directions[0] =
                                (char)(request.reserved & 0xffu);
                        directions[1] =
                                (char)((request.reserved >> 8) & 0xffu);
                        directions[2] =
                                (char)((request.reserved >> 16) & 0xffu);
                        directions[3] =
                                (char)((request.reserved >> 24) & 0xffu);
                        if (!ordinary_jobs && count >= 1 && count <= 4) {
                                reply.status = initialize_turnout_batch(
                                        switches, directions, count);
                                reply.affected =
                                        reply.status == 0 ? count : 0;
                        }
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else if (request.type ==
                           TC2_DISPATCH_MSG_TICK) {
                        ++dispatch_heartbeat;
                        dispatch_last_progress_usec =
                                timer_get_usec();
                        int now = Time();
                        if (now >= 0) {
                                dispatch_last_logical_time = now;
                        }
                        if (now < 0 ||
                            !dispatch_scheduler_healthy ||
                            dispatch_supervisor_trip) {
                                int failure_reason =
                                        dispatch_supervisor_trip ?
                                        TC2_FAILURE_WATCHDOG :
                                        TC2_FAILURE_INTERNAL;
                                dispatch_supervisor_trip = 0;
                                if (now < 0) {
                                        dispatch_scheduler_healthy = 0;
                                }
                                for (int slot = 0;
                                     slot < TC2_DISPATCH_MAX_JOBS;
                                     ++slot) {
                                        int state =
                                                dispatch_jobs[slot].state;
                                        if (state ==
                                                    TC2_JOB_PREPARING ||
                                            state == TC2_JOB_READY ||
                                            state ==
                                                    TC2_JOB_LAUNCHING ||
                                            state == TC2_JOB_RUNNING ||
                                            state == TC2_JOB_BRAKING ||
                                            state ==
                                                    TC2_JOB_REVERSING ||
                                            state ==
                                                    TC2_JOB_CANCEL_BRAKING) {
                                                fail_job(
                                                        slot,
                                                        failure_reason);
                                        }
                                }
                                process_stop_retries();
                        } else {
                                process_stop_retries();
                                process_conflict_zones(now);
                                process_running_jobs(now);
                                process_traffic_safety(now);
                                process_pending_retargets(now);
                                process_launching_jobs(now);
                                process_braking_and_reversing(now);
                                process_authority_holds(now);
                                process_waiting_jobs(now);
                                process_conflict_zones(now);
                                reply.status = 0;
                        }
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                } else {
                        Reply(sender, (const char *)&reply,
                              sizeof(reply));
                }
        }
}

#endif
